# IMessageFilter class that intercepts WM_HOTKEY messages from the application message loop
# Class name includes version to avoid stale cached type from previous session runs
$HotKeyFilterDeclaration = @'
using System;
using System.Windows.Forms;

public class JwlHotKeyFilter : IMessageFilter {
    private const int WM_HOTKEY = 0x0312;
    // Static flag: set by the message filter, polled by a WinForms timer on the UI thread
    public static volatile int LastHotKeyId = 0;
    
    public JwlHotKeyFilter() { }
    
    public bool PreFilterMessage(ref Message m) {
        if (m.Msg == WM_HOTKEY) {
            LastHotKeyId = m.WParam.ToInt32();
        }
        return false;  // Never consume — let normal processing continue
    }
}
'@

if (-not ([System.Management.Automation.PSTypeName]'JwlHotKeyFilter').Type) {
    try {
        $primitivesAsm = [System.Windows.Forms.Message].Assembly.Location
        Add-Type -TypeDefinition $HotKeyFilterDeclaration -ReferencedAssemblies @(
            [System.Windows.Forms.Form].Assembly.Location,
            $primitivesAsm
        )
    }
    catch {
        # Fallback: try with just the main Forms assembly
        try { Add-Type -TypeDefinition $HotKeyFilterDeclaration -ReferencedAssemblies System.Windows.Forms } catch {}
    }
}
