# ========== THREAD-SAFE UI HELPER (dispatcher abstraction) ==========
# WPF-migration Phase 1 step: generalized so call sites (`Invoke-OnUI { ... }`)
# never need to change regardless of which UI framework currently owns the
# main window. Today the app is 100% WinForms, so this still routes through
# $script:form's Control.Invoke/BeginInvoke exactly as before. Once a WPF
# shell exists (see WPF-Migration-Planning-Audit.md, Phase 2+) and assigns
# $script:MainWindow to a System.Windows.Window, this same function will
# automatically route through that window's Dispatcher instead - no caller
# needs updating either way.
function Invoke-OnUI([scriptblock]$action) {
    try {
        # Future WPF path: prefer a WPF main window's Dispatcher if one exists.
        if ($script:MainWindow -and ($script:MainWindow -is [System.Windows.Threading.DispatcherObject])) {
            $dispatcher = $script:MainWindow.Dispatcher
            if ($dispatcher.CheckAccess()) {
                & $action
            }
            else {
                $dispatcher.BeginInvoke($action) | Out-Null
            }
            return
        }

        # Current WinForms path (production shell today).
        if ($script:form -and -not $script:form.IsDisposed) {
            if ($script:form.InvokeRequired) {
                $script:form.BeginInvoke($action) | Out-Null
            }
            else {
                & $action
            }
        }
    }
    catch {}
}

function Initialize-HandAlertWpf {
    if ($script:HandAlertWpfLoaded) { return }
    try {
        Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase
        $script:HandAlertWpfLoaded = $true
    }
    catch {
        try { Log "Hand Alert: failed to load WPF assemblies: $_" } catch {}
    }
}

function Get-HandAlertScreen {
    try {
        # Force log the config value first
        $configVal = "NOT_FOUND"
        $configName = ""
        if ($script:Cfg -and $script:Cfg.Zoom) {
            if ($script:Cfg.Zoom.Contains('HandAlertMonitor')) { $configVal = $script:Cfg.Zoom.HandAlertMonitor }
            if ($script:Cfg.Zoom.Contains('HandAlertMonitorName')) { $configName = [string]$script:Cfg.Zoom.HandAlertMonitorName }
        }
        Log "HAND ALERT DEBUG: Config HandAlertMonitor = $configVal (last known device='$configName')"

        # Use the Win32 per-monitor enumeration (RoiScreen) instead of System.Windows.Forms.Screen:
        # it reports each monitor's OWN DPI, whereas WinForms' Screen DPI reflects only the calling
        # thread's current DPI-awareness context (effectively always the primary monitor's scale).
        # That mismatch is what could make the overlay land on/size for the wrong monitor when
        # monitors run at different Windows display-scaling percentages.
        $monitors = [RoiScreen]::Monitors()
        Log "HAND ALERT DEBUG: Found $($monitors.Count) screens total"

        # Ensure primary monitor is always index 0, others after (matches the Settings combo box order)
        $monitors = $monitors | Sort-Object @{ Expression = { -not $_.Primary } }, Name

        # Log all screens BEFORE selection
        for ($i = 0; $i -lt $monitors.Count; $i++) {
            $s = $monitors[$i]
            Log "HAND ALERT DEBUG: Screen[$i]: $($s.Name) $($s.Bounds.Width)x$($s.Bounds.Height) at $($s.Bounds.Left),$($s.Bounds.Top) Primary=$($s.Primary) dpi=$($s.Dpi)"
        }

        if (-not $monitors -or $monitors.Count -eq 0) {
            Log "HAND ALERT DEBUG: No screens found, using primary fallback"
            $pb = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
            return [PSCustomObject]@{ Bounds = $pb; DpiScale = 1.0; Name = ''; Primary = $true }
        }

        $index = 0
        if ($script:Cfg -and $script:Cfg.Zoom -and $script:Cfg.Zoom.Contains('HandAlertMonitor')) {
            $index = [int]$script:Cfg.Zoom.HandAlertMonitor
        }
        Log "HAND ALERT DEBUG: Using index $index (before bounds check)"

        if ($index -lt 0 -or $index -ge $monitors.Count) {
            Log "HAND ALERT DEBUG: Index $index out of bounds, resetting to 0"
            $index = 0
        }

        # Self-heal against monitor re-ordering/renumbering (e.g. after unplugging a display or a
        # driver update): if we recorded which physical monitor was selected last time (by its
        # stable Win32 device name), prefer that monitor even if its index shifted.
        if ($configName) {
            $byName = -1
            for ($i = 0; $i -lt $monitors.Count; $i++) { if ($monitors[$i].Name -eq $configName) { $byName = $i; break } }
            if ($byName -ge 0 -and $byName -ne $index) {
                Log "HAND ALERT DEBUG: Configured index $index no longer matches last known device '$configName'; re-matched to index $byName"
                $index = $byName
            }
            elseif ($byName -lt 0) {
                Log "HAND ALERT DEBUG: Last known device '$configName' not found among current screens; falling back to index $index"
            }
        }

        $m = $monitors[$index]
        # Remember which physical monitor this index resolved to, so a future run can self-heal
        # if Windows re-orders/renumbers displays.
        try { if ($script:Cfg -and $script:Cfg.Zoom) { $script:Cfg.Zoom.HandAlertMonitorName = $m.Name } } catch {}

        Log "HAND ALERT DEBUG: Selected screen: $($m.Name) bounds=$($m.Bounds.Left),$($m.Bounds.Top),$($m.Bounds.Width),$($m.Bounds.Height) dpi=$($m.Dpi)"

        return [PSCustomObject]@{
            Bounds   = $m.Bounds
            DpiScale = [double]$m.Dpi / 96.0
            Name     = $m.Name
            Primary  = $m.Primary
        }
    }
    catch {
        Log "HAND ALERT DEBUG: Exception in Get-HandAlertScreen: $($_.Exception.Message)"
        $pb = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
        return [PSCustomObject]@{ Bounds = $pb; DpiScale = 1.0; Name = ''; Primary = $true }
    }
}

function New-HandAlertWindow($screen) {
    Initialize-HandAlertWpf
    if (-not $script:HandAlertWpfLoaded) { return $null }

    $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        WindowStyle="None"
        ResizeMode="NoResize"
        AllowsTransparency="True"
        Background="Transparent"
        ShowInTaskbar="False"
        Topmost="True"
        WindowStartupLocation="Manual">
    <Grid Background="Transparent" IsHitTestVisible="False">
        <TextBlock Text="✋" FontSize="650" Foreground="Yellow"
                   HorizontalAlignment="Center" VerticalAlignment="Center"/>
    </Grid>
</Window>
"@

    $xml = [xml]$xaml
    $reader = New-Object System.Xml.XmlNodeReader $xml
    $window = [System.Windows.Markup.XamlReader]::Load($reader)

    $bounds = $screen.Bounds
    # WPF window coordinates are logical DIPs; Screen.Bounds returns physical pixels on a
    # DPI-aware process (pwsh.exe). Divide by the DPI scale so the overlay fills the screen
    # correctly at any Windows display scaling (100%, 125%, 150%, etc.).
    # Prefer the TARGET monitor's own DPI (set by Get-HandAlertScreen via RoiScreen) over the
    # process/primary-monitor DPI, since those can differ on a mixed-DPI multi-monitor setup.
    $dpi = Get-DpiScaleFactor
    if ($screen -and ($screen.PSObject.Properties.Name -contains 'DpiScale') -and [double]$screen.DpiScale -gt 0) {
        $dpi = [double]$screen.DpiScale
    }
    $window.Left = $bounds.Left / $dpi
    $window.Top = $bounds.Top / $dpi
    $window.Width = $bounds.Width / $dpi
    $window.Height = $bounds.Height / $dpi

    # Safety clamp: if the computed bounds ever land entirely outside the combined virtual
    # desktop (e.g. a stale DPI value captured right after a display-scaling change that hasn't
    # fully applied yet), fall back to the primary screen instead of showing an invisible/off-screen alert.
    try {
        $vs = [RoiScreen]::VirtualScreen()
        $vsLeft = $vs.Left / $dpi; $vsTop = $vs.Top / $dpi
        $vsRight = $vs.Right / $dpi; $vsBottom = $vs.Bottom / $dpi
        $winRight = $window.Left + $window.Width
        $winBottom = $window.Top + $window.Height
        $offscreen = ($window.Width -le 0 -or $window.Height -le 0 -or
            $winRight -le $vsLeft -or $window.Left -ge $vsRight -or
            $winBottom -le $vsTop -or $window.Top -ge $vsBottom)
        if ($offscreen) {
            Log "HAND ALERT DEBUG: Computed bounds $($window.Left),$($window.Top) $($window.Width)x$($window.Height) fall entirely outside the virtual desktop $($vsLeft),$($vsTop)-$($vsRight),$($vsBottom); clamping to primary screen"
            $prim = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
            $window.Left = $prim.Left / $dpi
            $window.Top = $prim.Top / $dpi
            $window.Width = $prim.Width / $dpi
            $window.Height = $prim.Height / $dpi
        }
    }
    catch {}

    try {
        Log "HAND ALERT DEBUG: New-HandAlertWindow physical bounds=$($bounds.Left),$($bounds.Top) $($bounds.Width)x$($bounds.Height) dpi=$dpi  WPF logical=$($window.Left),$($window.Top) $($window.Width)x$($window.Height)"
    }
    catch {}

    return $window
}

function Show-HandAlertOverlay {
    if ($script:HandOverlayVisible) { return }

    $screen = Get-HandAlertScreen
    $window = New-HandAlertWindow -screen $screen
    if (-not $window) { return }

    $script:HandOverlayWindow = $window
    $script:HandOverlayVisible = $true

    # Start transparent and fade in
    $window.Opacity = 0.0
    $window.Show()
    
    # Double-check window actually ended up on the right screen
    try {
        $actualLeft = $window.Left
        $actualTop = $window.Top
        $_dpi2 = Get-DpiScaleFactor
        if ($screen -and ($screen.PSObject.Properties.Name -contains 'DpiScale') -and [double]$screen.DpiScale -gt 0) {
            $_dpi2 = [double]$screen.DpiScale
        }
        $expectedLeft = $screen.Bounds.Left / $_dpi2
        $expectedTop = $screen.Bounds.Top / $_dpi2
        if ([Math]::Abs($actualLeft - $expectedLeft) -gt 10 -or [Math]::Abs($actualTop - $expectedTop) -gt 10) {
            Log ("Hand Alert: Window positioned wrong! Expected {0},{1} but got {2},{3} - forcing reposition" -f $expectedLeft, $expectedTop, $actualLeft, $actualTop)
            $window.Left = $expectedLeft
            $window.Top = $expectedTop
        }
        else {
            Log ("Hand Alert: Window positioned correctly at {0},{1}" -f $actualLeft, $actualTop)
        }
    }
    catch {
        Log ("Hand Alert: Could not verify window position")
    }

    # Make the window click-through at OS level
    try {
        $helper = New-Object System.Windows.Interop.WindowInteropHelper $window
        $hwnd = $helper.Handle
        if ($hwnd -ne [IntPtr]::Zero) {
            $style = [Win32]::GetWindowLong($hwnd, [Win32]::GWL_EXSTYLE)
            $style = $style -bor [Win32]::WS_EX_TRANSPARENT -bor [Win32]::WS_EX_LAYERED
            [void][Win32]::SetWindowLong($hwnd, [Win32]::GWL_EXSTYLE, $style)
        }
    }
    catch {
        try { Log "Hand Alert: failed to set click-through style: $_" } catch {}
    }

    $fadeIn = New-Object System.Windows.Media.Animation.DoubleAnimation
    $fadeIn.From = 0.0
    $fadeIn.To = 1.0
    $fadeIn.Duration = [System.Windows.Duration]::op_Implicit([TimeSpan]::FromMilliseconds(400))
    
    # Add completion handler to start blinking after fade-in
    $fadeIn.Add_Completed({
            # Start blinking animation - pulse between full and 30% opacity
            $blink = New-Object System.Windows.Media.Animation.DoubleAnimation
            $blink.From = 1.0
            $blink.To = 0.3
            $blink.Duration = [System.Windows.Duration]::op_Implicit([TimeSpan]::FromMilliseconds(800))
            $blink.AutoReverse = $true
            $blink.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $script:HandOverlayWindow.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $blink)
        })
    
    $window.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fadeIn)

    # Auto-timeout after 30 seconds
    if ($script:HandOverlayTimer) { $script:HandOverlayTimer.Stop(); $script:HandOverlayTimer = $null }
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromSeconds(30)
    $timer.Add_Tick({ param($src, $e)
            try { $src.Stop() } catch {}
            Hide-HandAlertOverlay
        })
    $script:HandOverlayTimer = $timer
    $timer.Start()

    # Start flashing the Hand Alert button
    try {
        if ($script:HandAlertButtonTimer) { try { $script:HandAlertButtonTimer.Stop(); $script:HandAlertButtonTimer.Dispose() } catch {}; $script:HandAlertButtonTimer = $null }
        $flashTimer = New-Object System.Windows.Forms.Timer
        $flashTimer.Interval = 400
        # Flash phase lives in script scope: a function-local $state is not visible inside the timer's
        # Tick handler (it always read as empty), so the button never actually alternated.
        $script:_handFlashState = $false
        $flashTimer.Add_Tick({
                if (-not $btnHandAlert) { return }
                $script:HandOverlayVisible = $true
                $global:__dummy = $null  # keep closure
                $script:__lastHandFlash = $script:_handFlashState
                if ($script:_handFlashState) {
                    $btnHandAlert.BackColor = [Drawing.Color]::FromArgb(64, 64, 64)
                }
                else {
                    $btnHandAlert.BackColor = [Drawing.Color]::FromArgb(255, 255, 0)
                }
                $script:_handFlashState = -not $script:_handFlashState
            })
        $script:HandAlertButtonTimer = $flashTimer
        $flashTimer.Start()
    }
    catch {}
}

function Hide-HandAlertOverlay {
    $script:_autoHandShown = $false
    if (-not $script:HandOverlayVisible -or -not $script:HandOverlayWindow) { return }

    if ($script:HandOverlayTimer) { $script:HandOverlayTimer.Stop(); $script:HandOverlayTimer = $null }

    if ($script:HandAlertButtonTimer) {
        try { $script:HandAlertButtonTimer.Stop(); $script:HandAlertButtonTimer.Dispose() } catch {}
        $script:HandAlertButtonTimer = $null
    }

    if ($btnHandAlert) {
        try {
            $btnHandAlert.BackColor = [Drawing.Color]::FromArgb(64, 64, 64)
        }
        catch {}
    }

    $window = $script:HandOverlayWindow

    $fadeOut = New-Object System.Windows.Media.Animation.DoubleAnimation
    $fadeOut.From = $window.Opacity
    $fadeOut.To = 0.0
    $fadeOut.Duration = [System.Windows.Duration]::op_Implicit([TimeSpan]::FromMilliseconds(400))
    $fadeOut.Add_Completed({
            try { $script:HandOverlayWindow.Close() } catch {}
            $script:HandOverlayWindow = $null
            $script:HandOverlayVisible = $false
        })
    $window.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fadeOut)
}

function Switch-HandAlertOverlay {
    # Re-entrancy guard: prevents overlapping Show/Hide calls if the hotkey or button fires twice
    # in quick succession (e.g. key-repeat) before the first invocation's synchronous work finishes.
    if ($script:HandAlertToggleBusy) {
        Log "Hand Alert: toggle ignored - already processing a previous toggle"
        return
    }
    $script:HandAlertToggleBusy = $true
    try {
        try {
            $idx = 0
            if ($script:Cfg -and $script:Cfg.Zoom -and $script:Cfg.Zoom.Contains('HandAlertMonitor')) {
                $idx = [int]$script:Cfg.Zoom.HandAlertMonitor
            }
            $scrCount = [System.Windows.Forms.Screen]::AllScreens.Count
            Log ("Hand Alert: toggle requested (selected index={0}, screens={1})" -f $idx, $scrCount)
        }
        catch {}

        if ($script:HandOverlayVisible) { Hide-HandAlertOverlay }
        else { Show-HandAlertOverlay }
    }
    finally {
        $script:HandAlertToggleBusy = $false
    }
}

# ===== Auto Hand Alert =====
# Watches the Zoom Participants list (UI Automation, background STA runspace) and raises the normal
# Hand Alert overlay when a participant newly raises a hand. The overlay's own 30 s timer turns it off.
function Test-AutoHandAlertEnabled {
    try { return [bool]$script:Cfg.Zoom.AutoHandAlert } catch { return $false }
}

function Stop-RunspaceAsync($ps, $rs) {
    # Tears a background PowerShell/runspace down WITHOUT ever blocking the UI thread. A scan can be wedged inside
    # a native UI Automation or socket call, and a plain Dispose()/Close() would wait for that call and freeze the
    # whole app. Idle or finished objects are simply disposed; running ones are told to stop in the background.
    $running = $false
    try { if ($ps -and $ps.InvocationStateInfo.State -eq 'Running') { $running = $true } } catch {}
    $busyRs = $running
    try { if ($rs -and $rs.RunspaceAvailability -ne [System.Management.Automation.Runspaces.RunspaceAvailability]::Available) { $busyRs = $true } } catch {}
    try {
        if ($ps) {
            if ($running) { [void]$ps.BeginStop($null, $null) } else { $ps.Dispose() }
        }
    }
    catch {}
    try {
        if ($rs) {
            if ($busyRs) { $rs.CloseAsync() } else { $rs.Close(); $rs.Dispose() }
        }
    }
    catch {}
}

function Stop-AutoHandScanRunspace {
    $ps = $script:_autoHandPS
    $rs = $script:_autoHandRS
    $script:_autoHandPS = $null
    $script:_autoHandRS = $null
    $script:_autoHandAsync = $null
    $script:_autoHandScanStartedAt = $null
    # Never block the UI thread here: a scan can be wedged inside a native UI Automation call, and a
    # synchronous Dispose()/Close() would wait for that call and freeze the whole app.
    try { if ($ps) { [void]$ps.BeginStop($null, $null) } } catch {}
    try { if ($rs) { $rs.CloseAsync() } } catch {}
}

function Start-AutoHandScan {
    $handScript = {
        param([bool]$WantDiag)
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        try {
            Add-Type -AssemblyName UIAutomationClient -ErrorAction SilentlyContinue
            Add-Type -AssemblyName UIAutomationTypes  -ErrorAction SilentlyContinue

            $root = [System.Windows.Automation.AutomationElement]::RootElement
            $nameProp = [System.Windows.Automation.AutomationElement]::NameProperty
            $typeProp = [System.Windows.Automation.AutomationElement]::ControlTypeProperty

            $listItemCond = New-Object System.Windows.Automation.PropertyCondition($typeProp, [System.Windows.Automation.ControlType]::ListItem)
            $childScope = [System.Windows.Automation.TreeScope]::Children
            $isWaitRow = { param($nm) ($nm -match 'Press Space to admit' -or $nm -match '^Waiting [Rr]oom \(\d+\)') }

            $findZoom = {
                $zw = $null
                try {
                    if (-not ('JwlHandScan.Win' -as [type])) {
                        Add-Type -Namespace JwlHandScan -Name Win -MemberDefinition '[System.Runtime.InteropServices.DllImport("user32.dll", CharSet = System.Runtime.InteropServices.CharSet.Unicode)] public static extern System.IntPtr FindWindow(string cls, string title);'
                    }
                    $zoomHwnd = [JwlHandScan.Win]::FindWindow($null, 'Zoom Meeting')
                    if ($zoomHwnd -ne [System.IntPtr]::Zero) { $zw = [System.Windows.Automation.AutomationElement]::FromHandle($zoomHwnd) }
                }
                catch {}
                if (-not $zw) {
                    # Same lookup the Waiting Room scan uses (the UI Automation name can differ from the Win32 title).
                    $nCond = New-Object System.Windows.Automation.PropertyCondition($nameProp, 'Zoom Meeting')
                    $tCond = New-Object System.Windows.Automation.PropertyCondition($typeProp, [System.Windows.Automation.ControlType]::Window)
                    $zCond = New-Object System.Windows.Automation.AndCondition($nCond, $tCond)
                    $zw = $root.FindFirst([System.Windows.Automation.TreeScope]::Children, $zCond)
                }
                return $zw
            }

            # Searching the whole Zoom window for list rows is the slow part (seconds). The runspace is persistent, so the
            # participants list element found by a full search is remembered and later scans only read its direct rows.
            # A full search is repeated every 15th scan and whenever the remembered list stops answering.
            $global:_jwlHandScanN = 1 + [int]$global:_jwlHandScanN
            $useCached = ($global:_jwlHandList -and (($global:_jwlHandScanN % 15) -ne 0))

            # Cache the Name property with the search so each row is not a separate cross-process call.
            $cr = New-Object System.Windows.Automation.CacheRequest
            $cr.Add($nameProp)
            $names = New-Object System.Collections.Generic.List[string]
            $fast = $false
            $act = $cr.Activate()
            try {
                $items = $null
                if ($useCached) {
                    try {
                        $items = $global:_jwlHandList.FindAll($childScope, $listItemCond)
                        if ($items.Count -eq 0) { $items = $null }
                    }
                    catch { $items = $null }
                    if ($items) { $fast = $true } else { $global:_jwlHandList = $null }
                }
                if (-not $items) {
                    $zoomWin = & $findZoom
                    if (-not $zoomWin) { return @{ WindowFound = $false; ElapsedMs = $sw.ElapsedMilliseconds } }
                    $items = $zoomWin.FindAll([System.Windows.Automation.TreeScope]::Subtree, $listItemCond)
                    $global:_jwlHandList = $null
                    $expected = 0; $firstRow = $null
                    for ($i = 0; $i -lt $items.Count; $i++) {
                        $n = ''
                        try { $n = $items.Item($i).Cached.Name } catch {}
                        if ($n -and -not (& $isWaitRow $n)) { $expected++; if (-not $firstRow) { $firstRow = $items.Item($i) } }
                    }
                    if ($firstRow) {
                        # Remember the list only when its direct rows are exactly the participant rows found by the full search.
                        try {
                            $parent = [System.Windows.Automation.TreeWalker]::ControlViewWalker.GetParent($firstRow)
                            if ($parent) {
                                $direct = $parent.FindAll($childScope, $listItemCond)
                                $got = 0
                                for ($j = 0; $j -lt $direct.Count; $j++) {
                                    $dn = ''
                                    try { $dn = $direct.Item($j).Cached.Name } catch {}
                                    if ($dn -and -not (& $isWaitRow $dn)) { $got++ }
                                }
                                if ($got -eq $expected) { $global:_jwlHandList = $parent }
                            }
                        }
                        catch {}
                    }
                }
                for ($i = 0; $i -lt $items.Count; $i++) {
                    $n = ''
                    try { $n = $items.Item($i).Cached.Name } catch { try { $n = $items.Item($i).Current.Name } catch {} }
                    if (-not [string]::IsNullOrWhiteSpace($n)) { $names.Add($n) }
                }
            }
            finally { $act.Dispose() }

            $hands = New-Object System.Collections.Generic.List[string]
            $sample = New-Object System.Collections.Generic.List[string]
            foreach ($n in $names) {
                # Waiting-room rows are handled by Auto-Admit.
                if ($n -match 'Press Space to admit' -or $n -match '^Waiting [Rr]oom \(\d+\)') { continue }
                # Row text is "Person name, status, status..." - keep only the status part in diagnostics.
                $comma = $n.IndexOf(',')
                $statusPart = if ($comma -ge 0) { $n.Substring($comma) } else { '' }
                if ($WantDiag -and $sample.Count -lt 3) { $sample.Add('<name>' + $statusPart) }
                if ($n -match '\((?:[^)]*,\s*)?me\)') { continue }   # the host's own row
                if ($n -match '(?i)raised hand|hand raised|raise[sd]? (?:their|his|her) hand|lower hand|\u270B') {
                    $hands.Add($(if ($comma -gt 0) { $n.Substring(0, $comma).Trim() } else { $n.Trim() }))
                }
            }

            return @{
                WindowFound    = $true
                Hands          = @($hands)
                Sample         = @($sample)
                TotalListItems = $names.Count
                ElapsedMs      = $sw.ElapsedMilliseconds
            }
        }
        catch { return @{ WindowFound = $false; Error = "$_"; ElapsedMs = $sw.ElapsedMilliseconds } }
    }

    $rs = $script:_autoHandRS
    if (-not $rs -or $rs.RunspaceStateInfo.State -ne 'Opened') {
        $rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $rs.ApartmentState = 'STA'
        $rs.ThreadOptions = 'ReuseThread'
        $rs.Open()
        $script:_autoHandRS = $rs
    }
    $ps = [System.Management.Automation.PowerShell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript($handScript).AddArgument((-not $script:_autoHandDiagLogged))
    $script:_autoHandPS = $ps
    $script:_autoHandScanStartedAt = Get-Date
    $script:_autoHandAsync = $ps.BeginInvoke()
}

function Complete-AutoHandScan {
    $result = $null
    try {
        $out = $script:_autoHandPS.EndInvoke($script:_autoHandAsync)
        if ($out -and $out.Count -gt 0) { $result = $out[0] }
    }
    catch {}
    try { $script:_autoHandPS.Dispose() } catch {}
    $script:_autoHandPS = $null
    $script:_autoHandAsync = $null
    $script:_autoHandScanStartedAt = $null

    if (-not $result -or -not $result['WindowFound']) {
        $err = if ($result -and $result['Error']) { $result['Error'] } else { 'zoom_window_not_found' }
        Write-ThrottledLog 'AutoHandScan' "Auto Hand Alert: no result ($err)" 30
        return
    }

    if (-not $script:_autoHandDiagLogged) {
        $script:_autoHandDiagLogged = $true
        Log "Auto Hand Alert: first scan read $($result['TotalListItems']) list rows in $($result['ElapsedMs']) ms"
        foreach ($s in @($result['Sample'])) { Log "Auto Hand Alert: sample row format = '$s'" }
        if ([int]$result['TotalListItems'] -eq 0) { Log 'Auto Hand Alert: no participant rows found - is the Zoom Participants panel open?' }
    }

    $current = @{}
    foreach ($h in @($result['Hands'])) { $current[(Get-NormalizedZoomName $h)] = $h }
    $newNames = @()
    foreach ($k in $current.Keys) { if (-not $script:_autoHandPrev.ContainsKey($k)) { $newNames += $current[$k] } }
    $prevCount = $script:_autoHandPrev.Count
    $script:_autoHandPrev = $current

    if ($newNames.Count -gt 0) {
        foreach ($n in $newNames) { Log "Auto Hand Alert: raised hand detected - '$n'" }
        if (-not $script:HandOverlayVisible) {
            Show-HandAlertOverlay
            $script:_autoHandShown = $true
        }
        elseif ($script:HandOverlayTimer) {
            # Alert already up: a new hand gives it a fresh 30 seconds.
            try { $script:HandOverlayTimer.Stop(); $script:HandOverlayTimer.Start() } catch {}
            Log 'Auto Hand Alert: new hand while the alert is up - timer restarted'
        }
    }
    elseif ($current.Count -eq 0 -and $prevCount -gt 0 -and $script:HandOverlayVisible -and $script:_autoHandShown) {
        # Every hand is down again: close the alert it opened without waiting for the 30 s timer.
        Log 'Auto Hand Alert: all hands lowered - closing the alert'
        Hide-HandAlertOverlay
    }
}

function Start-AutoHandAlertMonitor {
    if (-not (Test-AutoHandAlertEnabled)) { return }
    if ($script:_autoHandTimer -and -not $script:_autoHandTimer.IsDisposed -and $script:_autoHandTimer.Enabled) { return }
    $script:_autoHandDiagLogged = $false
    $script:_autoHandPrev = @{}
    $script:_autoHandNextAt = [DateTime]::MinValue
    $script:_autoHandTimer = New-Object System.Windows.Forms.Timer
    $script:_autoHandTimer.Interval = 500
    $script:_autoHandTimer.Add_Tick({
            try {
                if ($script:ShuttingDown -or -not (Test-AutoHandAlertEnabled)) { Stop-AutoHandAlertMonitor; return }
                if ($script:_autoHandAsync) {
                    if ($script:_autoHandAsync.IsCompleted) {
                        Complete-AutoHandScan
                        $script:_autoHandNextAt = (Get-Date).AddSeconds(1)
                    }
                    elseif ($script:_autoHandScanStartedAt -and ((Get-Date) - $script:_autoHandScanStartedAt).TotalSeconds -gt 45) {
                        Log 'Auto Hand Alert: scan stuck for 45 s - abandoning it and starting a fresh one'
                        Stop-AutoHandScanRunspace
                    }
                    return
                }
                if ((Get-Date) -lt $script:_autoHandNextAt) { return }
                # Keep the UI thread free of cross-process UI Automation traffic while the Settings dialog is being built.
                if ($script:_settingsDialogBusy -or (Test-ZoomInputBusy)) { return }
                if (-not $script:ZoomInMeeting) { $script:_autoHandPrev = @{}; return }
                if (-not $script:UIAutomationAvailable) { return }
                Start-AutoHandScan
            }
            catch { Write-ThrottledLog 'AutoHandTick' "Auto Hand Alert: tick error - $_" 30 }
        })
    $script:_autoHandTimer.Start()
    Log 'Auto Hand Alert: monitor started'
}

function Stop-AutoHandAlertMonitor {
    try { if ($script:_autoHandTimer) { $script:_autoHandTimer.Stop(); $script:_autoHandTimer.Dispose() } } catch {}
    $script:_autoHandTimer = $null
    Stop-AutoHandScanRunspace
    $script:_autoHandPrev = @{}
}

# ===== WPF shell preview (Phase 2 scaffold, WPF-migration) =====
# A standalone WPF window, separate from and not replacing $script:form, used to prove out the
# Phase 1 abstractions (theme-change callbacks, canonical theme colors) with a *real* WPF window
# before any production UI is touched. Mirrors the Hand Alert window's proven pattern of an
# independent WPF Window coexisting with the WinForms shell (see WPF-Migration-Planning-Audit.md
# section 11). Does NOT assign $script:MainWindow - Invoke-OnUI and friends keep routing through
# $script:form exactly as before, so this preview carries zero production risk. Launch with
# Ctrl+Alt+Shift+P while the main window has focus; close the preview window to dismiss it.
$script:_wpfShellLoaded = $false
$script:_wpfShellWindow = $null
$script:_wpfShellClockTimer = $null
$script:_wpfShellVCamFlashTimer = $null
$script:_wpfShellCutTimer = $null
$script:_wpfShellVCamFlashOn = $false
$script:_wpfShellThemeCallbackRegistered = $false
$script:_wpfShellFormsIntegrationLoaded = $false
$script:_wpfShellCamActive = $false
$script:_wpfShellCamLibVLC = $null
$script:_wpfShellCamMediaPlayer = $null
$script:_wpfShellCamPanel = $null
$script:_wpfShellPtzButtons = New-Object System.Collections.Generic.List[System.Windows.Forms.Button]
$script:_wpfShellPtzHoverTimer = $null
$script:_wpfShellHintLabel = $null
$script:_wpfShellUiScale = 1.0         # current S/M/L factor applied to the WPF window (1.0 / 1.25 / 1.5)
$script:_wpfShellOverlay = $null       # borderless window holding the clock + top-right buttons (sits above the video)
$script:_wpfShellVideoPanel = $null
$script:_wpfShellVideoShiftDip = 10    # picture shifted left by this many px (96-DPI units) - raise/lower to fine-tune centring
$script:_wpfShellBase = $null          # window chrome + content size at 100%, measured once after the window opens
$script:_wpfShellAfTimer = $null
$script:_wpfShellAfOverlay = $null
$script:_wpfShellAfSig = ''
$script:_wpfShellAfCtls = New-Object System.Collections.Generic.List[System.Windows.Forms.Control]
$script:_wpfRow3Sig = @{}
$script:_wpfMainCtlCache = @{}
$script:_wpfRow4Tick = 0
$script:_wpfShellMenuAtCursor = $false
$script:_wpfAfDragging = $false
$script:_wpfAfResizing = -1
$script:_wpfAfDragOff = $null
$script:_wpfAfResizeOrig = $null
$script:_wpfAfWasDown = $false

function Initialize-WpfShellRuntime {
    if ($script:_wpfShellLoaded) { return $true }
    try {
        Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase
        $script:_wpfShellLoaded = $true
        return $true
    }
    catch {
        try { Log "WPF shell preview: failed to load WPF assemblies: $_" } catch {}
        return $false
    }
}

function Initialize-WpfShellFormsIntegration {
    # WindowsFormsHost/WindowsFormsIntegration is the interop bridge documented back in Phase 1's
    # Get-CameraPreviewHostHandle comment: LibVLC cannot render into a WPF visual tree directly,
    # so a WinForms Panel hosted inside a WPF window is the real mechanism a future WPF shell
    # would use for the camera preview.
    if ($script:_wpfShellFormsIntegrationLoaded) { return $true }
    try {
        Add-Type -AssemblyName WindowsFormsIntegration, System.Windows.Forms
        $script:_wpfShellFormsIntegrationLoaded = $true
        return $true
    }
    catch {
        try { Log "WPF shell preview: failed to load WindowsFormsIntegration: $_" } catch {}
        return $false
    }
}

function ConvertTo-WpfBrush([System.Drawing.Color]$Color) {
    # Reuses the exact same canonical palette as the WinForms theme ($DarkTheme/$LightTheme,
    # via Get-ThemeKit) instead of inventing a separate WPF-only color set.
    $mediaColor = [System.Windows.Media.Color]::FromArgb($Color.A, $Color.R, $Color.G, $Color.B)
    return New-Object System.Windows.Media.SolidColorBrush $mediaColor
}

function Get-WpfShellPxScale {
    # Pixel factor for the native WinForms controls inside the shell: screen DPI x the S/M/L factor
    # (WPF itself scales through its LayoutTransform, but WindowsFormsHost children don't follow it).
    $d = 1.0
    try { $d = [double](Get-DpiScaleFactor) } catch {}
    $u = 1.0
    try { if ($script:_wpfShellUiScale -gt 0) { $u = [double]$script:_wpfShellUiScale } } catch {}
    return ($d * $u)
}

function Initialize-WpfShellScaleBase {
    # Called once right after the window is shown (still at 100%): remembers the chrome and content size.
    $w = $script:_wpfShellWindow
    if (-not $w) { return }
    try {
        $w.UpdateLayout()
        $c = $w.Content
        $script:_wpfShellBase = @{
            ChromeW = [double]($w.ActualWidth - $c.ActualWidth); ChromeH = [double]($w.ActualHeight - $c.ActualHeight)
            ContentW = [double]$c.ActualWidth; ContentH = [double]$c.ActualHeight
        }
    }
    catch {}
}

function Set-WpfShellScale {
    # Follows the main app's S/M/L level ($script:_currentUIScale = 1.0 / 1.25 / 1.5): scales the whole WPF
    # layout and grows/shrinks the window to match. The native camera panel is rebuilt so its buttons re-fit.
    $w = $script:_wpfShellWindow
    if (-not $w -or -not $script:_wpfShellBase) { return }
    try {
        $f = 1.0
        try { $f = [double]$script:_currentUIScale } catch {}
        if ($f -lt 1.0) { $f = 1.0 }
        if ([math]::Abs($f - [double]$script:_wpfShellUiScale) -lt 0.001) { return }
        $script:_wpfShellUiScale = $f
        $b = $script:_wpfShellBase
        $w.Content.LayoutTransform = New-Object System.Windows.Media.ScaleTransform $f, $f
        $w.Width = $b.ChromeW + $b.ContentW * $f
        $w.Height = $b.ChromeH + $b.ContentH * $f
        # Growing happens from the top-left corner, so pull the window back inside the monitor it is on.
        try {
            $d = [double](Get-DpiScaleFactor)
            $px = [int]($w.Left * $d); $py = [int]($w.Top * $d)
            $pw = [int]($w.Width * $d); $ph = [int]($w.Height * $d)
            $wa = [System.Windows.Forms.Screen]::FromRectangle((New-Object System.Drawing.Rectangle $px, $py, $pw, $ph)).WorkingArea
            $nx = $px; $ny = $py
            if ($nx + $pw -gt $wa.Right) { $nx = $wa.Right - $pw }
            if ($ny + $ph -gt $wa.Bottom) { $ny = $wa.Bottom - $ph }
            if ($nx -lt $wa.Left) { $nx = $wa.Left }
            if ($ny -lt $wa.Top) { $ny = $wa.Top }
            if ($nx -ne $px) { $w.Left = $nx / $d }
            if ($ny -ne $py) { $w.Top = $ny / $d }
        }
        catch {}
        try { Update-WpfShellScaleButtons } catch {}
        if ($script:_wpfShellCamActive) {
            Stop-WpfShellCameraPreview
            $rt = New-Object System.Windows.Forms.Timer
            $rt.Interval = 400
            $rt.Add_Tick({
                    param($tmr, $tmrArgs)
                    $tmr.Stop(); $tmr.Dispose()
                    try { if ($script:_wpfShellWindow -and -not $script:_wpfShellCamActive) { Start-WpfShellCameraPreview } } catch {}
                })
            $rt.Start()
        }
        Sync-LegacyWindowToShell
        Sync-WpfShellOverlay
    }
    catch { try { Log "WPF shell preview: scale change failed: $_" } catch {} }
}

function Set-WpfShellTitleBarTheme {
    # Makes the native title bar follow the app theme (dark bar in dark mode) via DWM:
    # immersive dark mode (Win10 20H1+), plus caption/text colours that match the panel (Win11).
    if (-not $script:_wpfShellWindow) { return }
    try {
        if (-not ('Win32.Dwm' -as [type])) { return }
        $h = (New-Object System.Windows.Interop.WindowInteropHelper $script:_wpfShellWindow).Handle
        if ($h -eq [IntPtr]::Zero) { return }
        $dark = Test-IsDarkTheme
        $kit = Get-ThemeKit $dark
        $v = if ($dark) { 1 } else { 0 }
        [void][Win32.Dwm]::DwmSetWindowAttribute($h, 20, [ref]$v, 4)
        $cap = [int]($kit.Panel.R + ($kit.Panel.G * 256) + ($kit.Panel.B * 65536))
        [void][Win32.Dwm]::DwmSetWindowAttribute($h, 35, [ref]$cap, 4)
        $txt = [int]($kit.Text.R + ($kit.Text.G * 256) + ($kit.Text.B * 65536))
        [void][Win32.Dwm]::DwmSetWindowAttribute($h, 36, [ref]$txt, 4)
    }
    catch {}
}

function Update-WpfShellTheme {
    if (-not $script:_wpfShellWindow) { return }
    try {
        $dark = Test-IsDarkTheme
        $kit = Get-ThemeKit $dark
        $w = $script:_wpfShellWindow
        $w.Background = ConvertTo-WpfBrush $kit.Back
        $topBar = $w.FindName('TopBar')
        if ($topBar) { $topBar.Background = ConvertTo-WpfBrush $kit.Panel }
        $contentArea = $w.FindName('ContentArea')
        if ($contentArea) { $contentArea.Background = ConvertTo-WpfBrush $kit.Back }
        foreach ($name in @('ScenePickerLabel', 'ProgramLabel')) {
            $tb = $w.FindName($name)
            if ($tb) { $tb.Foreground = ConvertTo-WpfBrush $kit.Text }
        }
        $statusBar = $w.FindName('StatusBar')
        if ($statusBar) { $statusBar.Background = ConvertTo-WpfBrush $kit.Panel }
        $nextMeetingLabel = $w.FindName('NextMeetingLabel')
        if ($nextMeetingLabel) { $nextMeetingLabel.Foreground = ConvertTo-WpfBrush $kit.Text }
        $themeToggleBtn = $w.FindName('ThemeToggleBtn')
        $sunIcon = $w.FindName('SunIcon')
        $moonIcon = $w.FindName('MoonIcon')
        if ($sunIcon) { $sunIcon.Visibility = if ($dark) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed } }
        if ($moonIcon) { $moonIcon.Visibility = if ($dark) { [System.Windows.Visibility]::Collapsed } else { [System.Windows.Visibility]::Visible } }
    }
    catch {}
    Update-WpfShellStatusBar
    Update-WpfShellScaleButtons
    Update-WpfShellScenePicker
    Set-WpfShellTitleBarTheme
}

function Get-WpfShellSavedGeometry {
    # Returns $null if there's no usable saved geometry, or a hashtable of clamped Left/Top/
    # Width/Height (WPF DIPs) if the saved position still falls on a currently connected monitor.
    # Mirrors Get-OnScreenPoint's off-screen safety check so a saved position from a monitor
    # that's since been unplugged/reconfigured can't strand the preview window off-screen.
    try {
        $saved = $script:Cfg.UI.WpfShellPreview
        if (-not $saved) { return $null }
        $x = [double]$saved.X; $y = [double]$saved.Y
        $width = [double]$saved.Width; $height = [double]$saved.Height
        if ($width -lt 300 -or $height -lt 200) { return $null }
        $dpi = Get-DpiScaleFactor
        $physX = $x * $dpi; $physY = $y * $dpi
        $onScreen = $false
        foreach ($screen in [System.Windows.Forms.Screen]::AllScreens) {
            $r = $screen.WorkingArea
            if ($physX -ge $r.Left -and $physX -le ($r.Right - 50) -and $physY -ge $r.Top -and $physY -le ($r.Bottom - 50)) {
                $onScreen = $true; break
            }
        }
        try { Log "WPF shell position: saved X=$x Y=$y W=$width H=$height dpi=$dpi onScreen=$onScreen screens=$(([System.Windows.Forms.Screen]::AllScreens | ForEach-Object { $_.DeviceName + ' ' + $_.WorkingArea }) -join ' | ')" } catch {}
        if (-not $onScreen) { return $null }
        return @{ Left = $x; Top = $y; Width = $width; Height = $height }
    }
    catch { return $null }
}

function Save-WpfShellWindowGeometry {
    if (-not $script:_wpfShellWindow) { return }
    try {
        $w = $script:_wpfShellWindow
        # Don't persist minimized/maximized bounds - only a normal, user-sized/positioned window.
        if ($w.WindowState -ne [System.Windows.WindowState]::Normal) { return }
        if (-not $script:Cfg.UI.Contains('WpfShellPreview')) { $script:Cfg.UI.WpfShellPreview = @{} }
        $script:Cfg.UI.WpfShellPreview.X = [double]$w.Left
        $script:Cfg.UI.WpfShellPreview.Y = [double]$w.Top
        $script:Cfg.UI.WpfShellPreview.Width = [double]$w.Width
        $script:Cfg.UI.WpfShellPreview.Height = [double]$w.Height
        try { Log "WPF shell position: saving X=$($w.Left) Y=$($w.Top) W=$($w.Width) H=$($w.Height)" } catch {}
        Save-Settings | Out-Null
    }
    catch { try { Log "WPF shell preview: failed to save window geometry: $_" } catch {} }
}

function Update-WpfShellScaleButtons {
    # The single scale button shows the main app's real, live $script:_uiScaleLevel as S/M/L;
    # the hover flyout offers the other two levels and drives the same Set-UIScale function the
    # main app's own S/M/L control uses, so this preview and the main window always agree.
    if (-not $script:_wpfShellWindow) { return }
    try {
        $w = $script:_wpfShellWindow
        $activeLevel = if ($null -ne $script:_uiScaleLevel) { [int]$script:_uiScaleLevel } else { 0 }
        $letters = @('S', 'M', 'L')
        $dark = Test-IsDarkTheme
        $kit = Get-ThemeKit $dark
        $accent = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0, 120, 215))
        $main = $w.FindName('ScaleBtn')
        if ($main) {
            $main.Content = $letters[$activeLevel]
            $main.Background = $accent
            $main.Foreground = [System.Windows.Media.Brushes]::White
        }
        $popupBorder = $w.FindName('ScalePopupBorder')
        if ($popupBorder) { $popupBorder.Background = ConvertTo-WpfBrush $kit.Back }
        $others = @(0..2 | Where-Object { $_ -ne $activeLevel })
        $optNames = @('ScaleOptA', 'ScaleOptB')
        for ($i = 0; $i -lt 2; $i++) {
            $opt = $w.FindName($optNames[$i])
            if (-not $opt) { continue }
            $opt.Content = $letters[$others[$i]]
            $opt.Tag = [int]$others[$i]
            $opt.Background = ConvertTo-WpfBrush $kit.Panel
            $opt.Foreground = ConvertTo-WpfBrush $kit.Text
        }
    }
    catch {}
}

function Set-WpfShellScaleLevel([int]$level) {
    # Same sequence as the main app's own S/M/L menu: apply, remember, save.
    Set-UIScale $level
    $script:Cfg.UI.ScaleLevel = $level
    Save-Settings | Out-Null
    Update-WpfShellScaleButtons
}

# ---- OBS / JW Library process helpers (start buttons, flashing hints, Auto Toggle guard) ----
$script:_procRunCache = @{}
$script:_jwlAppId = $null

function Test-ProcessRunningCached([string]$NamePattern, [int]$MaxAgeMs = 1500) {
    # Process lookups are cached for a moment so 1 s status ticks and 150 ms pollers stay cheap.
    $c = $script:_procRunCache[$NamePattern]
    if ($c -and (([DateTime]::UtcNow - $c.T).TotalMilliseconds -lt $MaxAgeMs)) { return [bool]$c.V }
    $found = $false
    try {
        foreach ($p in [System.Diagnostics.Process]::GetProcesses()) {
            try { if (-not $found -and $p.ProcessName -like $NamePattern) { $found = $true } } catch {}
            try { $p.Dispose() } catch {}
        }
    }
    catch {}
    $script:_procRunCache[$NamePattern] = @{ T = [DateTime]::UtcNow; V = $found }
    return $found
}

function Test-ObsHostIsLocal {
    $h = ''
    try { $h = [string]$script:ObsWsHost } catch {}
    return ([string]::IsNullOrWhiteSpace($h) -or $h -in @('127.0.0.1', 'localhost', '::1', '[::1]', '0.0.0.0', $env:COMPUTERNAME))
}

function Test-ObsProcessRunning([int]$MaxAgeMs = 1500) {
    # OBS on another PC cannot be checked (or started) from here, so it counts as "present".
    if (-not (Test-ObsHostIsLocal)) { return $true }
    return (Test-ProcessRunningCached 'obs64' $MaxAgeMs)
}

function Test-JwlProcessRunning([int]$MaxAgeMs = 1500) {
    return (Test-ProcessRunningCached 'JWLibrary*' $MaxAgeMs)
}

function Find-ObsExe {
    $cands = New-Object System.Collections.ArrayList
    foreach ($rk in 'HKLM:\SOFTWARE\OBS Studio', 'HKLM:\SOFTWARE\WOW6432Node\OBS Studio', 'HKCU:\SOFTWARE\OBS Studio') {
        try { $dir = (Get-Item $rk -ErrorAction Stop).GetValue(''); if ($dir) { [void]$cands.Add((Join-Path ([string]$dir) 'bin\64bit\obs64.exe')) } } catch {}
    }
    foreach ($pf in @($env:ProgramFiles, ${env:ProgramFiles(x86)})) {
        if ($pf) { [void]$cands.Add((Join-Path $pf 'obs-studio\bin\64bit\obs64.exe')) }
    }
    foreach ($c in $cands) { if ($c -and (Test-Path -LiteralPath $c)) { return $c } }
    return $null
}

function Start-ObsApp {
    # Launches OBS Studio (its working directory must be the bin\64bit folder). The app's 2 s auto-connect then picks it up.
    try {
        if (Test-ObsProcessRunning -MaxAgeMs 0) { return $true }
        $exe = Find-ObsExe
        if (-not $exe) {
            Log "OBS: obs64.exe was not found - start OBS manually"
            [void](Show-AppMessageBox "OBS Studio could not be found on this PC.`r`n`r`nStart OBS manually." 'OBS' ([System.Windows.Forms.MessageBoxButtons]::OK) ([System.Windows.Forms.MessageBoxIcon]::Warning))
            return $false
        }
        Start-Process -FilePath $exe -WorkingDirectory (Split-Path -Parent $exe)
        Log "OBS: started $exe"
        $script:_procRunCache.Remove('obs64')
        return $true
    }
    catch { Log "OBS: could not start - $_"; return $false }
}

function Get-JwlAppId {
    if ($script:_jwlAppId) { return $script:_jwlAppId }
    $queried = $false
    try {
        $apps = @(Get-StartApps -ErrorAction Stop | Where-Object { $_.Name -like 'JW Library*' })
        $queried = $true
        $pick = $apps | Where-Object { $_.Name -eq 'JW Library' } | Select-Object -First 1
        if (-not $pick) { $pick = $apps | Select-Object -First 1 }
        if ($pick) { $script:_jwlAppId = [string]$pick.AppID }
    }
    catch {}
    # Store app id of the regular JW Library, used only when the Start-menu query itself was unavailable
    if (-not $script:_jwlAppId -and -not $queried) { $script:_jwlAppId = 'WatchtowerBibleandTractSo.45909CDBADF3C_5rz59y55nfz3e!App' }
    return $script:_jwlAppId
}

function Start-JwlApp {
    # JW Library is a Microsoft Store app, so it is launched through its app id (this also brings a running instance forward).
    try {
        $id = Get-JwlAppId
        if (-not $id) {
            Log "JW Library: not found in the Start menu"
            [void](Show-AppMessageBox "JW Library is not installed on this PC." 'JW Library' ([System.Windows.Forms.MessageBoxButtons]::OK) ([System.Windows.Forms.MessageBoxIcon]::Warning))
            return $false
        }
        Start-Process -FilePath 'explorer.exe' -ArgumentList "shell:AppsFolder\$id"
        Log "JW Library: started"
        $script:_procRunCache.Remove('JWLibrary*')
        return $true
    }
    catch { Log "JW Library: could not start - $_"; return $false }
}

# ---- Start menu (red power button in the new UI) ----
# Starts the programs ticked in Settings one after another with a pause in between (so the PC is never overloaded)
# and always finishes with Zoom. A small always-on-top window and the status bar show the progress.
$script:_startMenu = $null

function Find-OnlyMExe {
    $saved = [string]$script:Cfg.StartMenu.OnlyMExePath
    if ($saved -and (Test-Path -LiteralPath $saved)) { return $saved }
    $cands = @("$env:ProgramFiles\OnlyM\OnlyM.exe", "${env:ProgramFiles(x86)}\OnlyM\OnlyM.exe", "$env:LOCALAPPDATA\Programs\OnlyM\OnlyM.exe", "$env:LOCALAPPDATA\OnlyM\OnlyM.exe")
    foreach ($c in $cands) { if ($c -and (Test-Path -LiteralPath $c)) { return $c } }
    try {
        foreach ($rk in 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall', 'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall') {
            foreach ($k in (Get-ChildItem $rk -ErrorAction SilentlyContinue)) {
                $ip = Get-ItemProperty $k.PSPath -ErrorAction SilentlyContinue
                if ($ip -and [string]$ip.DisplayName -match '^OnlyM' -and $ip.InstallLocation) {
                    $cand = Join-Path ([string]$ip.InstallLocation) 'OnlyM.exe'
                    if (Test-Path -LiteralPath $cand) { return $cand }
                }
            }
        }
    }
    catch {}
    return $null
}

function Get-OnlyMProcess {
    try { return (Get-Process -Name 'OnlyM' -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne [IntPtr]::Zero } | Select-Object -First 1) } catch { return $null }
}

function Show-StartMenuProgressForm {
    try {
        $f = New-Object System.Windows.Forms.Form
        $f.Text = 'Starting programs'
        $f.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
        $f.ControlBox = $false
        $f.MinimizeBox = $false; $f.MaximizeBox = $false
        $f.ShowInTaskbar = $false
        $f.TopMost = $true
        $f.StartPosition = [System.Windows.Forms.FormStartPosition]::CenterScreen
        $f.ClientSize = Sz 470 270
        $f.BackColor = [System.Drawing.Color]::FromArgb(36, 36, 36)
        $f.ForeColor = [System.Drawing.Color]::White

        $title = New-Object System.Windows.Forms.Label
        $title.Text = "Please be patient - wait until all programs are loaded!"
        $title.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        $title.ForeColor = [System.Drawing.Color]::FromArgb(255, 170, 40)
        $title.Location = Pt 16 14
        $title.Size = Sz 438 44
        $f.Controls.Add($title)

        $steps = New-Object System.Windows.Forms.Label
        $steps.Font = New-Object System.Drawing.Font('Segoe UI', 10)
        $steps.Location = Pt 16 66
        $steps.Size = Sz 438 120
        $f.Controls.Add($steps)

        $bar = New-Object System.Windows.Forms.ProgressBar
        $bar.Location = Pt 16 196
        $bar.Size = Sz 438 16
        $bar.Minimum = 0; $bar.Maximum = 100
        $f.Controls.Add($bar)

        $btnCancel = New-Object System.Windows.Forms.Button
        $btnCancel.Text = 'Cancel'
        $btnCancel.Size = Sz 90 28
        $btnCancel.Location = Pt 364 228
        $btnCancel.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
        $btnCancel.BackColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
        $btnCancel.ForeColor = [System.Drawing.Color]::White
        $btnCancel.Add_Click({ try { $script:_startMenu.Cancel = $true } catch {} })
        $f.Controls.Add($btnCancel)

        $f.Show()
        $f.Refresh()
        return @{ Form = $f; Steps = $steps; Bar = $bar }
    }
    catch { Log "Start menu: progress window failed - $_"; return $null }
}

function Update-StartMenuProgress {
    $s = $script:_startMenu
    if (-not $s) { return }
    try {
        $glyph = @{ pending = [string][char]0x25CB; run = [string][char]0x2026; ok = [string][char]0x2713; fail = [string][char]0x2717; skip = [string][char]0x2013 }
        $lines = New-Object System.Collections.Generic.List[string]
        $done = 0
        $current = $null
        foreach ($st in $s.Steps) {
            $note = if ($st.Note) { "  ($($st.Note))" } else { '' }
            [void]$lines.Add("$($glyph[$st.State])  $($st.Name)$note")
            if ($st.State -in @('ok', 'fail', 'skip')) { $done++ }
            if ($st.State -eq 'run') { $current = $st }
        }
        $s.Text = if ($current) { "Please wait - starting $($current.Name)$(if ($current.Note) { ' - ' + $current.Note }) ($($done + 1)/$($s.Steps.Count))" } else { 'Please wait until all programs are loaded...' }
        $p = $s.Progress
        if ($p -and $p.Form -and -not $p.Form.IsDisposed) {
            $p.Steps.Text = ($lines -join "`r`n")
            $p.Bar.Value = [int][math]::Min(100, [math]::Round(100 * $done / [math]::Max(1, $s.Steps.Count)))
            $p.Form.Refresh()
        }
        [void](Update-WpfShellStartupLabel)
    }
    catch {}
}

function Set-StartMenuStep($step, [string]$state, [string]$note = '') {
    $step.State = $state
    $step.Note = $note
    Update-StartMenuProgress
    if ($state -eq 'run') { Log "Start menu: $($step.Name) - $note" }
    elseif ($state -in @('ok', 'fail', 'skip')) { Log "Start menu: $($step.Name) - $state$(if ($note) { ' (' + $note + ')' })" }
}

function Update-StartMenuEarlyStatus {
    # Ticks OnlyT / OnlyM off as soon as they are running (they are launched while JW Library is still loading).
    $s = $script:_startMenu
    if (-not $s) { return }
    if (([DateTime]::UtcNow - [DateTime]$s.EarlyCheckAt).TotalMilliseconds -lt 700) { return }
    $s.EarlyCheckAt = [DateTime]::UtcNow
    foreach ($st in $s.Steps) {
        if ($st.Key -notin @('OnlyT', 'OnlyM') -or -not $st.Launched -or $st.State -ne 'pending') { continue }
        if (Test-StartMenuAppRunning $st.Key) { Set-StartMenuStep $st 'ok' }
    }
}

# Waits while keeping the window alive; returns $false when the user pressed Cancel.
function Wait-StartMenu([double]$Seconds) {
    $deadline = (Get-Date).AddSeconds($Seconds)
    while ((Get-Date) -lt $deadline -and -not $script:ShuttingDown) {
        if ($script:_startMenu.Cancel) { return $false }
        Update-StartMenuEarlyStatus
        Wait-UiPumped 250
    }
    return (-not $script:_startMenu.Cancel -and -not $script:ShuttingDown)
}

function Invoke-StartMenuObs($step) {
    if (-not (Test-ObsProcessRunning -MaxAgeMs 0)) {
        if (-not (Find-ObsExe)) { Set-StartMenuStep $step 'fail' 'obs64.exe not found'; return }
        Set-StartMenuStep $step 'run' 'opening OBS'
        [void](Start-ObsApp)
    }
    Set-StartMenuStep $step 'run' 'waiting for OBS to connect'
    $deadline = (Get-Date).AddSeconds(90)
    while (-not $script:ObsConnected -and (Get-Date) -lt $deadline) {
        if (-not (Wait-StartMenu 1)) { Set-StartMenuStep $step 'skip' 'cancelled'; return }
    }
    if (-not $script:ObsConnected) { Set-StartMenuStep $step 'fail' 'OBS did not connect'; return }
    Set-StartMenuStep $step 'run' 'starting Virtual Camera'
    if (-not (Wait-StartMenu 3)) { Set-StartMenuStep $step 'skip' 'cancelled'; return }
    [void](Sync-ObsVirtualCamStatus -Retries 3)
    if (-not $script:VirtualCameraStatus) {
        try { [void](Invoke-ObsRequest "StartVirtualCam" @{}) } catch { Log "Start menu: V-Cam start failed - $_" }
        [void](Wait-StartMenu 2)
        [void](Sync-ObsVirtualCamStatus -Retries 3)
    }
    if ($script:VirtualCameraStatus) { Set-StartMenuStep $step 'ok' 'Virtual Camera on' }
    else { Set-StartMenuStep $step 'fail' 'OBS is open but the Virtual Camera did not start' }
}

function Click-JwlNavTabReal([string]$tabName) {
    # Brings JW Library to the front and clicks the nav tab with a real mouse click (cursor is put back afterwards).
    # This app's own always-on-top windows are moved out of the way for the click if they cover the tab.
    # $script:_jwlClickWhy tells why a click was not possible (for the log).
    $script:_jwlClickWhy = ''
    $jwl = Get-JwlMainWindow
    if (-not $jwl) { $script:_jwlClickWhy = 'JW Library window not found'; return $false }
    $tab = Find-JwlToggleByName $jwl $tabName
    if (-not $tab) { $script:_jwlClickWhy = "'$tabName' tab not shown yet (JW Library still loading)"; return $false }
    $shell = $script:_wpfShellWindow
    $shellWasTop = $false
    $progForm = $null
    try { $progForm = $script:_startMenu.Progress.Form } catch {}
    $progWasVisible = $false
    try {
        try { [Win32JWL]::ForceSetForeground([IntPtr][int]$jwl.Current.NativeWindowHandle) } catch {}
        Wait-UiPumped 400
        $r = $tab.Current.BoundingRectangle
        if ($r.IsEmpty) { $script:_jwlClickWhy = "'$tabName' tab has no position on screen"; return $false }
        $cx = [int]($r.X + $r.Width / 2); $cy = [int]($r.Y + $r.Height / 2)
        if ($progForm -and -not $progForm.IsDisposed -and $progForm.Visible -and $progForm.Bounds.Contains($cx, $cy)) { $progWasVisible = $true; $progForm.Hide() }
        # only step aside when the shell really covers the tab
        try {
            if ($shell -and $shell.Topmost) {
                $sh = (New-Object System.Windows.Interop.WindowInteropHelper $shell).Handle
                $sr = New-Object OtWin+RECT
                if ([OtWin]::GetWindowRect($sh, [ref]$sr) -and $cx -ge $sr.Left -and $cx -le $sr.Right -and $cy -ge $sr.Top -and $cy -le $sr.Bottom) {
                    $shellWasTop = $true; $shell.Topmost = $false
                }
            }
        }
        catch {}
        Wait-UiPumped 200
        [Win32JWL]::ClickAtAndRestore($cx, $cy)
        Wait-UiPumped 300
        return $true
    }
    catch { Log "Start menu: clicking '$tabName' failed - $_"; return $false }
    finally {
        try {
            if ($shellWasTop) {
                $shell.Topmost = $true
                Restore-WpfShellOwnedWindows
            }
        }
        catch {}
        try { if ($progWasVisible -and -not $progForm.IsDisposed) { $progForm.Show() } } catch {}
    }
}

function Invoke-StartMenuJwl($step) {
    if (-not (Get-JwlAppId)) { Set-StartMenuStep $step 'fail' 'JW Library is not installed'; return }
    $maxTries = 3
    for ($try = 1; $try -le $maxTries; $try++) {
        Set-StartMenuStep $step 'run' "opening JW Library, try $try/$maxTries"
        [void](Start-JwlApp)
        # JW Library often crashes while it starts: give it 15 s, then try again (3 tries in total)
        $opened = $false
        $deadline = (Get-Date).AddSeconds(15)
        while ((Get-Date) -lt $deadline) {
            if ((Test-JwlProcessRunning -MaxAgeMs 0) -and (Get-JwlMainWindow)) { $opened = $true; break }
            if (-not (Wait-StartMenu 1)) { Set-StartMenuStep $step 'skip' 'cancelled'; return }
        }
        if (-not $opened) { Log "Start menu: JW Library did not open within 15 s (try $try/$maxTries)"; continue }
        if (-not [bool]$script:Cfg.StartMenu.JwlMeetings) { Set-StartMenuStep $step 'ok' 'open'; return }

        Set-StartMenuStep $step 'run' 'going to Meetings'
        if (-not (Wait-StartMenu 4)) { Set-StartMenuStep $step 'skip' 'cancelled'; return }
        # The tab only gets highlighted by UI Automation (it is "selected" but the page does not change), so a real
        # mouse click is needed. Two passes: JW Library is often still loading on the first one.
        # JW Library can take 20+ s before its tabs show up, so keep trying for up to 60 s.
        $clicks = 0
        $navDeadline = (Get-Date).AddSeconds(60)
        $miss = 0
        while ($clicks -lt 1 -and (Get-Date) -lt $navDeadline) {
            if (-not (Test-JwlProcessRunning -MaxAgeMs 0)) { break }
            if (Click-JwlNavTabReal 'Meetings') {
                $clicks++
                if (-not (Wait-StartMenu 2)) { Set-StartMenuStep $step 'skip' 'cancelled'; return }
            }
            else {
                $miss++
                if ($miss -eq 1 -or $miss % 5 -eq 0) { Log "Start menu: JW Library - $($script:_jwlClickWhy) (attempt $miss)" }
                if ($miss -eq 3) {
                    # One-time look at what JW Library shows to UI Automation, to see why the tab is not found
                    try {
                        $jw = Get-JwlMainWindow
                        if ($jw) {
                            $all = $jw.FindAll([System.Windows.Automation.TreeScope]::Descendants, [System.Windows.Automation.Condition]::TrueCondition)
                            $seen = New-Object System.Collections.Generic.List[string]
                            for ($k = 0; $k -lt $all.Count -and $seen.Count -lt 40; $k++) {
                                try { $nm = [string]$all.Item($k).Current.Name; if ($nm) { $seen.Add($nm) } } catch {}
                            }
                            Log "Start menu: JW Library elements seen ($($all.Count) total): $($seen -join ' | ')"
                        }
                    }
                    catch {}
                }
                if (-not (Wait-StartMenu 2)) { Set-StartMenuStep $step 'skip' 'cancelled'; return }
            }
        }
        if ($clicks -ge 1) { Set-StartMenuStep $step 'ok' 'Meetings'; return }
        if (Test-JwlProcessRunning -MaxAgeMs 0) { Set-StartMenuStep $step 'ok' 'open (could not click Meetings)'; return }
        Log "Start menu: JW Library closed while starting (try $try/$maxTries)"
    }
    Set-StartMenuStep $step 'fail' "JW Library did not stay open after $maxTries tries"
}

function Start-StartMenuEarlyApps {
    # Launches OnlyT / OnlyM (only if ticked, not open yet and not launched before) without waiting for them.
    $s = $script:_startMenu
    if (-not $s) { return }
    foreach ($key in @('OnlyT', 'OnlyM')) {
        $st = @($s.Steps | Where-Object { $_.Key -eq $key })[0]
        if (-not $st -or $st.State -ne 'pending' -or $st.Launched) { continue }
        try {
            if ($key -eq 'OnlyT') {
                if (@(Get-Process -Name 'OnlyT' -ErrorAction SilentlyContinue).Count -gt 0) { Set-StartMenuStep $st 'ok' 'already open'; continue }
                if (-not (Find-OnlyTExe)) { continue }
                Log 'Start menu: OnlyT - opening while JW Library loads'
                Start-OnlyTApp -Silent
            }
            else {
                if (@(Get-Process -Name 'OnlyM' -ErrorAction SilentlyContinue).Count -gt 0) { Set-StartMenuStep $st 'ok' 'already open'; continue }
                $exe = Find-OnlyMExe
                if (-not $exe) { continue }
                Log 'Start menu: OnlyM - opening while JW Library loads'
                Start-Process -FilePath $exe -WorkingDirectory (Split-Path -Parent $exe)
            }
            $st.Launched = $true
            $st.Note = 'opening'
        }
        catch { Log "Start menu: early start of $key failed - $_" }
    }
    Update-StartMenuProgress
}

function Test-StartMenuAppRunning([string]$Name) {
    # A running process counts as open: the window may be parked off-screen, minimized or in the tray (no main window handle).
    try { return (@(Get-Process -Name $Name -ErrorAction SilentlyContinue).Count -gt 0) } catch { return $false }
}

function Invoke-StartMenuOnlyT($step) {
    if ($step.Launched) { Set-StartMenuStep $step 'run' 'waiting for OnlyT' }
    else {
        if (Test-StartMenuAppRunning 'OnlyT') { Set-StartMenuStep $step 'ok' 'already open'; return }
        if (-not (Find-OnlyTExe)) { Set-StartMenuStep $step 'skip' 'OnlyT.exe not found - use the OnlyT button once to locate it'; return }
        Set-StartMenuStep $step 'run' 'opening OnlyT'
        Start-OnlyTApp -Silent
    }
    $deadline = (Get-Date).AddSeconds(30)
    while (-not (Test-StartMenuAppRunning 'OnlyT') -and (Get-Date) -lt $deadline) {
        if (-not (Wait-StartMenu 1)) { Set-StartMenuStep $step 'skip' 'cancelled'; return }
    }
    if (Test-StartMenuAppRunning 'OnlyT') { Set-StartMenuStep $step 'ok' } else { Set-StartMenuStep $step 'fail' 'OnlyT did not open' }
}

function Invoke-StartMenuOnlyM($step) {
    if ($step.Launched) { Set-StartMenuStep $step 'run' 'waiting for OnlyM' }
    else {
        if (Test-StartMenuAppRunning 'OnlyM') { Set-StartMenuStep $step 'ok' 'already open'; return }
        $exe = Find-OnlyMExe
        if (-not $exe) { Set-StartMenuStep $step 'skip' 'OnlyM.exe not found - locate it in Settings > Start menu'; return }
        Set-StartMenuStep $step 'run' 'opening OnlyM'
        Start-Process -FilePath $exe -WorkingDirectory (Split-Path -Parent $exe)
    }
    $deadline = (Get-Date).AddSeconds(30)
    while (-not (Test-StartMenuAppRunning 'OnlyM') -and (Get-Date) -lt $deadline) {
        if (-not (Wait-StartMenu 1)) { Set-StartMenuStep $step 'skip' 'cancelled'; return }
    }
    if (Test-StartMenuAppRunning 'OnlyM') { Set-StartMenuStep $step 'ok' } else { Set-StartMenuStep $step 'fail' 'OnlyM did not open' }
}

function Invoke-StartMenuZoom($step) {
    $btn = Get-WpfShellMainControl 'btnZoomJoin'
    if (-not $btn -or $btn.IsDisposed) { Set-StartMenuStep $step 'fail' 'Zoom Join button not available'; return }
    if ($script:_zoomJoinInProgress) { Set-StartMenuStep $step 'ok' 'join already in progress'; return }
    Set-StartMenuStep $step 'run' 'joining with the Zoom settings'
    # Same as pressing the Zoom Join button: joins the meeting and applies the automatic Zoom settings.
    $btn.PerformClick()
    [void](Wait-StartMenu 3)
    Set-StartMenuStep $step 'ok' 'joining - progress is shown in the status bar'
}

function Invoke-StartMenuSequence {
    if ($script:_startMenu -and $script:_startMenu.Active) {
        Log 'Start menu: already running - please wait until all programs are loaded'
        return
    }
    $cfg = $script:Cfg.StartMenu
    $defs = @(
        @{ Key = 'Obs'; Name = 'OBS + Virtual Camera'; On = [bool]$cfg.Obs; Run = { param($st) Invoke-StartMenuObs $st } },
        @{ Key = 'OnlyT'; Name = 'OnlyT'; On = [bool]$cfg.OnlyT; Run = { param($st) Invoke-StartMenuOnlyT $st } },
        @{ Key = 'OnlyM'; Name = 'OnlyM'; On = [bool]$cfg.OnlyM; Run = { param($st) Invoke-StartMenuOnlyM $st } },
        @{ Key = 'Zoom'; Name = 'Zoom'; On = [bool]$cfg.Zoom; Run = { param($st) Invoke-StartMenuZoom $st } },
        @{ Key = 'Jwl'; Name = $(if ([bool]$cfg.JwlMeetings) { 'JW Library (Meetings)' } else { 'JW Library' }); On = [bool]$cfg.Jwl; Run = { param($st) Invoke-StartMenuJwl $st } }   # always last: confirming the Meetings tab can take a while
    )
    $steps = @($defs | Where-Object { $_.On } | ForEach-Object { @{ Key = $_.Key; Name = $_.Name; State = 'pending'; Note = ''; Run = $_.Run } })
    if ($steps.Count -eq 0) {
        [void](Show-AppMessageBox "No programs are ticked for the Start menu.`r`n`r`nTick them in Settings > Start menu." 'Start menu' ([System.Windows.Forms.MessageBoxButtons]::OK) ([System.Windows.Forms.MessageBoxIcon]::Information))
        return
    }
    $script:_startMenu = @{ Active = $true; Cancel = $false; Steps = $steps; Text = ''; Progress = $null; EarlyCheckAt = [DateTime]::MinValue }
    try {
        $script:_startMenu.Progress = Show-StartMenuProgressForm
        Update-StartMenuProgress
        $gap = [math]::Max(0, [double]$cfg.PauseSeconds)
        $first = $true
        foreach ($st in $steps) {
            if ($script:_startMenu.Cancel -or $script:ShuttingDown) { Set-StartMenuStep $st 'skip' 'cancelled'; continue }
            if ($st.State -eq 'ok') { continue }   # OnlyT / OnlyM already confirmed open while JW Library was loading
            if (-not $first -and $gap -gt 0) {
                $st.Note = "pause $gap s"
                Update-StartMenuProgress
                if (-not (Wait-StartMenu $gap)) { Set-StartMenuStep $st 'skip' 'cancelled'; continue }
                if ($st.State -eq 'ok') { continue }
            }
            $first = $false
            try { & $st.Run $st }
            catch { Set-StartMenuStep $st 'fail' "$_" }
        }
        # Leave the result visible for a moment (Zoom keeps showing its own progress in the status bar)
        $script:_startMenu.Cancel = $false
        $failed = @($steps | Where-Object { $_.State -eq 'fail' })
        Log $(if ($failed.Count -gt 0) { "Start menu: finished - $($failed.Count) program(s) did not start" } else { 'Start menu: all programs are started' })
        [void](Wait-StartMenu $(if ($failed.Count -gt 0) { 6 } else { 3 }))
    }
    catch { Log "Start menu error: $_" }
    finally {
        $script:_startMenu.Active = $false
        try { $p = $script:_startMenu.Progress; if ($p -and $p.Form -and -not $p.Form.IsDisposed) { $p.Form.Close(); $p.Form.Dispose() } } catch {}
        [void](Update-WpfShellStartupLabel)
    }
}

function Update-WpfShellObsButton {
    # Green = OBS connected. Blue = OBS is open (connecting). Flashing blue = OBS is not running (click to start it).
    if (-not $script:_wpfShellWindow) { return }
    try {
        $btn = $script:_wpfShellWindow.FindName('ObsConnectBtn')
        if (-not $btn) { return }
        if ($script:ObsConnected) { $c = [System.Drawing.Color]::FromArgb(0, 160, 0) }
        elseif (Test-ObsProcessRunning) { $c = [System.Drawing.Color]::FromArgb(0, 80, 200) }
        else { $c = if ($script:_wpfShellVCamFlashOn) { [System.Drawing.Color]::FromArgb(70, 150, 255) } else { [System.Drawing.Color]::FromArgb(0, 45, 120) } }
        $btn.Background = ConvertTo-WpfBrush $c
    }
    catch {}
}

function Update-WpfShellStartMenuButton {
    # The red power button is only visible when "Enable Start menu" is ticked in Settings (its place stays reserved).
    if (-not $script:_wpfShellWindow) { return }
    try {
        $btn = $script:_wpfShellWindow.FindName('StartMenuBtn')
        if ($btn) {
            $btn.Visibility = $(if ([bool]$script:Cfg.StartMenu.Enabled) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Hidden })
        }
    }
    catch {}
}

function Update-WpfShellJwlAppButton {
    # JW Library button: blue = JW Library is not open (click to start it), green = running.
    if (-not $script:_wpfShellWindow) { return }
    try {
        $btn = $script:_wpfShellWindow.FindName('JwlAppBtn')
        if (-not $btn) { return }
        $c = if (Test-JwlProcessRunning) { [System.Drawing.Color]::FromArgb(0, 160, 0) }
        elseif ($script:_wpfShellVCamFlashOn) { [System.Drawing.Color]::FromArgb(70, 150, 255) }
        else { [System.Drawing.Color]::FromArgb(0, 45, 120) }
        $btn.Background = ConvertTo-WpfBrush $c
    }
    catch {}
}

function Update-WpfShellVCamButton {
    # Mirrors Update-VCamStatusVisual: OBS offline = blue (whatever the last V-Cam state was); OBS online and
    # V-Cam on = green; OBS online but V-Cam off = flashing red (same bright/dark red pair as VCamFlashTimer).
    if (-not $script:_wpfShellWindow) { return }
    try {
        $btn = $script:_wpfShellWindow.FindName('VCamBtn')
        if (-not $btn) { return }
        if (-not $script:ObsConnected) { $c = [System.Drawing.Color]::FromArgb(0, 80, 200) }
        elseif ($script:VirtualCameraStatus) { $c = [System.Drawing.Color]::FromArgb(0, 160, 0) }
        else {
            $c = if ($script:_wpfShellVCamFlashOn) { [System.Drawing.Color]::FromArgb(200, 0, 0) } else { [System.Drawing.Color]::FromArgb(120, 0, 0) }
        }
        $btn.Background = ConvertTo-WpfBrush $c
    }
    catch {}
}

function Step-WpfShellVCamFlash {
    # Flips the flash phase here (not inside the timer's closure) so the state lives in the
    # main script scope that Update-WpfShellVCamButton reads.
    $script:_wpfShellVCamFlashOn = -not $script:_wpfShellVCamFlashOn
    Update-WpfShellVCamButton
    Update-WpfShellObsButton
    Update-WpfShellJwlAppButton
}

# ---- Zoom start-up progress (status bar of the new UI) ----
# Steps: Join -> Participants panel -> Polls. States: pending, run, retry, ok, fail, skip.
# While active it temporarily replaces the update / next-meeting texts in the status bar, then disappears.
function Start-ZoomStartup([string]$JoinState = 'run') {
    try {
        $pollsState = 'skip'
        try { if ($script:Cfg.Zoom.AutoPollsAfterJoin) { $pollsState = 'pending' } } catch {}
        $script:_zoomStartup = @{ Active = $true; Join = $JoinState; Parts = 'pending'; Polls = $pollsState; StartedAt = Get-Date; EndAt = $null }
        [void](Update-WpfShellStartupLabel)
    }
    catch {}
}

function Set-ZoomStartupStep([string]$Step, [string]$State) {
    try {
        $s = $script:_zoomStartup
        if (-not $s -or -not $s.Active) { return }
        $s[$Step] = $State
        [void](Update-WpfShellStartupLabel)
    }
    catch {}
}

function Stop-ZoomStartup {
    try {
        if ($script:_zoomStartup) { $script:_zoomStartup.Active = $false }
        [void](Update-WpfShellStartupLabel)
    }
    catch {}
}

# Draws the progress line; returns $true while it is shown.
function Update-WpfShellStartupLabel {
    $w = $script:_wpfShellWindow
    if (-not $w) { return $false }
    $show = $false
    try {
        $lbl = $w.FindName('ZoomStartupLabel')
        $s = $script:_zoomStartup
        if ($lbl -and $s -and $s.Active) {
            $now = Get-Date
            $age = ($now - $s.StartedAt).TotalSeconds
            if ($s.Join -eq 'run' -and $age -gt 80) { $s.Join = 'fail' }
            if ($age -gt 150) { $s.Active = $false }
            else {
                $steps = @('Join', 'Parts')
                if ($s.Polls -ne 'skip') { $steps += 'Polls' }
                $open = @($steps | Where-Object { $s[$_] -in @('pending', 'run', 'retry') })
                $failed = @($steps | Where-Object { $s[$_] -eq 'fail' })
                if ($open.Count -eq 0 -and -not $s.EndAt) { $s.EndAt = $now.AddSeconds($(if ($failed.Count -gt 0) { 20 } else { 6 })) }
                if ($s.EndAt -and $now -ge $s.EndAt) { $s.Active = $false }
                else {
                    $glyph = @{ ok = [string][char]0x2713; run = [string][char]0x2026; retry = [string][char]0x21BB; fail = [string][char]0x2717; pending = [string][char]0x25CB }
                    $parts = New-Object System.Collections.Generic.List[string]
                    $joinName = if ($s.Join -eq 'run') { 'Joining' } else { 'Joined' }
                    [void]$parts.Add("$($glyph[$s.Join]) $joinName")
                    [void]$parts.Add("$($glyph[$s.Parts]) Participants" + $(if ($s.Parts -eq 'fail') { ' (open manually)' } else { '' }))
                    if ($s.Polls -ne 'skip') {
                        $pollsText = switch ($s.Polls) {
                            'run' { 'Polls opening' }
                            'ok' { if ($s.PollsNote) { "Polls $($s.PollsNote)" } else { 'Polls launched' } }
                            'fail' { 'Polls (click Polls)' }
                            default { 'Polls' }
                        }
                        [void]$parts.Add("$($glyph[$s.Polls]) $pollsText")
                    }
                    $lbl.Text = 'Zoom:  ' + ($parts -join '   ')
                    $rgb = if ($failed.Count -gt 0) { @(220, 0, 0) } elseif ($open.Count -gt 0) { @(255, 150, 0) } else { @(0, 192, 0) }
                    $lbl.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb($rgb[0], $rgb[1], $rgb[2]))
                    $show = $true
                }
            }
        }
        if ($lbl) {
            $vis = if ($show) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
            $other = if ($show) { [System.Windows.Visibility]::Collapsed } else { [System.Windows.Visibility]::Visible }
            if ($lbl.Visibility -ne $vis) { $lbl.Visibility = $vis }
            foreach ($n in @('UpdateStatusLabel', 'NextMeetingLabel')) {
                $o = $w.FindName($n)
                if ($o -and $o.Visibility -ne $other) { $o.Visibility = $other }
            }
        }
        # Start menu progress (power button) takes the same spot while Zoom's own progress line is not showing
        $smLbl = $w.FindName('StartMenuLabel')
        if ($smLbl) {
            $smOn = (-not $show) -and $script:_startMenu -and $script:_startMenu.Active
            if ($smOn) {
                $smLbl.Text = [string]$script:_startMenu.Text
                $smLbl.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(255, 150, 0))
                foreach ($n in @('UpdateStatusLabel', 'NextMeetingLabel')) {
                    $o = $w.FindName($n)
                    if ($o -and $o.Visibility -ne [System.Windows.Visibility]::Collapsed) { $o.Visibility = [System.Windows.Visibility]::Collapsed }
                }
            }
            $smVis = if ($smOn) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
            if ($smLbl.Visibility -ne $smVis) { $smLbl.Visibility = $smVis }
            if ($smOn) { $show = $true }
        }
    }
    catch {}
    return $show
}

function Update-WpfShellStatusBar {
    # Read-only reflection of the main app's own cached state ($script:ObsConnected,
    # $script:_lastProgramScene) - no OBS requests are made here, so this is safe to call
    # on every clock tick without adding any load or latency.
    if (-not $script:_wpfShellWindow) { return }
    try {
        $w = $script:_wpfShellWindow
        $obsLabel = $w.FindName('ObsStatusLabel')
        if ($obsLabel) {
            if ($script:ObsConnected) {
                $obsLabel.Text = 'OBS ✓'
                $obsLabel.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0, 192, 0))
            }
            else {
                $obsLabel.Text = 'OBS ✗'
                $obsLabel.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(220, 0, 0))
            }
        }
        Update-WpfShellObsButton
        Update-WpfShellJwlAppButton
        Update-WpfShellVCamButton
        Update-WpfShellMediaButton
        $updLabel = $w.FindName('UpdateStatusLabel')
        $updSrc = Get-WpfShellMainControl 'lblUpdateStatus'
        if ($updLabel -and $updSrc -and -not $updSrc.IsDisposed) {
            # Same text/colour the main app's update readout shows; its neutral light-grey is swapped for the theme text colour.
            $updText = [string]$updSrc.Text
            $updTag = [string]$updSrc.Tag
            # The main label stays short (fixed-width button above it); the status bar has room for the version.
            if (-not [string]::IsNullOrWhiteSpace($updTag) -and ($updText -eq 'Up to date' -or $updText -eq 'Update available' -or $updText -eq 'Dev build')) { $updText = "${updText}: $updTag" }
            $updLabel.Text = $updText
            $uc = $updSrc.ForeColor
            if ($uc.ToArgb() -eq [System.Drawing.Color]::LightGray.ToArgb()) { $updLabel.Foreground = ConvertTo-WpfBrush (Get-ThemeKit (Test-IsDarkTheme)).Text }
            else { $updLabel.Foreground = ConvertTo-WpfBrush $uc }
        }
        $startupShown = Update-WpfShellStartupLabel
        $zoomHealthLabel = $w.FindName('ZoomHealthLabel')
        if ($zoomHealthLabel) {
            $want = if ((Get-ZoomHealthWarn) -and -not $startupShown) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
            if ($zoomHealthLabel.Visibility -ne $want) { $zoomHealthLabel.Visibility = $want }
        }
        $nextMeetingLabel = $w.FindName('NextMeetingLabel')
        if ($nextMeetingLabel) {
            # Day and start time of the next meeting only (no T-/T+ countdown).
            try {
                $next = Get-NextMeeting (Get-Date)
                if (-not $next) {
                    $nextMeetingLabel.Text = 'Next: —'
                }
                else {
                    $nextMeetingLabel.Text = "Next: " + $next.ToString("ddd h:mm tt")
                }
            }
            catch { $nextMeetingLabel.Text = 'Next: —' }
        }
    }
    catch {}
}

function Update-WpfShellClock {
    # Mirrors the real app's own $btnClock control (text + flash colors) read-only - during the
    # 5-minute countdown window the main app's meetingTimer already drives $btnClock.Text/BackColor/
    # ForeColor (green->yellow->red flash), so copying those same values keeps the preview's clock
    # in lock-step with the real one without duplicating the countdown/flash logic.
    if (-not $script:_wpfShellWindow) { return }
    try {
        $clockText = $script:_wpfShellWindow.FindName('ClockText')
        $clockBorder = $script:_wpfShellWindow.FindName('ClockBorder')
        if (-not $clockText) { return }
        if ($script:btnClock -and $script:_clockCountdownMode) {
            $clockText.Text = $script:btnClock.Text
            $clockText.Foreground = ConvertTo-WpfBrush $script:btnClock.ForeColor
            $clockText.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
            if ($clockBorder) {
                $clockBorder.Background = ConvertTo-WpfBrush $script:btnClock.BackColor
                $clockBorder.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Stretch
            }
        }
        else {
            $clockText.Text = (Get-Date).ToString('h:mm:ss tt')
            # Always white on a translucent dark pill: the clock now sits on top of the video, not on the theme panel.
            $clockText.Foreground = [System.Windows.Media.Brushes]::White
            $clockText.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
            if ($clockBorder) {
                $clockBorder.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromArgb(0x99, 0, 0, 0))
                $clockBorder.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Left
            }
        }
    }
    catch {}
}

function Get-WpfShellDefaultSpeakerScene {
    # Mirrors the main app's own $DEFAULT_SPEAKER fallback used by the real btnCam picker.
    try { if (-not [string]::IsNullOrWhiteSpace($script:DEFAULT_SPEAKER)) { return [string]$script:DEFAULT_SPEAKER } } catch {}
    return 'Speaker'
}

function Update-WpfShellMediaButton {
    # PiP badge mirrors the real $btnPip: shown only when PiP is enabled in Settings,
    # orange = PiP off, green = PiP on ($script:_pipOn).
    if (-not $script:_wpfShellWindow) { return }
    try {
        $pip = $script:_wpfShellWindow.FindName('PipBtn')
        if (-not $pip) { return }
        $enabled = $false
        try { $enabled = [bool]$script:Cfg.PiP.Enabled } catch {}
        $pip.Visibility = if ($enabled) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
        $c = if ($script:_pipOn) { [System.Drawing.Color]::FromArgb(0, 180, 60) } else { [System.Drawing.Color]::FromArgb(210, 90, 0) }
        $pip.Background = ConvertTo-WpfBrush $c
    }
    catch {}
}

function Set-WpfShellSelectedScene([string]$name) {
    # Selection only (same as the main app's btnCam): remembers the scene for <Cut and flashes Cut.
    if ([string]::IsNullOrWhiteSpace($name)) { return }
    $script:SelectedScene = $name
    try { if ($script:btnCam -and -not $script:btnCam.IsDisposed) { $script:btnCam.Text = $name } } catch {}
    Start-CutButtonFlash
    Update-WpfShellScenePicker
}

function Show-WpfAwareMenu($menu, $anchor) {
    # Shows a main-app context menu under its own button, or at the mouse pointer when the click
    # came from the WPF shell (the main button may be on another window / off screen).
    if ($script:_wpfShellMenuAtCursor) { $menu.Show([System.Windows.Forms.Cursor]::Position) }
    else { $menu.Show($anchor, 0, $anchor.Height) }
}

function ConvertTo-WpfImageSource($bmp) {
    # Re-uses the main app's own GDI+ icon bitmaps (clapperboard, record dot, TV) as WPF images.
    if (-not $bmp) { return $null }
    $ms = New-Object System.IO.MemoryStream
    try {
        $bmp.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
        $ms.Position = 0
        $bi = New-Object System.Windows.Media.Imaging.BitmapImage
        $bi.BeginInit()
        $bi.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
        $bi.StreamSource = $ms
        $bi.EndInit()
        $bi.Freeze()
        return $bi
    }
    finally { $ms.Dispose() }
}

function Set-WpfShellRowButtonLook($wpfBtn, $src, [string]$key) {
    # Mirrors the main button's live BackColor/ForeColor/border so all existing color logic
    # (music green, REC red, JWL on/off, hand-alert flash...) keeps working untouched.
    if (-not $wpfBtn -or -not $src -or $src.IsDisposed) { return }
    $bc = $src.BackColor
    $fc = $src.ForeColor
    $bd = [System.Drawing.Color]::Empty
    try { $bd = $src.FlatAppearance.BorderColor } catch {}
    if ($bd.IsEmpty) { $bd = $bc }
    $sig = "$($bc.ToArgb())|$($fc.ToArgb())|$($bd.ToArgb())"
    if ($script:_wpfRow3Sig[$key] -eq $sig) { return }
    $script:_wpfRow3Sig[$key] = $sig
    $wpfBtn.Background = ConvertTo-WpfBrush $bc
    $wpfBtn.Foreground = ConvertTo-WpfBrush $fc
    $wpfBtn.BorderBrush = ConvertTo-WpfBrush $bd
}

function Get-WpfShellMainControl([string]$name) {
    # Looks the main app's control up by variable name (script scope first, then any parent scope).
    # Found controls are remembered (this is called ~60 times per 150 ms): a control that was disposed is looked up again.
    $c = $script:_wpfMainCtlCache[$name]
    if ($null -ne $c) {
        $gone = $false
        try { $gone = [bool]$c.IsDisposed } catch {}
        if (-not $gone) { return $c }
    }
    $v = Get-Variable -Name $name -Scope Script -ValueOnly -ErrorAction SilentlyContinue
    if (-not $v) { $v = Get-Variable -Name $name -ValueOnly -ErrorAction SilentlyContinue }
    if ($v) { $script:_wpfMainCtlCache[$name] = $v }
    return $v
}

function Set-WpfShellBadge($wpfTb, $srcLbl, [string]$key) {
    # Mirrors one of the main app's small status labels (countdowns / "Waiting: N" / "Polls: --").
    if (-not $wpfTb) { return }
    if (-not $srcLbl -or $srcLbl.IsDisposed) { return }
    $text = [string]$srcLbl.Text
    if ([string]::IsNullOrEmpty($text)) { $text = ' ' }
    $vis = if ($srcLbl.Visible) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Hidden }
    $sig = "$text|$($srcLbl.ForeColor.ToArgb())|$vis"
    if ($script:_wpfRow3Sig[$key] -eq $sig) { return }
    $script:_wpfRow3Sig[$key] = $sig
    $wpfTb.Text = $text
    $wpfTb.Foreground = ConvertTo-WpfBrush $srcLbl.ForeColor
    $wpfTb.Visibility = $vis
}

function Set-WpfShellStateGlyph($w, [string]$iconName, [string]$glyphName, [string]$glyphText) {
    # Shows the normal vector icon, or (when the main button is busy/in another state) a small glyph instead.
    $icon = $w.FindName($iconName); $glyph = $w.FindName($glyphName)
    if (-not $icon -or -not $glyph) { return }
    $showGlyph = -not [string]::IsNullOrEmpty($glyphText)
    $iv = if ($showGlyph) { [System.Windows.Visibility]::Collapsed } else { [System.Windows.Visibility]::Visible }
    $gv = if ($showGlyph) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
    if ($icon.Visibility -ne $iv) { $icon.Visibility = $iv }
    if ($glyph.Visibility -ne $gv) { $glyph.Visibility = $gv }
    if ($showGlyph -and $glyph.Text -ne $glyphText) { $glyph.Text = $glyphText }
}

function Update-WpfShellRow4 {
    # Row 4 (Zoom): colors / enabled state / visibility / badge texts all come live from the main
    # app's own Zoom controls, so every existing Zoom state rule keeps working unchanged.
    if (-not $script:_wpfShellWindow) { return }
    try {
        $w = $script:_wpfShellWindow
        $map = @(
            @('ZoomJoinBtn', 'btnZoomJoin', 'zjoin'), @('ZoomMuteBtn', 'btnZoomMuteAll', 'zmute'),
            @('ZoomMicBtn', 'btnZoomMic', 'zmic'), @('ZoomCamBtn', 'btnZoomCamera', 'zcam'),
            @('ZoomPollsBtn', 'btnZoomPolls', 'zpolls'), @('ZoomFocusBtn', 'btnZoomFocus', 'zfocus'),
            @('ZoomAdmitBtn', 'btnAdmit', 'zadmit'), @('OnlyTBtn', 'btnOnlyT', 'tonlyt')
        )
        foreach ($m in $map) {
            $wb = $w.FindName($m[0])
            $src = Get-WpfShellMainControl $m[1]
            if (-not $wb -or -not $src -or $src.IsDisposed) { continue }
            Set-WpfShellRowButtonLook $wb $src $m[2]
            if ($wb.IsEnabled -ne [bool]$src.Enabled) { $wb.IsEnabled = [bool]$src.Enabled }
            if ($wb.Parent -is [System.Windows.Controls.Panel]) {
                $pv = if ($src.Visible) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
                if ($wb.Parent.Visibility -ne $pv) { $wb.Parent.Visibility = $pv }
            }
        }

        $join = Get-WpfShellMainControl 'btnZoomJoin'
        if ($join) {
            $jt = [string]$join.Text
            $g = if ($jt -eq 'Join Zoom') { '' } elseif ($jt -eq 'In Meeting') { [string][char]0x2714 } else { [string][char]0x2026 }
            Set-WpfShellStateGlyph $w 'JoinIcon' 'JoinStateGlyph' $g
        }
        $focus = Get-WpfShellMainControl 'btnZoomFocus'
        if ($focus) {
            $g = if ([string]$focus.Text -eq 'Focus') { '' } else { [string][char]0x2026 }
            Set-WpfShellStateGlyph $w 'FocusIcon' 'FocusStateGlyph' $g
        }
        $admit = Get-WpfShellMainControl 'btnAdmit'
        if ($admit) {
            $at = [string]$admit.Text
            $g = if ($at -eq 'Admit') { '' } elseif ($at -eq 'Scan') { [string][char]0x27F3 } else { [string][char]0x2026 }
            Set-WpfShellStateGlyph $w 'AdmitIcon' 'AdmitStateGlyph' $g
        }
        # OnlyT: play symbol while the timer is stopped, stop symbol while it runs
        $onlyT = Get-WpfShellMainControl 'btnOnlyT'
        if ($onlyT) {
            $otRunning = ([string]$onlyT.Tag -eq 'running')
            $otPlay = $w.FindName('OnlyTPlay'); $otStop = $w.FindName('OnlyTStop')
            if ($otPlay -and $otStop) {
                $pv = if ($otRunning) { [System.Windows.Visibility]::Collapsed } else { [System.Windows.Visibility]::Visible }
                $sv = if ($otRunning) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
                if ($otPlay.Visibility -ne $pv) { $otPlay.Visibility = $pv }
                if ($otStop.Visibility -ne $sv) { $otStop.Visibility = $sv }
            }
        }

        # Mic / camera glyphs follow the main buttons (they swap glyphs by state); the red slash = locked by Auto Toggle.
        foreach ($pair in @(@('MicGlyph', 'btnZoomMic', 'MicSlash', $script:ZoomMicLocked), @('CamGlyph', 'btnZoomCamera', 'CamSlash', $script:ZoomCamLocked))) {
            $tb = $w.FindName($pair[0]); $src = Get-WpfShellMainControl $pair[1]
            if ($tb -and $src -and $tb.Text -ne [string]$src.Text) { $tb.Text = [string]$src.Text }
            $slash = $w.FindName($pair[2])
            if ($slash) {
                $sv = if ($pair[3]) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
                if ($slash.Visibility -ne $sv) { $slash.Visibility = $sv }
            }
        }

        Set-WpfShellBadge $w.FindName('MuteBadge') (Get-WpfShellMainControl 'lblZoomMuteBadge') 'bMute'
        Set-WpfShellBadge $w.FindName('MicBadge') (Get-WpfShellMainControl 'lblZoomMicBadge') 'bMic'
        Set-WpfShellBadge $w.FindName('CamBadge') (Get-WpfShellMainControl 'lblZoomCamBadge') 'bCam'
        Set-WpfShellBadge $w.FindName('FocusBadge') (Get-WpfShellMainControl 'lblZoomFocusBadge') 'bFocus'
        Set-WpfShellBadge $w.FindName('AdmitBadge') (Get-WpfShellMainControl 'lblAdmitBadge') 'bAdmit'
        Set-WpfShellBadge $w.FindName('PollsReadout') (Get-WpfShellMainControl 'lblAttendance') 'bPolls'
        $pr = $w.FindName('PollsReadout')
        if ($pr -and $pr.Visibility -ne [System.Windows.Visibility]::Visible) { $pr.Visibility = [System.Windows.Visibility]::Visible }
    }
    catch {}
}

function Set-WpfShellPill($w, [string]$pillName, [string]$textName, $badge) {
    # Mirrors one of the main app's T-minus pills ($script:_badge_* = @{ Visible; Text; Color }),
    # e.g. the "8m" bubble on Auto Toggle / V-Cam / Music. Colours come straight from Get-BadgeColor.
    $pill = $w.FindName($pillName); $tb = $w.FindName($textName)
    if (-not $pill -or -not $tb) { return }
    $show = [bool]($badge -and $badge.Visible -and $badge.Text)
    $sig = if ($show) { "$($badge.Text)|$($badge.Color.ToArgb())" } else { 'hidden' }
    if ($script:_wpfRow3Sig["pill$pillName"] -eq $sig) { return }
    $script:_wpfRow3Sig["pill$pillName"] = $sig
    if ($show) {
        $tb.Text = [string]$badge.Text
        $pill.Background = ConvertTo-WpfBrush $badge.Color
        $pill.Visibility = [System.Windows.Visibility]::Visible
    }
    else { $pill.Visibility = [System.Windows.Visibility]::Collapsed }
}

function Update-WpfShellRow3 {
    if (-not $script:_wpfShellWindow) { return }
    try {
        Set-WpfShellPill $script:_wpfShellWindow 'AutoPill' 'AutoPillText' $script:_badge_AutoToggle
        Set-WpfShellPill $script:_wpfShellWindow 'VCamPill' 'VCamPillText' $script:_badge_VCam
        Set-WpfShellPill $script:_wpfShellWindow 'MusicPill' 'MusicPillText' $script:_badge_Music
    }
    catch {}
    Update-WpfShellRow3Buttons
}

function Update-WpfShellRow3Buttons {
    if (-not $script:_wpfShellWindow) { return }
    try {
        $w = $script:_wpfShellWindow
        $mMusic = Get-WpfShellMainControl 'btnMusicToggle'
        $mRec = Get-WpfShellMainControl 'btnOBSRecord'
        $mJwl = Get-WpfShellMainControl 'btnJwlMonitor'
        $mZoom = Get-WpfShellMainControl 'btnZoomToggle'
        $mHand = Get-WpfShellMainControl 'btnHandAlert'

        $b = $w.FindName('MusicBtn')
        if ($b) {
            try { Update-MusicButtonVisual } catch {}
            Set-WpfShellRowButtonLook $b $mMusic 'music'
            if ($mMusic -and -not $mMusic.IsDisposed -and $b.IsEnabled -ne [bool]$mMusic.Enabled) { $b.IsEnabled = [bool]$mMusic.Enabled }
            $icon = $w.FindName('MusicStateIcon')
            if ($icon) {
                $playing = $false
                try { $playing = [bool](Test-MusicIsPlaying) } catch {}
                $glyph = if ($playing) { [string][char]0x25A0 } else { ([string][char]0x25B6) + [char]0xFE0E }
                if ($icon.Text -ne $glyph) { $icon.Text = $glyph }
                # Dancing notes: while music plays, highlight note 1, 2, 3 in turn (lifted + full opacity, others dimmed).
                $step = if ($playing) { [int]([math]::Floor([DateTime]::UtcNow.Ticks / 3000000) % 3) } else { -1 }
                if ($script:_wpfRow3Sig['musicNotes'] -ne $step) {
                    $script:_wpfRow3Sig['musicNotes'] = $step
                    for ($n = 1; $n -le 3; $n++) {
                        $nt = $w.FindName("MusicNote$n")
                        if (-not $nt) { continue }
                        $on = ($step -eq ($n - 1))
                        $nt.Opacity = if ($step -lt 0 -or $on) { 1.0 } else { 0.4 }
                        if ($nt.RenderTransform -is [System.Windows.Media.TranslateTransform]) { $nt.RenderTransform.Y = if ($on) { -3 } else { 0 } }
                    }
                }
            }
        }

        $b = $w.FindName('RecBtn')
        if ($b) {
            Set-WpfShellRowButtonLook $b $mRec 'rec'
            $img = $w.FindName('RecImage')
            if ($img) {
                $state = if ($script:OBSRecording) { 'active' } else { 'idle' }
                if ($script:_wpfRow3Sig['recImg'] -ne $state) {
                    $script:_wpfRow3Sig['recImg'] = $state
                    $img.Source = ConvertTo-WpfImageSource $(if ($script:OBSRecording) { $script:_obsRecActiveImage } else { $script:_obsRecIdleImage })
                    # Same text colours as the main REC button's paint code: red idle, white while recording.
                    $recText = $w.FindName('RecText')
                    if ($recText) { $recText.Foreground = ConvertTo-WpfBrush $(if ($script:OBSRecording) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(230, 70, 70) }) }
                }
            }
        }

        $b = $w.FindName('JwlBtn')
        if ($b) {
            Set-WpfShellRowButtonLook $b $mJwl 'jwl'
            $img = $w.FindName('JwlImage')
            if ($img -and -not $img.Source) { $img.Source = ConvertTo-WpfImageSource $script:_tvMonitorImage }
            $badge = $w.FindName('JwlBadge')
            if ($badge) {
                $vis = if ($script:_ocrBroken -eq $true) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
                if ($badge.Visibility -ne $vis) { $badge.Visibility = $vis }
            }
        }

        $b = $w.FindName('ZoomToggleBtn')
        if ($b) {
            Set-WpfShellRowButtonLook $b $mZoom 'zoomtoggle'
            $arrows = $w.FindName('ZoomArrows')
            if ($arrows) {
                $key = if ($script:PS_projected) { 'proj' } else { 'norm' }
                if ($script:_wpfRow3Sig['arrows'] -ne $key) {
                    $script:_wpfRow3Sig['arrows'] = $key
                    $c = if ($script:PS_projected) { [System.Drawing.Color]::FromArgb(255, 140, 60) } else { [System.Drawing.Color]::FromArgb(80, 220, 80) }
                    $arrows.Stroke = ConvertTo-WpfBrush $c
                }
            }
        }

        $b = $w.FindName('HandBtn')
        if ($b) {
            Set-WpfShellRowButtonLook $b $mHand 'hand'
            # While the alert flashes the button turns yellow, which would hide the (yellow) hand
            # symbol - draw it dark on the bright phase so it stays visible.
            if ($mHand -and -not $mHand.IsDisposed) {
                $hbc = $mHand.BackColor
                $brightYellow = ($hbc.R -gt 200 -and $hbc.G -gt 200 -and $hbc.B -lt 120)
                if ($brightYellow) { $b.Foreground = [System.Windows.Media.Brushes]::Black }
            }
            $autoDot = $w.FindName('HandAutoDot')
            if ($autoDot) {
                $dotVis = if (Test-AutoHandAlertEnabled) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
                if ($autoDot.Visibility -ne $dotVis) { $autoDot.Visibility = $dotVis }
            }
        }
    }
    catch {}
}

function Update-WpfShellCutButton {
    # Mirrors the real $script:btnCut (flash color + enabled state during a fade-to-black cut).
    if (-not $script:_wpfShellWindow) { return }
    try {
        $btn = $script:_wpfShellWindow.FindName('CutBtn')
        if (-not $btn) { return }
        if ($script:btnCut -and -not $script:btnCut.IsDisposed) {
            $btn.Background = ConvertTo-WpfBrush $script:btnCut.BackColor
            $btn.IsEnabled = [bool]$script:btnCut.Enabled
        }
    }
    catch {}
}

function Update-WpfShellScenePicker {
    # Read-only refresh from cached state (no OBS requests, safe on every timer tick): the Program
    # button shows the live program scene ($script:_lastProgramScene), the picker shows the
    # scene selected for <Cut ($script:SelectedScene). Colors are fixed (match the main app's
    # btnBlank green / btnCam blue) rather than theme-driven.
    if (-not $script:_wpfShellWindow) { return }
    try {
        $w = $script:_wpfShellWindow
        $programBtn = $w.FindName('ProgramBtn')
        if ($programBtn) {
            $scene = [string]$script:_lastProgramScene
            $programBtn.Content = if ([string]::IsNullOrWhiteSpace($scene)) { Get-WpfShellDefaultSpeakerScene } else { $scene }
        }
        $btn = $w.FindName('ScenePickerBtn')
        if ($btn) {
            $sel = [string]$script:SelectedScene
            $btn.Content = if ([string]::IsNullOrWhiteSpace($sel)) { Get-WpfShellDefaultSpeakerScene } else { $sel }
        }
    }
    catch {}
}

function Update-WpfShellAutoToggleButton {
    # Read-only refresh mirroring the real $btnAuto's running state ($script:running) - same
    # colors as Set-RunStateUI, just read here instead of duplicated as a state machine.
    # The blip dot + label mirror the real $script:chip's live BackColor/Text (OCR
    # Inactive/Present/Absent) directly, same "read the live control" pattern used elsewhere.
    if (-not $script:_wpfShellWindow) { return }
    try {
        $btn = $script:_wpfShellWindow.FindName('AutoToggleBtn')
        $txt = $script:_wpfShellWindow.FindName('AutoToggleBtnText')
        if (-not $btn -or -not $txt) { return }
        $txt.Text = "$([char]::ConvertFromUtf32(0x1F500))$([char]0xFE0E)"
        $btn.Foreground = [System.Windows.Media.Brushes]::White
        # Symbol-only button: inactive = blue button + grey dot; running = green button whose dot
        # shows OCR status (Present = blue, Absent = red, anything else = grey).
        $dotColor = [System.Drawing.Color]::FromArgb(128, 128, 128)
        if ($script:running) {
            $btn.Background = ConvertTo-WpfBrush ([System.Drawing.Color]::FromArgb(0, 160, 0))
            if ($script:chip -and -not $script:chip.IsDisposed) {
                if ($script:chip.Text -eq 'Present') { $dotColor = [System.Drawing.Color]::FromArgb(0, 90, 220) }
                elseif ($script:chip.Text -eq 'Absent') { $dotColor = [System.Drawing.Color]::FromArgb(224, 0, 0) }
            }
        }
        else {
            $btn.Background = ConvertTo-WpfBrush ([System.Drawing.Color]::FromArgb(0, 80, 200))
        }
        $blip = $script:_wpfShellWindow.FindName('AutoToggleBlip')
        if ($blip) { $blip.Fill = ConvertTo-WpfBrush $dotColor }
    }
    catch {}
}

function Update-WpfShellAfButton {
    # AF button: grey = off, green = on (the main AF toggle's state). Only usable while the Speaker scene is live,
    # exactly like the old on-preview AF buttons, so it is dimmed otherwise.
    if (-not $script:_wpfShellWindow) { return }
    try {
        $btn = $script:_wpfShellWindow.FindName('AfBtn')
        if (-not $btn) { return }
        $on = [bool]$script:afEnabled
        $usable = [bool]$script:afSceneActive
        $sig = "$on|$usable"
        if ($script:_wpfRow3Sig['afBtn'] -eq $sig) { return }
        $script:_wpfRow3Sig['afBtn'] = $sig
        $bg = if ($on) { [System.Drawing.Color]::FromArgb(0, 160, 0) } else { [System.Drawing.Color]::FromArgb(128, 128, 128) }
        $bd = if ($on) { [System.Drawing.Color]::FromArgb(0, 110, 0) } else { [System.Drawing.Color]::FromArgb(96, 96, 96) }
        $btn.Background = ConvertTo-WpfBrush $bg
        $btn.BorderBrush = ConvertTo-WpfBrush $bd
        $btn.IsEnabled = $usable
        $btn.Opacity = if ($usable) { 1.0 } else { 0.5 }
    }
    catch {}
}

function Invoke-WpfShellMainAfButton([string]$name) {
    # Presses the main app's own AF control so the existing AF code (and its state) does the work.
    $b = Get-WpfShellMainControl $name
    if ($b -and -not $b.IsDisposed) { $b.PerformClick() }
}

function Show-WpfShellAfRoiPopup {
    # Shown while the AF ROI is being set up: stays open (clicking or dragging on the video does not close it) until
    # the ROI is confirmed with the button, so the ROI can't be left forgotten in setup mode.
    if (-not $script:_wpfShellWindow) { return }
    $btn = $script:_wpfShellWindow.FindName('AfBtn')
    if (-not $btn) { return }
    try {
        if ($script:_wpfAfRoiPopup -and $script:_wpfAfRoiPopup.IsOpen) { return }
        $pop = New-Object System.Windows.Controls.Primitives.Popup
        $pop.StaysOpen = $true
        $pop.AllowsTransparency = $true
        $pop.PopupAnimation = [System.Windows.Controls.Primitives.PopupAnimation]::None
        $pop.PlacementTarget = $btn
        $pop.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Bottom

        $bd = New-Object System.Windows.Controls.Border
        $bd.CornerRadius = New-Object System.Windows.CornerRadius 8
        $bd.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(30, 30, 30))
        $bd.BorderBrush = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0, 160, 0))
        $bd.BorderThickness = New-Object System.Windows.Thickness 1.5
        $bd.Padding = New-Object System.Windows.Thickness 10
        $bd.Margin = New-Object System.Windows.Thickness 0, 4, 0, 0

        $sp = New-Object System.Windows.Controls.StackPanel
        $tb = New-Object System.Windows.Controls.TextBlock
        $tb.Text = 'Set the ROI: drag or resize the green box on the video.'
        $tb.Foreground = [System.Windows.Media.Brushes]::White
        $tb.FontSize = 12
        $tb.Margin = New-Object System.Windows.Thickness 0, 0, 0, 8
        [void]$sp.Children.Add($tb)

        $ok = New-Object System.Windows.Controls.Button
        $ok.Content = ([string][char]0x2714) + '  Confirm ROI'
        $ok.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0, 160, 0))
        $ok.Foreground = [System.Windows.Media.Brushes]::White
        $ok.FontWeight = [System.Windows.FontWeights]::SemiBold
        $ok.Padding = New-Object System.Windows.Thickness 14, 6, 14, 6
        $ok.Cursor = [System.Windows.Input.Cursors]::Hand
        $ok.Add_Click({
                try { if ([bool]$script:afRoiVisible) { Invoke-WpfShellMainAfButton 'btnAfSetRoi' } }
                catch { Log "WPF shell preview: ROI confirm failed: $_" }
                try { $script:_wpfAfRoiPopup.IsOpen = $false } catch {}
            })
        [void]$sp.Children.Add($ok)

        $bd.Child = $sp
        $pop.Child = $bd
        $script:_wpfAfRoiPopup = $pop
        $pop.IsOpen = $true
    }
    catch { Log "WPF shell preview: ROI panel failed: $_" }
}

function Show-WpfShellAfMenu {
    # Right-click menu of the AF button: Set ROI, speed -/+ and the setup guide (all existing AF actions).
    if (-not $script:_wpfShellWindow) { return }
    $btn = $script:_wpfShellWindow.FindName('AfBtn')
    if (-not $btn) { return }
    # While the ROI is being set up the right-click shows the stay-open confirm panel instead of the normal menu.
    if ([bool]$script:afRoiVisible) { Show-WpfShellAfRoiPopup; return }
    try {
        # Only one AF menu at a time (a still-open "Set ROI" menu must not pile up).
        try { if ($script:_wpfAfMenu -and $script:_wpfAfMenu.IsOpen) { $script:_wpfAfMenu.StaysOpen = $false; $script:_wpfAfMenu.IsOpen = $false } } catch {}
        $menu = New-Object System.Windows.Controls.ContextMenu
        $script:_wpfAfMenu = $menu
        try { $menu.Style = $script:_wpfShellWindow.FindResource('ScenePickerMenuStyle') } catch {}
        $itemStyle = $null
        try { $itemStyle = $script:_wpfShellWindow.FindResource('ScenePickerMenuItemStyle') } catch {}
        $usable = [bool]$script:afSceneActive
        $roiOn = [bool]$script:afRoiVisible
        $add = {
            param($header, $tag, $enabled, $stayOpen)
            $mi = New-Object System.Windows.Controls.MenuItem
            $mi.Header = $header
            $mi.Tag = $tag
            $mi.IsEnabled = $enabled
            $mi.StaysOpenOnClick = $stayOpen
            if ($itemStyle) { $mi.Style = $itemStyle }
            [void]$menu.Items.Add($mi)
            return $mi
        }
        $roiHeader = if ($roiOn) { 'ROI: ON  (click to confirm)' } else { 'Set ROI' }
        $roiItem = & $add $roiHeader 'roi' $usable $false
        $script:_wpfAfRoiItem = $roiItem
        $speedItem = & $add "Speed: $($script:afSpeed)" 'speedlabel' $false $true
        $slower = & $add '−   Slower' 'slower' $usable $true
        $faster = & $add '+   Faster' 'faster' $usable $true
        [void]$menu.Items.Add((New-Object System.Windows.Controls.Separator))
        $infoItem = & $add 'Info - PTZ & Auto Frame guide' 'info' $true $false
        $script:_wpfAfSpeedItem = $speedItem
        foreach ($mi in @($roiItem, $slower, $faster, $infoItem)) {
            $mi.Add_Click({
                    param($clickSender, $clickArgs)
                    try {
                        switch ([string]$clickSender.Tag) {
                            'roi' {
                                Invoke-WpfShellMainAfButton 'btnAfSetRoi'
                                $script:_wpfAfMenu.IsOpen = $false
                                # ROI setup started: a normal menu would close the moment you click on the video to place the ROI,
                                # so show a small panel that stays until the ROI is confirmed.
                                if ([bool]$script:afRoiVisible) {
                                    [void]$script:_wpfShellWindow.Dispatcher.BeginInvoke([Action] { Show-WpfShellAfRoiPopup })
                                }
                            }
                            'slower' { Invoke-WpfShellMainAfButton 'btnAfSpeedDown'; $script:_wpfAfSpeedItem.Header = "Speed: $($script:afSpeed)" }
                            'faster' { Invoke-WpfShellMainAfButton 'btnAfSpeedUp'; $script:_wpfAfSpeedItem.Header = "Speed: $($script:afSpeed)" }
                            'info' { Show-PTZSetupHelp }
                        }
                    }
                    catch { Log "WPF shell preview: AF menu action failed: $_" }
                })
        }
        $btn.ContextMenu = $menu
        $menu.PlacementTarget = $btn
        $menu.IsOpen = $true
    }
    catch { Log "WPF shell preview: AF menu failed: $_" }
}

function Show-WpfShellScenePickerMenu {
    # Right-click menu, built fresh from the live OBS scene list every time it's opened - mirrors
    # the main app's own Show-ScenePickerForCamera (same Update-ObsSceneList/$script:_AllScenes
    # ordering, same Set-ObsScene switch function). No scene list is cached here.
    if (-not $script:_wpfShellWindow) { return }
    $btn = $script:_wpfShellWindow.FindName('ScenePickerBtn')
    if (-not $btn) { return }
    try {
        if (-not $script:ObsConnected) {
            Log "WPF shell preview: scene picker - OBS not connected"
            return
        }
        Update-ObsSceneList
        $names = @($script:_AllScenes)
        $menu = New-Object System.Windows.Controls.ContextMenu
        try { $menu.Style = $script:_wpfShellWindow.FindResource('ScenePickerMenuStyle') } catch {}
        $menuItemStyle = $null
        try { $menuItemStyle = $script:_wpfShellWindow.FindResource('ScenePickerMenuItemStyle') } catch {}
        if ($names.Count -eq 0) {
            $mi = New-Object System.Windows.Controls.MenuItem
            $mi.Header = 'No scenes found'
            $mi.IsEnabled = $false
            if ($menuItemStyle) { $mi.Style = $menuItemStyle }
            [void]$menu.Items.Add($mi)
        }
        else {
            $active = [string]$script:SelectedScene
            foreach ($name in $names) {
                $mi = New-Object System.Windows.Controls.MenuItem
                $isActive = [string]::Equals($name, $active, [System.StringComparison]::InvariantCultureIgnoreCase)
                $mi.Header = if ($isActive) { "●  $name" } else { "     $name" }
                if ($menuItemStyle) { $mi.Style = $menuItemStyle }
                if ($isActive) { $mi.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(100, 180, 255)) }
                $mi.Tag = $name
                $mi.Add_Click({
                        param($clickSender, $clickArgs)
                        try { Set-WpfShellSelectedScene ([string]$clickSender.Tag) } catch { Log "WPF shell preview: scene select failed: $_" }
                    })
                [void]$menu.Items.Add($mi)
            }
        }
        $btn.ContextMenu = $menu
        $menu.PlacementTarget = $btn
        $menu.IsOpen = $true
    }
    catch { Log "WPF shell preview: scene picker menu failed: $_" }
}

function New-WpfShellPtzButton($parent, [string]$name, [string]$symbol, [string]$keyId) {
    # Same look and behaviour as the main app's New-PTZButton (hold = repeat, hover = bright),
    # but parented to the shell's own video container instead of $script:pPreview. They are
    # sibling windows above the video panel, so the native video can't cover them.
    $btn = New-Object System.Windows.Forms.Button
    $btn.Name = $name
    $btn.Text = $symbol
    $btn.Font = $script:_ptzFontNorm
    $btn.FlatStyle = 'Flat'
    $btn.FlatAppearance.BorderSize = 0
    $btn.FlatAppearance.MouseOverBackColor = $script:_ptzBackBright
    $btn.FlatAppearance.MouseDownBackColor = [System.Drawing.Color]::FromArgb(100, 100, 100)
    $btn.BackColor = $script:_ptzBackDim
    $btn.ForeColor = $script:_ptzColorDim
    $btn.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btn.TabStop = $false
    $btn.Visible = $false
    $btn.Tag = $keyId
    $btn.Add_MouseDown({ Start-PTZRepeat ([string]$args[0].Tag) })
    $btn.Add_MouseUp({ Stop-PTZRepeat })
    $btn.Add_MouseEnter({
            $b = $args[0]
            $b.ForeColor = $script:_ptzColorBright
            $b.BackColor = $script:_ptzBackBright
            $b.Font = $script:_ptzFontBold
        })
    $btn.Add_MouseLeave({
            Stop-PTZRepeat
            $b = $args[0]
            $b.ForeColor = $script:_ptzColorDim
            $b.BackColor = $script:_ptzBackDim
            $b.Font = $script:_ptzFontNorm
        })
    $parent.Controls.Add($btn)
    $btn.BringToFront()
    $script:_wpfShellPtzButtons.Add($btn)
    return $btn
}

function Update-WpfShellPtzLayout($parent) {
    # D-pad + zoom in the lower-right corner, scaled by DPI (WinForms children aren't auto-scaled
    # inside a WindowsFormsHost) and re-run whenever the video container is resized.
    try {
        $s = 1.0
        try { $s = [double](Get-WpfShellPxScale) } catch {}
        $cw = $parent.ClientSize.Width; $ch = $parent.ClientSize.Height
        if ($cw -lt 100 -or $ch -lt 80) { return }
        $m = [int](14 * $s); $w = [int](40 * $s); $h = [int](30 * $s); $z = [int](26 * $s)
        $gap = [int](2 * $s); $rowGap = [int](8 * $s)
        $zoomX = $cw - $m - $z
        $dpadRight = $zoomX - [int](8 * $s)
        $rightX = $dpadRight - $w
        $midX = $rightX - $w - $gap
        $leftX = $midX - $w - $gap
        $upY = $ch - $m - (2 * $h + $rowGap)
        $downY = $upY + $h + $rowGap
        $midY = $upY + [int](($h + $rowGap) / 2)
        $zoomY1 = $upY + [int]((2 * $h + $rowGap) / 2) - $z - $gap
        $zoomY2 = $zoomY1 + $z + 2 * $gap
        $place = @{
            up    = @($midX, $upY, $w, $h)
            down  = @($midX, $downY, $w, $h)
            left  = @($leftX, $midY, $w, $h)
            right = @($rightX, $midY, $w, $h)
            zin   = @($zoomX, $zoomY1, $z, $z)
            zout  = @($zoomX, $zoomY2, $z, $z)
        }
        foreach ($b in $script:_wpfShellPtzButtons) {
            if ($b.IsDisposed -or -not $place.ContainsKey($b.Name)) { continue }
            $r = $place[$b.Name]
            $b.SetBounds([int]$r[0], [int]$r[1], [int]$r[2], [int]$r[3])
        }
    }
    catch {}
}

function Get-WpfShellAfMap {
    # The AF engine keeps $script:afRoi / $script:afClickPt in the main preview panel's pixel space;
    # this maps that space onto the shell's video container (and back) with simple scale factors.
    $c = $script:_wpfShellCamPanel; $pp = $script:pPreview
    if (-not $c -or $c.IsDisposed -or -not $pp -or $pp.IsDisposed -or $pp.Width -lt 50 -or $pp.Height -lt 50) { return $null }
    return @{ SX = ($c.ClientSize.Width / [double]$pp.Width); SY = ($c.ClientSize.Height / [double]$pp.Height) }
}

function ConvertTo-WpfShellAfRect($r, $m) {
    return New-Object System.Drawing.Rectangle ([int][math]::Round($r.X * $m.SX)), ([int][math]::Round($r.Y * $m.SY)), ([int][math]::Round($r.Width * $m.SX)), ([int][math]::Round($r.Height * $m.SY))
}

function ConvertFrom-WpfShellAfRect($r, $m) {
    return (_AFRect ([int][math]::Round($r.X / $m.SX)) ([int][math]::Round($r.Y / $m.SY)) ([int][math]::Round($r.Width / $m.SX)) ([int][math]::Round($r.Height / $m.SY)))
}

function Get-WpfShellAfHandleRects($r) {
    $s = 1.0
    try { $s = [double](Get-WpfShellPxScale) } catch {}
    $h = [int](9 * $s); $half = [int]($h / 2)
    return @(
        (_AFRect ($r.Left - $half) ($r.Top - $half) $h $h),
        (_AFRect ($r.Right - $half) ($r.Top - $half) $h $h),
        (_AFRect ($r.Left - $half) ($r.Bottom - $half) $h $h),
        (_AFRect ($r.Right - $half) ($r.Bottom - $half) $h $h)
    )
}

function Get-WpfShellAfRegion {
    # Same shaped-region idea as the main app's Get-AfOverlayRegion: the overlay only owns the
    # pixels it draws (border, handles, crosshair, label), so the video underneath stays visible.
    $m = Get-WpfShellAfMap
    if (-not $m -or (-not $script:afEnabled -and -not $script:afRoiVisible)) { return New-Object System.Drawing.Region([System.Drawing.Rectangle]::Empty) }
    $s = 1.0
    try { $s = [double](Get-WpfShellPxScale) } catch {}
    $path = New-Object System.Drawing.Drawing2D.GraphicsPath
    $r = ConvertTo-WpfShellAfRect $script:afRoi $m
    $bw = [int](3 * $s)
    $path.AddRectangle((New-Object System.Drawing.Rectangle($r.X, $r.Y, $r.Width, $bw)))
    $path.AddRectangle((New-Object System.Drawing.Rectangle($r.X, ($r.Bottom - $bw), $r.Width, $bw)))
    $path.AddRectangle((New-Object System.Drawing.Rectangle($r.X, $r.Y, $bw, $r.Height)))
    $path.AddRectangle((New-Object System.Drawing.Rectangle(($r.Right - $bw), $r.Y, $bw, $r.Height)))
    if ($script:afRoiVisible) {
        foreach ($hRect in (Get-WpfShellAfHandleRects $r)) { $path.AddRectangle($hRect) }
    }
    if ($script:afEnabled) {
        $rcx = $r.X + [int]($r.Width / 2); $rcy = $r.Y + [int]($r.Height / 2)
        $path.AddRectangle((New-Object System.Drawing.Rectangle($r.X, ($rcy - 1), $r.Width, 2)))
        $path.AddRectangle((New-Object System.Drawing.Rectangle(($rcx - 1), $r.Y, 2, $r.Height)))
        if ($script:afClickPt) {
            $cx = [int][math]::Round($script:afClickPt.X * $m.SX); $cy = [int][math]::Round($script:afClickPt.Y * $m.SY)
            $path.AddRectangle((New-Object System.Drawing.Rectangle(($cx - 9), ($cy - 2), 18, 4)))
            $path.AddRectangle((New-Object System.Drawing.Rectangle(($cx - 2), ($cy - 9), 4, 18)))
        }
        $path.AddRectangle((New-Object System.Drawing.Rectangle($r.X, $r.Y, [int](100 * $s), [int](22 * $s))))
    }
    return New-Object System.Drawing.Region($path)
}

function Update-WpfShellAfOverlay {
    # Re-shapes and repaints the overlay only when something it shows has changed.
    $ov = $script:_wpfShellAfOverlay
    if (-not $ov -or $ov.IsDisposed) { return }
    try {
        $c = $script:_wpfShellCamPanel
        $moving = ($script:afPanPulses -ne 0 -or $script:afTiltPulses -ne 0)
        $sig = "$($script:afEnabled)|$($script:afRoiVisible)|$($script:afRoi)|$($script:afClickPt)|$moving|$($c.ClientSize)|$($script:pPreview.Size)"
        if ($sig -eq $script:_wpfShellAfSig) { return }
        $script:_wpfShellAfSig = $sig
        $old = $ov.Region
        $ov.Region = Get-WpfShellAfRegion
        if ($old) { try { $old.Dispose() } catch {} }
        $ov.Invalidate()
    }
    catch {}
}

function Show-WpfShellAfPaint($e) {
    if (-not $script:afEnabled -and -not $script:afRoiVisible) { return }
    $m = Get-WpfShellAfMap
    if (-not $m) { return }
    try {
        $g = $e.Graphics
        $s = 1.0
        try { $s = [double](Get-WpfShellPxScale) } catch {}
        $r = ConvertTo-WpfShellAfRect $script:afRoi $m
        # Fill exactly the pixels the shaped region keeps (see Get-WpfShellAfRegion), so nothing
        # is left as the overlay's black background.
        $bw = [int](3 * $s)
        $green = [System.Drawing.Brushes]::LimeGreen
        $g.FillRectangle($green, $r.X, $r.Y, $r.Width, $bw)
        $g.FillRectangle($green, $r.X, ($r.Bottom - $bw), $r.Width, $bw)
        $g.FillRectangle($green, $r.X, $r.Y, $bw, $r.Height)
        $g.FillRectangle($green, ($r.Right - $bw), $r.Y, $bw, $r.Height)
        foreach ($hRect in (Get-WpfShellAfHandleRects $r)) { if ($script:afRoiVisible) { $g.FillRectangle($green, $hRect) } }
        if (-not $script:afEnabled) { return }
        $rcx = $r.X + [int]($r.Width / 2); $rcy = $r.Y + [int]($r.Height / 2)
        $guide = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(0, 140, 0))
        try {
            $g.FillRectangle($guide, $r.X, ($rcy - 1), $r.Width, 2)
            $g.FillRectangle($guide, ($rcx - 1), $r.Y, 2, $r.Height)
        }
        finally { $guide.Dispose() }
        if ($script:afClickPt) {
            $cx = [int][math]::Round($script:afClickPt.X * $m.SX); $cy = [int][math]::Round($script:afClickPt.Y * $m.SY)
            $g.FillRectangle([System.Drawing.Brushes]::Red, ($cx - 9), ($cy - 2), 18, 4)
            $g.FillRectangle([System.Drawing.Brushes]::Red, ($cx - 2), ($cy - 9), 4, 18)
        }
        $moving = ($script:afPanPulses -ne 0 -or $script:afTiltPulses -ne 0)
        $lColor = if ($moving) { [System.Drawing.Brushes]::Yellow } else { [System.Drawing.Brushes]::LimeGreen }
        $lText = if ($moving) { 'AF: MOVING' } else { 'AF: READY' }
        $g.DrawString($lText, $script:_ptzFontNorm, $lColor, ($r.X + 4), ($r.Y + 4))
    }
    catch {}
}

function New-WpfShellAfControl($parent, [string]$kind, [string]$name, [string]$text, [double[]]$rect, [string]$mainVar) {
    # Small AF buttons / speed label in the top-left corner, mirroring the main app's AF controls.
    $s = 1.0
    try { $s = [double](Get-WpfShellPxScale) } catch {}
    if ($kind -eq 'label') { $ctl = New-Object System.Windows.Forms.Label; $ctl.TextAlign = 'MiddleCenter' }
    else {
        $ctl = New-Object System.Windows.Forms.Button
        $ctl.FlatStyle = 'Flat'
        $ctl.FlatAppearance.BorderSize = 1
        $ctl.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(90, 90, 90)
        $ctl.Cursor = [System.Windows.Forms.Cursors]::Hand
        $ctl.TabStop = $false
    }
    $ctl.Name = $name
    $ctl.Text = $text
    $ctl.Tag = $mainVar
    $ctl.Font = New-Object System.Drawing.Font('Segoe UI', ([float](7.5 * $script:_wpfShellUiScale)), [System.Drawing.FontStyle]::Bold)
    $ctl.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $ctl.ForeColor = [System.Drawing.Color]::FromArgb(200, 200, 200)
    $ctl.SetBounds([int]($rect[0] * $s), [int]($rect[1] * $s), [int]($rect[2] * $s), [int]($rect[3] * $s))
    $ctl.Visible = $false
    if ($kind -eq 'button') {
        # Drives the main app's real AF control of the same name, so state and behavior stay shared.
        $ctl.Add_Click({
                try {
                    $target = Get-Variable -Name ([string]$args[0].Tag) -Scope Script -ValueOnly -ErrorAction Stop
                    if ($target -and -not $target.IsDisposed) { $target.PerformClick() }
                }
                catch {}
            })
    }
    $parent.Controls.Add($ctl)
    $ctl.BringToFront()
    $script:_wpfShellAfCtls.Add($ctl)
    return $ctl
}

function Initialize-JwlCursorGuard {
    # The live video is drawn by a native VLC window (often on its own thread) that answers every WM_SETCURSOR with the
    # arrow, so setting the cursor from a timer only works between mouse moves ("sometimes crosshair"). This hooks the
    # window threads and re-applies the crosshair / move cursor right after the window has handled WM_SETCURSOR, while
    # the AF poll says the mouse is inside the ROI. Mode: 0 = leave alone, 1 = crosshair, 2 = move.
    if ('JwlCursorGuard' -as [type]) { return $true }
    try {
        Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class JwlCursorGuard {
    sealed class Zone { public int Mode, L, T, R, B; }
    delegate IntPtr HookProc(int code, IntPtr w, IntPtr l);
    delegate bool EnumProc(IntPtr h, IntPtr l);
    [StructLayout(LayoutKind.Sequential)]
    struct CWPRETSTRUCT { public IntPtr lResult; public IntPtr lParam; public IntPtr wParam; public uint message; public IntPtr hwnd; }
    [StructLayout(LayoutKind.Sequential)]
    struct POINT { public int X, Y; }
    [DllImport("user32.dll")] static extern IntPtr SetWindowsHookEx(int id, HookProc p, IntPtr mod, uint tid);
    [DllImport("user32.dll")] static extern bool UnhookWindowsHookEx(IntPtr h);
    [DllImport("user32.dll")] static extern IntPtr CallNextHookEx(IntPtr h, int c, IntPtr w, IntPtr l);
    [DllImport("user32.dll")] static extern IntPtr SetCursor(IntPtr c);
    [DllImport("user32.dll")] static extern IntPtr LoadCursor(IntPtr inst, IntPtr name);
    [DllImport("user32.dll")] static extern bool EnumChildWindows(IntPtr p, EnumProc cb, IntPtr l);
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
    [DllImport("user32.dll")] static extern bool GetCursorPos(out POINT p);
    [DllImport("user32.dll")] static extern bool IsChild(IntPtr parent, IntPtr wnd);
    [DllImport("user32.dll")] static extern short GetAsyncKeyState(int vKey);
    [DllImport("user32.dll")] static extern IntPtr WindowFromPoint(POINT p);
    // Physical left-button state, independent of which thread's message queue received the click.
    public static bool LeftDown() { return (GetAsyncKeyState(0x01) & 0x8000) != 0; }
    // True only when the window directly under the mouse is 'root' or one of its children, i.e. nothing else (such as the
    // Settings dialog) is covering that spot. The ROI zone is just a screen rectangle, so without this it also reacts
    // through windows that sit on top of it.
    public static bool IsOver(IntPtr root) {
        POINT p;
        if (!GetCursorPos(out p)) return false;
        IntPtr h = WindowFromPoint(p);
        if (h == IntPtr.Zero) return false;
        return h == root || IsChild(root, h);
    }
    static readonly HookProc Proc = Callback;
    static readonly Dictionary<uint, IntPtr> Hooks = new Dictionary<uint, IntPtr>();
    static IntPtr cross = LoadCursor(IntPtr.Zero, (IntPtr)32515);
    static IntPtr move = LoadCursor(IntPtr.Zero, (IntPtr)32646);
    static volatile Zone Cur = new Zone();
    static volatile HashSet<IntPtr> Excl = new HashSet<IntPtr>();
    static IntPtr Root = IntPtr.Zero;
    // mode: 0 = leave alone, 1 = crosshair inside the rectangle, 2 = move cursor inside the rectangle, 3 = move cursor everywhere (dragging).
    // The rectangle is in screen pixels. The hook itself checks the mouse position, so the cursor stays right even when the UI thread is busy.
    public static void SetZone(int mode, int l, int t, int r, int b) {
        Zone z = new Zone(); z.Mode = mode; z.L = l; z.T = t; z.R = r; z.B = b; Cur = z;
    }
    public static void SetExcluded(IntPtr[] handles) {
        HashSet<IntPtr> s = new HashSet<IntPtr>();
        foreach (IntPtr h in handles) s.Add(h);
        Excl = s;
    }
    static IntPtr Callback(int code, IntPtr w, IntPtr l) {
        try {
            Zone z = Cur;
            if (code >= 0 && z.Mode != 0) {
                CWPRETSTRUCT m = (CWPRETSTRUCT)Marshal.PtrToStructure(l, typeof(CWPRETSTRUCT));
                if (m.message == 0x20 && (((long)m.lParam) & 0xFFFF) == 1) {
                    IntPtr under = m.wParam;
                    IntPtr root = Root;
                    if (root != IntPtr.Zero && (under == root || IsChild(root, under)) && !Excl.Contains(under)) {
                        bool apply = (z.Mode == 3);
                        if (!apply) {
                            POINT p;
                            if (GetCursorPos(out p)) apply = (p.X >= z.L && p.X < z.R && p.Y >= z.T && p.Y < z.B);
                        }
                        if (apply) SetCursor(z.Mode == 1 ? cross : move);
                    }
                }
            }
        } catch { }
        return CallNextHookEx(IntPtr.Zero, code, w, l);
    }
    public static int Attach(IntPtr root) {
        Root = root;
        HashSet<uint> tids = new HashSet<uint>();
        uint p;
        tids.Add(GetWindowThreadProcessId(root, out p));
        EnumChildWindows(root, delegate(IntPtr h, IntPtr x) { uint q; tids.Add(GetWindowThreadProcessId(h, out q)); return true; }, IntPtr.Zero);
        int added = 0;
        lock (Hooks) {
            foreach (uint t in tids) {
                if (Hooks.ContainsKey(t)) continue;
                IntPtr hk = SetWindowsHookEx(12, Proc, IntPtr.Zero, t);
                if (hk != IntPtr.Zero) { Hooks[t] = hk; added++; }
            }
        }
        return added;
    }
    public static void Detach() {
        Cur = new Zone();
        lock (Hooks) { foreach (KeyValuePair<uint, IntPtr> kv in Hooks) UnhookWindowsHookEx(kv.Value); Hooks.Clear(); }
    }
}
'@
        return $true
    }
    catch { try { Log "AF cursor guard could not start: $_" } catch {}; return $false }
}

function Step-WpfShellAf {
    # 30 ms tick: mirror AF state onto the shell's controls and handle ROI mouse editing. The video
    # is a native window that swallows mouse messages, so (like the main app) the mouse is polled.
    $c = $script:_wpfShellCamPanel
    if (-not $c -or $c.IsDisposed) { return }
    try {
        # The ROI confirm panel closes by itself once the ROI is no longer in setup (e.g. confirmed from another place).
        try { if ($script:_wpfAfRoiPopup -and $script:_wpfAfRoiPopup.IsOpen -and -not $script:afRoiVisible) { $script:_wpfAfRoiPopup.IsOpen = $false } } catch {}
        # Mirror the main AF controls (visible only while the Speaker scene is live).
        foreach ($ctl in $script:_wpfShellAfCtls) {
            if ($ctl.IsDisposed) { continue }
            $src = $null
            try { $src = Get-Variable -Name ([string]$ctl.Tag) -Scope Script -ValueOnly -ErrorAction Stop } catch {}
            if ($src -and -not $src.IsDisposed) {
                if ($ctl.Text -ne $src.Text) { $ctl.Text = $src.Text }
                if ($ctl.BackColor -ne $src.BackColor) { $ctl.BackColor = $src.BackColor }
                if ($ctl.ForeColor -ne $src.ForeColor) { $ctl.ForeColor = $src.ForeColor }
            }
            $show = [bool]$script:afSceneActive
            if ($ctl.Visible -ne $show) { $ctl.Visible = $show }
        }

        if ($script:afEnabled -or $script:afRoiVisible) {
            # (Re)hook the video window threads about once a second - VLC creates its window some time after playback starts.
            if ([DateTime]::UtcNow -gt $script:_wpfAfHookNext) {
                $script:_wpfAfHookNext = [DateTime]::UtcNow.AddSeconds(1)
                try {
                    if ('JwlCursorGuard' -as [type]) {
                        [void][JwlCursorGuard]::Attach($c.Handle)
                        # The AF/PTZ buttons keep their own (hand) cursor.
                        $ex = New-Object System.Collections.Generic.List[IntPtr]
                        foreach ($ctl in @($script:_wpfShellAfCtls) + @($script:_wpfShellPtzButtons)) {
                            try { if ($ctl -and -not $ctl.IsDisposed -and $ctl.IsHandleCreated) { $ex.Add($ctl.Handle) } } catch {}
                        }
                        [JwlCursorGuard]::SetExcluded($ex.ToArray())
                    }
                }
                catch {}
            }
            $m = Get-WpfShellAfMap
            if ($m) {
                $leftDown = ([System.Windows.Forms.Control]::MouseButtons -band [System.Windows.Forms.MouseButtons]::Left) -ne 0
                try { if ('JwlCursorGuard' -as [type]) { $leftDown = $leftDown -or [JwlCursorGuard]::LeftDown() } } catch {}
                $pt = $c.PointToClient([System.Windows.Forms.Control]::MousePosition)
                $over = $c.ClientRectangle.Contains($pt)
                # Another window (e.g. the Settings dialog) may be covering this spot: then the ROI must not react at all.
                try { if ($over -and $c.IsHandleCreated -and ('JwlCursorGuard' -as [type]) -and -not [JwlCursorGuard]::IsOver($c.Handle)) { $over = $false } } catch {}
                # "Over a button" = over a VISIBLE AF/PTZ control. (GetChildAtPoint also returns hidden controls such as the
                # full-size "Waiting for OBS" hint label, which made every click inside the ROI count as a button click -
                # only the 2 px centre line, owned by the shaped overlay, still got through.)
                $overButton = $false
                if ($over) {
                    foreach ($b in (@($script:_wpfShellAfCtls) + @($script:_wpfShellPtzButtons))) {
                        try { if ($b -and -not $b.IsDisposed -and $b.Visible -and $b.Bounds.Contains($pt)) { $overButton = $true; break } } catch {}
                    }
                }
                $roi = ConvertTo-WpfShellAfRect $script:afRoi $m
                $handles = Get-WpfShellAfHandleRects $roi

                $cursorMode = 0
                if ($script:_wpfAfDragging -or $script:_wpfAfResizing -ge 0) { $cursorMode = 2 }
                elseif ($over -and -not $overButton) {
                    $onHandle = $false
                    if ($script:afRoiVisible) { foreach ($hRect in $handles) { if ($hRect.Contains($pt)) { $onHandle = $true; break } } }
                    if ($script:afEnabled -and -not $script:afRoiVisible -and $roi.Contains($pt)) { $cursorMode = 1; [System.Windows.Forms.Cursor]::Current = [System.Windows.Forms.Cursors]::Cross }
                    elseif ($onHandle -or ($script:afRoiVisible -and $roi.Contains($pt))) { $cursorMode = 2; [System.Windows.Forms.Cursor]::Current = [System.Windows.Forms.Cursors]::SizeAll }
                }
                # Tell the cursor guard (window-thread hook) the screen zone where the cursor must be a crosshair / move cursor.
                # The hook checks the mouse itself, so this stays right even while the UI thread is busy.
                try {
                    if ('JwlCursorGuard' -as [type]) {
                        $zMode = 0; $zr = [System.Drawing.Rectangle]::Empty
                        if ($script:_wpfAfDragging -or $script:_wpfAfResizing -ge 0) { $zMode = 3 }
                        elseif (-not $over) { $zMode = 0 }
                        elseif ($script:afRoiVisible) { $zMode = 2; $zr = $c.RectangleToScreen([System.Drawing.Rectangle]::Inflate($roi, 10, 10)) }
                        elseif ($script:afEnabled) { $zMode = 1; $zr = $c.RectangleToScreen($roi) }
                        [JwlCursorGuard]::SetZone($zMode, $zr.Left, $zr.Top, $zr.Right, $zr.Bottom)
                    }
                }
                catch {}

                if ($leftDown -and -not $script:_wpfAfWasDown -and $over) {
                    Write-ThrottledLog "af-click-diag" "AF click: pt=($($pt.X),$($pt.Y)) roi=$roi inRoi=$($roi.Contains($pt)) overButton=$overButton enabled=$($script:afEnabled) setup=$($script:afRoiVisible) drag=$($script:_wpfAfDragging) resize=$($script:_wpfAfResizing)" 1
                }
                if ($leftDown -and -not $script:_wpfAfWasDown -and $over -and -not $overButton -and -not $script:_wpfAfDragging -and $script:_wpfAfResizing -lt 0) {
                    if ($script:afRoiVisible) {
                        $idx = -1
                        for ($i = 0; $i -lt $handles.Count; $i++) { if ($handles[$i].Contains($pt)) { $idx = $i; break } }
                        if ($idx -ge 0) { $script:_wpfAfResizing = $idx; $script:_wpfAfResizeOrig = $roi }
                        elseif ($roi.Contains($pt)) {
                            $script:_wpfAfDragging = $true
                            $script:_wpfAfDragOff = New-Object System.Drawing.Point ($pt.X - $roi.X), ($pt.Y - $roi.Y)
                        }
                    }
                    elseif ($script:afEnabled -and $roi.Contains($pt)) {
                        # Same click-to-centre rule as the main app: tilt only, by vertical offset from the ROI centre.
                        $rcy = $roi.Y + $roi.Height / 2.0
                        $ndy = ($pt.Y - $rcy) / ($roi.Height / 2.0)
                        $script:afPanPulses = 0
                        $script:afTiltPulses = [int][Math]::Round($ndy * $script:afSpeed)
                        $script:afClickPt = New-Object System.Drawing.Point ($script:afRoi.X + [int]($script:afRoi.Width / 2)), ([int][math]::Round($pt.Y / $m.SY))
                        Log "AF: centering - tilt=$($script:afTiltPulses)"
                        Update-AfOverlay
                    }
                }
                elseif ($leftDown -and ($script:_wpfAfDragging -or $script:_wpfAfResizing -ge 0)) {
                    $newRoi = $null
                    if ($script:_wpfAfResizing -ge 0 -and $script:_wpfAfResizeOrig) {
                        $o = $script:_wpfAfResizeOrig
                        $nx = $o.X; $ny = $o.Y; $nw = $o.Width; $nh = $o.Height
                        if ($script:_wpfAfResizing -eq 0) { $nx = $pt.X; $ny = $pt.Y; $nw = $o.Right - $pt.X; $nh = $o.Bottom - $pt.Y }
                        if ($script:_wpfAfResizing -eq 1) { $ny = $pt.Y; $nw = $pt.X - $o.Left; $nh = $o.Bottom - $pt.Y }
                        if ($script:_wpfAfResizing -eq 2) { $nx = $pt.X; $nw = $o.Right - $pt.X; $nh = $pt.Y - $o.Top }
                        if ($script:_wpfAfResizing -eq 3) { $nw = $pt.X - $o.Left; $nh = $pt.Y - $o.Top }
                        $newRoi = New-Object System.Drawing.Rectangle $nx, $ny, $nw, $nh
                    }
                    elseif ($script:_wpfAfDragging -and $script:_wpfAfDragOff) {
                        $nx = [Math]::Max(0, [Math]::Min($pt.X - $script:_wpfAfDragOff.X, $c.ClientSize.Width - $roi.Width))
                        $ny = [Math]::Max(0, [Math]::Min($pt.Y - $script:_wpfAfDragOff.Y, $c.ClientSize.Height - $roi.Height))
                        $newRoi = New-Object System.Drawing.Rectangle $nx, $ny, $roi.Width, $roi.Height
                    }
                    if ($newRoi) {
                        $mainRoi = ConvertFrom-WpfShellAfRect $newRoi $m
                        if ($mainRoi.Width -gt 40 -and $mainRoi.Height -gt 40) {
                            $script:afRoi = $mainRoi
                            Update-AfOverlay
                        }
                    }
                }
                elseif (-not $leftDown -and $script:_wpfAfWasDown) {
                    $script:_wpfAfDragging = $false
                    $script:_wpfAfResizing = -1
                    $script:_wpfAfDragOff = $null
                    $script:_wpfAfResizeOrig = $null
                }
                $script:_wpfAfWasDown = $leftDown
            }
        }
        else {
            $script:_wpfAfDragging = $false
            $script:_wpfAfResizing = -1
            $script:_wpfAfWasDown = $false
            try { if ('JwlCursorGuard' -as [type]) { [JwlCursorGuard]::SetZone(0, 0, 0, 0, 0) } } catch {}
        }
        Update-WpfShellAfOverlay
    }
    catch {}
}

# AF/ROI overlay + the six PTZ buttons on top of a preview container panel. Used by the OBS screenshot preview so the
# controls are available in every preview mode, not only with the live camera feed.
function Add-WpfShellControlLayer($panel) {
    $afOverlay = New-Object System.Windows.Forms.Panel
    $afOverlay.Dock = 'Fill'
    $afOverlay.BackColor = [System.Drawing.Color]::Black
    $afOverlay.Region = New-Object System.Drawing.Region([System.Drawing.Rectangle]::Empty)
    $afOverlay.Add_Paint({ param($snd, $pe) Show-WpfShellAfPaint $pe })
    $panel.Controls.Add($afOverlay)
    $afOverlay.BringToFront()
    $script:_wpfShellAfOverlay = $afOverlay
    $script:_wpfShellAfSig = ''
    $script:_wpfShellAfCtls.Clear()
    $script:_wpfAfDragging = $false; $script:_wpfAfResizing = -1; $script:_wpfAfWasDown = $false
    $script:_wpfShellPtzButtons.Clear()
    New-WpfShellPtzButton $panel 'up'    ([string][char]0x25B2) 'OBS_KEY_UP'       | Out-Null
    New-WpfShellPtzButton $panel 'down'  ([string][char]0x25BC) 'OBS_KEY_DOWN'     | Out-Null
    New-WpfShellPtzButton $panel 'left'  ([string][char]0x25C4) 'OBS_KEY_LEFT'     | Out-Null
    New-WpfShellPtzButton $panel 'right' ([string][char]0x25BA) 'OBS_KEY_RIGHT'    | Out-Null
    New-WpfShellPtzButton $panel 'zin'   '+'                    'OBS_KEY_NUMPLUS'  | Out-Null
    New-WpfShellPtzButton $panel 'zout'  ([string][char]0x2212) 'OBS_KEY_NUMMINUS' | Out-Null
}

# Hover timer (PTZ buttons only while the pointer is over the preview) and the AF mouse/ROI timer.
function Start-WpfShellControlTimers {
    if ($script:_wpfShellPtzHoverTimer) { try { $script:_wpfShellPtzHoverTimer.Stop(); $script:_wpfShellPtzHoverTimer.Dispose() } catch {} }
    $script:_wpfShellPtzHoverTimer = New-Object System.Windows.Forms.Timer
    $script:_wpfShellPtzHoverTimer.Interval = 100
    $script:_wpfShellPtzHoverTimer.Add_Tick({
            try {
                Update-WpfShellHint
                $pnl = $script:_wpfShellCamPanel
                if ($pnl -and -not $pnl.IsDisposed -and $pnl.IsHandleCreated) {
                    $sr = $pnl.RectangleToScreen($pnl.ClientRectangle)
                    $inside = $sr.Contains([System.Windows.Forms.Control]::MousePosition)
                    foreach ($b in $script:_wpfShellPtzButtons) { if (-not $b.IsDisposed) { $b.Visible = $inside } }
                    Update-OnlyTHover $inside
                }
            }
            catch {}
        })
    $script:_wpfShellPtzHoverTimer.Start()

    $script:_wpfAfHookNext = [DateTime]::MinValue
    try { [void](Initialize-JwlCursorGuard) } catch {}
    if ($script:_wpfShellAfTimer) { try { $script:_wpfShellAfTimer.Stop(); $script:_wpfShellAfTimer.Dispose() } catch {} }
    $script:_wpfShellAfTimer = New-Object System.Windows.Forms.Timer
    $script:_wpfShellAfTimer.Interval = 30
    $script:_wpfShellAfTimer.Add_Tick({ Step-WpfShellAf })
    $script:_wpfShellAfTimer.Start()
}

# Removes the OBS screenshot host (and its controls/timers) before the live camera takes its place.
function Clear-WpfShellObsPreviewHost {
    try { if ($script:_wpfShellObsSyncTimer) { $script:_wpfShellObsSyncTimer.Stop(); $script:_wpfShellObsSyncTimer.Dispose() } } catch {}
    $script:_wpfShellObsSyncTimer = $null
    try { if ($script:_wpfShellObsPreview) { $script:_wpfShellObsPreview.Image = $null } } catch {}
    $script:_wpfShellObsPreview = $null
    try { Stop-PTZRepeat } catch {}
    try { if ('JwlCursorGuard' -as [type]) { [JwlCursorGuard]::Detach() } } catch {}
    try { if ($script:_wpfShellPtzHoverTimer) { $script:_wpfShellPtzHoverTimer.Stop(); $script:_wpfShellPtzHoverTimer.Dispose() } } catch {}
    $script:_wpfShellPtzHoverTimer = $null
    try { if ($script:_wpfShellAfTimer) { $script:_wpfShellAfTimer.Stop(); $script:_wpfShellAfTimer.Dispose() } } catch {}
    $script:_wpfShellAfTimer = $null
    try { $script:_wpfShellPtzButtons.Clear() } catch {}
    try { $script:_wpfShellAfCtls.Clear() } catch {}
    $script:_wpfShellAfOverlay = $null
    $script:_wpfShellHintLabel = $null
    $script:_wpfAfDragging = $false; $script:_wpfAfResizing = -1; $script:_wpfAfWasDown = $false
    $obsHost = $script:_wpfShellObsHost
    try {
        if ($script:_wpfShellWindow) {
            $hb = $script:_wpfShellWindow.FindName('CameraHostBorder')
            if ($hb -and $obsHost -and [object]::ReferenceEquals($hb.Child, $obsHost)) { $hb.Child = $null }
        }
    }
    catch {}
    try { if ($obsHost) { $obsHost.Dispose() } } catch {}
    $script:_wpfShellObsHost = $null
    $script:_wpfShellCamPanel = $null
    $script:_wpfShellObsLoading = $false
}

function Ensure-WpfShellObsPreviewHost {
    # The WPF shell must show the same OBS screenshot preview as the classic form when camera mode is off.
    # If the shell is already hosting a live camera feed, leave it alone.
    if ($script:_wpfShellCamActive) { return }
    if (-not $script:_wpfShellWindow) { return }
    $hostBorder = $script:_wpfShellWindow.FindName('CameraHostBorder')
    if (-not $hostBorder) { return }
    if (-not (Initialize-WpfShellFormsIntegration)) { return }

    if (-not $script:_wpfShellObsHost -or $hostBorder.Child -ne $script:_wpfShellObsHost) {
        $panel = New-Object System.Windows.Forms.Panel
        $panel.Dock = 'Fill'
        $panel.BackColor = [System.Drawing.Color]::Black

        $pic = New-Object System.Windows.Forms.PictureBox
        $pic.Dock = 'Fill'
        $pic.SizeMode = 'Zoom'
        $pic.BackColor = [System.Drawing.Color]::Black
        $pic.BorderStyle = [System.Windows.Forms.BorderStyle]::None
        $panel.Controls.Add($pic)
        $script:_wpfShellObsPreview = $pic

        $hint = New-Object System.Windows.Forms.Label
        $hint.Dock = 'Fill'
        $hint.TextAlign = 'MiddleCenter'
        $hint.BackColor = [System.Drawing.Color]::Black
        $hint.ForeColor = [System.Drawing.Color]::FromArgb(176, 176, 176)
        $hint.Font = New-Object System.Drawing.Font('Segoe UI', 11)
        $hint.Text = 'Waiting for OBS...'
        $hint.Visible = (-not $script:ObsConnected)
        $panel.Controls.Add($hint)
        $hint.BringToFront()
        $script:_wpfShellHintLabel = $hint

        # AF/ROI overlay and the PTZ buttons, exactly as with the live camera
        $panel.Add_SizeChanged({ param($pnl, $pnlArgs) Update-WpfShellPtzLayout $pnl })
        Add-WpfShellControlLayer $panel

        $wfHostObs = New-Object System.Windows.Forms.Integration.WindowsFormsHost
        $wfHostObs.Child = $panel
        $hostBorder.Child = $wfHostObs
        $script:_wpfShellObsHost = $wfHostObs
        $script:_wpfShellCamPanel = $panel
        Start-WpfShellControlTimers

        # Keeps the hint label and the picture in step with the main OBS preview (no camera timer runs in this mode).
        if ($script:_wpfShellObsSyncTimer) { try { $script:_wpfShellObsSyncTimer.Stop(); $script:_wpfShellObsSyncTimer.Dispose() } catch {} }
        $script:_wpfShellObsSyncTimer = New-Object System.Windows.Forms.Timer
        $script:_wpfShellObsSyncTimer.Interval = 100
        $script:_wpfShellObsSyncTick = 0
        $script:_wpfShellObsSyncTimer.Add_Tick({
                try {
                    $script:_wpfShellObsSyncTick++
                    $pic = $script:_wpfShellObsPreview
                    if ($pic -and -not $pic.IsDisposed -and $script:pbObs -and -not $script:pbObs.IsDisposed) {
                        if (-not [object]::ReferenceEquals($pic.Image, $script:pbObs.Image)) { $pic.Image = $script:pbObs.Image }
                    }
                    Update-WpfShellHint
                    # Hide the hint as soon as a real frame is showing, regardless of the connected flag.
                    $lbl = $script:_wpfShellHintLabel
                    if ($lbl -and -not $lbl.IsDisposed -and $pic -and $pic.Image -and $lbl.Visible) { $lbl.Visible = $false }
                    if ($script:_wpfShellObsSyncTick -eq 30 -or $script:_wpfShellObsSyncTick -eq 100) {
                        $hasMain = [bool]($script:pbObs -and -not $script:pbObs.IsDisposed -and $script:pbObs.Image)
                        $hasShell = [bool]($pic -and $pic.Image)
                        $workerOn = [bool]($script:obsWorkerPS -and $script:obsWorkerAsync -and -not $script:obsWorkerAsync.IsCompleted)
                        $timerOn = [bool]($script:obsTimer -and $script:obsTimer.Enabled)
                        $gotBytes = [bool]($script:obsShared -and $script:obsShared.LatestBytes)
                        Log "WPF shell preview: OBS diag - connected=$($script:ObsConnected) mainImage=$hasMain shellImage=$hasShell worker=$workerOn obsTimer=$timerOn pendingBytes=$gotBytes hintVisible=$($lbl.Visible)"
                    }
                }
                catch { try { Log "WPF shell preview: OBS sync tick failed: $_" } catch {} }
            })
        $script:_wpfShellObsSyncTimer.Start()
        Log 'WPF shell preview: OBS screenshot preview host attached'
    }
    Update-WpfShellHint
}

function Update-WpfShellHint {
    # Mirrors the classic preview's hint label: shown while OBS isn't connected, using the
    # main app's own text ("Waiting for OBS...", or the "waiting for WebSocket on host:port" variant).
    # While the camera engine is still loading it says so (until a screenshot is available to show).
    $lbl = $script:_wpfShellHintLabel
    if (-not $lbl -or $lbl.IsDisposed) { return }
    $loading = [bool]($script:_wpfShellObsLoading -and -not $script:_wpfShellCamActive -and $script:_wpfShellObsPreview -and -not $script:_wpfShellObsPreview.Image)
    $show = (-not $script:ObsConnected) -or $loading
    if ($lbl.Visible -ne $show) { $lbl.Visible = $show }
    if ($show) {
        $t = ''
        if ($loading -and $script:ObsConnected) { $t = 'Starting camera preview...' }
        else { try { $t = [string]$script:lblHint.Text } catch {} }
        if ([string]::IsNullOrWhiteSpace($t)) { $t = 'Waiting for OBS...' }
        if ($lbl.Text -ne $t) { $lbl.Text = $t }
    }
}

function Update-WpfShellVideoShift($pnl) {
    # Nudges the picture left inside the preview frame: the video panel is made wider by twice the shift and
    # moved left by twice the shift, so the (centred, never stretched) picture ends up shifted left by exactly
    # $script:_wpfShellVideoShiftDip. The part pushed past the frame is simply clipped.
    $v = $script:_wpfShellVideoPanel
    if (-not $v -or $v.IsDisposed -or -not $pnl -or $pnl.IsDisposed) { return }
    try {
        $cw = $pnl.ClientSize.Width; $ch = $pnl.ClientSize.Height
        if ($cw -lt 50 -or $ch -lt 50) { return }
        $d = [int][math]::Round([double]$script:_wpfShellVideoShiftDip * (Get-WpfShellPxScale))
        $v.SetBounds((-2 * $d), 0, ($cw + 2 * $d), $ch)
    }
    catch {}
}

function Show-WpfShellPreviewPlaceholder {
    # Shown in the preview frame from the moment the window opens until the camera engine has loaded
    # (that load blocks the UI thread for several seconds). Pure WPF, so its progress bar keeps animating on the render thread.
    try {
        if (-not $script:_wpfShellWindow) { return }
        if (-not [bool]$script:Cfg.OBS.PreviewUseCamera) { return }
        $hb = $script:_wpfShellWindow.FindName('CameraHostBorder')
        if (-not $hb -or $hb.Child) { return }

        $bg = New-Object System.Windows.Media.LinearGradientBrush
        $bg.StartPoint = New-Object System.Windows.Point(0, 0)
        $bg.EndPoint = New-Object System.Windows.Point(1, 1)
        [void]$bg.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromRgb(8, 18, 36)), 0.0))
        [void]$bg.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromRgb(20, 52, 96)), 0.55))
        [void]$bg.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromRgb(10, 24, 48)), 1.0))

        $title = New-Object System.Windows.Controls.TextBlock
        $title.Text = 'Building preview and plugins...'
        $title.FontSize = 20
        $title.FontWeight = [System.Windows.FontWeights]::SemiBold
        $title.Foreground = [System.Windows.Media.Brushes]::White
        $title.HorizontalAlignment = 'Center'

        $sub = New-Object System.Windows.Controls.TextBlock
        $sub.Text = 'Starting the camera engine - the live picture appears in a few seconds'
        $sub.FontSize = 12
        $sub.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(176, 190, 210))
        $sub.HorizontalAlignment = 'Center'
        $sub.Margin = New-Object System.Windows.Thickness(0, 6, 0, 14)

        $bar = New-Object System.Windows.Controls.ProgressBar
        $bar.IsIndeterminate = $true
        $bar.Width = 240
        $bar.Height = 4
        $bar.BorderThickness = New-Object System.Windows.Thickness(0)
        $bar.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromArgb(60, 255, 255, 255))
        $bar.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(0, 140, 255))

        $stack = New-Object System.Windows.Controls.StackPanel
        $stack.VerticalAlignment = 'Center'
        $stack.HorizontalAlignment = 'Center'
        [void]$stack.Children.Add($title)
        [void]$stack.Children.Add($sub)
        [void]$stack.Children.Add($bar)

        $card = New-Object System.Windows.Controls.Border
        $card.CornerRadius = New-Object System.Windows.CornerRadius(8)
        $card.Background = $bg
        $card.Child = $stack

        $hb.Child = $card
        $script:_wpfShellPlaceholder = $card
    }
    catch { try { Log "WPF shell preview: placeholder failed: $_" } catch {} }
}

function Clear-WpfShellPreviewPlaceholder {
    try {
        if ($script:_wpfShellPlaceholder -and $script:_wpfShellWindow) {
            $hb = $script:_wpfShellWindow.FindName('CameraHostBorder')
            if ($hb -and [object]::ReferenceEquals($hb.Child, $script:_wpfShellPlaceholder)) { $hb.Child = $null }
        }
    }
    catch {}
    $script:_wpfShellPlaceholder = $null
}

function Start-WpfShellCameraPreview {
    if ($script:_wpfShellCamActive) { return }
    if (-not $script:_wpfShellWindow) { return }
    if (-not [bool]$script:Cfg.OBS.PreviewUseCamera) {
        Ensure-WpfShellObsPreviewHost
        return
    }
    if ([string]::IsNullOrWhiteSpace($script:Cfg.OBS.PreviewCameraName)) {
        Log "WPF shell preview: camera - no camera selected in Settings"
        Ensure-WpfShellObsPreviewHost
        return
    }
    if (-not (Initialize-WpfShellFormsIntegration)) { Clear-WpfShellPreviewPlaceholder; return }
    if (-not $script:VlcAvailable -and (Test-LibVlcPreloadBusy)) {
        # The video engine is still being prepared in the background: wait for it (the preload handler restarts
        # the preview when it is ready) instead of loading or downloading it here on the UI thread.
        $script:_vlcPreloadCameraDeferred = $true
        Log 'WPF shell preview: camera - waiting for the background engine load'
        # Meanwhile show the preview frame WITH its PTZ / AF controls instead of a bare placeholder
        $script:_wpfShellObsLoading = $true
        Ensure-WpfShellObsPreviewHost
        return
    }
    if (-not (Initialize-LibVLC)) {
        Log "WPF shell preview: camera - LibVLC not available"
        Clear-WpfShellPreviewPlaceholder
        Ensure-WpfShellObsPreviewHost
        return
    }
    if (-not (Test-DShowPluginAvailable)) { Clear-WpfShellPreviewPlaceholder; Ensure-WpfShellObsPreviewHost; return }

    $hostBorder = $script:_wpfShellWindow.FindName('CameraHostBorder')
    if (-not $hostBorder) { return }

    # The screenshot host (with its controls) is replaced by the live camera host below
    if ($script:_wpfShellObsHost) { Clear-WpfShellObsPreviewHost }

    $panel = $null
    $mp = $null
    try {
        # Deliberately an INDEPENDENT LibVLC instance/MediaPlayer/panel from the main app's live
        # production preview ($script:_camLibVLC / $script:_camMediaPlayer / $script:pLivePreview).
        # This proves the WindowsFormsHost interop pattern works end-to-end without ever touching,
        # pausing, or disturbing the production camera feed shown in the real app.
        $panel = New-Object System.Windows.Forms.Panel
        $panel.BackColor = [System.Drawing.Color]::Black
        # The live video is a native child window (WPF can't clip it), so round it with a GDI region.
        $panel.Add_SizeChanged({
                param($pnl, $pnlArgs)
                try {
                    $pw = $pnl.Width; $ph = $pnl.Height
                    if ($pw -lt 40 -or $ph -lt 40) { return }
                    $d = 22
                    try { $d = [int][math]::Round(16 * (Get-WpfShellPxScale)) } catch {}
                    $gp = New-Object System.Drawing.Drawing2D.GraphicsPath
                    $gp.AddArc(0, 0, $d, $d, 180, 90)
                    $gp.AddArc($pw - $d, 0, $d, $d, 270, 90)
                    $gp.AddArc($pw - $d, $ph - $d, $d, $d, 0, 90)
                    $gp.AddArc(0, $ph - $d, $d, $d, 90, 90)
                    $gp.CloseFigure()
                    $pnl.Region = New-Object System.Drawing.Region($gp)
                    $gp.Dispose()
                }
                catch {}
            })

        $panel.Add_SizeChanged({ param($pnl, $pnlArgs) Update-WpfShellPtzLayout $pnl; Update-WpfShellVideoShift $pnl })

        # The native video lives in its own panel; the PTZ buttons are siblings above it.
        $video = New-Object System.Windows.Forms.Panel
        $script:_wpfShellVideoPanel = $video
        $video.Dock = 'None'
        $video.BackColor = [System.Drawing.Color]::Black
        $panel.Controls.Add($video)
        Update-WpfShellVideoShift $panel

        # Same "Waiting for OBS..." hint the classic preview shows while OBS isn't connected (see Update-WpfShellHint).
        $hintLbl = New-Object System.Windows.Forms.Label
        $hintLbl.Dock = 'Fill'
        $hintLbl.TextAlign = 'MiddleCenter'
        $hintLbl.BackColor = [System.Drawing.Color]::Black
        $hintLbl.ForeColor = [System.Drawing.Color]::FromArgb(176, 176, 176)
        $hintLbl.Font = New-Object System.Drawing.Font('Segoe UI', 11)
        $hintLbl.Text = 'Waiting for OBS...'
        $hintLbl.Visible = (-not $script:ObsConnected)
        $panel.Controls.Add($hintLbl)
        $hintLbl.BringToFront()
        $script:_wpfShellHintLabel = $hintLbl

        # AF/ROI overlay (shaped region, drawn above the video) and the AF buttons in the top-left.
        $afOverlay = New-Object System.Windows.Forms.Panel
        $afOverlay.Dock = 'Fill'
        $afOverlay.BackColor = [System.Drawing.Color]::Black
        $afOverlay.Region = New-Object System.Drawing.Region([System.Drawing.Rectangle]::Empty)
        $afOverlay.Add_Paint({ param($snd, $pe) Show-WpfShellAfPaint $pe })
        $panel.Controls.Add($afOverlay)
        $afOverlay.BringToFront()
        $script:_wpfShellAfOverlay = $afOverlay
        $script:_wpfShellAfSig = ''
        $script:_wpfShellAfCtls.Clear()
        $script:_wpfAfDragging = $false; $script:_wpfAfResizing = -1; $script:_wpfAfWasDown = $false
        # The AF buttons (AF on/off, Set ROI, speed, info) no longer sit on the preview: they live in the AF button
        # next to the V-Cam button (left-click = AF on/off, right-click = menu). Only the ROI drawing stays here.
        $script:_wpfShellPtzButtons.Clear()
        New-WpfShellPtzButton $panel 'up'    ([string][char]0x25B2) 'OBS_KEY_UP'       | Out-Null
        New-WpfShellPtzButton $panel 'down'  ([string][char]0x25BC) 'OBS_KEY_DOWN'     | Out-Null
        New-WpfShellPtzButton $panel 'left'  ([string][char]0x25C4) 'OBS_KEY_LEFT'     | Out-Null
        New-WpfShellPtzButton $panel 'right' ([string][char]0x25BA) 'OBS_KEY_RIGHT'    | Out-Null
        New-WpfShellPtzButton $panel 'zin'   '+'                    'OBS_KEY_NUMPLUS'  | Out-Null
        New-WpfShellPtzButton $panel 'zout'  ([string][char]0x2212) 'OBS_KEY_NUMMINUS' | Out-Null

        $wfHost = New-Object System.Windows.Forms.Integration.WindowsFormsHost
        $wfHost.Child = $panel
        $script:_wpfShellPlaceholder = $null
        $hostBorder.Child = $wfHost

        # Direct3D9 output uses the classic windowed blit path, which honors the rounded window
        # region above (the default Direct3D11 flip-model output ignores it and stays square).
        if (-not $script:_wpfShellCamLibVLC) { $script:_wpfShellCamLibVLC = [LibVLCSharp.Shared.LibVLC]::new($false, [string[]]@('--vout=direct3d9')) }
        $mp = [LibVLCSharp.Shared.MediaPlayer]::new($script:_wpfShellCamLibVLC)
        # The whole picture is always shown at its true 16:9 shape (letterboxed, never stretched or cropped).
        $mp.AspectRatio = '16:9'
        $devName = [string]$script:Cfg.OBS.PreviewCameraName
        $media = [LibVLCSharp.Shared.Media]::new(
            $script:_wpfShellCamLibVLC, 'dshow://', [LibVLCSharp.Shared.FromType]::FromLocation,
            [string[]]@(":dshow-vdev=$devName", ":dshow-adev=none", ":live-caching=100")
        )
        $mp.Media = $media
        $media.Dispose()
        $mp.Hwnd = $video.Handle
        [void]$mp.Play()

        # Show the PTZ buttons only while the pointer is over the preview (same as the main app).
        if ($script:_wpfShellPtzHoverTimer) { try { $script:_wpfShellPtzHoverTimer.Stop(); $script:_wpfShellPtzHoverTimer.Dispose() } catch {} }
        $script:_wpfShellPtzHoverTimer = New-Object System.Windows.Forms.Timer
        $script:_wpfShellPtzHoverTimer.Interval = 100
        $script:_wpfShellPtzHoverTimer.Add_Tick({
                try {
                    Update-WpfShellHint
                    $pnl = $script:_wpfShellCamPanel
                    if ($pnl -and -not $pnl.IsDisposed -and $pnl.IsHandleCreated) {
                        $sr = $pnl.RectangleToScreen($pnl.ClientRectangle)
                        $inside = $sr.Contains([System.Windows.Forms.Control]::MousePosition)
                        foreach ($b in $script:_wpfShellPtzButtons) { if (-not $b.IsDisposed) { $b.Visible = $inside } }
                        Update-OnlyTHover $inside
                    }
                }
                catch {}
            })
        $script:_wpfShellPtzHoverTimer.Start()

        $script:_wpfAfHookNext = [DateTime]::MinValue
        try { [void](Initialize-JwlCursorGuard) } catch {}
        if ($script:_wpfShellAfTimer) { try { $script:_wpfShellAfTimer.Stop(); $script:_wpfShellAfTimer.Dispose() } catch {} }
        $script:_wpfShellAfTimer = New-Object System.Windows.Forms.Timer
        $script:_wpfShellAfTimer.Interval = 30
        $script:_wpfShellAfTimer.Add_Tick({ Step-WpfShellAf })
        $script:_wpfShellAfTimer.Start()

        $script:_wpfShellCamMediaPlayer = $mp
        $script:_wpfShellCamPanel = $panel
        $script:_wpfShellCamActive = $true
        $script:_wpfShellCamName = $devName
        $script:_wpfShellCamStartedAt = [DateTime]::UtcNow

        # The camera device may not exist yet when the app starts before OBS has its virtual camera running (VLC then gives up and
        # the preview stays black). While the virtual camera is reported ON but the player is not playing, start the preview again.
        if ($script:_wpfShellCamWatchdog) { try { $script:_wpfShellCamWatchdog.Stop(); $script:_wpfShellCamWatchdog.Dispose() } catch {} }
        $script:_wpfShellCamWatchdog = New-Object System.Windows.Forms.Timer
        $script:_wpfShellCamWatchdog.Interval = 2000
        $script:_wpfShellCamWatchdog.Add_Tick({
                try {
                    if ($script:ShuttingDown -or -not $script:_wpfShellCamActive -or -not $script:_wpfShellCamMediaPlayer) { return }
                    if (-not $script:ObsConnected -or -not $script:VirtualCameraStatus) { return }
                    if (([DateTime]::UtcNow - $script:_wpfShellCamStartedAt).TotalSeconds -lt 4) { return }
                    $st = [string]$script:_wpfShellCamMediaPlayer.State
                    if ($st -eq 'Error' -or $st -eq 'Stopped' -or $st -eq 'Ended' -or $st -eq 'NothingSpecial') {
                        Log "WPF shell preview: camera feed not running (player $st) - restarting preview"
                        Stop-WpfShellCameraPreview
                        Start-WpfShellCameraPreview
                    }
                }
                catch {}
            })
        $script:_wpfShellCamWatchdog.Start()
        $toggleBtn = $script:_wpfShellWindow.FindName('CameraToggleBtn')
        if ($toggleBtn) { $toggleBtn.Content = '■' }

        Log "WPF shell preview: camera preview started using '$devName' (independent WindowsFormsHost instance)"
    }
    catch {
        Log "WPF shell preview: camera preview failed to start - $_"
        Stop-WpfShellCameraPreview
    }
}

function Stop-WpfShellCameraPreview {
    try { if ($script:_wpfShellCamWatchdog) { $script:_wpfShellCamWatchdog.Stop(); $script:_wpfShellCamWatchdog.Dispose() } } catch {}
    $script:_wpfShellCamWatchdog = $null
    try { if ($script:_wpfShellObsSyncTimer) { $script:_wpfShellObsSyncTimer.Stop(); $script:_wpfShellObsSyncTimer.Dispose() } } catch {}
    $script:_wpfShellObsSyncTimer = $null
    try { if ($script:_wpfShellObsPreview) { $script:_wpfShellObsPreview.Image = $null } } catch {}
    $script:_wpfShellObsPreview = $null
    $script:_wpfShellObsHost = $null
    $script:_wpfShellObsLoading = $false
    try { Stop-PTZRepeat } catch {}
    try { if ('JwlCursorGuard' -as [type]) { [JwlCursorGuard]::Detach() } } catch {}
    try { if ($script:_wpfAfRoiPopup) { $script:_wpfAfRoiPopup.IsOpen = $false } } catch {}
    try { if ($script:_wpfShellPtzHoverTimer) { $script:_wpfShellPtzHoverTimer.Stop(); $script:_wpfShellPtzHoverTimer.Dispose() } } catch {}
    $script:_wpfShellPtzHoverTimer = $null
    try { $script:_wpfShellPtzButtons.Clear() } catch {}
    try { if ($script:_wpfShellAfTimer) { $script:_wpfShellAfTimer.Stop(); $script:_wpfShellAfTimer.Dispose() } } catch {}
    $script:_wpfShellAfTimer = $null
    $script:_wpfShellHintLabel = $null
    $script:_wpfShellAfOverlay = $null
    try { $script:_wpfShellAfCtls.Clear() } catch {}
    $script:_wpfAfDragging = $false; $script:_wpfAfResizing = -1; $script:_wpfAfWasDown = $false
    try { if ($script:_wpfShellCamMediaPlayer) { $script:_wpfShellCamMediaPlayer.Stop() } } catch {}
    try { if ($script:_wpfShellCamMediaPlayer) { $script:_wpfShellCamMediaPlayer.Dispose() } } catch {}
    $script:_wpfShellCamMediaPlayer = $null
    try {
        if ($script:_wpfShellWindow) {
            $hostBorder = $script:_wpfShellWindow.FindName('CameraHostBorder')
            if ($hostBorder) { $hostBorder.Child = $null }
            $toggleBtn = $script:_wpfShellWindow.FindName('CameraToggleBtn')
            if ($toggleBtn) { $toggleBtn.Content = '▶' }
        }
    }
    catch {}
    try { if ($script:_wpfShellCamPanel) { $script:_wpfShellCamPanel.Dispose() } } catch {}
    $script:_wpfShellCamPanel = $null
    $wasActive = $script:_wpfShellCamActive
    $script:_wpfShellCamActive = $false
    if ($wasActive) { Log "WPF shell preview: camera preview stopped" }
}

$script:NewUiPrimary = $false          # $true while the WPF window is the app's main UI
$script:_legacyUiHidden = $false       # $true while the WinForms window is invisible + click-through
$script:_wpfShellAppClosing = $false   # set once the app is really shutting down

function Hide-LegacyWindow {
    # Invisible and click-through, but still shown/enabled, so every PerformClick/dialog owner
    # relationship of the existing code keeps working exactly as before.
    try {
        $script:form.Opacity = 0.0
        $script:form.TopMost = $false
        $h = $script:form.Handle
        $ex = [Win32]::GetWindowLong($h, -20)
        [void][Win32]::SetWindowLong($h, -20, ($ex -bor 0x20 -bor 0x80))   # WS_EX_TRANSPARENT | WS_EX_TOOLWINDOW
        $script:_legacyUiHidden = $true
        # The new window goes back on top once the classic one is invisible again.
        if ($script:NewUiPrimary -and $script:_wpfShellWindow) {
            try { $script:_wpfShellWindow.Topmost = $true; [void]$script:_wpfShellWindow.Activate() } catch {}
        }
    }
    catch { Log "New UI: could not hide the classic window: $_" }
}

function Show-LegacyWindow {
    try {
        $h = $script:form.Handle
        $ex = [Win32]::GetWindowLong($h, -20)
        [void][Win32]::SetWindowLong($h, -20, ($ex -band (-bnot 0xA0)))
        $script:form.Opacity = 1.0
        $script:_legacyUiHidden = $false
        # The new window is Topmost and sits at the same spot, so it would cover the classic one: drop it
        # below while the classic window is visible.
        if ($script:NewUiPrimary -and $script:_wpfShellWindow) {
            try { $script:_wpfShellWindow.Topmost = $false } catch {}
            $script:form.TopMost = $true
        }
        $script:form.Activate()
        $script:form.BringToFront()
    }
    catch { Log "New UI: could not show the classic window: $_" }
}

function Switch-LegacyWindow {
    if ($script:_legacyUiHidden) { Show-LegacyWindow } else { Hide-LegacyWindow }
}

# Ctrl+Shift+O can arrive from the WPF window, the classic form, or the key poll below; only one toggle
# per key press is allowed.
function Invoke-LegacySwitchHotkey {
    try {
        $now = [DateTime]::UtcNow
        if ($script:_legacySwitchLastAt -and ($now - $script:_legacySwitchLastAt).TotalMilliseconds -lt 400) { return }
        $script:_legacySwitchLastAt = $now
        if ($script:NewUiPrimary) {
            Switch-LegacyWindow
            Log "New UI: Ctrl+Shift+O - classic window is now $(if ($script:_legacyUiHidden) { 'hidden' } else { 'shown' })"
        }
        else {
            Enter-WpfNewUiMode
        }
    }
    catch { Log "New UI: Ctrl+Shift+O failed: $_" }
}

function Initialize-LegacySwitchKeyPoll {
    # Focus-independent Ctrl+Shift+O: WPF key events do not reach the window when a hosted WinForms control
    # (video panel, PTZ buttons) or the overlay window has the focus, so poll the keyboard while one of
    # this app's own windows is in the foreground.
    if ($script:_legacySwitchKeyTimer) { return }
    try {
        if (-not ('JwlKb.Native' -as [type])) {
            Add-Type -Namespace JwlKb -Name Native -MemberDefinition @'
[DllImport("user32.dll")] public static extern short GetAsyncKeyState(int vKey);
[DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
[DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);
'@
        }
        $script:_legacySwitchKeyWasDown = $true   # a key still held from the press that started the new UI must not retrigger
        $script:_legacySwitchKeyTimer = New-Object System.Windows.Forms.Timer
        $script:_legacySwitchKeyTimer.Interval = 40
        $script:_legacySwitchKeyTimer.Add_Tick({
                try {
                    $combo = ([JwlKb.Native]::GetAsyncKeyState(0x11) -lt 0) -and ([JwlKb.Native]::GetAsyncKeyState(0x10) -lt 0) -and
                    -not ([JwlKb.Native]::GetAsyncKeyState(0x12) -lt 0) -and ([JwlKb.Native]::GetAsyncKeyState(0x4F) -lt 0)
                    if ($combo -and -not $script:_legacySwitchKeyWasDown) {
                        $fg = [JwlKb.Native]::GetForegroundWindow()
                        [uint32]$fgPid = 0
                        [void][JwlKb.Native]::GetWindowThreadProcessId($fg, [ref]$fgPid)
                        if ($fgPid -eq [uint32]$PID) { Invoke-LegacySwitchHotkey }
                    }
                    $script:_legacySwitchKeyWasDown = $combo
                }
                catch {}
            })
        $script:_legacySwitchKeyTimer.Start()
    }
    catch { Log "New UI: key poll could not start: $_" }
}

function Sync-LegacyWindowToShell {
    # Keeps the hidden classic window on top of the new window's position so dialogs that open
    # relative to it ($script:form.Left/Top) still land over the visible UI.
    try {
        $w = $script:_wpfShellWindow
        if (-not $w -or -not $script:NewUiPrimary -or -not $script:_legacyUiHidden) { return }
        $d = [double](Get-DpiScaleFactor)
        $script:form.Location = New-Object System.Drawing.Point ([int]($w.Left * $d)), ([int]($w.Top * $d))
    }
    catch {}
}

function Apply-UiModeFromSettings {
    try {
        if ([bool]$script:Cfg.UI.UseNewUI) {
            if (-not $script:NewUiPrimary) {
                if ($script:form -and -not $script:form.IsDisposed) {
                    [void]$script:form.BeginInvoke([System.Action] { Enter-WpfNewUiMode })
                }
                else {
                    Enter-WpfNewUiMode
                }
            }
            return
        }

        if ($script:NewUiPrimary) {
            $script:NewUiPrimary = $false
            try { if ($script:_wpfShellWindow) { $script:_wpfShellWindow.Hide() } } catch {}
        }
        Show-LegacyWindow
    }
    catch {
        Log "New UI: config-driven mode change failed: $_"
    }
}

function Get-AppBottomY {
    # Y (physical pixels) just under the visible main window - used to place dialogs below the app.
    try {
        if ($script:NewUiPrimary -and $script:_wpfShellWindow) {
            $w = $script:_wpfShellWindow
            return [int](($w.Top + $w.ActualHeight) * [double](Get-DpiScaleFactor)) + 5
        }
    }
    catch {}
    return [int]($script:form.Location.Y + $script:form.Height + 5)
}

function Start-WpfSettingsSpinner($btn) {
    # While Settings is built and drawn the main UI thread is busy, and animations inside the main windows need that
    # thread (the gear sat still). A small separate window on its OWN thread draws the spinning gear on top of the
    # Settings button instead, so it keeps turning no matter how busy the main thread is. Returns a state table; set
    # .Stop = $true to remove it (it also removes itself after ~20 s at the latest).
    try {
        $src = [System.Windows.PresentationSource]::FromVisual($btn)
        if (-not $src) { return $null }
        $tl = $btn.PointToScreen((New-Object System.Windows.Point 0, 0))
        $br = $btn.PointToScreen((New-Object System.Windows.Point $btn.ActualWidth, $btn.ActualHeight))
        $m = $src.CompositionTarget.TransformFromDevice
        $left = $tl.X * $m.M11; $top = $tl.Y * $m.M22
        $w = ($br.X - $tl.X) * $m.M11; $h = ($br.Y - $tl.Y) * $m.M22
        if ($w -lt 8 -or $h -lt 8) { return $null }

        # Clean up the previous spinner's runspace (it has finished by now).
        if ($script:_wpfSpinPrev) { Stop-RunspaceAsync $script:_wpfSpinPrev.PS $script:_wpfSpinPrev.RS; $script:_wpfSpinPrev = $null }

        $shared = [hashtable]::Synchronized(@{ Stop = $false; PS = $null; RS = $null })
        $spinScript = {
            param([double]$L, [double]$T, [double]$W, [double]$H, $shared)
            try {
                Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase
                if (-not ('JwlSpin.Win' -as [type])) {
                    Add-Type -Namespace JwlSpin -Name Win -MemberDefinition '[System.Runtime.InteropServices.DllImport("user32.dll")] public static extern int GetWindowLong(System.IntPtr h, int i); [System.Runtime.InteropServices.DllImport("user32.dll")] public static extern int SetWindowLong(System.IntPtr h, int i, int v);'
                }
                $fs = [math]::Round($H * 0.69, 1)
                $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent" ShowInTaskbar="False" ShowActivated="False" Topmost="True" ResizeMode="NoResize">
  <Border CornerRadius="8" Background="#C87800" BorderBrush="#444444" BorderThickness="1">
    <TextBlock x:Name="G" Text="&#x2699;&#xFE0E;" FontFamily="Segoe UI Symbol" FontSize="$fs" Foreground="#FFD54A" HorizontalAlignment="Center" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5" Margin="0,-3,0,0"/>
  </Border>
</Window>
"@
                $win = [System.Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader ([xml]$xaml)))
                $win.Left = $L; $win.Top = $T; $win.Width = $W; $win.Height = $H
                $rot = New-Object System.Windows.Media.RotateTransform
                $win.FindName('G').RenderTransform = $rot
                $anim = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0, 360.0, (New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(900))))
                $anim.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
                $rot.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $anim)
                $win.Show()
                $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper $win).Handle
                $ex = [JwlSpin.Win]::GetWindowLong($hwnd, -20)
                [void][JwlSpin.Win]::SetWindowLong($hwnd, -20, ($ex -bor 0x08000000 -bor 0x80 -bor 0x20))   # no-activate, tool window, click-through
                $state = @{ Ticks = 0 }
                $timer = New-Object System.Windows.Threading.DispatcherTimer
                $timer.Interval = [TimeSpan]::FromMilliseconds(80)
                $timer.Add_Tick({
                        $state.Ticks++
                        if ($shared.Stop -or $state.Ticks -gt 250) {
                            $timer.Stop()
                            try { $win.Close() } catch {}
                            [System.Windows.Threading.Dispatcher]::CurrentDispatcher.InvokeShutdown()
                        }
                    }.GetNewClosure())
                $timer.Start()
                [System.Windows.Threading.Dispatcher]::Run()
            }
            catch { }
        }
        $rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $rs.ApartmentState = 'STA'; $rs.ThreadOptions = 'ReuseThread'; $rs.Open()
        $ps = [System.Management.Automation.PowerShell]::Create(); $ps.Runspace = $rs
        [void]$ps.AddScript($spinScript).AddArgument($left).AddArgument($top).AddArgument($w).AddArgument($h).AddArgument($shared)
        $shared.PS = $ps; $shared.RS = $rs
        $script:_wpfSpinPrev = $shared
        [void]$ps.BeginInvoke()
        return $shared
    }
    catch { return $null }
}

function Initialize-ModalShellGuard {
    # The new window is always-on-top, so any dialog that is not itself TopMost opens BEHIND it; the dialog is
    # modal, so the new UI then ignores every click and the app looks frozen. While ANY WinForms modal loop
    # (dialog or message box) runs, put the new window back to normal stacking, then restore it afterwards.
    if ($script:_modalGuardInstalled) { return }
    $script:_modalGuardInstalled = $true
    $script:_modalDepth = 0
    $script:_modalShellWasTopmost = $false
    try {
        [System.Windows.Forms.Application]::add_EnterThreadModal({
                try {
                    $script:_modalDepth++
                    if ($script:_modalDepth -eq 1 -and $script:NewUiPrimary -and $script:_wpfShellWindow -and -not $script:ShuttingDown) {
                        $script:_modalShellWasTopmost = [bool]$script:_wpfShellWindow.Topmost
                        if ($script:_modalShellWasTopmost) {
                            $script:_wpfShellWindow.Topmost = $false
                            foreach ($ow in @($script:_wpfShellOverlay, $script:_wpfShellHeader)) {
                                if ($ow) { $oh = (New-Object System.Windows.Interop.WindowInteropHelper $ow).Handle; if ($oh -ne [IntPtr]::Zero) { [void][OtWin]::SetWindowPos($oh, [IntPtr](-2), 0, 0, 0, 0, 0x13) } }
                            }
                        }
                    }
                }
                catch {}
            })
        [System.Windows.Forms.Application]::add_LeaveThreadModal({
                try {
                    $script:_modalDepth = [Math]::Max(0, $script:_modalDepth - 1)
                    if ($script:_modalDepth -eq 0) {
                        if ($script:_modalShellWasTopmost -and $script:NewUiPrimary -and $script:_wpfShellWindow -and $script:_legacyUiHidden -and -not $script:ShuttingDown) {
                            $script:_wpfShellWindow.Topmost = $true
                        }
                        $script:_modalShellWasTopmost = $false
                    }
                }
                catch {}
            })
    }
    catch { Log "New UI: modal guard could not start: $_" }
}

function Enter-WpfNewUiMode {
    # Opt-in switch-over: open the WPF window as the real UI and park the WinForms window
    # (still the engine for all logic) invisibly behind it. Any failure falls back to the classic UI.
    try {
        # The classic form must exist (it is the engine) but is not made visible here; the catch
        # block below restores it if the new shell cannot open.
        if ($script:form -and -not $script:form.IsDisposed) {
            if (-not $script:form.Visible) {
                try { $script:form.Opacity = 0.0; $script:form.ShowInTaskbar = $false; $script:form.Show(); Hide-LegacyWindow } catch {}
            }
        }

        Show-WpfShellPreview
        $w = $script:_wpfShellWindow
        if (-not $w) { throw 'the new UI window did not open' }

        try { $w.WindowState = [System.Windows.WindowState]::Normal } catch {}
        try { $w.Show() } catch {}
        try { $w.Activate() | Out-Null } catch {}
        try { $w.Topmost = $true } catch {}

        $script:NewUiPrimary = $true
        # Same title (with version) as the classic window, so the two never drift apart.
        $w.Title = $(if ([string]::IsNullOrWhiteSpace([string]$script:form.Text)) { 'JWL+OBS Assistant' } else { ([string]$script:form.Text).Trim() })
        if ($script:_wpfShellHeader) {
            try { $script:_wpfShellHeader.FindName('HeaderTitle').Text = $w.Title; $w.Title = ' ' } catch {}
        }
        try {
            if ($script:form.Icon) {
                $w.Icon = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon($script:form.Icon.Handle, [System.Windows.Int32Rect]::Empty, [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions())
            }
        }
        catch {}
        # Closing the new window = closing the app, through the classic window's confirm-and-shutdown path.
        $w.Add_Closing({
                param($closeSender, $closeArgs)
                if ($script:NewUiPrimary -and -not $script:_wpfShellAppClosing) {
                    $closeArgs.Cancel = $true
                    try { $script:form.Close() } catch {}
                }
            })
        $w.Add_LocationChanged({ Sync-LegacyWindowToShell })
        $w.Add_PreviewKeyDown({
                param($keySender, $keyArgs)
                $mods = [System.Windows.Input.Keyboard]::Modifiers
                if (($mods -band [System.Windows.Input.ModifierKeys]::Control) -and ($mods -band [System.Windows.Input.ModifierKeys]::Shift) -and $keyArgs.Key -eq [System.Windows.Input.Key]::O) {
                    Invoke-LegacySwitchHotkey
                    $keyArgs.Handled = $true
                }
            })
        try { [System.Windows.Forms.Integration.ElementHost]::EnableModelessKeyboardInterop($w) } catch {}
        Initialize-LegacySwitchKeyPoll
        Initialize-ModalShellGuard

        # The WPF shell is on screen: make sure the classic form is invisible and parked behind it.
        $script:form.ShowInTaskbar = $false
        Hide-LegacyWindow
        Sync-LegacyWindowToShell
        Log 'New UI: active - classic window is hidden (Ctrl+Shift+O shows/hides it).'
    }
    catch {
        $script:NewUiPrimary = $false
        $script:_legacyUiHidden = $false
        try {
            $script:form.ShowInTaskbar = $true
            if (-not $script:form.Visible) { $script:form.Show() }
            Show-LegacyWindow
        }
        catch {}
        Log "New UI: could not start, staying on the classic window: $_"
    }
}

function Add-WpfShellButtonStyling($xml) {
    # Gives every rounded Button template the classic 3D look (the same top highlight / bottom shade as
    # Set-Button3DStyle) plus a soft white glow on hover. Done here on the parsed XAML so none of the
    # templates has to be edited by hand; colours still come from each button's Background.
    try {
        $ns = $xml.DocumentElement.NamespaceURI
        $xns = 'http://schemas.microsoft.com/winfx/2006/xaml'
        $glossXml = '<Border.Background xmlns="' + $ns + '"><LinearGradientBrush StartPoint="0,0" EndPoint="0,1">' +
        '<GradientStop Color="#70FFFFFF" Offset="0"/><GradientStop Color="#1AFFFFFF" Offset="0.42"/>' +
        '<GradientStop Color="#00808080" Offset="0.67"/><GradientStop Color="#24000000" Offset="1"/></LinearGradientBrush></Border.Background>'
        $glowXml = '<Setter xmlns="' + $ns + '" TargetName="GlowRoot" Property="Effect"><Setter.Value>' +
        '<DropShadowEffect Color="White" BlurRadius="14" ShadowDepth="0" Opacity="0.8"/></Setter.Value></Setter>'
        foreach ($ct in @($xml.GetElementsByTagName('ControlTemplate'))) {
            if ($ct.GetAttribute('TargetType') -ne 'Button') { continue }
            $bd = $null
            foreach ($n in $ct.ChildNodes) { if ($n.LocalName -eq 'Border') { $bd = $n; break } }
            if (-not $bd) { continue }
            $cr = $bd.GetAttribute('CornerRadius')
            $crv = 0.0
            if (-not [double]::TryParse($cr, [ref]$crv) -or $crv -lt 8) { continue }   # skips the tiny PiP pill
            $cp = $null
            foreach ($n in $bd.ChildNodes) { if ($n.LocalName -eq 'ContentPresenter') { $cp = $n; break } }
            if (-not $cp) { continue }
            $hadPadding = $bd.HasAttribute('Padding')
            if ($hadPadding) { $bd.RemoveAttribute('Padding') }
            [void]$bd.RemoveChild($cp)
            # Grid { background border, gloss, content } - the gloss sits UNDER the content so text/icons stay crisp.
            $grid = $xml.CreateElement('Grid', $ns)
            $nameAttr = $xml.CreateAttribute('x', 'Name', $xns)
            $nameAttr.Value = 'GlowRoot'
            [void]$grid.Attributes.Append($nameAttr)
            [void]$ct.ReplaceChild($grid, $bd)
            [void]$grid.AppendChild($bd)
            $gloss = $xml.CreateElement('Border', $ns)
            $gloss.SetAttribute('CornerRadius', $cr)
            $gloss.SetAttribute('Margin', '1')
            $gloss.SetAttribute('IsHitTestVisible', 'False')
            [void]$grid.AppendChild($gloss)
            $gloss.InnerXml = $glossXml
            if ($hadPadding) { $cp.SetAttribute('Margin', '{TemplateBinding Padding}') }
            [void]$grid.AppendChild($cp)
            foreach ($trig in @($ct.GetElementsByTagName('Trigger'))) {
                if ($trig.GetAttribute('Property') -ne 'IsMouseOver') { continue }
                foreach ($st in @($trig.ChildNodes)) {
                    if ($st.LocalName -eq 'Setter' -and $st.GetAttribute('Property') -eq 'Opacity') { $st.SetAttribute('Value', '0.93') }
                }
                $frag = $xml.CreateDocumentFragment()
                $frag.InnerXml = $glowXml
                [void]$trig.AppendChild($frag)
            }
        }
    }
    catch { try { Log "WPF shell preview: button styling failed (buttons stay flat): $_" } catch {} }
}

function New-WpfShellOverlay($window, [string]$mainXaml, [string]$overlayXaml) {
    # Builds the overlay window (clock + top-right buttons). Its named elements are also registered in the main
    # window's name scope, so every existing FindName('ClockText' / 'SettingsBtn' / ...) keeps working unchanged.
    try {
        $res = [regex]::Match($mainXaml, '(?s)<Window\.Resources>.*?</Window\.Resources>').Value
        $xml = [xml]($overlayXaml.Replace('<!--RESOURCES-->', $res))
        Add-WpfShellButtonStyling $xml
        $ov = [System.Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xml))
        foreach ($n in @('ClockBorder', 'ClockText', 'ScaleButtonsPanel', 'ScaleBtn', 'ScalePopup', 'ScalePopupBorder', 'ScaleOptA', 'ScaleOptB',
                'ThemeToggleBtn', 'SunIcon', 'MoonIcon', 'SettingsBtn', 'SettingsGlyph',
                'OnlyTCountPanel', 'OnlyTLeftPanel', 'OnlyTRightPanel', 'OnlyTToggleBtn', 'OnlyTToggleGlyph', 'OnlyTPauseBtn', 'OnlyTMinusBtn', 'OnlyTCoBtn', 'OnlyTPlusBtn', 'OnlyTCountBorder', 'OnlyTCountText')) {
            $el = $ov.FindName($n)
            if ($el) { $window.RegisterName($n, $el) }
        }
        $script:_wpfShellOverlay = $ov
        return $ov
    }
    catch {
        try { Log "WPF shell preview: overlay failed to build: $_" } catch {}
        return $null
    }
}

function Sync-WpfShellOverlay {
    # Keeps the overlay exactly over the top 48 units of the main window's client area (follows moves and S/M/L scaling).
    $ov = $script:_wpfShellOverlay; $w = $script:_wpfShellWindow
    if (-not $ov -or -not $w) { return }
    try {
        $c = $w.Content
        if (-not $c -or -not $c.IsLoaded) { return }
        $src = [System.Windows.PresentationSource]::FromVisual($c)
        if (-not $src) { return }
        $f = 1.0
        try { if ($script:_wpfShellUiScale -gt 0) { $f = [double]$script:_wpfShellUiScale } } catch {}
        $root = $ov.Content
        if ($root) {
            if ([math]::Abs($root.Width - $c.ActualWidth) -gt 0.01 -or $root.Width -ne $root.Width) { $root.Width = $c.ActualWidth }
            $root.LayoutTransform = New-Object System.Windows.Media.ScaleTransform $f, $f
        }
        $dev = $c.PointToScreen((New-Object System.Windows.Point 0, 0))
        $dip = $src.CompositionTarget.TransformFromDevice.Transform($dev)
        if ([math]::Abs($ov.Left - $dip.X) -gt 0.2) { $ov.Left = $dip.X }
        if ([math]::Abs($ov.Top - $dip.Y) -gt 0.2) { $ov.Top = $dip.Y }
    }
    catch {}
}

function Restore-WpfShellOwnedWindows {
    # The overlay (clock, brightness, S/M/L, settings) and the title strip must never end up behind the video:
    # while the shell is Topmost, keep them Topmost too (no activation, no move).
    $w = $script:_wpfShellWindow
    if (-not $w -or -not $w.IsVisible -or -not $w.Topmost) { return }
    foreach ($ow in @($script:_wpfShellOverlay, $script:_wpfShellHeader)) {
        try {
            if (-not $ow) { continue }
            if (-not $ow.IsVisible) { $ow.Show() }
            $oh = (New-Object System.Windows.Interop.WindowInteropHelper $ow).Handle
            if ($oh -ne [IntPtr]::Zero) { [void][OtWin]::SetWindowPos($oh, [IntPtr](-1), 0, 0, 0, 0, 0x13) }
        }
        catch {}
    }
}

function Show-WpfShellOverlay {
    $ov = $script:_wpfShellOverlay; $w = $script:_wpfShellWindow
    if (-not $ov -or -not $w) { return }
    try {
        $ov.Owner = $w            # an owned window is always kept above its owner, so it stays above the native video
        $ov.Show()
        # Never take focus (clicking the clock/buttons must not grey out the main window's title bar) and stay off Alt-Tab.
        $h = (New-Object System.Windows.Interop.WindowInteropHelper $ov).Handle
        $ex = [Win32]::GetWindowLong($h, -20)
        [void][Win32]::SetWindowLong($h, -20, ($ex -bor 0x08000000 -bor 0x80))
        $w.Add_LocationChanged({ Sync-WpfShellOverlay })
        $w.Add_SizeChanged({ Sync-WpfShellOverlay })
        Sync-WpfShellOverlay
        $w.Dispatcher.BeginInvoke([System.Action] { Sync-WpfShellOverlay }, [System.Windows.Threading.DispatcherPriority]::Loaded) | Out-Null
    }
    catch { try { Log "WPF shell preview: overlay failed to show: $_" } catch {} }
}

if (-not ('OtWin' -as [type])) {
    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class OtWin {
    [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
    [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr h, IntPtr after, int x, int y, int cx, int cy, uint flags);
    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
    [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr h);
    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h, int cmd);
    [DllImport("user32.dll")] public static extern bool ShowWindowAsync(IntPtr h, int cmd);
    [DllImport("user32.dll")] public static extern bool IsHungAppWindow(IntPtr h);
}
'@
}

function Test-OnlyTUpdateAvailable {
    # OnlyT shows a green download button (AutomationId 'NewVersionButton') when a new version is available;
    # WPF leaves a collapsed button out of the UI tree, so finding it means the update notice is showing.
    try {
        if (-not $script:UIAutomationAvailable) { return $false }
        $p = Get-OnlyTProcess
        if (-not $p -or [OtWin]::IsHungAppWindow($p.MainWindowHandle)) { return $false }
        $root = [System.Windows.Automation.AutomationElement]::FromHandle($p.MainWindowHandle)
        $cond = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty, 'NewVersionButton')
        $el = $root.FindFirst([System.Windows.Automation.TreeScope]::Descendants, $cond)
        if (-not $el) { return $false }
        $r = $el.Current.BoundingRectangle
        return (-not $r.IsEmpty -and $r.Width -gt 0 -and $r.Height -gt 0)
    }
    catch { return $false }
}

# Parks OnlyT's window far off-screen (not minimized, so its controls keep working) or brings it back.
# The window calls are asynchronous (SWP_ASYNCWINDOWPOS / ShowWindowAsync) and skipped while OnlyT is frozen, so a hung
# OnlyT can never block this app.
function Set-OnlyTWindowVisible([bool]$visible, [switch]$Front) {
    try {
        $p = Get-OnlyTProcess
        if (-not $p) { return }
        $h = $p.MainWindowHandle
        if ([OtWin]::IsHungAppWindow($h)) { return }
        $r = New-Object OtWin+RECT
        if (-not [OtWin]::GetWindowRect($h, [ref]$r)) { return }
        $parked = ($r.Left -le -30000)
        if ($visible) {
            if ($parked) {
                $x = [int]$script:Cfg.OnlyT.SavedX; $y = [int]$script:Cfg.OnlyT.SavedY
                if ($x -le -30000 -or $x -eq 0 -and $y -eq 0) { $x = 100; $y = 100 }
                [void][OtWin]::SetWindowPos($h, [IntPtr]::Zero, $x, $y, 0, 0, 0x0001 -bor 0x0004 -bor 0x0010 -bor 0x4000)
            }
            if ($Front) {
                if ([OtWin]::IsIconic($h)) { [void][OtWin]::ShowWindowAsync($h, 9) }
                [void][OtWin]::SetWindowPos($h, [IntPtr](-1), 0, 0, 0, 0, 0x0001 -bor 0x0002 -bor 0x4000)
                [void][OtWin]::SetForegroundWindow($h)
            }
        }
        elseif (-not $parked) {
            if ([OtWin]::IsIconic($h)) { [void][OtWin]::ShowWindowAsync($h, 9) }
            $script:Cfg.OnlyT.SavedX = [int]$r.Left; $script:Cfg.OnlyT.SavedY = [int]$r.Top
            try { Save-Settings | Out-Null } catch {}
            [void][OtWin]::SetWindowPos($h, [IntPtr]::Zero, -32000, -32000, 0, 0, 0x0001 -bor 0x0004 -bor 0x0010 -bor 0x4000)
        }
    }
    catch { try { Log "OnlyT window: $_" } catch {} }
}

function Get-OnlyTParts {
    # Opens OnlyT's talk list for a moment (expand, read, collapse). Returns $null if OnlyT is not reachable.
    $p = Get-OnlyTProcess
    if (-not $p -or -not $script:UIAutomationAvailable) { return $null }
    $parts = @()
    $combo = $null
    try {
        $root = [System.Windows.Automation.AutomationElement]::FromHandle($p.MainWindowHandle)
        $combo = $root.FindFirst([System.Windows.Automation.TreeScope]::Descendants, (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty, 'TalkSelectorComboBox')))
        if (-not $combo) { return $null }
        $ec = $combo.GetCurrentPattern([System.Windows.Automation.ExpandCollapsePattern]::Pattern)
        $ec.Expand()
        $items = @()
        for ($try = 0; $try -lt 10 -and $items.Count -eq 0; $try++) {
            Start-Sleep -Milliseconds 150
            $items = @($combo.FindAll([System.Windows.Automation.TreeScope]::Descendants, (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::ListItem))))
        }
        $textCond = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::Text)
        $i = 0
        foreach ($it in $items) {
            $names = @($it.FindAll([System.Windows.Automation.TreeScope]::Descendants, $textCond) | ForEach-Object { [string]$_.Current.Name } | Where-Object { $_ })
            $sel = $false
            try { $sel = [bool]($it.GetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern)).Current.IsSelected } catch {}
            $time = ''; $title = ''
            foreach ($n in $names) { if (-not $time -and $n -match '^\d{1,2}:\d{2}$') { $time = $n } elseif (-not $title) { $title = $n } }
            $parts += [pscustomobject]@{ Index = $i; Time = $time; Title = $title; Selected = $sel }
            $i++
        }
    }
    catch { try { Log "OnlyT parts: $_" } catch {} }
    finally { try { if ($combo) { $combo.GetCurrentPattern([System.Windows.Automation.ExpandCollapsePattern]::Pattern).Collapse() } } catch {} }
    return , $parts
}

function Set-OnlyTPart([int]$index) {
    $p = Get-OnlyTProcess
    if (-not $p) { return }
    $combo = $null
    try {
        $root = [System.Windows.Automation.AutomationElement]::FromHandle($p.MainWindowHandle)
        $combo = $root.FindFirst([System.Windows.Automation.TreeScope]::Descendants, (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty, 'TalkSelectorComboBox')))
        if (-not $combo) { return }
        $combo.GetCurrentPattern([System.Windows.Automation.ExpandCollapsePattern]::Pattern).Expand()
        $items = @()
        for ($try = 0; $try -lt 10 -and $items.Count -eq 0; $try++) {
            Start-Sleep -Milliseconds 150
            $items = @($combo.FindAll([System.Windows.Automation.TreeScope]::Descendants, (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::ListItem))))
        }
        if ($index -lt $items.Count) { $items[$index].GetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern).Select() }
    }
    catch { try { Log "OnlyT select part: $_" } catch {} }
    finally { try { if ($combo) { $combo.GetCurrentPattern([System.Windows.Automation.ExpandCollapsePattern]::Pattern).Collapse() } } catch {} }
}

function Get-OnlyTTitle {
    # OnlyT does not expose the selected talk while its dropdown is closed, so the list is only opened (briefly)
    # when something suggests the part changed: timer state, planned duration, or 20 s since the last look.
    try {
        $p = Get-OnlyTProcess
        if (-not $p -or -not $script:UIAutomationAvailable -or -not $p.Responding) { return '' }
        $root = [System.Windows.Automation.AutomationElement]::FromHandle($p.MainWindowHandle)
        $cond = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::Text)
        $planned = ''; $minH = 1e9
        foreach ($t in $root.FindAll([System.Windows.Automation.TreeScope]::Descendants, $cond)) {
            $n = [string]$t.Current.Name
            if ($n -notmatch '^\d{1,2}(:\d{2}){1,2}$') { continue }
            $h = [double]$t.Current.BoundingRectangle.Height
            if ($h -lt $minH) { $minH = $h; $planned = $n }
        }
        $running = [bool]$root.FindFirst([System.Windows.Automation.TreeScope]::Descendants, (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty, 'StopTimerButton')))
        $sig = "$running|$planned"
        $age = if ($script:_onlyTTitleAt) { ((Get-Date) - $script:_onlyTTitleAt).TotalSeconds } else { 999 }
        # never open OnlyT's list while a timer runs (live meeting), and only re-read when something changed
        if ($running) { $script:_onlyTTitleSig = $null; return [string]$script:_onlyTTitle }
        if ($sig -eq $script:_onlyTTitleSig) { return [string]$script:_onlyTTitle }
        $script:_onlyTTitleSig = $sig
        $script:_onlyTTitleAt = Get-Date
        $parts = Get-OnlyTParts
        $sel = @($parts | Where-Object { $_.Selected }) | Select-Object -First 1
        if ($sel) { $script:_onlyTTitle = [string]$sel.Title }
        return [string]$script:_onlyTTitle
    }
    catch { return '' }
}

function Sync-WpfShellHeader {
    # Keeps the header strip exactly over the native title bar (between the icon and the caption buttons).
    $hd = $script:_wpfShellHeader; $w = $script:_wpfShellWindow
    if (-not $hd -or -not $w) { return }
    if (-not $script:_wpfShellTitleAt) { $script:_wpfShellTitleAt = [datetime]::MinValue }
    try {
        $c = $w.Content
        if (-not $c -or -not $c.IsLoaded) { return }
        $src = [System.Windows.PresentationSource]::FromVisual($c)
        if (-not $src) { return }
        $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper $w).Handle
        $r = New-Object PSw34+RECT
        if (-not [PSw34]::GetWindowRect($hwnd, [ref]$r)) { return }
        $clientTop = [int]($c.PointToScreen((New-Object System.Windows.Point 0, 0))).Y
        $m = $src.CompositionTarget.TransformFromDevice
        $dpi = 1.0 / $m.M11
        $left = $r.Left + [int](34 * $dpi)
        $right = $r.Right - [int](56 * $dpi)
        $top = $r.Top + [int](1 * $dpi)
        $height = $clientTop - $top - 1
        if ($right - $left -lt 100 -or $height -lt 10) { return }
        $tl = $m.Transform((New-Object System.Windows.Point $left, $top))
        $wd = ($right - $left) * $m.M11
        $ht = $height * $m.M22
        if ([math]::Abs($hd.Left - $tl.X) -gt 0.2) { $hd.Left = $tl.X }
        if ([math]::Abs($hd.Top - $tl.Y) -gt 0.2) { $hd.Top = $tl.Y }
        if ([math]::Abs($hd.Width - $wd) -gt 0.2) { $hd.Width = $wd }
        if ([math]::Abs($hd.Height - $ht) -gt 0.2) { $hd.Height = $ht }
        $dark = Test-IsDarkTheme
        $kit = Get-ThemeKit $dark
        $hd.Background = ConvertTo-WpfBrush $kit.Panel
        $fg = ConvertTo-WpfBrush $kit.Text
        $hd.FindName('HeaderTitle').Foreground = $fg
        $hd.FindName('HeaderPartText').Foreground = $fg
        $hd.FindName('HeaderArrow').Foreground = $fg
        $hd.FindName('HeaderPartBtn').BorderBrush = ConvertTo-WpfBrush $kit.Border
        $on = [bool]$script:Cfg.OnlyT.Enabled -and [bool]$script:Cfg.OnlyT.ShowCountdown -and [bool](Get-OnlyTProcess)
        $pv = if ($on) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
        $pb = $hd.FindName('HeaderPartBtn')
        if ($pb.Visibility -ne $pv) { $pb.Visibility = $pv }
        if ($on) {
            if (((Get-Date) - $script:_wpfShellTitleAt).TotalMilliseconds -gt 1500) {
                $script:_wpfShellTitleAt = Get-Date
                $tt = if ($script:_onlyTMon) { [string]$script:_onlyTMon.Shared.Title } elseif ($script:_onlyTMonStopped) { '' } else { Get-OnlyTTitle }
                if ($tt -and $tt -ne $script:_wpfShellPartLabel) {
                    $script:_wpfShellPartLabel = $tt
                    $hd.FindName('HeaderPartText').Text = $tt
                }
            }
            # centre over the countdown, which sits at the middle of the window
            $winCenter = ($r.Right - $r.Left) / 2.0 * $m.M11
            $x = $winCenter - ($left - $r.Left) * $m.M11 - $pb.ActualWidth / 2.0
            $x = [math]::Max(0, $x)
            if ([math]::Abs($pb.Margin.Left - $x) -gt 0.5) { $pb.Margin = New-Object System.Windows.Thickness $x, 3, 2, 3 }
        }
        $eye = $hd.FindName('HeaderEyeBtn')
        $eyeOn = [bool]$script:Cfg.OnlyT.Enabled -and [bool](Get-OnlyTProcess)
        $ev = if ($eyeOn) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
        if ($eye.Visibility -ne $ev) { $eye.Visibility = $ev }
        if ($eyeOn) {
            $op = Get-OnlyTProcess
            if ($op -and $script:_otSeenPid -ne $op.Id) {
                # a new OnlyT: start the auto-hide countdown (it opens visible, whatever was saved)
                $script:_otSeenPid = $op.Id; $script:_otSeenAt = Get-Date; $script:_otAutoDone = $false
                if ([bool]$script:Cfg.OnlyT.AutoHide) { $script:Cfg.OnlyT.HideWindow = $false }
            }
            if ([bool]$script:Cfg.OnlyT.AutoHide -and -not $script:_otAutoDone -and ((Get-Date) - $script:_otSeenAt).TotalSeconds -ge [int]$script:Cfg.OnlyT.AutoHideSec) {
                $script:_otAutoDone = $true
                if (Test-OnlyTUpdateAvailable) {
                    # an update notice is showing: keep the window visible so the user can see it (hide it by hand to ignore)
                    try { Log 'OnlyT: update available - window left open (not auto-hidden)' } catch {}
                }
                else {
                    $script:Cfg.OnlyT.HideWindow = $true
                    try { Save-Settings | Out-Null } catch {}
                    try { Log "OnlyT: window auto-hidden after $([int]$script:Cfg.OnlyT.AutoHideSec) s" } catch {}
                }
            }
            $hide = [bool]$script:Cfg.OnlyT.HideWindow
            Set-OnlyTWindowVisible (-not $hide)
            $partW = if ($on) { $pb.ActualWidth } else { 0 }
            $ex = if ($on) { $pb.Margin.Left + $partW + 6 } else { [math]::Max(0, ($r.Right - $r.Left) / 2.0 * $m.M11 - ($left - $r.Left) * $m.M11 - 15) }
            if ([math]::Abs($eye.Margin.Left - $ex) -gt 0.5) { $eye.Margin = New-Object System.Windows.Thickness $ex, 3, 2, 3 }
            $eye.FindName('HeaderEyeGlyph').Foreground = ConvertTo-WpfBrush $kit.Text
            $sl = if ($hide) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
            $slash = $eye.FindName('HeaderEyeSlash')
            if ($slash.Visibility -ne $sl) { $slash.Visibility = $sl }
            $eye.BorderBrush = if ($hide) { ConvertTo-WpfBrush $kit.Border } else { [System.Windows.Media.Brushes]::SteelBlue }
            $eye.ToolTip = if ($hide) { 'OnlyT window is hidden - click to show it' } else { 'OnlyT window is visible - click to hide it' }
        }
    }
    catch {}
}

function Show-OnlyTPartMenu {
    $hd = $script:_wpfShellHeader
    if (-not $hd) { return }
    try {
        $dark = Test-IsDarkTheme
        $kit = Get-ThemeKit $dark
        $menu = New-Object System.Windows.Controls.ContextMenu
        $hex = { param($c) '#{0:X2}{1:X2}{2:X2}' -f $c.R, $c.G, $c.B }
        $pnl = & $hex $kit.Panel; $txtc = & $hex $kit.Text; $brd = & $hex $kit.Border
        $hov = if ($dark) { '#3A3A3A' } else { '#DDE6F3' }
        $ns = 'xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"'
        $menu.Template = [System.Windows.Markup.XamlReader]::Parse("<ControlTemplate $ns TargetType=`"ContextMenu`"><Border Background=`"$pnl`" BorderBrush=`"$brd`" BorderThickness=`"1`" Padding=`"2`"><StackPanel IsItemsHost=`"True`"/></Border></ControlTemplate>")
        $itemTpl = "<ControlTemplate $ns TargetType=`"MenuItem`"><Border x:Name=`"B`" xmlns:x=`"http://schemas.microsoft.com/winfx/2006/xaml`" Background=`"Transparent`" Padding=`"10,5`"><ContentPresenter ContentSource=`"Header`"/></Border><ControlTemplate.Triggers><Trigger Property=`"IsHighlighted`" Value=`"True`"><Setter TargetName=`"B`" Property=`"Background`" Value=`"$hov`"/></Trigger></ControlTemplate.Triggers></ControlTemplate>"
        $menu.Background = ConvertTo-WpfBrush $kit.Panel
        $menu.Foreground = ConvertTo-WpfBrush $kit.Text
        $menu.PlacementTarget = $hd.FindName('HeaderPartBtn')
        $menu.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Bottom
        $parts = $null
        if (Get-OnlyTProcess) { $parts = Get-OnlyTParts }
        if (-not $parts -or $parts.Count -eq 0) {
            $mi = New-Object System.Windows.Controls.MenuItem
            if (Get-OnlyTProcess) { $mi.Header = 'No parts found in OnlyT' } else { $mi.Header = 'OnlyT is not open - click to open it' }
            $mi.Template = [System.Windows.Markup.XamlReader]::Parse($itemTpl)
            $mi.Foreground = ConvertTo-WpfBrush $kit.Text
            $mi.Add_Click({ try { if (-not (Get-OnlyTProcess)) { $script:btnOnlyT.PerformClick() } } catch {} })
            [void]$menu.Items.Add($mi)
        }
        else {
            foreach ($pt in $parts) {
                $mi = New-Object System.Windows.Controls.MenuItem
                $mi.Template = [System.Windows.Markup.XamlReader]::Parse($itemTpl)
                $mi.Foreground = ConvertTo-WpfBrush $kit.Text
                $mi.Header = ("{0}   {1}" -f $pt.Time, $pt.Title).Trim()
                $mi.IsCheckable = $false
                $mi.FontWeight = if ($pt.Selected) { [System.Windows.FontWeights]::Bold } else { [System.Windows.FontWeights]::Normal }
                if ($pt.Selected) { $script:_wpfShellPartLabel = $pt.Title; $script:_onlyTTitle = $pt.Title }
                $mi.Tag = $pt
                $mi.Add_Click({
                        param($s, $e)
                        $q = $s.Tag
                        Set-OnlyTPart $q.Index
                        $script:_wpfShellPartLabel = $q.Title; $script:_onlyTTitle = $q.Title
                        try { $script:_wpfShellHeader.FindName('HeaderPartText').Text = $script:_wpfShellPartLabel } catch {}
                        Update-OnlyTButton
                    })
                [void]$menu.Items.Add($mi)
            }
            try { if ($script:_wpfShellPartLabel) { $hd.FindName('HeaderPartText').Text = $script:_wpfShellPartLabel } } catch {}
        }
        $menu.IsOpen = $true
    }
    catch { try { Log "OnlyT part menu: $_" } catch {} }
}

function Show-WpfShellHeader {
    # Borderless strip owned by the main window, laid over the native title bar: version text + OnlyT part dropdown.
    $w = $script:_wpfShellWindow
    if (-not $w -or $script:_wpfShellHeader) { return }
    try {
        $xaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        WindowStyle="None" ResizeMode="NoResize" ShowInTaskbar="False" Topmost="False" Width="400" Height="30" Background="#202020">
  <Grid>
    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <TextBlock x:Name="HeaderTitle" Grid.Column="0" VerticalAlignment="Center" FontFamily="Segoe UI" FontSize="12" TextTrimming="CharacterEllipsis" Margin="2,0,8,0"/>
    <Border x:Name="HeaderPartBtn" Grid.Column="0" Grid.ColumnSpan="2" HorizontalAlignment="Left" BorderThickness="1" CornerRadius="3" Margin="0,3,2,3" Padding="8,0" Cursor="Hand" Background="Transparent" ToolTip="OnlyT: choose the meeting part">
      <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
        <TextBlock x:Name="HeaderPartText" FontFamily="Segoe UI" FontSize="12" Text="Meeting parts" VerticalAlignment="Center" MaxWidth="190" TextTrimming="CharacterEllipsis"/>
        <TextBlock x:Name="HeaderArrow" FontFamily="Segoe UI Symbol" FontSize="9" Text="&#x25BC;" Margin="8,1,0,0" VerticalAlignment="Center"/>
      </StackPanel>
    </Border>
    <Border x:Name="HeaderEyeBtn" Grid.Column="0" Grid.ColumnSpan="2" HorizontalAlignment="Left" BorderThickness="1" CornerRadius="3" Margin="0,3,2,3" Padding="7,0" Cursor="Hand" Background="Transparent" Visibility="Collapsed" ToolTip="Show / hide the OnlyT window">
      <Grid Width="16" Height="16">
        <TextBlock x:Name="HeaderEyeGlyph" FontFamily="Segoe MDL2 Assets" FontSize="13" Text="&#xE7B3;" VerticalAlignment="Center" HorizontalAlignment="Center"/>
        <Line x:Name="HeaderEyeSlash" X1="1" Y1="15" X2="15" Y2="1" Width="16" Height="16" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round" Stroke="#E53935" Visibility="Collapsed" IsHitTestVisible="False"/>
      </Grid>
    </Border>
  </Grid>
</Window>
'@
        $hd = [System.Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader ([xml]$xaml)))
        $hd.Owner = $w
        if (-not ('OtDrag' -as [type])) {
            Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class OtDrag { [DllImport("user32.dll")] public static extern bool ReleaseCapture(); [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr h, int m, IntPtr w, IntPtr l); }'
        }
        # the strip covers the native title bar, so dragging it must move the main window
        $hd.Add_MouseLeftButtonDown({
                try {
                    $h2 = $script:_wpfShellHeader
                    if ($h2.FindName('HeaderPartBtn').IsMouseOver -or $h2.FindName('HeaderEyeBtn').IsMouseOver) { return }
                    $ow = (New-Object System.Windows.Interop.WindowInteropHelper $script:_wpfShellWindow).Handle
                    [void][OtDrag]::ReleaseCapture()
                    [void][OtDrag]::SendMessage($ow, 0xA1, [IntPtr]2, [IntPtr]::Zero)
                }
                catch {}
            })
        $hd.FindName('HeaderTitle').Text = $w.Title
        $w.Title = ' '
        if ($script:_wpfShellPartLabel) { $hd.FindName('HeaderPartText').Text = $script:_wpfShellPartLabel }
        $hd.FindName('HeaderPartBtn').Add_MouseLeftButtonUp({ Show-OnlyTPartMenu })
        $hd.FindName('HeaderEyeBtn').Add_MouseLeftButtonUp({
                try {
                    $script:_otAutoDone = $true   # a manual choice overrides the auto-hide for this OnlyT session
                    $script:Cfg.OnlyT.HideWindow = -not [bool]$script:Cfg.OnlyT.HideWindow
                    try { Save-Settings | Out-Null } catch {}
                    Set-OnlyTWindowVisible (-not [bool]$script:Cfg.OnlyT.HideWindow) -Front
                    Sync-WpfShellHeader
                }
                catch {}
            })
        $hd.Show()
        $h = (New-Object System.Windows.Interop.WindowInteropHelper $hd).Handle
        $ex = [Win32]::GetWindowLong($h, -20)
        [void][Win32]::SetWindowLong($h, -20, ($ex -bor 0x08000000 -bor 0x80))
        $script:_wpfShellHeader = $hd
        $w.Add_LocationChanged({ Sync-WpfShellHeader })
        $w.Add_SizeChanged({ Sync-WpfShellHeader })
        $t = New-Object System.Windows.Threading.DispatcherTimer
        $t.Interval = [TimeSpan]::FromMilliseconds(500)
        $t.Add_Tick({ Sync-WpfShellHeader; Restore-WpfShellOwnedWindows })
        $t.Start()
        $script:_wpfShellHeaderTimer = $t
        Sync-WpfShellHeader
    }
    catch { try { Log "WPF shell header failed: $_" } catch {} }
}

function Show-WpfShellPreview {
    # Already open - just bring it to front instead of creating a second instance.
    if ($script:_wpfShellWindow) {
        try { $script:_wpfShellWindow.Activate() | Out-Null; return } catch { $script:_wpfShellWindow = $null }
    }
    if (-not (Initialize-WpfShellRuntime)) { return }

    $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="JWL+OBS Assistant - WPF Shell Preview (Phase 2 scaffold)"
        Width="684" SizeToContent="Height" ResizeMode="NoResize" WindowStartupLocation="Manual"
        Topmost="True" ShowInTaskbar="False" ShowActivated="True">
  <Window.Resources>
    <!-- Dark, flat scene-picker context menu - mirrors the look of the main app's own
         dark ContextMenuStrip (e.g. the Toggle Zoom menu): dark panel, no native chevrons/
         checkboxes, flat blue highlight on hover instead of the default Windows theme. -->
    <Style x:Key="ScenePickerMenuStyle" TargetType="ContextMenu">
      <Setter Property="Background" Value="#2D2D2D"/>
      <Setter Property="BorderBrush" Value="#3F3F3F"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Padding" Value="2"/>
      <!-- Full template: the default ContextMenu template draws a light icon-gutter strip down the left side
           (hiding the first characters of every item on this dark menu), so replace it with a plain dark panel. -->
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ContextMenu">
            <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" Padding="{TemplateBinding Padding}" CornerRadius="6">
              <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Cycle"/>
            </Border>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="ScenePickerMenuItemStyle" TargetType="MenuItem">
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="Foreground" Value="White"/>
      <Setter Property="FontSize" Value="13"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="MenuItem">
            <Border x:Name="Bd" Background="{TemplateBinding Background}" Padding="14,7">
              <ContentPresenter ContentSource="Header" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsHighlighted" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="#2D499E"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <!-- Flat rounded-corner style shared by the S/M/L scale buttons and the theme toggle -
         same accent/flat look as the scene picker and camera buttons, just smaller/square. -->
    <Style x:Key="RoundedSquareButtonStyle" TargetType="Button">
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="8">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Opacity" Value="0.85"/>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Setter Property="Opacity" Value="0.7"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <!-- Row 3 icon buttons: radius-12 corners (like the ScenePicker); colors are pushed in from the main app's own buttons. -->
    <Style x:Key="Row3ButtonStyle" TargetType="Button">
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="12">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Opacity" Value="0.85"/>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Setter Property="Opacity" Value="0.7"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
  </Window.Resources>
  <Grid>
    <Grid.RowDefinitions>
      <RowDefinition Height="48"/>
      <RowDefinition Height="*"/>
      <RowDefinition Height="28"/>
    </Grid.RowDefinitions>
    <Border x:Name="TopBar" Grid.Row="0"/>
    <Border x:Name="ContentArea" Grid.Row="0" Grid.RowSpan="2">
      <StackPanel Margin="0,6,0,8">
        <Border x:Name="CameraHostBorder" Height="300" Margin="4,0,4,0" Padding="4" Background="Black" BorderBrush="Gray" BorderThickness="1" CornerRadius="12"/>
        <Grid Margin="0,10,0,0">
        <StackPanel Orientation="Horizontal" HorizontalAlignment="Left">
          <Grid>
          <Button x:Name="AutoToggleBtn" Height="32" Padding="22,0" Margin="4,0,18,0"
                  Background="#0050C8" Foreground="White" BorderBrush="#003580" BorderThickness="1"
                  ToolTip="🔀 Start/Stop Auto Toggle - the dot mirrors the OCR status (grey = inactive, blue = present, red = absent)">
            <Button.Template>
              <ControlTemplate TargetType="Button">
                <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" Padding="{TemplateBinding Padding}" CornerRadius="12">
                  <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/>
                </Border>
                <ControlTemplate.Triggers>
                  <Trigger Property="IsMouseOver" Value="True">
                    <Setter Property="Opacity" Value="0.85"/>
                  </Trigger>
                  <Trigger Property="IsPressed" Value="True">
                    <Setter Property="Opacity" Value="0.7"/>
                  </Trigger>
                </ControlTemplate.Triggers>
              </ControlTemplate>
            </Button.Template>
            <Grid>
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="Auto"/>
              </Grid.ColumnDefinitions>
              <TextBlock x:Name="AutoToggleBtnText" Grid.Column="0" Text="🔀&#xFE0E;" FontFamily="Segoe UI Symbol" FontSize="26" HorizontalAlignment="Center" VerticalAlignment="Center" Margin="0,-6,0,-6"/>
              <Ellipse x:Name="AutoToggleBlip" Grid.Column="1" Width="12" Height="12" Fill="#808080" Margin="10,0,0,0" VerticalAlignment="Center"/>
            </Grid>
          </Button>
          <Border x:Name="AutoPill" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,-6,22,0" Height="14" MinWidth="28" Padding="4,0" CornerRadius="7" Background="#22A022" Visibility="Collapsed" IsHitTestVisible="False">
            <TextBlock x:Name="AutoPillText" Foreground="White" FontSize="9" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/>
          </Border>
          </Grid>
          <Button x:Name="ObsConnectBtn" Width="46" Height="32" Margin="4,0"
                  Background="#0050C8" Foreground="White" BorderBrush="#003580" BorderThickness="1"
                  ToolTip="OBS - flashing blue = OBS is not running (click to start it), blue = OBS is open and connecting, green = online (click to disconnect)">
            <Button.Template>
              <ControlTemplate TargetType="Button">
                <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="12">
                  <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
                <ControlTemplate.Triggers>
                  <Trigger Property="IsMouseOver" Value="True">
                    <Setter Property="Opacity" Value="0.85"/>
                  </Trigger>
                  <Trigger Property="IsPressed" Value="True">
                    <Setter Property="Opacity" Value="0.7"/>
                  </Trigger>
                </ControlTemplate.Triggers>
              </ControlTemplate>
            </Button.Template>
            <Viewbox Width="24" Height="24">
              <Canvas Width="24" Height="24">
                <Ellipse Canvas.Left="1" Canvas.Top="1" Width="22" Height="22" Fill="#1B1B1B" Stroke="#DCDCDC" StrokeThickness="1.4"/>
                <Path Data="M 8.5,4.5 C 7.5,8.5 9.5,11.5 13.5,12.3" Stroke="#DCDCDC" StrokeThickness="1.5" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                <Path Data="M 8.5,4.5 C 7.5,8.5 9.5,11.5 13.5,12.3" Stroke="#DCDCDC" StrokeThickness="1.5" StrokeStartLineCap="Round" StrokeEndLineCap="Round">
                  <Path.RenderTransform><RotateTransform Angle="120" CenterX="12" CenterY="12"/></Path.RenderTransform>
                </Path>
                <Path Data="M 8.5,4.5 C 7.5,8.5 9.5,11.5 13.5,12.3" Stroke="#DCDCDC" StrokeThickness="1.5" StrokeStartLineCap="Round" StrokeEndLineCap="Round">
                  <Path.RenderTransform><RotateTransform Angle="240" CenterX="12" CenterY="12"/></Path.RenderTransform>
                </Path>
              </Canvas>
            </Viewbox>
          </Button>
          <Grid>
          <Button x:Name="VCamBtn" Width="46" Height="32" Margin="4,0"
                  Background="#0050C8" Foreground="White" BorderBrush="#003580" BorderThickness="1"
                  ToolTip="OBS Virtual Camera - blue = OBS offline, flashing red = camera not started (click to start), green = active (click to stop)">
            <Button.Template>
              <ControlTemplate TargetType="Button">
                <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="12">
                  <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
                <ControlTemplate.Triggers>
                  <Trigger Property="IsMouseOver" Value="True">
                    <Setter Property="Opacity" Value="0.85"/>
                  </Trigger>
                  <Trigger Property="IsPressed" Value="True">
                    <Setter Property="Opacity" Value="0.7"/>
                  </Trigger>
                </ControlTemplate.Triggers>
              </ControlTemplate>
            </Button.Template>
            <Viewbox Width="34" Height="34">
              <Canvas Width="24" Height="24">
                <Rectangle Canvas.Left="2" Canvas.Top="5" Width="14" Height="14" RadiusX="3.5" RadiusY="3.5" Stroke="White" StrokeThickness="1.7"/>
                <Path Data="M 7.6,9.2 L 7.6,14.8 L 12.2,12 Z" Stroke="White" StrokeThickness="1.5" StrokeLineJoin="Round"/>
                <Path Data="M 16.5,10.2 L 21.2,7.8 L 21.2,16.2 L 16.5,13.8" Stroke="White" StrokeThickness="1.7" StrokeLineJoin="Round"/>
              </Canvas>
            </Viewbox>
          </Button>
          <Border x:Name="VCamPill" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,-6,2,0" Height="14" MinWidth="28" Padding="4,0" CornerRadius="7" Background="#22A022" Visibility="Collapsed" IsHitTestVisible="False">
            <TextBlock x:Name="VCamPillText" Foreground="White" FontSize="9" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/>
          </Border>
          </Grid>
          <Button x:Name="AfBtn" Width="46" Height="32" Margin="4,0" BorderThickness="1" Background="#808080" Foreground="White" BorderBrush="#606060" Style="{StaticResource Row3ButtonStyle}" ToolTip="Auto Frame - click to turn on/off, right-click for Set ROI, speed and info">
            <Viewbox Width="24" Height="24">
              <Canvas Width="24" Height="24">
                <Ellipse Canvas.Left="4.5" Canvas.Top="4.5" Width="15" Height="15" Stroke="White" StrokeThickness="1.8"/>
                <Path Data="M 12,1.5 L 12,8.5 M 12,15.5 L 12,22.5 M 1.5,12 L 8.5,12 M 15.5,12 L 22.5,12" Stroke="White" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
              </Canvas>
            </Viewbox>
          </Button>
          <Button x:Name="JwlAppBtn" Width="46" Height="32" Margin="4,0" BorderThickness="1" Background="#0050C8" Foreground="White" BorderBrush="#003580" Style="{StaticResource Row3ButtonStyle}" ToolTip="JW Library - flashing blue = not open (click to start it), green = running (click to bring it forward)">
            <Border Width="24" Height="24" CornerRadius="3" Background="#5B3C9E">
              <TextBlock Text="JW" Foreground="White" FontFamily="Segoe UI" FontWeight="SemiBold" FontSize="13" HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
          </Button>
          <Border x:Name="FutureBtnSpace1" Width="46" Height="32" Margin="4,0" Visibility="Hidden" IsHitTestVisible="False"/>
          <Border x:Name="FutureBtnSpace2" Width="46" Height="32" Margin="4,0" Visibility="Hidden" IsHitTestVisible="False"/>
          <Button x:Name="StartMenuBtn" Width="46" Height="32" Margin="4,0" BorderThickness="1" Background="#C80000" Foreground="White" BorderBrush="#8C0000" Style="{StaticResource Row3ButtonStyle}" ToolTip="Start menu - starts the programs ticked in Settings, one after another (OBS + V-Cam, OnlyT, OnlyM, Zoom, then JW Library)">
            <TextBlock Text="&#x23FB;" FontFamily="Segoe UI Symbol" FontSize="20" FontWeight="Bold" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center"/>
          </Button>
        </StackPanel>
        </Grid>
        <StackPanel Orientation="Horizontal" Margin="0,10,0,0" HorizontalAlignment="Left">
        <StackPanel Orientation="Vertical" Width="150" Margin="4,0,0,0">
          <TextBlock x:Name="ProgramLabel" Text="Program:" FontSize="12" FontWeight="SemiBold" HorizontalAlignment="Center" Margin="0,0,0,4"/>
          <Button x:Name="ProgramBtn" Content="Speaker" Height="32" Padding="6,2" IsHitTestVisible="False" Focusable="False"
                  Background="#2D9E49" Foreground="White" BorderBrush="#227335" BorderThickness="1"
                  ToolTip="Current Program (live output) scene">
            <Button.Template>
              <ControlTemplate TargetType="Button">
                <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="12">
                  <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/>
                </Border>
              </ControlTemplate>
            </Button.Template>
          </Button>
        </StackPanel>
        <StackPanel Orientation="Vertical" Margin="8,0,0,0">
          <TextBlock Text=" " FontSize="12" FontWeight="SemiBold" Margin="0,0,0,4"/>
          <Button x:Name="CutBtn" Content="&lt;Cut" Width="56" Height="32" Padding="6,2"
                  Background="#2D9E49" Foreground="White" BorderBrush="#227335" BorderThickness="1"
                  ToolTip="Switch the selected scene to Program (live output)">
            <Button.Template>
              <ControlTemplate TargetType="Button">
                <Border x:Name="CutBd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="12">
                  <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/>
                </Border>
                <ControlTemplate.Triggers>
                  <Trigger Property="IsMouseOver" Value="True">
                    <Setter Property="Opacity" Value="0.85"/>
                  </Trigger>
                  <Trigger Property="IsPressed" Value="True">
                    <Setter Property="Opacity" Value="0.7"/>
                  </Trigger>
                  <Trigger Property="IsEnabled" Value="False">
                    <Setter Property="Opacity" Value="0.5"/>
                  </Trigger>
                </ControlTemplate.Triggers>
              </ControlTemplate>
            </Button.Template>
          </Button>
        </StackPanel>
        <StackPanel x:Name="OnlyTPanel" Orientation="Vertical" Margin="8,0,0,0" Visibility="Collapsed">
          <TextBlock Text=" " FontSize="12" FontWeight="SemiBold" Margin="0,0,0,4"/>
          <Button x:Name="OnlyTBtn" Width="44" Height="32" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}"
