                <Path Data="M 11,7 L 11,12 L 15,14.5" Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" StrokeThickness="2" StrokeLineJoin="Round" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                <Path x:Name="OnlyTPlay" Data="M 23,6.5 L 23,17.5 L 32,12 Z" Fill="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}"/>
                <Rectangle x:Name="OnlyTStop" Canvas.Left="23" Canvas.Top="7" Width="9" Height="10" Fill="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" Visibility="Collapsed"/>
              </Canvas>
            </Viewbox>
          </Button>
        </StackPanel>
        <StackPanel Orientation="Vertical" Width="150" Margin="8,0,0,0">
          <TextBlock x:Name="ScenePickerLabel" Text="ScenePicker:" FontSize="12" FontWeight="SemiBold" HorizontalAlignment="Center" Margin="0,0,0,4"/>
          <Button x:Name="ScenePickerBtn" Content="Speaker" Height="32" Padding="6,2"
                  Background="#2D499E" Foreground="White" BorderBrush="#223573" BorderThickness="1"
                  ToolTip="Left-click: select Speaker. Right-click: pick any scene. Then press Cut to take it live.">
            <Button.Template>
              <ControlTemplate TargetType="Button">
                <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="12">
                  <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/>
                </Border>
                <ControlTemplate.Triggers>
                  <Trigger Property="IsMouseOver" Value="True">
                    <Setter Property="Opacity" Value="0.85"/>
                  </Trigger>
                  <Trigger Property="IsPressed" Value="True">
                    <Setter Property="Opacity" Value="0.7"/>
                  </Trigger>
                </ControlTemplate.Triggers>
              </ControlTemplate>
            </Button.Template>
          </Button>
        </StackPanel>
        <StackPanel Orientation="Vertical" Margin="8,0,0,0">
          <TextBlock Text=" " FontSize="12" FontWeight="SemiBold" Margin="0,0,0,4"/>
          <Grid>
            <Button x:Name="MediaBtn" Width="56" Height="32" Margin="0,0,0,0"
                    Background="#2D499E" Foreground="White" BorderBrush="#223573" BorderThickness="1"
                    ToolTip="Media - switch to the Media scene">
              <Button.Template>
                <ControlTemplate TargetType="Button">
                  <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="12">
                    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                  </Border>
                  <ControlTemplate.Triggers>
                    <Trigger Property="IsMouseOver" Value="True">
                      <Setter Property="Opacity" Value="0.85"/>
                    </Trigger>
                    <Trigger Property="IsPressed" Value="True">
                      <Setter Property="Opacity" Value="0.7"/>
                    </Trigger>
                  </ControlTemplate.Triggers>
                </ControlTemplate>
              </Button.Template>
              <Viewbox Width="26" Height="26">
                <Canvas Width="24" Height="24">
                  <Rectangle Canvas.Left="2" Canvas.Top="3" Width="20" Height="18" RadiusX="3" RadiusY="3" Fill="White"/>
                  <Rectangle Canvas.Left="4.5" Canvas.Top="4.8" Width="2.2" Height="1.8" Fill="#2D499E"/>
                  <Rectangle Canvas.Left="8.6" Canvas.Top="4.8" Width="2.2" Height="1.8" Fill="#2D499E"/>
                  <Rectangle Canvas.Left="12.7" Canvas.Top="4.8" Width="2.2" Height="1.8" Fill="#2D499E"/>
                  <Rectangle Canvas.Left="16.8" Canvas.Top="4.8" Width="2.2" Height="1.8" Fill="#2D499E"/>
                  <Rectangle Canvas.Left="4.5" Canvas.Top="17.4" Width="2.2" Height="1.8" Fill="#2D499E"/>
                  <Rectangle Canvas.Left="8.6" Canvas.Top="17.4" Width="2.2" Height="1.8" Fill="#2D499E"/>
                  <Rectangle Canvas.Left="12.7" Canvas.Top="17.4" Width="2.2" Height="1.8" Fill="#2D499E"/>
                  <Rectangle Canvas.Left="16.8" Canvas.Top="17.4" Width="2.2" Height="1.8" Fill="#2D499E"/>
                  <Path Data="M 9.5,8.6 L 9.5,15.4 L 15.5,12 Z" Fill="#2D499E" Stroke="#2D499E" StrokeThickness="0.8" StrokeLineJoin="Round"/>
                </Canvas>
              </Viewbox>
            </Button>
            <Button x:Name="PipBtn" Width="30" Height="16" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,-10,-2,0"
                    Background="#D25A00" Foreground="White" BorderThickness="0" Visibility="Collapsed"
                    ToolTip="PiP on/off (only works while Media is live) - orange = off, green = on">
              <Button.Template>
                <ControlTemplate TargetType="Button">
                  <Border Background="{TemplateBinding Background}" CornerRadius="7">
                    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/>
                  </Border>
                  <ControlTemplate.Triggers>
                    <Trigger Property="IsMouseOver" Value="True">
                      <Setter Property="Opacity" Value="0.85"/>
                    </Trigger>
                    <Trigger Property="IsPressed" Value="True">
                      <Setter Property="Opacity" Value="0.7"/>
                    </Trigger>
                  </ControlTemplate.Triggers>
                </ControlTemplate>
              </Button.Template>
              <TextBlock Text="PIP" FontFamily="Segoe UI" FontSize="9.5" FontWeight="Bold"/>
            </Button>
          </Grid>
        </StackPanel>
        </StackPanel>
        <StackPanel Orientation="Horizontal" Margin="0,12,0,0" HorizontalAlignment="Left">
          <Grid>
          <Button x:Name="MusicBtn" Width="68" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="Background music - click to start/stop, right-click for the mini player">
            <StackPanel Orientation="Horizontal">
              <TextBlock x:Name="MusicNote1" Text="&#x2669;" FontFamily="Segoe UI Symbol" FontSize="15" VerticalAlignment="Center"><TextBlock.RenderTransform><TranslateTransform/></TextBlock.RenderTransform></TextBlock>
              <TextBlock x:Name="MusicNote2" Text="&#x266A;" FontFamily="Segoe UI Symbol" FontSize="15" VerticalAlignment="Center"><TextBlock.RenderTransform><TranslateTransform/></TextBlock.RenderTransform></TextBlock>
              <TextBlock x:Name="MusicNote3" Text="&#x266B;" FontFamily="Segoe UI Symbol" FontSize="15" VerticalAlignment="Center"><TextBlock.RenderTransform><TranslateTransform/></TextBlock.RenderTransform></TextBlock>
              <TextBlock x:Name="MusicStateIcon" Text="&#x25B6;&#xFE0E;" FontFamily="Segoe UI Symbol" FontSize="13" Margin="3,0,0,0" VerticalAlignment="Center"/>
            </StackPanel>
          </Button>
          <Border x:Name="MusicPill" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,-6,2,0" Height="14" MinWidth="28" Padding="4,0" CornerRadius="7" Background="#22A022" Visibility="Collapsed" IsHitTestVisible="False">
            <TextBlock x:Name="MusicPillText" Foreground="White" FontSize="9" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/>
          </Border>
          </Grid>
          <Button x:Name="RecBtn" Width="74" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="OBS recording - click to start/stop">
            <StackPanel Orientation="Horizontal">
              <Image x:Name="RecImage" Width="24" Height="24" RenderOptions.BitmapScalingMode="HighQuality"/>
              <TextBlock x:Name="RecText" Text="REC" FontSize="12" FontWeight="Bold" Foreground="#E64646" Margin="5,0,0,0" VerticalAlignment="Center"/>
            </StackPanel>
          </Button>
          <Button x:Name="JwlBtn" Width="46" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="JWL second display - click for the menu">
            <Grid>
              <Image x:Name="JwlImage" Width="26" Height="26" RenderOptions.BitmapScalingMode="HighQuality"/>
              <TextBlock x:Name="JwlBadge" Text="!" Foreground="#FFB900" FontWeight="Bold" FontSize="12" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,-6,-9,0" Visibility="Collapsed"/>
            </Grid>
          </Button>
          <Button x:Name="ZoomToggleBtn" Width="46" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="Toggle Zoom - move the Zoom meeting between the main monitor and the projector">
            <Viewbox Width="28" Height="20">
              <Canvas Width="26" Height="18">
                <Path x:Name="ZoomArrows" Data="M 11,4 L 4,9 L 11,14 M 4,9 L 17,9 M 15,4 L 22,9 L 15,14 M 22,9 L 9,9" Stroke="#50DC50" StrokeThickness="2.5" StrokeLineJoin="Round" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
              </Canvas>
            </Viewbox>
          </Button>
          <Button x:Name="HandBtn" Width="46" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="Hand alert - full-screen hand overlay">
            <Grid>
              <TextBlock x:Name="HandText" Text="&#x270B;" FontFamily="Segoe UI Emoji" FontSize="20" VerticalAlignment="Center"/>
              <Grid x:Name="HandAutoDot" Width="14" Height="14" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,-7,-9,0" Visibility="Collapsed" ToolTip="Auto Hand Alert is on">
                <Ellipse Fill="#E02020" Stroke="#FFFFFF" StrokeThickness="0.8"/>
                <TextBlock Text="A" Foreground="White" FontWeight="Bold" FontSize="9" FontFamily="Segoe UI" HorizontalAlignment="Center" VerticalAlignment="Center" Margin="0,-1,0,0"/>
              </Grid>
            </Grid>
          </Button>
        </StackPanel>
        <StackPanel Orientation="Horizontal" Margin="0,10,0,0" HorizontalAlignment="Left">
          <StackPanel Orientation="Vertical">
            <Button x:Name="ZoomJoinBtn" Width="92" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="Join the Zoom meeting">
              <StackPanel Orientation="Horizontal">
              <Grid>
                <Viewbox x:Name="JoinIcon" Width="26" Height="22">
                  <Canvas Width="24" Height="24">
                    <Rectangle Canvas.Left="2" Canvas.Top="5" Width="14" Height="14" RadiusX="3.5" RadiusY="3.5" Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" StrokeThickness="1.8"/>
                    <Path Data="M 16.5,10.2 L 21.2,7.8 L 21.2,16.2 L 16.5,13.8" Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" StrokeThickness="1.8" StrokeLineJoin="Round"/>
                    <Path Data="M 9,8.8 L 9,15.2 M 5.8,12 L 12.2,12" Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                  </Canvas>
                </Viewbox>
                <TextBlock x:Name="JoinStateGlyph" Text="&#x2714;" FontFamily="Segoe UI Symbol" FontSize="18" VerticalAlignment="Center" Visibility="Collapsed"/>
              </Grid>
              <TextBlock Text="Zoom" FontSize="14" FontWeight="SemiBold" Margin="6,0,0,0" VerticalAlignment="Center"/>
              </StackPanel>
            </Button>
          </StackPanel>
          <StackPanel Orientation="Vertical">
            <Button x:Name="ZoomMuteBtn" Width="44" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="Mute all Zoom participants">
              <TextBlock Text="&#xE74F;" FontFamily="Segoe MDL2 Assets" FontSize="17" VerticalAlignment="Center"/>
            </Button>
            <TextBlock x:Name="MuteBadge" Text=" " FontSize="10" FontWeight="Bold" Height="14" HorizontalAlignment="Center" Visibility="Hidden"/>
          </StackPanel>
          <StackPanel Orientation="Vertical">
            <Button x:Name="ZoomMicBtn" Width="36" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="Zoom microphone status / mute">
              <Grid>
                <TextBlock x:Name="MicGlyph" Text="&#xE720;" FontFamily="Segoe MDL2 Assets" FontSize="16" VerticalAlignment="Center" HorizontalAlignment="Center"/>
                <Line x:Name="MicSlash" Width="28" Height="24" X1="0" Y1="0" X2="28" Y2="24" Stroke="#FF4646" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" Visibility="Collapsed"/>
              </Grid>
            </Button>
            <TextBlock x:Name="MicBadge" Text=" " FontSize="10" FontWeight="Bold" Height="14" HorizontalAlignment="Center" Visibility="Hidden"/>
          </StackPanel>
          <StackPanel Orientation="Vertical">
            <Button x:Name="ZoomCamBtn" Width="36" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="Zoom camera status / toggle">
              <Grid>
                <TextBlock x:Name="CamGlyph" Text="&#xE714;" FontFamily="Segoe MDL2 Assets" FontSize="16" VerticalAlignment="Center" HorizontalAlignment="Center"/>
                <Line x:Name="CamSlash" Width="28" Height="24" X1="0" Y1="0" X2="28" Y2="24" Stroke="#FF4646" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" Visibility="Collapsed"/>
              </Grid>
            </Button>
            <TextBlock x:Name="CamBadge" Text=" " FontSize="10" FontWeight="Bold" Height="14" HorizontalAlignment="Center" Visibility="Hidden"/>
          </StackPanel>
          <StackPanel Orientation="Vertical">
            <Button x:Name="ZoomPollsBtn" Width="44" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="Zoom polls / quizzes">
              <Viewbox Width="22" Height="22">
                <Canvas Width="24" Height="24">
                  <Rectangle Canvas.Left="3" Canvas.Top="12" Width="5" Height="9" Fill="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}"/>
                  <Rectangle Canvas.Left="9.5" Canvas.Top="4" Width="5" Height="17" Fill="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}"/>
                  <Rectangle Canvas.Left="16" Canvas.Top="9" Width="5" Height="12" Fill="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}"/>
                </Canvas>
              </Viewbox>
            </Button>
            <TextBlock x:Name="PollsReadout" Text="Polls: --" FontSize="10" FontWeight="Bold" Height="14" HorizontalAlignment="Center" Foreground="#00E66E" Cursor="Hand" ToolTip="Click to read the poll/attendance status"/>
          </StackPanel>
          <StackPanel Orientation="Vertical">
            <Button x:Name="ZoomFocusBtn" Width="44" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="Zoom focus mode">
              <Grid>
                <Viewbox x:Name="FocusIcon" Width="22" Height="22">
                  <Canvas Width="24" Height="24">
                    <Ellipse Canvas.Left="3" Canvas.Top="3" Width="18" Height="18" Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" StrokeThickness="2"/>
                    <Ellipse Canvas.Left="8.5" Canvas.Top="8.5" Width="7" Height="7" Fill="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}"/>
                  </Canvas>
                </Viewbox>
                <TextBlock x:Name="FocusStateGlyph" Text="&#x2026;" FontFamily="Segoe UI Symbol" FontSize="18" VerticalAlignment="Center" Visibility="Collapsed"/>
              </Grid>
            </Button>
            <TextBlock x:Name="FocusBadge" Text=" " FontSize="10" FontWeight="Bold" Height="14" HorizontalAlignment="Center" Visibility="Hidden"/>
          </StackPanel>
          <StackPanel Orientation="Vertical">
            <Button x:Name="ZoomAdmitBtn" Width="44" Height="32" Margin="4,0" BorderThickness="1" Style="{StaticResource Row3ButtonStyle}" ToolTip="Admit participants from the Zoom waiting room">
              <Grid>
                <Viewbox x:Name="AdmitIcon" Width="24" Height="22">
                  <Canvas Width="26" Height="24">
                    <Ellipse Canvas.Left="4" Canvas.Top="3" Width="9" Height="9" Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" StrokeThickness="2"/>
                    <Path Data="M 2,21 C 2,15 5,13.5 8.5,13.5 C 12,13.5 15,15 15,21" Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                    <Path Data="M 16,12 L 19.5,15.5 L 25,8.5" Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" StrokeThickness="2.2" StrokeLineJoin="Round" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                  </Canvas>
                </Viewbox>
                <TextBlock x:Name="AdmitStateGlyph" Text="&#x27F3;" FontFamily="Segoe UI Symbol" FontSize="18" VerticalAlignment="Center" Visibility="Collapsed"/>
              </Grid>
            </Button>
            <TextBlock x:Name="AdmitBadge" Text=" " FontSize="10" FontWeight="Bold" Height="14" HorizontalAlignment="Center" Foreground="#FF8C00" Visibility="Hidden"/>
          </StackPanel>
        </StackPanel>
      </StackPanel>
    </Border>
    <Border x:Name="StatusBar" Grid.Row="2">
      <Grid>
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="Auto"/>
          <ColumnDefinition Width="Auto"/>
          <ColumnDefinition Width="Auto"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <TextBlock x:Name="ObsStatusLabel" Grid.Column="0" VerticalAlignment="Center" Margin="12,0" FontSize="12" FontWeight="SemiBold"/>
        <TextBlock x:Name="UpdateStatusLabel" Grid.Column="1" VerticalAlignment="Center" Margin="0,0,12,0" FontSize="12" Cursor="Hand" ToolTip="App update status - click to check / open the download"/>
        <TextBlock x:Name="ZoomHealthLabel" Grid.Column="2" VerticalAlignment="Center" Margin="0,0,12,0" FontSize="12" FontWeight="SemiBold" Foreground="#FF9A1E" Visibility="Collapsed" Text="&#x26A0; Zoom" ToolTip="Zoom is responding slowly or its status keeps flipping - restarting Zoom usually fixes it"/>
        <TextBlock x:Name="NextMeetingLabel" Grid.Column="3" VerticalAlignment="Center" Margin="0,0,12,0" FontSize="12" HorizontalAlignment="Right"/>
        <TextBlock x:Name="ZoomStartupLabel" Grid.Column="1" Grid.ColumnSpan="3" VerticalAlignment="Center" Margin="0,0,12,0" FontSize="12" FontWeight="SemiBold" HorizontalAlignment="Left" Visibility="Collapsed" ToolTip="Zoom start-up progress: join, Participants panel, Polls"/>
        <TextBlock x:Name="StartMenuLabel" Grid.Column="1" Grid.ColumnSpan="3" VerticalAlignment="Center" Margin="0,0,12,0" FontSize="12" FontWeight="SemiBold" HorizontalAlignment="Left" Visibility="Collapsed" ToolTip="Start menu progress"/>
      </Grid>
    </Border>
  </Grid>
</Window>
"@

    # The clock and the top-right buttons live in their own borderless, transparent window that sits ABOVE the
    # main window. The camera video is a native child window that WPF elements can never draw over, so the only way
    # to put the clock/buttons on top of the (now taller) preview is a separate top-level window that follows it.
    $overlayXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        WindowStyle="None" AllowsTransparency="True" Background="{x:Null}" ShowInTaskbar="False" ShowActivated="False"
        ResizeMode="NoResize" SizeToContent="WidthAndHeight" Title="JWL+OBS Assistant overlay">
  <!--RESOURCES-->
  <Grid x:Name="OverlayRoot" Height="48">
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="*"/>
      <ColumnDefinition Width="Auto"/>
      <ColumnDefinition Width="Auto"/>
      <ColumnDefinition Width="Auto"/>
    </Grid.ColumnDefinitions>
    <Border x:Name="ClockBorder" Grid.Column="0" Margin="12,6,12,0" Padding="10,2" CornerRadius="10" Background="#99000000" HorizontalAlignment="Left" VerticalAlignment="Center">
      <TextBlock x:Name="ClockText" FontSize="26" HorizontalAlignment="Left" Foreground="White"/>
    </Border>
    <Grid x:Name="OnlyTCountPanel" Grid.ColumnSpan="4" Margin="0,6,0,0" HorizontalAlignment="Center" VerticalAlignment="Center" Visibility="Collapsed">
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="108"/>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="108"/>
      </Grid.ColumnDefinitions>
      <StackPanel x:Name="OnlyTLeftPanel" Grid.Column="0" Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Center" Visibility="Hidden">
        <Button x:Name="OnlyTPauseBtn" Width="28" Height="28" Margin="2,0" Background="#CC1E1E1E" BorderBrush="#444444" BorderThickness="1" Style="{StaticResource RoundedSquareButtonStyle}" Visibility="Collapsed" ToolTip="Pause the OnlyT timer">
          <TextBlock Text="&#x275A;&#x275A;" FontFamily="Segoe UI Symbol" FontSize="11" Foreground="White"/>
        </Button>
        <Button x:Name="OnlyTToggleBtn" Width="28" Height="28" Margin="2,0" Background="#CC1E1E1E" BorderBrush="#444444" BorderThickness="1" Style="{StaticResource RoundedSquareButtonStyle}" ToolTip="Start / stop the OnlyT timer">
          <TextBlock x:Name="OnlyTToggleGlyph" Text="&#x25B6;" FontFamily="Segoe UI Symbol" FontSize="13" Foreground="White"/>
        </Button>
      </StackPanel>
      <Border x:Name="OnlyTCountBorder" Grid.Column="1" Margin="4,0" Padding="10,2" CornerRadius="10" Background="#99000000" VerticalAlignment="Center">
        <TextBlock x:Name="OnlyTCountText" FontSize="26" Foreground="White" Text="00:00" HorizontalAlignment="Center"/>
      </Border>
      <StackPanel x:Name="OnlyTRightPanel" Grid.Column="2" Orientation="Horizontal" HorizontalAlignment="Left" VerticalAlignment="Center" Visibility="Hidden">
        <Button x:Name="OnlyTPlusBtn" Width="28" Height="28" Margin="2,0" Background="#CC1E1E1E" BorderBrush="#444444" BorderThickness="1" Style="{StaticResource RoundedSquareButtonStyle}" ToolTip="OnlyT: plus 1 minute (Shift = plus 5 minutes)">
          <TextBlock Text="+" FontSize="18" Foreground="White" Margin="0,-3,0,0"/>
        </Button>
        <Button x:Name="OnlyTMinusBtn" Width="28" Height="28" Margin="2,0" Background="#CC1E1E1E" BorderBrush="#444444" BorderThickness="1" Style="{StaticResource RoundedSquareButtonStyle}" ToolTip="OnlyT: minus 1 minute (Shift = minus 5 minutes)">
          <TextBlock Text="&#x2212;" FontSize="18" Foreground="White" Margin="0,-3,0,0"/>
        </Button>
        <Button x:Name="OnlyTCoBtn" Width="28" Height="28" Margin="2,0" Background="#CC1E1E1E" BorderBrush="#444444" BorderThickness="1" Style="{StaticResource RoundedSquareButtonStyle}" ToolTip="OnlyT: circuit visit (changes only the title of the last part)">
          <TextBlock Text="CO" FontSize="11" FontWeight="Bold" Foreground="White" FontFamily="Segoe UI"/>
        </Button>
      </StackPanel>
    </Grid>
    <StackPanel x:Name="ScaleButtonsPanel" Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center" Margin="0,0,8,0">
      <Button x:Name="ScaleBtn" Content="S" Width="28" Height="28" Margin="2,0" BorderBrush="#444444" BorderThickness="1" Style="{StaticResource RoundedSquareButtonStyle}" ToolTip="Zoom size - hover to choose S / M / L (drives the main app's real S/M/L zoom)"/>
      <Popup x:Name="ScalePopup" PlacementTarget="{Binding ElementName=ScaleBtn}" Placement="Bottom" StaysOpen="True" AllowsTransparency="True" IsOpen="False">
        <Border x:Name="ScalePopupBorder" Background="#1E1E1E" BorderBrush="#444444" BorderThickness="1" CornerRadius="8" Padding="0,2">
          <StackPanel Orientation="Vertical">
            <Button x:Name="ScaleOptA" Content="M" Width="28" Height="28" Margin="2" BorderBrush="#444444" BorderThickness="1" Style="{StaticResource RoundedSquareButtonStyle}" ToolTip="Switch zoom size"/>
            <Button x:Name="ScaleOptB" Content="L" Width="28" Height="28" Margin="2" BorderBrush="#444444" BorderThickness="1" Style="{StaticResource RoundedSquareButtonStyle}" ToolTip="Switch zoom size"/>
          </StackPanel>
        </Border>
      </Popup>
    </StackPanel>
    <Button x:Name="ThemeToggleBtn" Grid.Column="1" Width="32" Height="32" Margin="0,0,8,0" Background="#1E1E1E" BorderBrush="#444444" BorderThickness="1" Style="{StaticResource RoundedSquareButtonStyle}" ToolTip="Toggle the main app's real dark/light theme">
      <Grid Width="20" Height="20">
        <Canvas x:Name="SunIcon" Width="20" Height="20">
          <Ellipse Canvas.Left="6" Canvas.Top="6" Width="8" Height="8" Fill="#FFD54A"/>
          <Line X1="16.5" Y1="10" X2="19" Y2="10" Stroke="#FFD54A" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
          <Line X1="14.6" Y1="14.6" X2="16.4" Y2="16.4" Stroke="#FFD54A" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
          <Line X1="10" Y1="16.5" X2="10" Y2="19" Stroke="#FFD54A" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
          <Line X1="5.4" Y1="14.6" X2="3.6" Y2="16.4" Stroke="#FFD54A" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
          <Line X1="3.5" Y1="10" X2="1" Y2="10" Stroke="#FFD54A" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
          <Line X1="5.4" Y1="5.4" X2="3.6" Y2="3.6" Stroke="#FFD54A" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
          <Line X1="10" Y1="3.5" X2="10" Y2="1" Stroke="#FFD54A" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
          <Line X1="14.6" Y1="5.4" X2="16.4" Y2="3.6" Stroke="#FFD54A" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
        </Canvas>
        <Canvas x:Name="MoonIcon" Width="20" Height="20" Visibility="Collapsed">
          <Canvas.Clip>
            <EllipseGeometry Center="10,10" RadiusX="7" RadiusY="7"/>
          </Canvas.Clip>
          <Ellipse Canvas.Left="3" Canvas.Top="3" Width="14" Height="14" Fill="#FFD54A"/>
          <Ellipse Canvas.Left="6.5" Canvas.Top="1.5" Width="14" Height="14" Fill="#1E1E1E"/>
        </Canvas>
      </Grid>
    </Button>
    <Button x:Name="SettingsBtn" Grid.Column="3" Width="32" Height="32" Margin="0,0,12,0" Background="#1E1E1E" Foreground="#FFD54A" BorderBrush="#444444" BorderThickness="1" Style="{StaticResource RoundedSquareButtonStyle}" ToolTip="Settings - OBS connection, OCR, meeting times, XR mixer, and more">
      <TextBlock x:Name="SettingsGlyph" Text="&#x2699;&#xFE0E;" FontFamily="Segoe UI Symbol" FontSize="22" Margin="0,-3,0,0" RenderTransformOrigin="0.5,0.5"/>
    </Button>
  </Grid>
</Window>
"@

    try {
        $xml = [xml]$xaml
        Add-WpfShellButtonStyling $xml
        $reader = New-Object System.Xml.XmlNodeReader $xml
        $window = [System.Windows.Markup.XamlReader]::Load($reader)
    }
    catch {
        Log "WPF shell preview: failed to build window: $_"
        return
    }

    # The preview's Width must match the main app's real content width (both represent the
    # same "S" scale), but WPF Width is in 96-DPI device-independent units while the main
    # app's ClientSize.Width is physical pixels — convert so they render the same physical
    # size regardless of the monitor's DPI scaling. Always applied (ignoring any stale saved
    # Width) since the window is no longer user-resizable.
    $__previewWidthDip = 684
    try {
        if ($script:_baseMinW) { $__previewWidthDip = [double]$script:_baseMinW / (Get-DpiScaleFactor) }
    }
    catch {}
    $window.Width = $__previewWidthDip

    # Window height in 96-DPI units - edit this number to make the window taller/shorter.
    $__previewHeightDip = 583
    $window.SizeToContent = [System.Windows.SizeToContent]::Manual
    $window.Height = $__previewHeightDip

    # Restore the last saved position if it still lands on a connected monitor; otherwise force
    # the shell to a visible spot on the primary monitor so it cannot appear off-screen or flicker
    # in and immediately disappear.
    $savedGeom = Get-WpfShellSavedGeometry
    $screen = [System.Windows.Forms.Screen]::PrimaryScreen
    $work = $screen.WorkingArea
    $dpi = [double](Get-DpiScaleFactor)
    $window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::Manual
    $window.Left = ($work.Left + (($work.Width - ($window.Width * $dpi)) / 2)) / $dpi
    $window.Top = ($work.Top + (($work.Height - ($window.Height * $dpi)) / 2)) / $dpi
    if ($savedGeom) {
        # The window is no longer user-resizable, so only the position is restored; the height
        # always fits the content (a stale saved height would leave empty space at the bottom).
        $window.Left = $savedGeom.Left
        $window.Top = $savedGeom.Top
        $window.Width = $__previewWidthDip
    }
    $window.Topmost = $true

    $script:_wpfShellWindow = $window
    [void](New-WpfShellOverlay $window $xaml $overlayXaml)

    $clockText = $window.FindName('ClockText')
    if ($clockText) { $clockText.Text = (Get-Date).ToString('h:mm:ss tt') }

    # These buttons call the exact same functions the main WinForms app's own theme/scale
    # buttons use ($btnTheme.Add_Click logic and Set-UIScale) - they are real controls that
    # drive the live app, not a cosmetic mirror. Confirms the WPF shell can act as a genuine
    # control surface ahead of eventually replacing the WinForms chrome.
    $themeToggleBtn = $window.FindName('ThemeToggleBtn')
    if ($themeToggleBtn) {
        $themeToggleBtn.Add_Click({
                try {
                    $script:Cfg.UI.Theme = $(if ([string]$script:Cfg.UI.Theme -eq 'Dark') { 'Light' } else { 'Dark' })
                    Set-ThemeFromCfg
                    Save-Settings | Out-Null
                }
                catch { Log "WPF shell preview: theme toggle failed: $_" }
            })
    }
    $scalePopup = $window.FindName('ScalePopup')
    $scaleMainBtn = $window.FindName('ScaleBtn')
    $scalePopupBorder = $window.FindName('ScalePopupBorder')
    if ($scalePopup -and $scaleMainBtn -and $scalePopupBorder) {
        # Hover flyout: opens when the pointer enters the S/M/L button, closes ~300ms after the
        # pointer leaves both the button and the flyout (the delay lets it cross the gap).
        $scaleCloseTimer = New-Object System.Windows.Threading.DispatcherTimer
        $scaleCloseTimer.Interval = [TimeSpan]::FromMilliseconds(300)
        $scaleCloseTimer.Add_Tick({
                param($tmr, $tmrArgs)
                $tmr.Stop()
                $scalePopup.IsOpen = $false
            }.GetNewClosure())
        $scaleMainBtn.Add_MouseEnter({
                $scaleCloseTimer.Stop()
                $scalePopup.IsOpen = $true
            }.GetNewClosure())
        $scaleMainBtn.Add_MouseLeave({ $scaleCloseTimer.Start() }.GetNewClosure())
        $scalePopupBorder.Add_MouseEnter({ $scaleCloseTimer.Stop() }.GetNewClosure())
        $scalePopupBorder.Add_MouseLeave({ $scaleCloseTimer.Start() }.GetNewClosure())
        foreach ($optName in @('ScaleOptA', 'ScaleOptB')) {
            $opt = $window.FindName($optName)
            if ($opt) {
                $opt.Add_Click({
                        param($clickSender, $clickArgs)
                        try { Set-WpfShellScaleLevel ([int]$clickSender.Tag) } catch { Log "WPF shell preview: scale change failed: $_" }
                        $scaleCloseTimer.Stop()
                        $scalePopup.IsOpen = $false
                    }.GetNewClosure())
            }
        }
    }
    # OnlyT hover controls (shown only while the pointer is over the preview and "Show Countdown in UI" is on):
    # minus / plus drive OnlyT's own -/+ buttons (Shift = 5 minutes), the third one is the app's OnlyT start/stop button.
    foreach ($ot in @(@('OnlyTMinusBtn', 'DecrementTimerButton'), @('OnlyTPlusBtn', 'IncrementTimerButton'))) {
        $otBtn = $window.FindName($ot[0])
        $otId = $ot[1]
        if ($otBtn) {
            $otBtn.Add_Click({
                    $n = if ([System.Windows.Forms.Control]::ModifierKeys -band [System.Windows.Forms.Keys]::Shift) { 5 } else { 1 }
                    Step-OnlyTTimer $otId $n
                }.GetNewClosure())
        }
    }
    $otToggle = $window.FindName('OnlyTToggleBtn')
    if ($otToggle) { $otToggle.Add_Click({ try { $script:btnOnlyT.PerformClick() } catch {} }) }
    $otCo = $window.FindName('OnlyTCoBtn')
    if ($otCo) { $otCo.Add_Click({ try { Invoke-OnlyTCircuitVisit } catch {} }) }
    $otPause = $window.FindName('OnlyTPauseBtn')
    if ($otPause) { $otPause.Add_Click({ try { Invoke-OnlyTPause } catch {} }) }

    $settingsBtn = $window.FindName('SettingsBtn')
    if ($settingsBtn) {
        # Drives the main app's real settings button (same Show-SettingsDialog). Building that dialog takes a
        # moment and blocks the UI thread, so the gear spins on WPF's render thread (keeps turning while the
        # UI thread is busy) and the button turns orange; both revert as soon as the dialog appears.
        $settingsBtn.Add_Click({
                param($clickSender, $clickArgs)
                Log "WPF shell: settings button clicked (busy=$([bool]$script:_settingsDialogBusy))"
                if ($script:_settingsDialogBusy) { return }
                $glyph = $null; $rot = $null; $oldBg = $null; $spin = $null
                $stopSpin = {}
                try {
                    $glyph = $script:_wpfShellWindow.FindName('SettingsGlyph')
                    if ($glyph) {
                        $oldBg = $clickSender.Background
                        $clickSender.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromRgb(200, 120, 0))
                        # The spinning gear is drawn by a small window on its own thread (see Start-WpfSettingsSpinner),
                        # so it keeps turning while this thread builds the dialog.
                        $spin = Start-WpfSettingsSpinner $clickSender
                        # Let WPF show the orange button and the spinner before the UI thread gets busy.
                        $clickSender.Dispatcher.Invoke([Action] {}, [System.Windows.Threading.DispatcherPriority]::Render)
                    }
                    $script:_wpfSettingsSpinStop = {
                        try { if ($spin) { $spin.Stop = $true } } catch {}
                        try { if ($oldBg) { $clickSender.Background = $oldBg } } catch {}
                    }.GetNewClosure()
                    $script:_onSettingsDialogShowing = $script:_wpfSettingsSpinStop
                    if ($script:btnSettingsGear -and -not $script:btnSettingsGear.IsDisposed) { $script:btnSettingsGear.PerformClick() }
                }
                catch { Log "WPF shell preview: settings failed: $_" }
                finally {
                    $script:_onSettingsDialogShowing = $null
                    try { if ($script:_wpfSettingsSpinStop) { & $script:_wpfSettingsSpinStop } } catch {}
                    $script:_wpfSettingsSpinStop = $null
                }
            })
    }
    $cameraToggleBtn = $window.FindName('CameraToggleBtn')
    if ($cameraToggleBtn) {
        $cameraToggleBtn.Add_Click({
                try {
                    if ($script:_wpfShellCamActive) { Stop-WpfShellCameraPreview } else { Start-WpfShellCameraPreview }
                }
                catch { Log "WPF shell preview: camera toggle failed: $_" }
            })
    }
    $obsConnectBtn = $window.FindName('ObsConnectBtn')
    if ($obsConnectBtn) {
        # Drives the main app's real OBS connect/disconnect button so behavior stays identical.
        $obsConnectBtn.Add_Click({
                try { if ($script:btnObsWS -and -not $script:btnObsWS.IsDisposed) { $script:btnObsWS.PerformClick() } } catch { Log "WPF shell preview: OBS connect failed: $_" }
            })
    }
    $afBtnWpf = $window.FindName('AfBtn')
    if ($afBtnWpf) {
        # Left-click drives the main app's AF on/off button; right-click opens the AF menu (Set ROI / speed / info).
        $afBtnWpf.Add_Click({
                try { Invoke-WpfShellMainAfButton 'btnAfToggle' } catch { Log "WPF shell preview: AF toggle failed: $_" }
            })
        $afBtnWpf.Add_MouseRightButtonUp({
                param($clickSender, $clickArgs)
                try { Show-WpfShellAfMenu } catch { Log "WPF shell preview: AF menu failed: $_" }
                $clickArgs.Handled = $true
            })
    }
    $vcamBtn = $window.FindName('VCamBtn')
    $jwlAppBtn = $window.FindName('JwlAppBtn')
    if ($jwlAppBtn) {
        $jwlAppBtn.Add_Click({
                try { [void](Start-JwlApp); Update-WpfShellJwlAppButton } catch { Log "WPF shell preview: JW Library start failed: $_" }
            })
    }
    $startMenuBtn = $window.FindName('StartMenuBtn')
    if ($startMenuBtn) {
        $startMenuBtn.Add_Click({
                try { Invoke-StartMenuSequence } catch { Log "WPF shell preview: Start menu failed: $_" }
            })
        Update-WpfShellStartMenuButton
    }
    if ($vcamBtn) {
        # Drives the main app's real V-Cam button so start/stop behavior stays identical.
        $vcamBtn.Add_Click({
                try { if ($script:btnVCamStatus -and -not $script:btnVCamStatus.IsDisposed) { $script:btnVCamStatus.PerformClick() } } catch { Log "WPF shell preview: V-Cam toggle failed: $_" }
            })
    }
    $autoToggleBtn = $window.FindName('AutoToggleBtn')
    if ($autoToggleBtn) {
        $autoToggleBtn.Add_Click({
                try { if ($script:running) { Stop-AutoToggle } else { Start-AutoToggle } } catch { Log "WPF shell preview: auto toggle failed: $_" }
            })
    }
    $mediaBtn = $window.FindName('MediaBtn')
    if ($mediaBtn) {
        # Drives the main app's real Media button (remembers the previous scene, handles PiP reset).
        $mediaBtn.Add_Click({
                try { if ($script:btnMed -and -not $script:btnMed.IsDisposed) { $script:btnMed.PerformClick() } } catch { Log "WPF shell preview: media failed: $_" }
            })
    }
    $pipBtn = $window.FindName('PipBtn')
    if ($pipBtn) {
        $pipBtn.Add_Click({
                try { Switch-MediaPip; Update-WpfShellMediaButton } catch { Log "WPF shell preview: PiP toggle failed: $_" }
            })
    }
    $cutBtn = $window.FindName('CutBtn')
    # Row 3: each button drives the main app's real button of the same job (all existing logic,
    # dialogs and colors stay in the main app); menus open at the mouse pointer.
    $row3Map = @{ MusicBtn = 'btnMusicToggle'; RecBtn = 'btnOBSRecord'; JwlBtn = 'btnJwlMonitor'; ZoomToggleBtn = 'btnZoomToggle'; HandBtn = 'btnHandAlert'
        ZoomJoinBtn = 'btnZoomJoin'; ZoomMuteBtn = 'btnZoomMuteAll'; ZoomMicBtn = 'btnZoomMic'; ZoomCamBtn = 'btnZoomCamera'
        ZoomPollsBtn = 'btnZoomPolls'; ZoomFocusBtn = 'btnZoomFocus'; ZoomAdmitBtn = 'btnAdmit'; OnlyTBtn = 'btnOnlyT'
    }
    foreach ($row3Name in $row3Map.Keys) {
        $row3Btn = $window.FindName($row3Name)
        if (-not $row3Btn) { continue }
        $row3Btn.Tag = $row3Map[$row3Name]
        $row3Btn.Add_Click({
                param($clickSender, $clickArgs)
                try {
                    $target = Get-WpfShellMainControl ([string]$clickSender.Tag)
                    if ($target -and -not $target.IsDisposed) {
                        $script:_wpfShellMenuAtCursor = $true
                        try { $target.PerformClick() } finally { $script:_wpfShellMenuAtCursor = $false }
                    }
                }
                catch { Log "WPF shell preview: row 3 button failed: $_" }
            })
    }
    $pollsReadout = $window.FindName('PollsReadout')
    if ($pollsReadout) {
        $pollsReadout.Add_MouseLeftButtonUp({
                try { Invoke-ZoomAttendanceReadDelayed -DelayMs 500 } catch { Log "WPF shell preview: polls read failed: $_" }
            })
    }
    $updateLabel = $window.FindName('UpdateStatusLabel')
    if ($updateLabel) {
        # Same behaviour as the main app's update readout: open the download if one is available, otherwise re-check.
        $updateLabel.Add_MouseLeftButtonUp({
                try {
                    if ($script:UpdateAvailable -and -not [string]::IsNullOrWhiteSpace($script:UpdateLatestUrl)) { Start-Process $script:UpdateLatestUrl }
                    else { Test-ForAppUpdate }
                }
                catch { Log "WPF shell preview: update check failed: $_" }
            })
    }
    $musicWpfBtn = $window.FindName('MusicBtn')
    if ($musicWpfBtn) {
        # Right-click opens the mini music player, like the main Play Music button.
        $musicWpfBtn.Add_MouseRightButtonUp({
                param($clickSender, $clickArgs)
                try {
                    $mainMusicBtn = Get-WpfShellMainControl 'btnMusicToggle'
                    if ($mainMusicBtn -and $mainMusicBtn.Enabled) { Show-MusicPlayerPopup }
                }
                catch { Log "WPF shell preview: music popup failed: $_" }
                $clickArgs.Handled = $true
            })
    }
    if ($cutBtn) {
        # Drives the main app's real <Cut button (fade-to-black, snapshots, etc. all unchanged).
        $cutBtn.Add_Click({
                try { if ($script:btnCut -and -not $script:btnCut.IsDisposed) { $script:btnCut.PerformClick() } } catch { Log "WPF shell preview: cut failed: $_" }
                Update-WpfShellScenePicker
            })
    }
    $scenePickerBtn = $window.FindName('ScenePickerBtn')
    if ($scenePickerBtn) {
        # Selection only, like the main app's btnCam: left-click selects Speaker, right-click opens
        # the scene menu. The selected scene goes live when <Cut is pressed.
        $scenePickerBtn.Add_Click({
                try { Set-WpfShellSelectedScene (Get-WpfShellDefaultSpeakerScene) } catch { Log "WPF shell preview: scene select failed: $_" }
            })
        $scenePickerBtn.Add_MouseRightButtonUp({
                param($clickSender, $clickArgs)
                try { Show-WpfShellScenePickerMenu } catch { Log "WPF shell preview: scene picker menu failed: $_" }
                $clickArgs.Handled = $true
            })
    }

    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromSeconds(1)
    $timer.Add_Tick({
            Invoke-Prof 'shell clock' { Update-WpfShellClock }
            Invoke-Prof 'shell status bar' { Update-WpfShellStatusBar }
            Invoke-Prof 'shell scene picker' { Update-WpfShellScenePicker }
            Invoke-Prof 'shell auto toggle btn' { Update-WpfShellAutoToggleButton }
        }.GetNewClosure())
    $timer.Start()
    $script:_wpfShellClockTimer = $timer

    # 600ms flash timer (same cadence as the main app's VCamFlashTimer) so the V-Cam button
    # flashes red when OBS is online but the virtual camera is off.
    $flashTimer = New-Object System.Windows.Threading.DispatcherTimer
    $flashTimer.Interval = [TimeSpan]::FromMilliseconds(600)
    $flashTimer.Add_Tick({
            Step-WpfShellVCamFlash
        }.GetNewClosure())
    $flashTimer.Start()
    $script:_wpfShellVCamFlashTimer = $flashTimer

    # Fast poll so the Cut button follows the real Cut button's 500ms green/red flash smoothly.
    $cutTimer = New-Object System.Windows.Threading.DispatcherTimer
    $cutTimer.Interval = [TimeSpan]::FromMilliseconds(150)
    $cutTimer.Add_Tick({
            Invoke-Prof 'shell cut btn' { Update-WpfShellCutButton }
            Invoke-Prof 'shell row3' { Update-WpfShellRow3 }
            # The Zoom row (row 4) changes slowly: every other tick (300 ms) is plenty and halves its cost
            $script:_wpfRow4Tick = 1 - [int]$script:_wpfRow4Tick
            if ($script:_wpfRow4Tick -eq 1) { Invoke-Prof 'shell row4' { Update-WpfShellRow4 } }
            Invoke-Prof 'shell AF btn' { Update-WpfShellAfButton }
        }.GetNewClosure())
    $cutTimer.Start()
    $script:_wpfShellCutTimer = $cutTimer

    Update-WpfShellTheme
    Update-WpfShellAutoToggleButton

    # Register once (idempotent across repeated opens); the callback itself safely no-ops
    # whenever the preview window isn't currently open.
    if (-not $script:_wpfShellThemeCallbackRegistered) {
        Register-ThemeChangeCallback { Update-WpfShellTheme }
        $script:_wpfShellThemeCallbackRegistered = $true
    }

    $window.Add_Closed({
            Save-WpfShellWindowGeometry
            try { Set-OnlyTWindowVisible $true } catch {}
            Stop-WpfShellCameraPreview
            try { if ($script:_wpfShellClockTimer) { $script:_wpfShellClockTimer.Stop() } } catch {}
            $script:_wpfShellClockTimer = $null
            try { if ($script:_wpfShellVCamFlashTimer) { $script:_wpfShellVCamFlashTimer.Stop() } } catch {}
            $script:_wpfShellVCamFlashTimer = $null
            try { if ($script:_wpfShellCutTimer) { $script:_wpfShellCutTimer.Stop() } } catch {}
            $script:_wpfShellCutTimer = $null
            $script:_wpfShellOverlay = $null
            try { if ($script:_wpfShellHeaderTimer) { $script:_wpfShellHeaderTimer.Stop() } } catch {}
            $script:_wpfShellHeaderTimer = $null
            $script:_wpfShellHeader = $null
            $script:_wpfShellWindow = $null
        })

    $window.Show()
    try { Log "WPF shell position: after Show Left=$($window.Left) Top=$($window.Top) restored=$([bool]$savedGeom)" } catch {}
    try { $window.Activate() | Out-Null } catch {}
    try { $window.Topmost = $true } catch {}
    Show-WpfShellOverlay
    Show-WpfShellHeader
    Set-WpfShellTitleBarTheme
    Initialize-WpfShellScaleBase
    Set-WpfShellScale
    Log "WPF shell preview: opened"
    Show-WpfShellPreviewPlaceholder
    # There is no play button any more: the camera preview starts by itself (short delay so the window finishes opening first).
    $startTimer = New-Object System.Windows.Forms.Timer
    $startTimer.Interval = 800
    $startTimer.Add_Tick({
            param($tmr, $tmrArgs)
            $tmr.Stop(); $tmr.Dispose()
            try { if ($script:_wpfShellWindow -and -not $script:_wpfShellCamActive) { Start-WpfShellCameraPreview } } catch { Log "WPF shell preview: camera auto-start failed: $_" }
        })
    $startTimer.Start()
}

function Set-Anchor($ctrl, [string]$sides) {
    try {
        if (-not $ctrl) { return }
        if (-not ($ctrl.PSObject.Properties.Name -contains 'Anchor')) { return }
        $flags = [System.Windows.Forms.AnchorStyles]::None
        foreach ($s in $sides.Split(',')) {
            switch ($s.Trim()) {
                'Left' { $flags = $flags -bor [System.Windows.Forms.AnchorStyles]::Left }
                'Right' { $flags = $flags -bor [System.Windows.Forms.AnchorStyles]::Right }
                'Top' { $flags = $flags -bor [System.Windows.Forms.AnchorStyles]::Top }
                'Bottom' { $flags = $flags -bor [System.Windows.Forms.AnchorStyles]::Bottom }
            }
        }
        $ctrl.Anchor = $flags
    }
    catch {}
}

function Pt([int]$x, [int]$y) { New-Object System.Drawing.Point $x, $y }
function Sz([int]$w, [int]$h) { New-Object System.Drawing.Size  $w, $h }

# ===== ROUNDED CORNERS FOR MODERN UI =====
$script:RoundedButtonHelperAvailable = $false
$script:_roundedControls = New-Object System.Collections.ArrayList  # tracks (control, radius) for re-apply after scale
$roundedRefAssemblies = @("System.Windows.Forms.dll", "System.Drawing.dll")
try {
    $drawingAsm = [System.Drawing.Region].Assembly
    if ($drawingAsm -and $drawingAsm.Location) {
        $roundedRefAssemblies += $drawingAsm.Location
    }
}
catch {}

try {
    Add-Type -TypeDefinition @"
using System;
using System.Drawing;
using System.Runtime.InteropServices;
using System.Windows.Forms;

public static class RoundedButton {
    [DllImport("gdi32.dll")]
    public static extern IntPtr CreateRoundRectRgn(int nLeftRect, int nTopRect, int nRightRect, int nBottomRect, int nWidthEllipse, int nHeightEllipse);
    
    [DllImport("gdi32.dll")]
    public static extern bool DeleteObject(IntPtr hObject);
    
    public static void MakeRounded(Control control, int radius = 15) {
        try {
            IntPtr ptr = CreateRoundRectRgn(0, 0, control.Width, control.Height, radius, radius);
            if (ptr != IntPtr.Zero) {
                control.Region = Region.FromHrgn(ptr);
                DeleteObject(ptr);
            }
        }
        catch { }
    }
}
"@ -ReferencedAssemblies $roundedRefAssemblies
    $script:RoundedButtonHelperAvailable = $true
}
catch {
    try { Log ("RoundedButton helper disabled: {0}" -f $_.Exception.Message) } catch {}
    $script:RoundedButtonHelperAvailable = $false
}

# WM_SETREDRAW helper — suspends/resumes drawing on a control to batch visual updates without flicker
$script:_winMsgAvail = $false
try {
    Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class WinMsg {
    [DllImport("user32.dll")]
    private static extern bool SendMessage(IntPtr hWnd, int msg, IntPtr wParam, IntPtr lParam);
    public static void SuspendDraw(IntPtr hwnd) {
        try { SendMessage(hwnd, 11, IntPtr.Zero, IntPtr.Zero); } catch { }
    }
    public static void ResumeDraw(IntPtr hwnd) {
        try { SendMessage(hwnd, 11, new IntPtr(1), IntPtr.Zero); } catch { }
    }
}
"@ -ReferencedAssemblies "System.Runtime.InteropServices.dll"
    $script:_winMsgAvail = $true
}
catch {
    $script:_winMsgAvail = $false
}

# ── PSw34: Zoom window finder + positioning (used by Toggle Zoom button) ─────
$script:PSw34Loaded = $false
$script:PSw34Error = $null
try {
    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using System.Text;
public static class PSw34 {
    public const int SW_RESTORE  = 9;
    public const int SW_MINIMIZE = 6;
    public const int SW_SHOW     = 5;
    public const int SW_HIDE     = 0;
    public const uint SWP_NOSIZE         = 0x0001;
    public const uint SWP_NOMOVE         = 0x0002;
    public const uint SWP_NOACTIVATE     = 0x0010;
    public const uint SWP_SHOWWINDOW     = 0x0040;
    public const uint SWP_NOCOPYBITS    = 0x0100;
    public const uint SWP_NOSENDCHANGING = 0x0400;
    public const uint SWP_NOOWNERZORDER  = 0x0200;
    public static readonly IntPtr HWND_TOPMOST   = new IntPtr(-1);
    public static readonly IntPtr HWND_NOTOPMOST = new IntPtr(-2);
    public const uint LWA_ALPHA     = 0x00000002;
    public const uint LWA_COLORKEY  = 0x00000001;
    public const uint WS_EX_LAYERED = 0x00080000;
    public const int  GWL_EXSTYLE   = -20;
    public const uint DWMWA_TRANSITIONS_FORCEDISABLED = 3;
    public const uint DWMWA_CLOAK                     = 13;
    [StructLayout(LayoutKind.Sequential)]
    public struct RECT { public int Left, Top, Right, Bottom; }
    public delegate bool EnumWndProc(IntPtr hWnd, IntPtr lParam);
    [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr hWnd, IntPtr hAfter, int X, int Y, int cx, int cy, uint flags);
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT r);
    [DllImport("user32.dll")] public static extern bool GetClientRect(IntPtr hWnd, out RECT r);
    [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr hWnd);
    [DllImport("user32.dll")] public static extern bool ShowWindowAsync(IntPtr hWnd, int cmd);
    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int cmd);
    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
    [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] public static extern uint  GetWindowThreadProcessId(IntPtr hWnd, out uint pid);
    [DllImport("kernel32.dll")] public static extern uint  GetCurrentThreadId();
    [DllImport("user32.dll")] public static extern bool  AttachThreadInput(uint a, uint b, bool attach);
    [DllImport("user32.dll")] public static extern bool  BringWindowToTop(IntPtr hWnd);
    [DllImport("user32.dll")] public static extern bool  SetLayeredWindowAttributes(IntPtr hw, uint crKey, byte bAlpha, uint dwFlags);
    [DllImport("user32.dll")] public static extern IntPtr SetWindowLongPtr(IntPtr hw, int idx, IntPtr val);
    [DllImport("user32.dll")] public static extern IntPtr GetWindowLongPtr(IntPtr hw, int idx);
    [DllImport("user32.dll")] public static extern bool  RedrawWindow(IntPtr hWnd, IntPtr r, IntPtr rgn, uint flags);
    [DllImport("dwmapi.dll")]  public static extern int   DwmSetWindowAttribute(IntPtr hw, uint attr, ref int pv, int cb);
    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWndProc cb, IntPtr lParam);
    [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder sb, int n);
    [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder sb, int n);
    [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
    [DllImport("user32.dll")] public static extern bool EnumChildWindows(IntPtr hWnd, EnumWndProc cb, IntPtr lParam);
    public static bool EqualRect(RECT a, RECT b) {
        return a.Left==b.Left && a.Top==b.Top && a.Right==b.Right && a.Bottom==b.Bottom;
    }
    public static IntPtr FindZoomMediaWindow() {
        var candidates = new System.Collections.Generic.List<System.Tuple<IntPtr,int>>();
        EnumWindows(delegate(IntPtr hWnd, IntPtr lp) {
            if (!IsWindowVisible(hWnd)) return true;
            var cls = new StringBuilder(256);
            GetClassName(hWnd, cls, 256);
            if (cls.ToString() != "ConfMultiTabContentWndClass") return true;
            var title = new StringBuilder(256);
            GetWindowText(hWnd, title, 256);
            if (!title.ToString().Contains("Zoom Meeting")) return true;
            int kids = 0;
            EnumChildWindows(hWnd, delegate(IntPtr ch, IntPtr lp2) { kids++; return true; }, IntPtr.Zero);
            candidates.Add(System.Tuple.Create(hWnd, kids));
            return true;
        }, IntPtr.Zero);
        if (candidates.Count == 0) return IntPtr.Zero;
        candidates.Sort((a, b) => a.Item2.CompareTo(b.Item2));
        return candidates[0].Item1;
    }
    public static IntPtr FindZoomMainWindow() {
        var candidates = new System.Collections.Generic.List<System.Tuple<IntPtr,int>>();
        EnumWindows(delegate(IntPtr hWnd, IntPtr lp) {
            if (!IsWindowVisible(hWnd)) return true;
            var cls = new StringBuilder(256);
            GetClassName(hWnd, cls, 256);
            if (cls.ToString() != "ConfMultiTabContentWndClass") return true;
            var title = new StringBuilder(256);
            GetWindowText(hWnd, title, 256);
            if (!title.ToString().Contains("Zoom Meeting")) return true;
            int kids = 0;
            EnumChildWindows(hWnd, delegate(IntPtr ch, IntPtr lp2) { kids++; return true; }, IntPtr.Zero);
            candidates.Add(System.Tuple.Create(hWnd, kids));
            return true;
        }, IntPtr.Zero);
        if (candidates.Count == 0) return IntPtr.Zero;
        candidates.Sort((a, b) => b.Item2.CompareTo(a.Item2));
        return candidates[0].Item1;
    }
    public static void ForceSetForeground(IntPtr hwnd) {
        IntPtr fg = GetForegroundWindow();
        uint me = GetCurrentThreadId();
        uint fgT=0, tgt=0;
        if (fg != IntPtr.Zero) { uint _d; GetWindowThreadProcessId(fg, out _d); fgT = _d; }
        GetWindowThreadProcessId(hwnd, out tgt);
        if (fgT!=0 && fgT!=me) AttachThreadInput(me, fgT, true);
        if (tgt!=0 && tgt!=me) AttachThreadInput(me, tgt, true);
        BringWindowToTop(hwnd);
        SetForegroundWindow(hwnd);
        SetWindowPos(hwnd, HWND_TOPMOST, 0,0,0,0, SWP_NOMOVE|SWP_NOSIZE|SWP_NOOWNERZORDER|SWP_NOSENDCHANGING);
        if (fgT!=0 && fgT!=me) AttachThreadInput(me, fgT, false);
        if (tgt!=0 && tgt!=me) AttachThreadInput(me, tgt, false);
    }
}
'@ -ErrorAction Stop
}
catch { $script:PSw34Error = $_ }
# Always verify by actually accessing the type (works whether Add-Type just ran or type was already defined)
try { [void][PSw34]; $script:PSw34Loaded = $true } catch {}

