$script:_mixerPanelTimer = $null   # 100ms UI refresh timer
$script:_mixerReopeningForScale = $false   # True while close+reopen cycle for scale change
$script:_mixerUpdating = $false  # Anti-feedback guard for fader sync
$script:_mixerMeterPanels = @()     # Per-channel meter Panel controls (10 entries)
$script:_mixerFaderBars = @()     # Per-channel TrackBar controls (10 entries)
$script:_mixerLevelLabels = @()     # Per-channel meter dB Label controls (10 entries)
$script:_mixerFaderLabels = @()     # Per-channel fader-position dB Label controls (10 entries)

# ------- Auto Mode state -------
$script:_autoModeActive = $false         # true when Auto Mode is running
$script:_autoModeChHoldUntil = @{}       # ch# → [DateTime] hold expiry per channel
$script:_autoModeWavePhase = 0.0         # sine-wave phase for idle animation
$script:_autoModeWaveTick = 0            # counter to throttle wave writes (update every 2 timer ticks)
$script:_autoModeLastDB = @{}            # ch# → last dB sent (to skip redundant OSC writes)
$script:_autoModeTimer = $null           # System.Windows.Forms.Timer for Auto Mode logic
$script:_autoMusicWasPlaying = $false    # tracks previous music-playing state for edge detection
$script:_limiterChCoolUntil = @{}        # ch# → [DateTime] limiter cooldown expiry per channel
$script:_limiterPreValue = @{}        # ch# → linear fader value before limiter reduced it
$script:_limiterBelowSince = @{}        # ch# → [DateTime] when level first dropped below threshold

function New-ReqId { $script:_reqId++; "req$($script:_reqId)" }
function Get-RootErrorMessage($ex) { try { $e = $ex; while ($e.InnerException) { $e = $e.InnerException }; return [string]$e.Message }catch { return [string]$ex } }

function Get-ObsAuthResponse($pwdText, $saltB64, $chB64) {
    $sha = [System.Security.Cryptography.SHA256]::Create(); $hmac = New-Object System.Security.Cryptography.HMACSHA256
    $salt = [Convert]::FromBase64String($saltB64); $pw = [Text.Encoding]::UTF8.GetBytes($pwdText)
    $mix = New-Object byte[] ($pw.Length + $salt.Length); [Array]::Copy($pw, 0, $mix, 0, $pw.Length); [Array]::Copy($salt, 0, $mix, $pw.Length, $salt.Length)
    $hmac.Key = $sha.ComputeHash($mix); $auth = $hmac.ComputeHash([Convert]::FromBase64String($chB64)); [Convert]::ToBase64String($auth)
}
# --- Legacy OBS connection helpers below (superseded by New-ObsClient/Connect-Obs); kept for reference, currently unused ---
function Test-ObsOpenLegacy {
    try { return ($script:ObsWs -and $script:ObsWs.State -eq 'Open') } catch { return $false }
}
function Reset-ObsConnectionLegacy {
    try { if ($script:ObsWs) { $script:ObsWs.Dispose() } }catch {}
    $script:ObsWs = $null; $script:ObsConnected = $false
    Update-ObsButton $false
}
function Read-ObsJsonLegacy($ws, [int]$timeoutMs = 5000) {
    $ms = $null; $cts = $null
    try {
        if (-not $ws) { Log "Read-ObsJsonLegacy: no websocket"; return $null }
        $buffer = New-Object byte[] 8192
        $ms = New-Object System.IO.MemoryStream
        $cts = New-Object System.Threading.CancellationTokenSource
        $cts.CancelAfter([Math]::Max(100, [int]$timeoutMs))

        while ($true) {
            $seg = [System.ArraySegment[byte]]::new($buffer)
            $task = $ws.ReceiveAsync($seg, $cts.Token)
            $completed = $task.Wait($timeoutMs)
            if (-not $completed) {
                Log "Read-ObsJsonLegacy: receive timed out after $timeoutMs ms"
                return $null
            }
            $res = $task.Result
            if ($res.MessageType -eq [System.Net.WebSockets.WebSocketMessageType]::Close) {
                Log "OBS closed socket: $($ws.CloseStatus) $($ws.CloseStatusDescription)"
                return $null
            }
            if ($res.Count -gt 0) { $ms.Write($buffer, 0, $res.Count) }
            if ($res.EndOfMessage) { break }
        }

        return [Text.Encoding]::UTF8.GetString($ms.ToArray())
    }
    catch {
        Log "OBS read error: $(Get-RootErrorMessage $_.Exception)"
        return $null
    }
    finally {
        try { if ($ms) { $ms.Dispose() } } catch {}
        try { if ($cts) { $cts.Dispose() } } catch {}
    }
}
function Send-ObsJsonLegacy($ws, $obj, [int]$timeoutMs = 3000) {
    try {
        if (-not $ws) { Log "Send-ObsJsonLegacy: no websocket instance"; return $false }
        $json = if ($obj -is [string]) { $obj } else { $obj | ConvertTo-Json -Depth 10 -Compress }
        $bytes = [Text.Encoding]::UTF8.GetBytes($json)
        $seg = [System.ArraySegment[byte]]::new($bytes)

        $cts = New-Object System.Threading.CancellationTokenSource
        $cts.CancelAfter([Math]::Max(100, [int]$timeoutMs))

        $task = $ws.SendAsync($seg, [System.Net.WebSockets.WebSocketMessageType]::Text, $true, $cts.Token)
        $ok = $task.Wait($timeoutMs)
        if (-not $ok -or $task.IsFaulted) {
            Log "Send-ObsJsonLegacy: send failed or timed out after $timeoutMs ms"
            return $false
        }
        return $true
    }
    catch {
        Log "OBS send error: $(Get-RootErrorMessage $_.Exception)"
        return $false
    }
    finally {
        try { if ($cts) { $cts.Dispose() } } catch {}
    }
}
  


function Connect-ObsLegacy {
    try {
        if (Test-ObsOpenLegacy) { $script:ObsConnected = $true; Update-ObsButton $true; return $true }
        if ($script:ObsWs) { try { $script:ObsWs.Dispose() }catch {} }
        $script:ObsWs = New-Object System.Net.WebSockets.ClientWebSocket
        $scheme = $(if ($script:Cfg.OBS.UseTLS) { "wss" }else { "ws" })
        $uri = "{0}://{1}:{2}" -f $scheme, $script:Cfg.OBS.Host, $script:Cfg.OBS.Port
        $prev = [System.Net.ServicePointManager]::ServerCertificateValidationCallback
        if ($script:Cfg.OBS.UseTLS -and $script:Cfg.OBS.AllowInsecure) { [System.Net.ServicePointManager]::ServerCertificateValidationCallback = { $true } }
        try {
            Log "OBS: Connecting $uri …"
            $cts = New-Object System.Threading.CancellationTokenSource; $cts.CancelAfter(4000)
            $script:ObsWs.ConnectAsync([Uri]$uri, $cts.Token).Wait(); $cts.Dispose()
        }
        catch { Log "OBS connect error: $(Get-RootErrorMessage $_.Exception)"; $script:ObsConnected = $false; Update-ObsButton $false; return $false }
        finally { [System.Net.ServicePointManager]::ServerCertificateValidationCallback = $prev }

        $helloJson = Read-ObsJsonLegacy $script:ObsWs 5000; if (-not $helloJson) { throw "No hello from OBS." }
        $hello = $helloJson | ConvertFrom-Json; if ($hello.op -ne 0) { throw "Unexpected hello opcode." }
        # Subscribe to Inputs (8) + Scenes (4) = 12 (no OBS audio-meter events: levels come from the XR mixer)
        $identify = @{op = 1; d = @{rpcVersion = 1; eventSubscriptions = 12 } }
        if ($hello.d.authentication) { $identify.d.authentication = Get-ObsAuthResponse $script:Cfg.OBS.Password $hello.d.authentication.salt $hello.d.authentication.challenge }
        Send-ObsJsonLegacy $script:ObsWs $identify
        $identifiedJson = Read-ObsJsonLegacy $script:ObsWs 5000; if (-not $identifiedJson) { throw "No identified from OBS." }
        $identified = $identifiedJson | ConvertFrom-Json; if ($identified.op -ne 2) { throw "Identification failed." }
        Log "OBS: Connected with event subscriptions: 12 (Inputs + Scenes)"
        $script:ObsConnected = $true; Update-ObsButton $true

        # Check for Auto Start scenes after successful connection
        Invoke-AutoStartScenes

        return $true
    }
    catch { Log "OBS connect error: $(Get-RootErrorMessage $_.Exception)"; Reset-ObsConnectionLegacy; return $false }
}

function Invoke-ObsRequestLegacy([string]$type, [hashtable]$data = @{}) {
    if (-not (Test-ObsOpenLegacy)) { Log "OBS: not connected. Click 'Start OBS WS'."; return $false }
    $rid = New-ReqId; $payload = @{op = 6; d = @{requestType = $type; requestId = $rid; requestData = $data } }
    try {
        Send-ObsJsonLegacy $script:ObsWs $payload
        $resp = Read-ObsJsonLegacy $script:ObsWs 5000
        if (-not $resp) { Log "OBS: request timeout ($type)"; return $false }
        $obj = $resp | ConvertFrom-Json
        if ($obj.op -ne 7 -or $obj.d.requestId -ne $rid) { Log "OBS: bad response ($type)"; return $false }
        $ok = [bool]$obj.d.requestStatus.result
        if (-not $ok -and $obj.d.requestStatus.comment) { Log ("OBS: " + $obj.d.requestStatus.comment) }
        return $obj
    }
    catch { Log "OBS request error ($type): $(Get-RootErrorMessage $_.Exception)"; return $false }
}

function Set-ObsScene([string]$scene) {
    if ([string]::IsNullOrWhiteSpace($scene)) { return $false }
    
    # Get actual current scene from OBS to prevent redundant switches
    $currentScene = Get-CurrentProgramSceneName
    if ([string]::Equals($currentScene, $scene, [StringComparison]::InvariantCultureIgnoreCase)) {
        # Already on target scene - no need to switch or log
        return $true
    }
    
    try {
        [void](Invoke-ObsRequest "SetCurrentProgramScene" @{ sceneName = $scene })
        Log "OBS: Scene -> '$scene' (was: '$currentScene')"
        return $true
    }
    catch {
        Log "OBS: Scene change FAILED '$scene' : $($_.Exception.Message)"
        return $false
    }
}

function Get-ObsSceneNames {
    try {
        $r = Invoke-ObsRequest "GetSceneList" @{}
        if (-not $r -or -not $r.scenes) { return @() }
        return @($r.scenes | ForEach-Object { $_.sceneName })
    }
    catch { return @() }
}

# ---- Live Camera Preview (LibVLC dshow capture, replaces screenshot polling) ----
$script:_camLibVLC = $null
$script:_camMediaPlayer = $null
$script:_camPreviewActive = $false

# The portable LibVLC redistribution bundled via NuGet (VideoLAN.LibVLC.Windows) does NOT
# include the DirectShow capture plugin (libdshow_plugin.dll) - it's built for media
# playback, not device capture. If a full desktop VLC install is present on this machine,
# copy its dshow plugin into our bundled plugins folder once. If not, camera preview simply
# isn't available on this machine and callers should fall back to screenshot mode.
function Test-DShowPluginAvailable {
    $natDir = Join-Path ([Environment]::GetFolderPath('ApplicationData')) 'JWL-OBS-Assistant\vlc\native'
    $target = Join-Path $natDir 'plugins\access\libdshow_plugin.dll'
    if (Test-Path $target) { return $true }

    # Prefer the copy shipped alongside this script/exe (VlcExtraPlugins\) - works on any
    # machine without needing a full VLC install. Fall back to a system VLC install if present.
    $bundled = Join-Path (Split-Path -Path $scriptPath) 'VlcExtraPlugins\libdshow_plugin.dll'
    $candidates = @(
        $bundled,
        "$env:ProgramFiles\VideoLAN\VLC\plugins\access\libdshow_plugin.dll",
        "${env:ProgramFiles(x86)}\VideoLAN\VLC\plugins\access\libdshow_plugin.dll"
    )
    $source = $candidates | Where-Object { $_ -and (Test-Path $_) } | Select-Object -First 1
    if (-not $source) {
        Log "Camera preview: DirectShow plugin not found - install VLC media player to enable this feature"
        return $false
    }
    try {
        $destDir = Join-Path $natDir 'plugins\access'
        if (-not (Test-Path $destDir)) { New-Item -ItemType Directory -Force -Path $destDir | Out-Null }
        Copy-Item -Path $source -Destination $target -Force
        Log "Camera preview: copied DirectShow plugin from $source"
        return $true
    }
    catch {
        Log "Camera preview: failed to copy DirectShow plugin - $_"
        return $false
    }
}

function Get-CameraPreviewHostHandle {
    # WPF-migration Phase 1 step: isolates which native HWND LibVLC renders camera-preview video
    # into. LibVLCSharp's Hwnd-based video output needs a real Win32 window handle - even a future
    # WPF shell will need a small interop host (e.g. a WindowsFormsHost wrapping a Panel, or a raw
    # HwndHost) for this, since LibVLC cannot render directly into a WPF visual tree. Centralizing
    # the lookup here means Start-ObsCameraPreview never needs to change once that host exists;
    # only this function does.
    if ($script:pLivePreview -and -not $script:pLivePreview.IsDisposed) { return $script:pLivePreview.Handle }
    return [IntPtr]::Zero
}

function Start-ObsCameraPreview {
    if ($script:_camPreviewActive) { return $true }
    if ([string]::IsNullOrWhiteSpace($script:Cfg.OBS.PreviewCameraName)) {
        Log "Camera preview: no camera selected in Settings"
        return $false
    }
    if (-not (Initialize-LibVLC)) {
        Log "Camera preview: LibVLC not available"
        return $false
    }
    if (-not (Test-DShowPluginAvailable)) { return $false }
    $mp = $null
    try {
        if (-not $script:_camLibVLC) { $script:_camLibVLC = [LibVLCSharp.Shared.LibVLC]::new($false) }
        $mp = [LibVLCSharp.Shared.MediaPlayer]::new($script:_camLibVLC)
        $mp.AspectRatio = '16:9'   # OBS's virtual cam output is 16:9 - force it so LibVLC letterboxes instead of stretching to fill the panel
        $devName = [string]$script:Cfg.OBS.PreviewCameraName
        # :dshow-adev=none skips capturing the camera's own microphone (we don't want that audio)
        $media = [LibVLCSharp.Shared.Media]::new(
            $script:_camLibVLC, 'dshow://', [LibVLCSharp.Shared.FromType]::FromLocation,
            [string[]]@(":dshow-vdev=$devName", ":dshow-adev=none", ":live-caching=100")
        )
        $mp.Media = $media
        $media.Dispose()

        $hostHandle = Get-CameraPreviewHostHandle
        if ($hostHandle -eq [IntPtr]::Zero) { throw "Live preview panel not available" }
        $mp.Hwnd = $hostHandle

        try { if ($script:pbObs) { $script:pbObs.Visible = $false } } catch {}
        $script:pLivePreview.Visible = $true
        # SendToBack (not BringToFront) - the AF/PTZ overlay buttons on $script:pPreview were
        # already brought to front during UI setup; bringing the video panel forward here would
        # cover them since this runs much later, at runtime when camera mode is toggled on.
        $script:pLivePreview.SendToBack()
        try { if ($script:lblHint) { $script:lblHint.Visible = $false } } catch {}

        [void]$mp.Play()
        $script:_camMediaPlayer = $mp
        $script:_camPreviewActive = $true
        Log "Camera preview: started using '$devName'"
        return $true
    }
    catch {
        Log "Camera preview: failed to start - $_"
        try { if ($mp) { $mp.Dispose() } } catch {}
        $script:_camMediaPlayer = $null
        $script:_camPreviewActive = $false
        return $false
    }
}

function Stop-ObsCameraPreview {
    if (-not $script:_camPreviewActive -and -not $script:_camMediaPlayer) { return }
    try { if ($script:_camMediaPlayer) { $script:_camMediaPlayer.Stop() } } catch {}
    try { if ($script:_camMediaPlayer) { $script:_camMediaPlayer.Dispose() } } catch {}
    $script:_camMediaPlayer = $null
    $script:_camPreviewActive = $false
    try {
        if ($script:pLivePreview -and -not $script:pLivePreview.IsDisposed) { $script:pLivePreview.Visible = $false }
        if ($script:pbObs -and -not $script:pbObs.IsDisposed) { $script:pbObs.Visible = $true }
    }
    catch {}
    Log "Camera preview: stopped"
}

# Decides which preview mode should be active and switches to it. Call after Settings save
# and after OBS connects, so the choice takes effect immediately without needing a restart.
# Returns '' when live camera preview can run, otherwise 'engine' (LibVLC missing) or 'plugin'
# (DirectShow capture plugin missing). Nothing is stopped or changed here.
function Test-CameraPreviewReady {
    if (-not (Initialize-LibVLC)) { return 'engine' }
    if (-not (Test-DShowPluginAvailable)) { return 'plugin' }
    return ''
}

# Tells the user why live camera preview is unavailable and offers the VLC download page.
# Shown once per session; the app keeps using the OBS screenshot preview meanwhile.
function Show-CameraEngineMissingPrompt([string]$Reason) {
    if ($script:_camMissingPromptShown) { return }
    $script:_camMissingPromptShown = $true
    $msg = if ($Reason -eq 'plugin') {
        "Live camera preview needs the VLC DirectShow plugin, which was not found on this PC.`n`nInstall VLC media player (free) and restart this app - the plugin is picked up automatically.`n`nUntil then the OBS screenshot preview stays active.`n`nOpen the VLC download page now?"
    }
    else {
        "Live camera preview needs the VLC engine, which could not be loaded (it is downloaded on first use - check the internet connection).`n`nUntil then the OBS screenshot preview stays active.`n`nOpen the VLC download page now?"
    }
    try {
        [void]$script:form.BeginInvoke([System.Action] {
                try {
                    $r = [System.Windows.Forms.MessageBox]::Show($msg, 'Live camera preview unavailable', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Information)
                    if ($r -eq [System.Windows.Forms.DialogResult]::Yes) { Start-Process 'https://www.videolan.org/vlc/' }
                }
                catch {}
            })
    }
    catch {}
}

function Set-ObsPreviewMode {
    $wantCamera = [bool]$script:Cfg.OBS.PreviewUseCamera -and -not [string]::IsNullOrWhiteSpace($script:Cfg.OBS.PreviewCameraName)

    if ($wantCamera) {
        # If the preload runspace is still running, defer camera start - it will
        # call Set-ObsPreviewMode again when it finishes (see preload poll timer tick).
        # The screenshot preview keeps running meanwhile so the picture never freezes.
        if ($script:_vlcPreloadAsyncResult -and -not $script:_vlcPreloadAsyncResult.IsCompleted) {
            $script:_vlcPreloadCameraDeferred = $true
            try { $script:sbLeft.Text = 'Loading camera engine, please wait...' } catch {}
            Log 'Camera preview: waiting for background engine load to finish...'
            # New UI: show the preview frame with its PTZ / AF controls while the engine loads
            try { if ($script:NewUiPrimary -and $script:_wpfShellWindow -and -not $script:_wpfShellCamActive) { $script:_wpfShellObsLoading = $true; Ensure-WpfShellObsPreviewHost } } catch {}
            return
        }

        # Check the engine and plugin BEFORE touching the running preview; if either is missing,
        # stay on the OBS screenshot preview and offer the download instead of freezing it.
        $notReady = Test-CameraPreviewReady
        if ($notReady) {
            Log "Camera preview: not available ($notReady) - staying on the OBS screenshot preview"
            Show-CameraEngineMissingPrompt $notReady
            $wantCamera = $false
        }
    }

    if ($wantCamera) {
        # Screenshot polling is pure overhead once a live feed is rendering - stop it.
        try { if ($script:obsTimer) { $script:obsTimer.Stop() } } catch {}
        try { Stop-ObsPreviewWorker } catch {}

        $ok = $false
        if ($script:NewUiPrimary -and $script:_wpfShellWindow) {
            # The new UI is what the user sees: render the camera there (the classic form is hidden).
            if (-not $script:_wpfShellCamActive -or $script:_wpfShellCamName -ne [string]$script:Cfg.OBS.PreviewCameraName) {
                try { Stop-WpfShellCameraPreview } catch {}
                try { Start-WpfShellCameraPreview } catch { Log "Camera preview: new UI start failed - $_" }
            }
            $ok = [bool]$script:_wpfShellCamActive
        }
        else {
            $r = @(Start-ObsCameraPreview)
            $ok = ($r.Count -gt 0 -and [bool]$r[-1])
        }
        if ($ok) { return }
        Log 'Camera preview: could not start - falling back to the OBS screenshot preview'
    }

    # Screenshot mode (camera off, or camera unavailable)
    try { if ($script:_wpfShellCamActive) { Stop-WpfShellCameraPreview } } catch {}
    Stop-ObsCameraPreview
    if ($script:ObsConnected) {
        try { Initialize-ObsTimer } catch {}
        try { if ($script:obsTimer -and -not $script:obsTimer.Enabled) { $script:obsTimer.Start() } } catch {}
        try { Start-ObsPreviewWorker } catch {}
    }
    try { if ($script:NewUiPrimary -and $script:_wpfShellWindow) { Ensure-WpfShellObsPreviewHost } } catch {}
}

# Enumerates DirectShow video capture devices (webcams, OBS Virtual Camera, etc.) via the
# registry - the same CLSID category (VideoInputDevice) that DirectShow/VLC's dshow module
# uses internally, so the "FriendlyName" returned here matches what LibVLC's dshow:// source
# expects for its :dshow-vdev= option.
function Get-DirectShowVideoDevices {
    $devices = @()
    # Real enumeration through the DirectShow system device enumerator (finds USB webcams,
    # phone cameras, capture cards - these are NOT in the registry list below).
    try {
        if (-not ('JwlDShowEnum' -as [type])) {
            Add-Type -TypeDefinition @'
using System; using System.Collections.Generic; using System.Runtime.InteropServices; using System.Runtime.InteropServices.ComTypes;
public static class JwlDShowEnum {
  [ComImport, Guid("29840822-5B84-11D0-BD3B-00A0C911CE86"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface ICreateDevEnum { [PreserveSig] int CreateClassEnumerator([In] ref Guid pType, out IEnumMoniker ppEnumMoniker, int dwFlags); }
  [ComImport, Guid("55272A00-42CB-11CE-8135-00AA004BB851"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IPropertyBag { [PreserveSig] int Read([MarshalAs(UnmanagedType.LPWStr)] string pszPropName, out object pVar, IntPtr pErrorLog); [PreserveSig] int Write([MarshalAs(UnmanagedType.LPWStr)] string pszPropName, ref object pVar); }
  public static string[] VideoDevices() {
    var list = new List<string>();
    Type t = Type.GetTypeFromCLSID(new Guid("62BE5D10-60EB-11D0-BD3B-00A0C911CE86"));
    object o = Activator.CreateInstance(t);
    var dev = (ICreateDevEnum)o;
    Guid cat = new Guid("860BB310-5D01-11D0-BD3B-00A0C911CE86");
    IEnumMoniker em;
    if (dev.CreateClassEnumerator(ref cat, out em, 0) != 0 || em == null) return list.ToArray();
    IMoniker[] m = new IMoniker[1];
    while (em.Next(1, m, IntPtr.Zero) == 0) {
      object bagObj; Guid bagId = typeof(IPropertyBag).GUID;
      m[0].BindToStorage(null, null, ref bagId, out bagObj);
      var bag = (IPropertyBag)bagObj; object v;
      if (bag.Read("FriendlyName", out v, IntPtr.Zero) == 0 && v != null) list.Add(v.ToString());
      Marshal.ReleaseComObject(bagObj); Marshal.ReleaseComObject(m[0]);
    }
    return list.ToArray();
  }
}
'@
        }
        foreach ($n in [JwlDShowEnum]::VideoDevices()) {
            if (-not [string]::IsNullOrWhiteSpace($n)) { $devices += [string]$n }
        }
    }
    catch { Log "Get-DirectShowVideoDevices COM enumeration error: $_" }
    try {
        $catPath = 'Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Classes\CLSID\{860BB310-5D01-11d0-BD3B-00A0C911CE86}\Instance'
        if (Test-Path $catPath) {
            Get-ChildItem $catPath -ErrorAction SilentlyContinue | ForEach-Object {
                try {
                    $name = (Get-ItemProperty -Path $_.PSPath -Name 'FriendlyName' -ErrorAction Stop).FriendlyName
                    if (-not [string]::IsNullOrWhiteSpace($name)) { $devices += [string]$name }
                }
                catch {}
            }
        }
    }
    catch { Log "Get-DirectShowVideoDevices error: $_" }
    return @($devices | Select-Object -Unique)
}

# Simple picker listing available capture devices (webcams, OBS Virtual Camera, etc.).
# Returns the selected device name, or $null if cancelled/none available.
function Show-CameraPickerDialog([string]$CurrentName, [System.Windows.Forms.Form]$Owner) {
    $devices = Get-DirectShowVideoDevices
    if ($devices.Count -eq 0) {
        [System.Windows.Forms.MessageBox]::Show(
            "No camera/capture devices were found.`n`nIf you want to use OBS's output as a source, enable OBS's Virtual Camera first (Controls panel -> Start Virtual Camera), then reopen this picker.",
            "No Devices Found",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        ) | Out-Null
        return $null
    }

    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = "Select Camera / Capture Device"
    $dlg.Size = [System.Drawing.Size]::new(420, 320)
    $dlg.StartPosition = "Manual"
    $dlg.FormBorderStyle = "FixedDialog"
    $dlg.MaximizeBox = $false
    $dlg.MinimizeBox = $false
    $dlg.TopMost = $true
    # Compute position manually - CenterParent can land off-screen on multi-monitor setups
    # with negative-coordinate monitors, leaving the modal dialog invisible but still blocking.
    try {
        $ownerBounds = if ($Owner) { $Owner.Bounds } else { [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea }
        $cx = [int]($ownerBounds.X + ($ownerBounds.Width - $dlg.Width) / 2)
        $cy = [int]($ownerBounds.Y + ($ownerBounds.Height - $dlg.Height) / 2)
        $dlg.Location = [System.Drawing.Point]::new($cx, $cy)
    }
    catch { $dlg.StartPosition = "CenterScreen" }

    $lbl = New-Object System.Windows.Forms.Label
    $lbl.Text = "Choose the device to use for the live preview feed:"
    $lbl.AutoSize = $true
    $lbl.Location = [System.Drawing.Point]::new(10, 10)
    $dlg.Controls.Add($lbl)

    $listBox = New-Object System.Windows.Forms.ListBox
    $listBox.Location = [System.Drawing.Point]::new(10, 35)
    $listBox.Size = [System.Drawing.Size]::new(384, 200)
    foreach ($d in $devices) { [void]$listBox.Items.Add($d) }
    $sel = $devices.IndexOf($CurrentName)
    $listBox.SelectedIndex = if ($sel -ge 0) { $sel } else { 0 }
    $dlg.Controls.Add($listBox)

    $btnOK = New-Object System.Windows.Forms.Button
    $btnOK.Text = "OK"
    $btnOK.Location = [System.Drawing.Point]::new(228, 245)
    $btnOK.Size = [System.Drawing.Size]::new(80, 28)
    $btnOK.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $dlg.Controls.Add($btnOK)

    $btnCancel = New-Object System.Windows.Forms.Button
    $btnCancel.Text = "Cancel"
    $btnCancel.Location = [System.Drawing.Point]::new(314, 245)
    $btnCancel.Size = [System.Drawing.Size]::new(80, 28)
    $btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $dlg.Controls.Add($btnCancel)

    $dlg.AcceptButton = $btnOK
    $dlg.CancelButton = $btnCancel
    if ($Owner) { $dlg.Owner = $Owner }

    $result = $dlg.ShowDialog()
    $dlg.Dispose()
    if ($result -eq [System.Windows.Forms.DialogResult]::OK -and $listBox.SelectedItem) {
        return [string]$listBox.SelectedItem
    }
    return $null
}

# =========================
# === BACKGROUND MUSIC  ===
# =========================
$script:VlcAvailable = $false   # set $true once LibVLC dlls are successfully loaded

# Supply-chain hardening: the first-run download is pinned to exact package versions and the
# SHA-256 of each .nupkg. A package whose hash does not match is deleted and never extracted.
# To update the engine: change the versions, download the new .nupkg files, and replace the hashes
# (Get-FileHash <file> -Algorithm SHA256).
$script:VlcPin = @{
    LibVLCSharpVer    = '3.10.0'
    LibVLCSharpSha256 = 'B1ED0CDFFAC10C1999A2CF95AF44324341AFC2DA635DDDB50397B9F4D0E95065'
    NativeVer         = '3.0.23'
    NativeSha256      = '39D3035CCC9DCF58206F9888959B78F47F52EB2EE79AF7F50B01C3342C279E7F'
}

# ---- LibVLC bootstrap: download & load engine on first music play ----
function Initialize-LibVLC {
    if ($script:VlcAvailable) { return $true }
    # This can run on the UI thread: never let a stalled download hang the app (function-local setting).
    $PSDefaultParameterValues = @{ 'Invoke-WebRequest:TimeoutSec' = 25; 'Invoke-RestMethod:TimeoutSec' = 25 }
    try {
        # Store VLC files in AppData — avoids OneDrive/network locking issues
        $vlcDir = Join-Path ([Environment]::GetFolderPath('ApplicationData')) 'JWL-OBS-Assistant\vlc'
        $natDir = Join-Path $vlcDir 'native'
        $dllPath = Join-Path $vlcDir 'LibVLCSharp.dll'
        $libvlc = Join-Path $natDir 'libvlc.dll'

        # Already extracted on a previous run — just load
        if ((Test-Path $dllPath) -and (Test-Path $libvlc)) {
            [Reflection.Assembly]::LoadFrom($dllPath) | Out-Null
            [LibVLCSharp.Shared.Core]::Initialize($natDir)
            Log 'LibVLC: loaded from cache'
            $script:VlcAvailable = $true
            return $true
        }

        # Check for bundled VLC files shipped alongside this script/exe (vlc\ folder).
        # This avoids any internet download on machines without a full VLC install.
        $bundledVlcDir = Join-Path (Split-Path -Path $scriptPath) 'vlc'
        $bundledNat = Join-Path $bundledVlcDir 'native'
        $bundledDll = Join-Path $bundledVlcDir 'LibVLCSharp.dll'
        $bundledLibVlc = Join-Path $bundledNat 'libvlc.dll'
        if ((Test-Path $bundledDll) -and (Test-Path $bundledLibVlc)) {
            try {
                if (-not (Test-Path $natDir)) { New-Item -ItemType Directory -Force -Path $natDir | Out-Null }
                # Copy all native files to AppData so Core.Initialize path is stable
                Copy-Item -Path "$bundledNat\*" -Destination $natDir -Recurse -Force
                Copy-Item -Path $bundledDll -Destination $dllPath -Force
                [Reflection.Assembly]::LoadFrom($dllPath) | Out-Null
                [LibVLCSharp.Shared.Core]::Initialize($natDir)
                Log 'LibVLC: loaded from bundled vlc\ folder'
                $script:VlcAvailable = $true
                return $true
            }
            catch { Log "LibVLC: bundled copy failed - $_" }
        }

        Log 'LibVLC: first-run download starting...'
        try { $script:sbLeft.Text = 'Downloading VLC engine (first run only)...' } catch {}
        try { if ($script:form -and -not $script:form.IsDisposed) { $script:form.Refresh() } } catch {}

        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

        $tmp = Join-Path $env:TEMP 'jwl_vlc_bootstrap'
        New-Item -ItemType Directory -Force -Path $tmp    | Out-Null
        New-Item -ItemType Directory -Force -Path $vlcDir | Out-Null
        New-Item -ItemType Directory -Force -Path $natDir | Out-Null

        # --- pinned package versions (see $script:VlcPin) ---
        $lvcsVer = $script:VlcPin.LibVLCSharpVer
        $winVer = $script:VlcPin.NativeVer

        # --- download LibVLCSharp ---
        $nupkg1 = Join-Path $tmp 'LibVLCSharp.nupkg'
        Invoke-WebRequest "https://www.nuget.org/api/v2/package/LibVLCSharp/$lvcsVer" `
            -OutFile $nupkg1 -UseBasicParsing -ErrorAction Stop
        if ((Get-FileHash -Path $nupkg1 -Algorithm SHA256).Hash -ne $script:VlcPin.LibVLCSharpSha256) {
            Remove-Item $nupkg1 -Force -ErrorAction SilentlyContinue
            throw "LibVLCSharp $lvcsVer package failed SHA-256 verification - not installed"
        }
        $z1 = [IO.Compression.ZipFile]::OpenRead($nupkg1)
        $e = $z1.Entries | Where-Object { $_.FullName -match 'netstandard2\.0/LibVLCSharp\.dll$' } | Select-Object -First 1
        if (-not $e) { $e = $z1.Entries | Where-Object { $_.FullName -match 'LibVLCSharp\.dll$' } | Select-Object -First 1 }
        [IO.Compression.ZipFileExtensions]::ExtractToFile($e, $dllPath, $true)
        $z1.Dispose()

        # --- download VideoLAN.LibVLC.Windows (native x64 dlls) ---
        $nupkg2 = Join-Path $tmp 'VLCWin.nupkg'
        Invoke-WebRequest "https://www.nuget.org/api/v2/package/VideoLAN.LibVLC.Windows/$winVer" `
            -OutFile $nupkg2 -UseBasicParsing -ErrorAction Stop
        if ((Get-FileHash -Path $nupkg2 -Algorithm SHA256).Hash -ne $script:VlcPin.NativeSha256) {
            Remove-Item $nupkg2 -Force -ErrorAction SilentlyContinue
            throw "VideoLAN.LibVLC.Windows $winVer package failed SHA-256 verification - not installed"
        }
        $z2 = [IO.Compression.ZipFile]::OpenRead($nupkg2)
        # Current packages keep the x64 engine under build/x64/ (older ones used runtimes/win-x64/native/).
        foreach ($entry in ($z2.Entries | Where-Object { $_.FullName -match '^(runtimes/win-x64/native|build/x64)/' -and $_.Length -gt 0 })) {
            $rel = ($entry.FullName -replace '^(runtimes/win-x64/native|build/x64)/', '')
            $dest = Join-Path $natDir $rel
            $dir = Split-Path $dest
            if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
            [IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $dest, $true)
        }
        $z2.Dispose()
        try { Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue } catch {}

        # --- load ---
        [Reflection.Assembly]::LoadFrom($dllPath) | Out-Null
        [LibVLCSharp.Shared.Core]::Initialize($natDir)
        Log 'LibVLC: bootstrap complete'
        $script:VlcAvailable = $true
        return $true
    }
    catch {
        Log "LibVLC: bootstrap failed (will use WPF fallback): $_"
        return $false
    }
}

# ---- Background LibVLC preload state ----
# The slow part isn't Assembly.LoadFrom/Core.Initialize above (fast) — it's
# [LibVLCSharp.Shared.LibVLC]::new(), which triggers native libvlc.dll load +
# its plugin-cache scan (~180 plugin DLLs). That used to happen synchronously
# on the UI thread the first time the user clicked Play. We now do it once on
# a background runspace right after app startup so Play is instant afterward.
$script:_vlcPreloadRS = $null
$script:_vlcPreloadPS = $null
$script:_vlcPreloadAsyncResult = $null
$script:_vlcPreloadPollTimer = $null
$script:_vlcPreloadedLib = $null
$script:_vlcPreloadCameraDeferred = $false   # set true when camera start was deferred waiting for preload
$script:_vlcPreloadMusicDeferred = $false    # set true when auto-start music began on WPF while LibVLC was still loading
$script:_vlcPreloadStatus = [hashtable]::Synchronized(@{ Text = '' })  # written by the runspace, read by the poll timer

function Test-LibVlcPreloadBusy {
    return [bool]($script:_vlcPreloadAsyncResult -and -not $script:_vlcPreloadAsyncResult.IsCompleted)
}

function Start-LibVlcPreload {
    if ($script:VlcAvailable -or $script:_vlcPreloadAsyncResult) { return }

    $vlcDir = Join-Path ([Environment]::GetFolderPath('ApplicationData')) 'JWL-OBS-Assistant\vlc'
    $natDir = Join-Path $vlcDir 'native'
    $dllPath = Join-Path $vlcDir 'LibVLCSharp.dll'
    $libvlc = Join-Path $natDir 'libvlc.dll'

    # Resolve bundled folder path now (on UI thread) so the runspace script can use it
    $bundledVlcDir = Join-Path (Split-Path -Path $scriptPath) 'vlc'
    $bundledNat = Join-Path $bundledVlcDir 'native'
    $bundledDll = Join-Path $bundledVlcDir 'LibVLCSharp.dll'

    $cacheReady = (Test-Path $dllPath) -and (Test-Path $libvlc)
    $bundledReady = (Test-Path $bundledDll) -and (Test-Path (Join-Path $bundledNat 'libvlc.dll'))
    # NOTE: even when neither cache nor bundled files exist, we still start the background
    # runspace below - its script now downloads from NuGet itself when needed, so this never
    # falls through to Initialize-LibVLC's synchronous download on the UI thread (which used to
    # freeze the whole app for the duration of the download on fresh systems with no bundled vlc\
    # folder).
    $script:_vlcPreloadStatus.Text = 'Checking for VLC engine...'

    $preloadScript = {
        param([string]$DllPath, [string]$NatDir, [string]$BundledDll, [string]$BundledNat, [System.Collections.Hashtable]$Status, [hashtable]$Pin)
        try {
            $cacheReady = (Test-Path $DllPath) -and (Test-Path (Join-Path $NatDir 'libvlc.dll'))
            if (-not $cacheReady) {
                $bundledReady = (Test-Path $BundledDll) -and (Test-Path (Join-Path $BundledNat 'libvlc.dll'))
                if ($bundledReady) {
                    $Status.Text = 'Loading camera/music engine (first run)...'
                    if (-not (Test-Path $NatDir)) { New-Item -ItemType Directory -Force -Path $NatDir | Out-Null }
                    Copy-Item -Path "$BundledNat\*" -Destination $NatDir -Recurse -Force
                    Copy-Item -Path $BundledDll -Destination $DllPath -Force
                }
                else {
                    # Neither cache nor bundled files - download from NuGet (first run only).
                    # Runs here in the background runspace so it can never block the UI thread.
                    $Status.Text = 'Downloading VLC engine (first run only)...'
                    Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
                    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
                    $vlcDir2 = Split-Path $DllPath
                    $tmp = Join-Path $env:TEMP 'jwl_vlc_bootstrap'
                    New-Item -ItemType Directory -Force -Path $tmp    | Out-Null
                    New-Item -ItemType Directory -Force -Path $vlcDir2 | Out-Null
                    New-Item -ItemType Directory -Force -Path $NatDir | Out-Null

                    # Pinned versions + SHA-256 (see $script:VlcPin in the main script).
                    $lvcsVer = $Pin.LibVLCSharpVer
                    $winVer = $Pin.NativeVer

                    $Status.Text = 'Downloading VLC engine (first run only) - LibVLCSharp...'
                    $nupkg1 = Join-Path $tmp 'LibVLCSharp.nupkg'
                    Invoke-WebRequest "https://www.nuget.org/api/v2/package/LibVLCSharp/$lvcsVer" `
                        -OutFile $nupkg1 -UseBasicParsing -ErrorAction Stop
                    if ((Get-FileHash -Path $nupkg1 -Algorithm SHA256).Hash -ne $Pin.LibVLCSharpSha256) {
                        Remove-Item $nupkg1 -Force -ErrorAction SilentlyContinue
                        throw "LibVLCSharp $lvcsVer package failed SHA-256 verification - not installed"
                    }
                    $z1 = [IO.Compression.ZipFile]::OpenRead($nupkg1)
                    $e = $z1.Entries | Where-Object { $_.FullName -match 'netstandard2\.0/LibVLCSharp\.dll$' } | Select-Object -First 1
                    if (-not $e) { $e = $z1.Entries | Where-Object { $_.FullName -match 'LibVLCSharp\.dll$' } | Select-Object -First 1 }
                    [IO.Compression.ZipFileExtensions]::ExtractToFile($e, $DllPath, $true)
                    $z1.Dispose()

                    $Status.Text = 'Downloading VLC engine (first run only) - native engine (larger file)...'
                    $nupkg2 = Join-Path $tmp 'VLCWin.nupkg'
                    Invoke-WebRequest "https://www.nuget.org/api/v2/package/VideoLAN.LibVLC.Windows/$winVer" `
                        -OutFile $nupkg2 -UseBasicParsing -ErrorAction Stop
                    if ((Get-FileHash -Path $nupkg2 -Algorithm SHA256).Hash -ne $Pin.NativeSha256) {
                        Remove-Item $nupkg2 -Force -ErrorAction SilentlyContinue
                        throw "VideoLAN.LibVLC.Windows $winVer package failed SHA-256 verification - not installed"
                    }
                    $z2 = [IO.Compression.ZipFile]::OpenRead($nupkg2)
                    $Status.Text = 'Extracting VLC engine...'
                    # Current packages keep the x64 engine under build/x64/ (older ones used runtimes/win-x64/native/).
                    foreach ($entry in ($z2.Entries | Where-Object { $_.FullName -match '^(runtimes/win-x64/native|build/x64)/' -and $_.Length -gt 0 })) {
                        $rel = ($entry.FullName -replace '^(runtimes/win-x64/native|build/x64)/', '')
                        $dest = Join-Path $NatDir $rel
                        $dir = Split-Path $dest
                        if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
                        [IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $dest, $true)
                    }
                    $z2.Dispose()
                    try { Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue } catch {}
                }
            }
            $Status.Text = 'Starting camera/music engine...'
            [Reflection.Assembly]::LoadFrom($DllPath) | Out-Null
            [LibVLCSharp.Shared.Core]::Initialize($NatDir)
            $lib = [LibVLCSharp.Shared.LibVLC]::new($false)
            return @{ Ok = $true; LibVLC = $lib }
        }
        catch { return @{ Ok = $false; Error = "$_" } }
    }

    try {
        $rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $rs.ThreadOptions = 'ReuseThread'
        $rs.Open()
        $script:_vlcPreloadRS = $rs

        $ps = [System.Management.Automation.PowerShell]::Create()
        $ps.Runspace = $rs
        [void]$ps.AddScript($preloadScript).AddArgument($dllPath).AddArgument($natDir).AddArgument($bundledDll).AddArgument($bundledNat).AddArgument($script:_vlcPreloadStatus).AddArgument($script:VlcPin)
        $script:_vlcPreloadPS = $ps
        $script:_vlcPreloadAsyncResult = $ps.BeginInvoke()

        $pollTimer = New-Object System.Windows.Forms.Timer
        $script:_vlcPreloadPollTimer = $pollTimer
        $pollTimer.Interval = 200
        $script:_vlcPreloadDone = $false   # belt-and-suspenders guard: this Timer has been observed to
        # keep firing Tick events even after Stop()+Dispose() in this
        # background-runspace-completion scenario, which without this
        # flag kept re-writing stale status text to the status bar
        # forever, overriding any other status message shown afterward.
        $pollTimer.Add_Tick({
                param($tickSrc, $tickArgs)
                $pollTimer = $tickSrc   # the function-local $pollTimer is gone once Start-LibVlcPreload returns
                try {
                    if ($script:_vlcPreloadDone) { try { $pollTimer.Stop() } catch {}; return }
                    # Reflect current download/extract progress while still running
                    try { if ($script:sbLeft -and -not $script:sbLeft.IsDisposed -and $script:_vlcPreloadStatus.Text) { $script:sbLeft.Text = $script:_vlcPreloadStatus.Text } } catch {}
                    if (-not $script:_vlcPreloadAsyncResult -or -not $script:_vlcPreloadAsyncResult.IsCompleted) { return }
                    $script:_vlcPreloadDone = $true
                    $script:_vlcPreloadStatus.Text = ''   # stop the guard-bypassed "reflect progress" line above from ever showing stale text
                    try { $pollTimer.Stop(); $pollTimer.Dispose() } catch {}
                    if ([object]::ReferenceEquals($script:_vlcPreloadPollTimer, $pollTimer)) { $script:_vlcPreloadPollTimer = $null }

                    $result = $null
                    try {
                        $out = $script:_vlcPreloadPS.EndInvoke($script:_vlcPreloadAsyncResult)
                        if ($out -and $out.Count -gt 0) { $result = $out[0] }
                    }
                    catch { Log "LibVLC preload: EndInvoke error: $_" }
                    try { $script:_vlcPreloadPS.Dispose() } catch {}
                    try { $script:_vlcPreloadRS.Close(); $script:_vlcPreloadRS.Dispose() } catch {}
                    $script:_vlcPreloadRS = $null; $script:_vlcPreloadPS = $null; $script:_vlcPreloadAsyncResult = $null

                    if ($result -and $result['Ok']) {
                        $script:_vlcPreloadedLib = $result['LibVLC']
                        $script:VlcAvailable = $true
                        Log 'LibVLC preload: engine ready in background (Play will start instantly)'
                        # If camera preview was deferred waiting for preload, start it now
                        try { if ($script:_vlcPreloadCameraDeferred) { $script:_vlcPreloadCameraDeferred = $false; Set-ObsPreviewMode } } catch {}
                        # If background music auto-start was deferred (engine still WPF at the time), switch it over now
                        try {
                            if ($script:_vlcPreloadMusicDeferred) {
                                $script:_vlcPreloadMusicDeferred = $false
                                if (-not (Test-MusicIsPlaying)) { Start-Music; Log "Background music: auto-started (after engine load)." }
                            }
                        }
                        catch { Log "Background music: deferred auto-start failed: $_" }
                        try { $script:sbLeft.Text = 'Ready' } catch {}
                    }
                    else {
                        Log "LibVLC preload: failed, will fall back to on-demand load: $($result['Error'])"
                        try { $script:sbLeft.Text = 'Camera engine failed to load — check logs' } catch {}
                        try {
                            if ($script:_vlcPreloadCameraDeferred) {
                                $script:_vlcPreloadCameraDeferred = $false
                                [System.Windows.Forms.MessageBox]::Show(
                                    "The camera engine (LibVLC) failed to load.`n`nLive camera preview is not available.`n`nError: $($result['Error'])",
                                    'Camera Engine Error',
                                    [System.Windows.Forms.MessageBoxButtons]::OK,
                                    [System.Windows.Forms.MessageBoxIcon]::Warning
                                ) | Out-Null
                            }
                        }
                        catch {}
                        $script:_vlcPreloadMusicDeferred = $false   # engine never arrived - WPF playback (already started) stays as-is
                    }
                }
                catch {}
            })
        $pollTimer.Start()
        $bundledMsg = if ($bundledReady -and -not $cacheReady) { ' from bundled folder (first run)' } elseif (-not $cacheReady -and -not $bundledReady) { ' (downloading, first run)' } else { '' }
        Log "LibVLC preload: loading engine in background$bundledMsg..."
        try { $script:sbLeft.Text = 'Loading camera engine, please wait...' } catch {}
    }
    catch { Log "LibVLC preload: init error: $_" }
}

# ---- Engine-agnostic adapter helpers ----
# These let Music-* functions stay clean regardless of which engine is active.
# NOTE: check $script:Music._LibVLC (not the global $script:VlcAvailable) - the background
# preload can flip VlcAvailable to $true while Music is still actively playing on WPF (started
# earlier while the engine was loading), and these adapters must match the CURRENT Music.Player
# instance, not the global engine-availability flag.
function Open-MusicPlayerFile([string]$filePath) {
    if ($script:Music._LibVLC) {
        # Must use 4-param constructor — 3-arg call causes PowerShell overload resolver to throw
        $m = [LibVLCSharp.Shared.Media]::new($script:Music._LibVLC, $filePath, [LibVLCSharp.Shared.FromType]::FromPath, [string[]]@())
        $script:Music.Player.Media = $m
        $m.Dispose()
    }
    else {
        $script:Music.Player.Open([System.Uri]::new($filePath))
    }
}
function Set-MusicPlayerVolume([int]$vol) {
    if ($script:Music._LibVLC) { $script:Music.Player.Volume = [int]$vol }
    else { $script:Music.Player.Volume = [double]$vol / 100.0 }
}
function Get-MusicPlayerVolume {
    try {
        if ($script:Music._LibVLC) { return [int]$script:Music.Player.Volume }
        else { return [int]($script:Music.Player.Volume * 100) }
    }
    catch { return [int]$script:Music.Volume }
}
function Set-MusicPlayerMute([bool]$muted) {
    if ($script:Music._LibVLC) { $script:Music.Player.Mute = $muted }
    else { $script:Music.Player.IsMuted = $muted }
}

$script:Music = [ordered]@{
    Player = $null; _LibVLC = $null; Playlist = $null; Folder = $script:Cfg.Music.Folder
    Files = @(); CurrentIndex = -1; _IsPlaying = $false
    Volume = [int]$script:Cfg.Music.Volume; Shuffle = [bool]$script:Cfg.Music.Shuffle
    AutoStart = [bool]$script:Cfg.Music.AutoStart
    AutoStopBeforeMeeting = [bool]$script:Cfg.Music.AutoStopBeforeMeeting
    PreStopSeconds = [int]$script:Cfg.Music.PreStopSeconds
    FadeOutSeconds = [int]$script:Cfg.Music.FadeOutSeconds
    _LastStartIndex = $null
}
$script:MusicTimer = New-Object System.Windows.Forms.Timer
$script:MusicTimer.Interval = 1000

$script:MusicFadeTimer = New-Object System.Windows.Forms.Timer
$script:MusicFadeTimer.Interval = 60
$script:_fadeActive = $false
$script:_fadeStartTime = $null
$script:_fadeEndTime = $null
$script:_fadeStartVol = 0
$script:_fadeRestoreVol = 0
$script:_fadeStopAfter = $true
$script:_postFadeStopTimer = $null        # kept as null — no longer used (Pause() approach)
$script:_musicStopCooldownUntil = $null  # suppress ducking for 1.5s after music stops
$script:_musicFadeFlashTimer = $null      # flashes the music button green while a fade-out is in progress

# Flashes the music toggle button green/dark-green while fading out, so a Stop Music click is
# never ambiguous (no more "did that register?" double-clicks).
function Start-MusicFadeFlash {
    if (-not $btnMusicToggle) { return }
    if ($script:_musicFadeFlashTimer -and -not $script:_musicFadeFlashTimer.IsDisposed) { return }  # already flashing
    $script:_musicFadeFlashFrame = 0
    $flashTimer = New-Object System.Windows.Forms.Timer
    $script:_musicFadeFlashTimer = $flashTimer
    $flashTimer.Interval = 300
    $flashTimer.Add_Tick({
            try {
                $script:_musicFadeFlashFrame++
                $bright = ($script:_musicFadeFlashFrame % 2) -eq 0
                if ($btnMusicToggle) {
                    $btnMusicToggle.BackColor = if ($bright) { [System.Drawing.Color]::FromArgb(0, 230, 0) } else { [System.Drawing.Color]::FromArgb(0, 100, 0) }
                    $btnMusicToggle.ForeColor = [System.Drawing.Color]::Black
                    $btnMusicToggle.Text = "Fading..."
                }
            }
            catch {}
        })
    $flashTimer.Start()
}

function Stop-MusicFadeFlash {
    if ($script:_musicFadeFlashTimer -and -not $script:_musicFadeFlashTimer.IsDisposed) {
        try { $script:_musicFadeFlashTimer.Stop(); $script:_musicFadeFlashTimer.Dispose() } catch {}
    }
    $script:_musicFadeFlashTimer = $null
}

$script:MusicFadeTimer.Add_Tick({
        try {
            if (-not $script:_fadeActive -or -not $script:Music.Player) { $script:MusicFadeTimer.Stop(); return }
            try { Set-MusicPlayerMute $false }catch {}
            $now = Get-Date
            $curVol = 0; try { $curVol = Get-MusicPlayerVolume }catch {}
            if ($now -ge $script:_fadeEndTime) {
                try { Set-MusicPlayerVolume 0 }catch {}
                $script:_fadeActive = $false; $script:MusicFadeTimer.Stop()
                Stop-MusicFadeFlash
                if ($script:_fadeStopAfter) {
                    # Use Pause() NOT Stop() — avoids pipeline flush noise.
                    # LibVLC Pause() also holds cleanly; Start-Music re-opens the track next time.
                    $script:Music._IsPlaying = $false  # set BEFORE Pause() so EndReached BeginInvoke can't trigger Skip-MusicTrack
                    try { $script:Music.Player.Pause() } catch {}
                    $script:_musicStopCooldownUntil = (Get-Date).AddMilliseconds(3000)  # suppress ducking 3s
                    # Do NOT restore volume here — doing so while LibVLC is mid-Pause causes a pop
                    # because buffered decode frames still in flight get the full volume applied.
                    # Start-Music and Skip-MusicTrack both call Set-MusicPlayerVolume before Play().
                    Update-MusicButtonVisual
                    Update-MusicToggleButton
                    try { Update-MusicPopup } catch {}
                }
                else {
                    try { Set-MusicPlayerVolume ([int]$script:_fadeRestoreVol) }catch {}
                    Update-MusicButtonVisual; Update-MusicToggleButton
                    try { Update-MusicPopup } catch {}
                }
                return
            }
            $total = ($script:_fadeEndTime - $script:_fadeStartTime).TotalMilliseconds
            $elapsed = [math]::Min($total, ($now - $script:_fadeStartTime).TotalMilliseconds)
            $linearRatio = 1.0 - ($elapsed / $total)
            $target = [int][math]::Floor($script:_fadeStartVol * $linearRatio)
            if ($target -ge $curVol) { $target = [math]::Max(0, $curVol - 1) }
            try { Set-MusicPlayerVolume $target }catch {}
        }
        catch {}
    })
# ---- Auto Start Scene Functions ----
$script:_autoStartTriggered = $false  # Prevent multiple triggers
$script:_suppressAutoStart = $false   # Skip auto-start when reconnecting for settings changes
$script:_preservedScene = $null       # Scene to restore after settings reconnection
$script:_settingsReconnecting = $false # Block ALL scene changes during settings reconnection

function Invoke-AutoStartScenes {
    # Skip if suppressing auto-start (settings save in progress)
    if ($script:_autoStartTriggered -or $script:_suppressAutoStart) { 
        if ($script:_suppressAutoStart) {
            Log "Auto Start skipped (settings reconnection)"
        }
        return  # Only run once per session or when suppressed
    }
    $script:_autoStartTriggered = $true
    
    try {
        Log "Checking for Auto Start scenes..."
        foreach ($cfg in @($script:Cfg.ScenePTZ)) {
            if ($cfg.AutoStart -and $cfg.Scene) {
                Log "Auto Start triggered: Setting scene '$($cfg.Scene)'"
                try {
                    Set-ObsScene $cfg.Scene
                    if ($cfg.Snapshot) {
                        Start-Sleep -Milliseconds 500  # Allow scene switch to complete
                        if (-not $script:_autoModeActive) {
                            Restore-XrSnapshot $cfg.Snapshot
                        }
                        else {
                            Log "Auto Start: Snapshot auto-load skipped — Auto Mode is active"
                        }
                    }
                    return  # Only trigger first AutoStart=true scene found
                }
                catch {
                    Log "Auto Start scene error: $_"
                }
            }
        }
        Log "No Auto Start scenes found or configured."
    }
    catch {
        Log "Auto Start check error: $_"
    }
}

