# ---- Cut Hotkey Functions ----
function Get-HotKeyWindowHandle {
    # WPF-migration Phase 1 step: hotkey (de)registration needs a raw HWND regardless of which
    # UI framework currently owns the main window - mirrors the Invoke-OnUI dispatcher pattern.
    # Today $script:MainWindow is always $null so this always falls through to $script:form.Handle
    # (zero behavior change). Once a WPF shell exists and assigns $script:MainWindow, this reads
    # its HWND via WindowInteropHelper instead, so Register-CutHotKey/Unregister-CutHotKey never
    # need to change.
    # NOTE (not solved here, flagged for Phase 2): the WM_HOTKEY routing below still relies on
    # WinForms' Application.AddMessageFilter/message pump. A pure-WPF shell would need to swap
    # that for HwndSource.AddHook - that decision depends on whether Phase 2 keeps a hybrid
    # WinForms+WPF message loop or moves to Application.Run() on the WPF side.
    try {
        if ($script:MainWindow -and ($script:MainWindow -is [System.Windows.Threading.DispatcherObject])) {
            Add-Type -AssemblyName PresentationFramework -ErrorAction SilentlyContinue
            return [System.Windows.Interop.WindowInteropHelper]::new($script:MainWindow).Handle
        }
    }
    catch { return [IntPtr]::Zero }
    if ($script:form -and -not $script:form.IsDisposed) { return $script:form.Handle }
    return [IntPtr]::Zero
}

function Register-CutHotKey {
    $hwnd = Get-HotKeyWindowHandle
    if ($hwnd -eq [IntPtr]::Zero) { return }
    if ($script:_cutHotKeyId -gt 0) { Unregister-CutHotKey }
    
    $enabled = [bool]$script:Cfg.OBSControl.CutHotKeyEnabled
    $fkey = [string]$script:Cfg.OBSControl.CutHotKeyFKey
    
    if (-not $enabled -or [string]::IsNullOrWhiteSpace($fkey)) { return }
    
    $vk = $script:FKeyVirtualKeyCodes[$fkey]
    if (-not $vk) { Log "Cut hotkey: invalid F-key '$fkey'"; return }
    
    try {
        $hotKeyId = 1001   # arbitrary ID for Cut hotkey
        
        # MOD_NONE = 0 (no modifiers: bare F-key)
        $result = [User32.HotKeyAPI]::RegisterHotKey($hwnd, $hotKeyId, 0, $vk)
        
        if ($result) {
            $script:_cutHotKeyId = $hotKeyId
            $script:_cutHotKeyFKey = $fkey
            Log "Cut hotkey registered: $fkey (VK=$vk)"
            
            # Install the message filter to intercept WM_HOTKEY on the UI thread
            if ($null -eq $script:_hotKeyFilter) {
                try {
                    $script:_hotKeyFilter = New-Object JwlHotKeyFilter
                    [System.Windows.Forms.Application]::AddMessageFilter($script:_hotKeyFilter)
                    
                    # Polling timer: reads the static flag every 50ms on the UI thread
                    if ($null -eq $script:_hotKeyPollTimer) {
                        $script:_hotKeyPollTimer = New-Object System.Windows.Forms.Timer
                        $script:_hotKeyPollTimer.Interval = 50
                        $script:_hotKeyPollTimer.Add_Tick({
                                $firedId = [JwlHotKeyFilter]::LastHotKeyId
                                if ($firedId -ne 0) {
                                    [JwlHotKeyFilter]::LastHotKeyId = 0
                                    Log "DEBUG: WM_HOTKEY received, id=$firedId (expected 1001 for Cut)"
                                    if ($firedId -eq 1001) {
                                        Invoke-CutHotKeyPressed
                                    }
                                }
                            })
                        $script:_hotKeyPollTimer.Start()
                    }
                }
                catch { Log "Cut hotkey: IMessageFilter not available: $_" }
            }
        }
        else {
            Log "Cut hotkey registration failed for $fkey"
        }
    }
    catch {
        Log "Cut hotkey registration error: $_"
    }
}

function Unregister-CutHotKey {
    if ($script:_cutHotKeyId -le 0) { return }
    $hwnd = Get-HotKeyWindowHandle
    if ($hwnd -eq [IntPtr]::Zero) { return }
    
    try {
        # Remove the message filter and stop the poll timer
        if ($null -ne $script:_hotKeyPollTimer) {
            try { $script:_hotKeyPollTimer.Stop(); $script:_hotKeyPollTimer.Dispose() } catch {}
            $script:_hotKeyPollTimer = $null
        }
        if ($null -ne $script:_hotKeyFilter) {
            try { [System.Windows.Forms.Application]::RemoveMessageFilter($script:_hotKeyFilter) } catch {}
            $script:_hotKeyFilter = $null
        }
        
        [User32.HotKeyAPI]::UnregisterHotKey($hwnd, $script:_cutHotKeyId) | Out-Null
        Log "Cut hotkey unregistered: $script:_cutHotKeyFKey"
        $script:_cutHotKeyId = 0
    }
    catch {
        Log "Cut hotkey unregistration error: $_"
    }
}

function Invoke-CutHotKeyPressed {
    # Called from a WinForms timer tick — already on the UI thread, so PerformClick directly
    try {
        if ($script:btnCut -and -not $script:btnCut.IsDisposed -and $script:btnCut.Enabled) {
            Log "Cut hotkey fired: performing Cut"
            $script:btnCut.PerformClick()
        }
    }
    catch {
        Log "Cut hotkey click error: $_"
    }
}


# Confirmation logic used before *any* music start (manual or auto)

function Confirm-MusicStart {
    # Hard block during the meeting window (no prompt)
    if (Test-MeetingGuardActive) {
        try {
            Show-CenteredDialog `
                -Text "Background music is blocked during the meeting window." `
                -Title "Meeting Mode" `
                -Buttons OK `
                -Icon Information | Out-Null
        }
        catch {}
        return $false
    }

    # Optional global “always confirm”
    if ($script:Cfg.Music.RequireConfirmAlways) {
        $r = Show-CenteredDialog `
            -Text "Play Background Music?" `
            -Title "Confirm" `
            -Buttons YesNo `
            -Icon Question
        return ($r -eq [System.Windows.Forms.DialogResult]::Yes)
    }

    return $true
}

function New-MusicEngine {
    if ($script:Music.Player) { return }

    # First-time init loads native LibVLC DLLs and can take several seconds — show
    # feedback and force a repaint now, since nothing pumps the UI during that call
    try {
        if ($script:sbLeft -and -not $script:sbLeft.IsDisposed) { $script:sbLeft.Text = 'Loading music engine (first play only)...' }
        if ($script:form -and -not $script:form.IsDisposed) { $script:form.Refresh() }
    }
    catch {}

    # --- Try LibVLC first (no pop/click on fade or stop) ---
    # Skip while the background preload/download is still running - calling Initialize-LibVLC
    # here would start a second, synchronous download racing the same destination files and
    # freeze the UI for however long that takes. WPF plays immediately instead; once the
    # background engine finishes loading, Start-LibVlcPreload's completion handler switches
    # playback over to LibVLC automatically (see $script:_vlcPreloadMusicDeferred).
    if (Test-LibVlcPreloadBusy) {
        $script:_vlcPreloadMusicDeferred = $true
        Log 'Music engine: LibVLC still loading in background - using WPF for now'
    }
    elseif ($script:VlcAvailable -or (Initialize-LibVLC)) {
        try {
            # Reuse the background-preloaded engine instance if ready — avoids re-triggering
            # the several-second native load/plugin-scan that already ran on Start-LibVlcPreload.
            if ($script:_vlcPreloadedLib) {
                $script:Music._LibVLC = $script:_vlcPreloadedLib
                $script:_vlcPreloadedLib = $null
            }
            else {
                $script:Music._LibVLC = [LibVLCSharp.Shared.LibVLC]::new($false)
            }
            $mp = [LibVLCSharp.Shared.MediaPlayer]::new($script:Music._LibVLC)
            $mp.Volume = [int]$script:Music.Volume
            $mp.Mute = $false
            # NOTE: deliberately NOT subscribing to add_EndReached here. EndReached fires on a raw
            # native VLC thread that has no PowerShell runspace attached — invoking a PowerShell
            # scriptblock from that thread throws PSInvalidOperationException in
            # ScriptBlock.GetContextFromTLS() *before* any try/catch in the block can run, which is
            # unhandled and hard-crashes the whole process (confirmed via Windows Event Log).
            # Track-end is instead detected safely by polling Player.State from $script:MusicTimer's
            # UI-thread tick (see below) — same effect, zero cross-thread PowerShell invocation risk.
            $script:Music.Player = $mp
            $script:VlcAvailable = $true
            Log 'Music engine initialised using LibVLC (clean fade/stop, no noise)'
            return
        }
        catch {
            Log "LibVLC engine init failed, falling back to WPF: $_"
            try { if ($script:Music._LibVLC) { $script:Music._LibVLC.Dispose() } } catch {}
            $script:Music._LibVLC = $null
            $script:VlcAvailable = $false
        }
    }

    # --- Fallback: WPF MediaPlayer ---
    try { Add-Type -AssemblyName PresentationCore, WindowsBase -ErrorAction Stop } catch {}
    try {
        $script:Music.Player = New-Object System.Windows.Media.MediaPlayer
        $script:Music.Player.Volume = [double]$script:Music.Volume / 100.0
        $script:Music.Player.IsMuted = $false
        $script:Music.Player.Add_MediaEnded({
                try { if ($script:Music._IsPlaying) { Skip-MusicTrack } } catch { Log "Music auto-advance (WPF) failed: $_" }
            })
        Log 'Music engine initialised using WPF MediaPlayer (LibVLC not available)'
    }
    catch {
        Log "Music init failed: $_"
        $script:Music.Player = $null
    }
}
function Remove-MusicEngine {
    try { if ($script:MusicTimer) { $script:MusicTimer.Stop() } } catch {}
    try { if ($script:MusicFadeTimer) { $script:MusicFadeTimer.Stop() } } catch {}
    try { if ($script:AudioMonitorTimer) { $script:AudioMonitorTimer.Stop() } } catch {}
    try { if ($script:Music.Player) { $script:Music.Player.Stop(); $script:Music.Player.Dispose() } } catch {}
    try { if ($script:Music._LibVLC) { $script:Music._LibVLC.Dispose() } } catch {}
    $script:Music.Player = $null; $script:Music._LibVLC = $null; $script:Music.Playlist = $null
    $script:Music.Files = @(); $script:Music.CurrentIndex = -1; $script:Music._IsPlaying = $false
    $script:_fadeActive = $false
}
function Skip-MusicTrack {
    # Called when a track ends — advance to the next (or random) track.
    if (-not $script:Music._IsPlaying -or -not $script:Music.Player) { return }
    # Do NOT advance while a fade is active: Player.Open() is internally Stop()+load which
    # flushes the audio pipeline and causes the same spike as Stop().
    if ($script:_fadeActive) { return }
    $files = $script:Music.Files
    $count = $files.Count
    if ($count -eq 0) { $script:Music._IsPlaying = $false; return }
    if ($script:Music.Shuffle) {
        $next = Get-Random -Minimum 0 -Maximum $count
        $tries = 0
        while ($next -eq $script:Music.CurrentIndex -and $count -gt 1 -and $tries -lt 6) {
            $next = Get-Random -Minimum 0 -Maximum $count; $tries++
        }
    }
    else {
        $next = ($script:Music.CurrentIndex + 1) % $count
    }
    $script:Music.CurrentIndex = $next
    $script:Music._LastStartIndex = $next
    try {
        Open-MusicPlayerFile $files[$next]
        Set-MusicPlayerVolume ([int]$script:Music.Volume)
        $script:Music.Player.Play()
    }
    catch { $script:Music._IsPlaying = $false }
    Update-MusicButtonVisual
    Update-MusicToggleButton
    try { Update-MusicPopup } catch {}
}
function Import-MusicFolder([string]$Folder) {
    if (-not (Test-Path $Folder -PathType Container)) { throw "Music: Folder not found: $Folder" }
    New-MusicEngine
    if (-not $script:Music.Player) { throw "Music: MediaPlayer failed to initialize" }
    $exts = @(".mp3", ".wma", ".wav", ".m4a", ".aac", ".flac")
    $files = Get-ChildItem -Path $Folder -File -Recurse | Where-Object { $exts -contains ([IO.Path]::GetExtension($_.FullName).ToLower()) }
    if (-not $files) { throw "Music: No audio files in $Folder" }
    $script:Music.Files = @($files | ForEach-Object { $_.FullName })
    $script:Music.Playlist = $script:Music.Files  # keep .Playlist alias for compatibility
    $script:Music.CurrentIndex = -1
    $script:Music.Folder = $Folder
}
function Save-MusicState {
    # Persist the currently playing filename so the next session can avoid repeating it
    try {
        $stateFile = Join-Path (Split-Path (Get-ConfigPath)) 'music_state.json'
        @{ LastPlayedFile = $script:Music.Files[$script:Music.CurrentIndex] } |
        ConvertTo-Json | Set-Content $stateFile -Encoding UTF8 -ErrorAction Stop
    }
    catch {}
}
function Get-LastPlayedMusicFile {
    try {
        $stateFile = Join-Path (Split-Path (Get-ConfigPath)) 'music_state.json'
        if (Test-Path $stateFile) {
            $s = Get-Content $stateFile -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json
            return $s.LastPlayedFile
        }
    }
    catch {}
    return $null
}
function Start-Music {
    New-MusicEngine
    if (-not $script:Music.Player) { throw "Music: MediaPlayer failed to initialize" }
    try { if ($script:MusicFadeTimer.Enabled) { $script:MusicFadeTimer.Stop(); $script:_fadeActive = $false } }catch {}
    if (-not $script:Music.Files -or $script:Music.Files.Count -eq 0) {
        if (-not $script:Music.Folder) { throw "Music: No playlist. Choose a folder first." }
        Import-MusicFolder $script:Music.Folder
    }
    $count = $script:Music.Files.Count
    if ($count -eq 0) { throw "Music: No audio files found" }
    # On first start of this session, seed _LastStartIndex from the persisted last-played file
    # so we never repeat the same opening song across restarts.
    if ($null -eq $script:Music._LastStartIndex) {
        $lastFile = Get-LastPlayedMusicFile
        if ($lastFile) {
            $idx = [Array]::IndexOf([array]$script:Music.Files, $lastFile)
            if ($idx -ge 0) { $script:Music._LastStartIndex = $idx }
        }
    }
    $rand = Get-Random -Minimum 0 -Maximum $count
    if ($count -gt 1 -and $null -ne $script:Music._LastStartIndex) {
        $tries = 0; while ($rand -eq $script:Music._LastStartIndex -and $tries -lt 6) { $rand = Get-Random -Minimum 0 -Maximum $count; $tries++ }
    }
    $script:Music.CurrentIndex = $rand
    $script:Music._LastStartIndex = $rand
    Save-MusicState   # persist choice so next session starts on a different song
    Open-MusicPlayerFile $script:Music.Files[$rand]
    Set-MusicPlayerVolume ([int]$script:Music.Volume)
    Set-MusicPlayerMute $false
    $script:Music.Player.Play()
    $script:Music._IsPlaying = $true
    try { Update-MusicPopup } catch {}
}
function Stop-Music {
    $script:Music._IsPlaying = $false  # set BEFORE Stop() so EndReached BeginInvoke can't trigger Skip-MusicTrack
    try { if ($script:Music.Player) { $script:Music.Player.Stop() } } catch {}
}
function Set-MusicVolume([int]$Volume) { if ($Volume -lt 0 -or $Volume -gt 100) { throw "Volume 0..100" }; $script:Music.Volume = $Volume; if ($script:Music.Player) { Set-MusicPlayerVolume $Volume } }
function Set-MusicShuffle([bool]$Enabled) { $script:Music.Shuffle = $Enabled }
function Test-MusicIsPlaying { return ($null -ne $script:Music.Player -and $script:Music._IsPlaying) }
function Stop-MusicFade([int]$ms = 3000, [bool]$StopAfter = $true) {
    try {
        if (-not $script:Music.Player) { return }
        if (-not (Test-MusicIsPlaying)) { if ($StopAfter) { Stop-Music }; return }
        if ($ms -le 0) { if ($StopAfter) { Stop-Music }; return }
        try { Set-MusicPlayerMute $false }catch {}
        $curVol = 0; try { $curVol = Get-MusicPlayerVolume }catch {}
        if ($curVol -le 0) { $curVol = [int]$script:Music.Volume }
        $script:_fadeStartVol = $curVol
        $script:_fadeRestoreVol = [int]$script:Music.Volume
        $script:_fadeStopAfter = $StopAfter
        $script:_fadeStartTime = Get-Date
        $script:_fadeEndTime = $script:_fadeStartTime.AddMilliseconds([math]::Max(200, $ms))
        $script:_fadeActive = $true
        $script:MusicFadeTimer.Start()
        Start-MusicFadeFlash
    }
    catch { Log "Fade error: $_" }
}

# visuals for toggle
function Update-MusicButtonVisual {
    try {
        if (Test-MusicIsPlaying) {
            $btnMusicToggle.BackColor = [System.Drawing.Color]::FromArgb(0, 192, 0); $btnMusicToggle.ForeColor = [System.Drawing.Color]::Black
        }
        else {
            $btnMusicToggle.UseVisualStyleBackColor = $true; $btnMusicToggle.ForeColor = [System.Drawing.Color]::Black
        }
    }
    catch {}
}
function Update-MusicToggleButton {
    try {
        if ($script:_musicFadeFlashTimer -and -not $script:_musicFadeFlashTimer.IsDisposed) { return }  # don't fight the fade-out flash
        if (Test-MusicIsPlaying) { $btnMusicToggle.Text = "⏹ Stop Music" }
        else { $btnMusicToggle.Text = "♪ Play Music" }
    }
    catch {}
}

# ---- Mini Music Player Popup ----
$script:_musicPopup = $null   # the floating Form
$script:_musicPopupTimer = $null  # refresh timer

function Get-CurrentSongName {
    try {
        $idx = $script:Music.CurrentIndex
        if ($idx -ge 0 -and $script:Music.Files -and $idx -lt $script:Music.Files.Count) {
            return [System.IO.Path]::GetFileNameWithoutExtension($script:Music.Files[$idx])
        }
    }
    catch {}
    return '— no track —'
}

function Update-MusicPopup {
    try {
        $p = $script:_musicPopup
        if (-not $p -or $p.IsDisposed) { return }
        $songLbl = $p.Controls | Where-Object { $_.Name -eq 'lblSong' } | Select-Object -First 1
        $statLbl = $p.Controls | Where-Object { $_.Name -eq 'lblStatus' } | Select-Object -First 1
        $volLbl = $p.Controls | Where-Object { $_.Name -eq 'lblVol' } | Select-Object -First 1
        $vol = $p.Controls | Where-Object { $_.Name -eq 'trkVol' } | Select-Object -First 1
        $playBtn = $p.Controls | Where-Object { $_.Name -eq 'btnPlay' } | Select-Object -First 1
        if ($songLbl) { $songLbl.Text = Get-CurrentSongName }
        if ($statLbl) {
            if (Test-MusicIsPlaying) { $statLbl.Text = '▶  Playing'; $statLbl.ForeColor = [Drawing.Color]::LimeGreen }
            elseif ($script:_fadeActive) { $statLbl.Text = '↓  Fading out'; $statLbl.ForeColor = [Drawing.Color]::Orange }
            else { $statLbl.Text = '⏸  Stopped'; $statLbl.ForeColor = [Drawing.Color]::Silver }
        }
        if ($vol -and -not $vol.Capture) { $vol.Value = [math]::Max(0, [math]::Min(100, [int]$script:Music.Volume)) }
        if ($volLbl) { $volLbl.Text = "Vol: $([int]$script:Music.Volume)%" }
        if ($playBtn) { $playBtn.Text = if (Test-MusicIsPlaying) { '⏸' } else { '▶' } }
    }
    catch {}
}

# Mini player wallpaper (206x157 JPEG, cropped without the black border / play overlay), base64.
$script:_musicPopupBgB64 = -join @(
