)

function New-MusicPopupBackground([int]$w, [int]$h) {
    # Cover-fits the wallpaper to the popup size (no borders) and darkens it so the text stays readable.
    $bytes = [Convert]::FromBase64String($script:_musicPopupBgB64)
    $ms = New-Object System.IO.MemoryStream(, $bytes)
    $img = [System.Drawing.Image]::FromStream($ms)
    try {
        $bmp = New-Object System.Drawing.Bitmap($w, $h, [System.Drawing.Imaging.PixelFormat]::Format24bppRgb)
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        try {
            $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $scale = [math]::Max($w / $img.Width, $h / $img.Height)
            $dw = [int][math]::Ceiling($img.Width * $scale)
            $dh = [int][math]::Ceiling($img.Height * $scale)
            $g.DrawImage($img, [int](($w - $dw) / 2), [int](($h - $dh) / 2), $dw, $dh)
            $br = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(150, 0, 0, 0))
            try { $g.FillRectangle($br, 0, 0, $w, $h) } finally { $br.Dispose() }
        }
        finally { $g.Dispose() }
        return $bmp
    }
    finally { $img.Dispose(); $ms.Dispose() }
}

function Show-MusicPlayerPopup {
    # Music is disabled while Auto Toggle is active - no mini player either.
    if ($btnMusicToggle -and -not $btnMusicToggle.Enabled) { return }
    # Reuse existing popup if still open
    if ($script:_musicPopup -and -not $script:_musicPopup.IsDisposed) {
        $script:_musicPopup.BringToFront()
        Update-MusicPopup
        return
    }

    $popup = New-Object System.Windows.Forms.Form
    $popup.FormBorderStyle = 'None'
    $popup.ShowInTaskbar = $false
    $popup.TopMost = $true
    $popup.BackColor = [Drawing.Color]::FromArgb(30, 30, 30)
    $popup.ForeColor = [Drawing.Color]::White
    $popup.Size = [Drawing.Size]::new(270, 230)
    $popup.StartPosition = 'Manual'
    $popup.Opacity = 0.96

    # Wallpaper (cropped photo, darkened) instead of plain black; double-buffered to avoid flicker.
    $popupBgColor = [Drawing.Color]::FromArgb(30, 30, 30)
    try {
        $bg = New-MusicPopupBackground $popup.ClientSize.Width $popup.ClientSize.Height
        $popup.BackgroundImage = $bg
        $popup.BackgroundImageLayout = [System.Windows.Forms.ImageLayout]::None
        [System.Windows.Forms.Form].GetProperty('DoubleBuffered', [System.Reflection.BindingFlags]'Instance,NonPublic').SetValue($popup, $true, $null)
        # The volume slider can't be transparent: give it the wallpaper's average colour under it.
        $sr = 0; $sg = 0; $sb = 0; $sn = 0
        foreach ($sx in 100, 130, 160, 190, 220, 250) { foreach ($sy in 160, 171, 182) { $sc = $bg.GetPixel($sx, $sy); $sr += $sc.R; $sg += $sc.G; $sb += $sc.B; $sn++ } }
        $popupBgColor = [Drawing.Color]::FromArgb([int]($sr / $sn), [int]($sg / $sn), [int]($sb / $sn))
    }
    catch { Log "Music popup wallpaper failed: $_" }

    # Position above the Play Music button
    try {
        $btnPt = $btnMusicToggle.PointToScreen([Drawing.Point]::new(0, 0))
        $px = $btnPt.X
        $py = $btnPt.Y - $popup.Height - 6
        $screen = [System.Windows.Forms.Screen]::FromControl($btnMusicToggle).WorkingArea
        if ($px + $popup.Width -gt $screen.Right) { $px = $screen.Right - $popup.Width }
        if ($py -lt $screen.Top + 15) { $py = $btnPt.Y + $btnMusicToggle.Height + 6 }
        $popup.Location = [Drawing.Point]::new($px, $py)
    }
    catch {}

    # ---- rounded border via Region ----
    try {
        Add-Type -AssemblyName System.Drawing
        $path = New-Object System.Drawing.Drawing2D.GraphicsPath
        $r = $popup.ClientRectangle; $rad = 14
        $path.AddArc($r.X, $r.Y, $rad, $rad, 180, 90)
        $path.AddArc($r.Right - $rad, $r.Y, $rad, $rad, 270, 90)
        $path.AddArc($r.Right - $rad, $r.Bottom - $rad, $rad, $rad, 0, 90)
        $path.AddArc($r.X, $r.Bottom - $rad, $rad, $rad, 90, 90)
        $path.CloseAllFigures()
        $popup.Region = New-Object System.Drawing.Region($path)
    }
    catch {}

    function New-PopupLabel([string]$text, [int]$x, [int]$y, [int]$w, [int]$h, [string]$name = '', [float]$sz = 9.5) {
        $l = New-Object System.Windows.Forms.Label
        $l.Text = $text; $l.Name = $name
        $l.Location = [Drawing.Point]::new($x, $y); $l.Size = [Drawing.Size]::new($w, $h)
        $l.ForeColor = [Drawing.Color]::White; $l.BackColor = [Drawing.Color]::Transparent
        $l.Font = New-Object Drawing.Font('Segoe UI', $sz)
        $l.TextAlign = 'MiddleCenter'
        return $l
    }
    function New-PopupBtn([string]$text, [int]$x, [int]$y, [int]$w, [int]$h, [string]$name = '') {
        $b = New-Object System.Windows.Forms.Button
        $b.Text = $text; $b.Name = $name
        $b.Location = [Drawing.Point]::new($x, $y); $b.Size = [Drawing.Size]::new($w, $h)
        $b.FlatStyle = 'Flat'; $b.BackColor = [Drawing.Color]::FromArgb(55, 55, 55)
        $b.ForeColor = [Drawing.Color]::White; $b.Font = New-Object Drawing.Font('Segoe UI', 12)
        $b.FlatAppearance.BorderColor = [Drawing.Color]::FromArgb(80, 80, 80)
        $b.FlatAppearance.BorderSize = 1
        return $b
    }

    # Title
    $title = New-PopupLabel '♪  JWL Music Player' 0 24 240 22 '' 9
    $title.ForeColor = [Drawing.Color]::FromArgb(180, 220, 255)

    # Close [X] — clearly visible red-tinted button in top-right
    $closeBtn = New-Object System.Windows.Forms.Button
    $closeBtn.Text = '✕'; $closeBtn.Size = [Drawing.Size]::new(26, 22)
    $closeBtn.Location = [Drawing.Point]::new(238, 23)
    $closeBtn.FlatStyle = 'Flat'
    $closeBtn.ForeColor = [Drawing.Color]::White
    $closeBtn.BackColor = [Drawing.Color]::FromArgb(140, 40, 40)
    $closeBtn.FlatAppearance.BorderColor = [Drawing.Color]::FromArgb(180, 60, 60)
    $closeBtn.FlatAppearance.BorderSize = 1
    $closeBtn.Font = New-Object Drawing.Font('Segoe UI', 8, [Drawing.FontStyle]::Bold)
    $closeBtn.Add_Click({ try { $script:_musicPopup.Close() } catch {} })

    # Song name
    $songLbl = New-PopupLabel (Get-CurrentSongName) 8 50 254 36 'lblSong' 9.5
    $songLbl.ForeColor = [Drawing.Color]::FromArgb(255, 220, 80)
    $songLbl.AutoEllipsis = $true

    # Status line
    $statLbl = New-PopupLabel '' 8 86 254 18 'lblStatus' 8.5

    # Transport buttons  ⏮  ▶/⏸  ⏭  ⏹
    $btnPrev = New-PopupBtn '⏮' 14  112 48 40 'btnPrev'
    $btnPlay = New-PopupBtn '▶'  68  112 48 40 'btnPlay'
    $btnNext = New-PopupBtn '⏭' 122  112 48 40 'btnNext'
    $btnStop = New-PopupBtn '⏹' 196  112 60 40 'btnStop'
    $btnStop.BackColor = [Drawing.Color]::FromArgb(80, 30, 30)

    # Volume
    $volLbl = New-PopupLabel "Vol: $([int]$script:Music.Volume)%" 8 160 80 22 'lblVol' 8.5
    $volLbl.TextAlign = 'MiddleLeft'

    $trkVol = New-Object System.Windows.Forms.TrackBar
    $trkVol.Name = 'trkVol'; $trkVol.Minimum = 0; $trkVol.Maximum = 100
    $trkVol.Value = [math]::Max(0, [math]::Min(100, [int]$script:Music.Volume))
    $trkVol.TickFrequency = 10; $trkVol.LargeChange = 10; $trkVol.SmallChange = 5
    $trkVol.Location = [Drawing.Point]::new(88, 156); $trkVol.Size = [Drawing.Size]::new(170, 30)
    $trkVol.BackColor = $popupBgColor

    # Engine badge
    $engLbl = New-PopupLabel '' 8 196 254 16 '' 7.5
    $engLbl.ForeColor = [Drawing.Color]::FromArgb(190, 190, 190)
    $engLbl.Text = if ($script:Music._LibVLC) { 'Engine: LibVLC' } else { 'Engine: WPF MediaPlayer' }

    # Wire up buttons
    $btnPrev.Add_Click({
            try {
                $count = $script:Music.Files.Count
                if ($count -gt 0) {
                    $prev = ($script:Music.CurrentIndex - 1 + $count) % $count
                    $script:Music.CurrentIndex = $prev
                    Open-MusicPlayerFile $script:Music.Files[$prev]
                    Set-MusicPlayerVolume ([int]$script:Music.Volume)
                    $script:Music.Player.Play()
                    $script:Music._IsPlaying = $true
                    Update-MusicButtonVisual; Update-MusicToggleButton; Update-MusicPopup
                }
            }
            catch { Log "Popup Prev: $_" }
        })
    $btnPlay.Add_Click({
            try {
                if (Test-MusicIsPlaying) {
                    $ms = [int]($script:Music.FadeOutSeconds * 1000)
                    Stop-MusicFade -ms $ms -StopAfter $true
                }
                else {
                    if (-not (Confirm-MusicStart)) { return }
                    if (-not $script:Music.Folder -or -not (Test-Path $script:Music.Folder -PathType Container)) { return }
                    if (-not $script:Music.Playlist -or $script:Music.Playlist.Count -eq 0) { Import-MusicFolder $script:Music.Folder }
                    Start-Music
                }
                Update-MusicButtonVisual; Update-MusicToggleButton; Update-MusicPopup
            }
            catch { Log "Popup Play/Pause: $_" }
        })
    $btnNext.Add_Click({
            try { Skip-MusicTrack }
            catch { Log "Popup Next: $_" }
        })
    $btnStop.Add_Click({
            try {
                $ms = [int]($script:Music.FadeOutSeconds * 1000)
                Stop-MusicFade -ms $ms -StopAfter $true
                Update-MusicButtonVisual; Update-MusicToggleButton; Update-MusicPopup
            }
            catch { Log "Popup Stop: $_" }
        })
    # Volume scroll — use sender ($s) to read Value, avoiding closure capture issues
    $trkVol.Add_Scroll({
            param($s, $e)
            try {
                $v = [int]$s.Value
                $script:Music.Volume = $v
                $script:Cfg.Music.Volume = $v
                if ($script:Music.Player) { Set-MusicPlayerVolume $v }
            }
            catch {}
        })

    # Escape key closes the popup — use $script:_musicPopup (local $popup is null in event handlers)
    $popup.KeyPreview = $true
    $popup.Add_KeyDown({
            param($s, $e)
            if ($e.KeyCode -eq [System.Windows.Forms.Keys]::Escape) { try { $script:_musicPopup.Close() } catch {} }
        })

    # Assign script-level ref BEFORE wiring timer (timer handler needs it)
    $script:_musicPopup = $popup
    $popup.Controls.AddRange(@($title, $closeBtn, $songLbl, $statLbl, $btnPrev, $btnPlay, $btnNext, $btnStop, $volLbl, $trkVol, $engLbl))

    # Refresh timer (500ms) — uses $script:_musicPopup, not closed-over $popup
    $script:_musicPopupTimer = New-Object System.Windows.Forms.Timer
    $script:_musicPopupTimer.Interval = 500
    $script:_musicPopupTimer.Add_Tick({
            try {
                if ($script:_musicPopup -and -not $script:_musicPopup.IsDisposed) { Update-MusicPopup }
                else { $script:_musicPopupTimer.Stop(); $script:_musicPopupTimer.Dispose(); $script:_musicPopupTimer = $null }
            }
            catch {}
        })
    $popup.Add_FormClosed({
            try { if ($script:_musicPopupTimer) { $script:_musicPopupTimer.Stop(); $script:_musicPopupTimer.Dispose(); $script:_musicPopupTimer = $null } } catch {}
            try { if ($script:_musicPopup -and $script:_musicPopup.BackgroundImage) { $script:_musicPopup.BackgroundImage.Dispose() } } catch {}
            $script:_musicPopup = $null
        })
    $script:_musicPopupTimer.Start()

    $popup.Show($script:form)
    Update-MusicPopup
}

function Update-AudioIndicator {
    try {
        if (-not $script:lblAudioStatus) { return }
        if (-not $script:Cfg.XR.DuckingEnabled) {
            $script:lblAudioStatus.Text = "XR Audio: Disabled"
            $script:lblAudioStatus.ForeColor = [System.Drawing.Color]::Gray
            return
        }
        $monCh = [int]$script:Cfg.XR.MediaChannel
        $threshDB = [double]$script:Cfg.XR.ThresholdDB
        $levelDB = -90.0
        if ($script:XrMeterLevels.Contains($monCh)) {
            $levelDB = [double]$script:XrMeterLevels[$monCh]
        }
        $levelText = $levelDB.ToString('F1')
        if ($levelDB -gt $threshDB) {
            $script:lblAudioStatus.Text = "XR Audio CH${monCh}: ACTIVE ($levelText dB  thr: $($threshDB)dB)"
            $script:lblAudioStatus.ForeColor = [System.Drawing.Color]::LimeGreen
        }
        else {
            $script:lblAudioStatus.Text = "XR Audio CH${monCh}: Silent ($levelText dB  thr: $($threshDB)dB)"
            $script:lblAudioStatus.ForeColor = [System.Drawing.Color]::DarkGray
        }
    }
    catch {}
}

$script:MusicTimer.Add_Tick({ 
        if ($script:ShuttingDown) { return }
        try {
            # Poll for LibVLC track-end instead of subscribing to add_EndReached (that event fires on
            # a native thread with no PowerShell runspace and crashes the process — see New-MusicEngine).
            if ($script:Music._LibVLC -and $script:Music._IsPlaying -and $script:Music.Player -and -not $script:_fadeActive) {
                try {
                    if ($script:Music.Player.State -eq [LibVLCSharp.Shared.VLCState]::Ended) { Skip-MusicTrack }
                }
                catch {}
            }
            Update-MusicButtonVisual
            Update-MusicToggleButton
            try { Update-MusicPopup } catch {}
        }
        catch {}
    })

