# 2) Define it (keep as-is)

function Set-ThemeFromCfg {
    $dark = Test-IsDarkTheme
    Enable-DarkMode $script:form $dark
    try { Sync-ObsPreviewTheme } catch {}
    if ($btnTheme) {
        $btnTheme.Text = $(if ($dark) { '☀' }else { '🌙' })
        $btnTheme.ForeColor = [Drawing.Color]::Goldenrod
    }
    # Re-theme the mixer panel's outer chrome live if it's currently open (channel-strip name tags,
    # role labels, meters and snapshot buttons keep their own hand-picked colors - see NOTE in
    # Show-MixerPanel; only the outer form + strip/snapshot backgrounds follow the app theme)
    try {
        if ($script:_mixerPanel -and -not $script:_mixerPanel.IsDisposed) {
            $script:_mixerDark = $dark
            $mTheme = if ($dark) { $DarkTheme } else { $LightTheme }
            $script:_mixerPanel.BackColor = $mTheme.Back
            foreach ($stripPnl in $script:_mixerStripPanels) {
                if ($stripPnl -and -not $stripPnl.IsDisposed) {
                    $isMasterStrip = ([string]$stripPnl.Tag -eq 'master')
                    $stripPnl.BackColor = if ($dark) {
                        if ($isMasterStrip) { [System.Drawing.Color]::FromArgb(38, 38, 52) } else { [System.Drawing.Color]::FromArgb(42, 42, 42) }
                    }
                    else {
                        if ($isMasterStrip) { [System.Drawing.Color]::FromArgb(210, 210, 226) } else { [System.Drawing.Color]::FromArgb(222, 222, 222) }
                    }
                }
            }
            if ($script:_mixerSnapPanel -and -not $script:_mixerSnapPanel.IsDisposed) {
                $script:_mixerSnapPanel.BackColor = if ($dark) { [System.Drawing.Color]::FromArgb(26, 26, 44) } else { [System.Drawing.Color]::FromArgb(212, 212, 226) }
            }
            $script:_mixerPanel.Invalidate($true)
            $script:_mixerPanel.Update()
            if (([System.Management.Automation.PSTypeName]'DwmDarkTitle').Type) {
                $dwmDark = [int]$dark
                [DwmDarkTitle]::DwmSetWindowAttribute($script:_mixerPanel.Handle, 20, [ref]$dwmDark, 4) | Out-Null
            }
        }
    }
    catch {}

    # WPF-migration hook: lets a future resource-dictionary-based shell react to theme toggles
    # without this function needing to know anything about WPF.
    Invoke-ThemeChangeCallbacks $dark
}

function Sync-ObsPreviewTheme {
    $dark = Test-IsDarkTheme
    $previewBack = if ($dark) { [Drawing.Color]::FromArgb(0x18, 0x18, 0x18) } else { [Drawing.Color]::FromArgb(245, 245, 245) }
    $hintFore = if ($dark) { [Drawing.Color]::FromArgb(0xB0, 0xB0, 0xB0) } else { [Drawing.SystemColors]::GrayText }

    try { if ($script:pPreview) { $script:pPreview.BackColor = $previewBack } } catch {}
    try { if ($script:pbObs) { $script:pbObs.BackColor = $previewBack } } catch {}
    try {
        if ($script:lblHint) {
            $script:lblHint.BackColor = [Drawing.Color]::Transparent
            $script:lblHint.ForeColor = $hintFore
        }
    }
    catch {}
}

