function Show-PTZSetupHelp {
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = 'PTZ Camera & Auto Frame — Setup Guide'
    $dlg.Size = [System.Drawing.Size]::new(640, 660)
    $dlg.MinimumSize = [System.Drawing.Size]::new(500, 400)
    $dlg.StartPosition = 'CenterParent'
    $dlg.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $dlg.ForeColor = [System.Drawing.Color]::FromArgb(220, 220, 220)
    $dlg.FormBorderStyle = 'Sizable'
    $dlg.MaximizeBox = $true
    $dlg.MinimizeBox = $false
    try { if ($script:form -and -not $script:form.IsDisposed) { $dlg.Owner = $script:form } } catch {}

    $rtb = New-Object System.Windows.Forms.RichTextBox
    $rtb.Dock = 'Fill'
    $rtb.ReadOnly = $true
    $rtb.BackColor = [System.Drawing.Color]::FromArgb(25, 25, 25)
    $rtb.ForeColor = [System.Drawing.Color]::FromArgb(220, 220, 220)
    $rtb.Font = New-Object System.Drawing.Font('Consolas', 9)
    $rtb.BorderStyle = 'None'
    $rtb.ScrollBars = 'Vertical'
    $rtb.WordWrap = $true
    $rtb.Padding = [System.Windows.Forms.Padding]::new(8)

    # Helper closures for styled text
    $appendHeading = {
        param([string]$text)
        $rtb.SelectionStart = $rtb.TextLength
        $rtb.SelectionLength = 0
        $rtb.SelectionFont = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        $rtb.SelectionColor = [System.Drawing.Color]::FromArgb(80, 180, 255)
        $rtb.AppendText("`r`n$text`r`n")
    }
    $appendRule = {
        $rtb.SelectionStart = $rtb.TextLength
        $rtb.SelectionLength = 0
        $rtb.SelectionFont = New-Object System.Drawing.Font('Consolas', 9)
        $rtb.SelectionColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
        $rtb.AppendText("  $('─' * 60)`r`n")
    }
    $appendBody = {
        param([string]$text)
        $rtb.SelectionStart = $rtb.TextLength
        $rtb.SelectionLength = 0
        $rtb.SelectionFont = New-Object System.Drawing.Font('Segoe UI', 10)
        $rtb.SelectionColor = [System.Drawing.Color]::FromArgb(210, 210, 210)
        $rtb.AppendText($text)
    }
    $appendWarn = {
        param([string]$text)
        $rtb.SelectionStart = $rtb.TextLength
        $rtb.SelectionLength = 0
        $rtb.SelectionFont = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        $rtb.SelectionColor = [System.Drawing.Color]::FromArgb(255, 200, 60)
        $rtb.AppendText($text)
    }
    $appendGreen = {
        param([string]$text)
        $rtb.SelectionStart = $rtb.TextLength
        $rtb.SelectionLength = 0
        $rtb.SelectionFont = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        $rtb.SelectionColor = [System.Drawing.Color]::FromArgb(80, 220, 100)
        $rtb.AppendText($text)
    }

    # Title
    $rtb.SelectionStart = $rtb.TextLength
    $rtb.SelectionFont = New-Object System.Drawing.Font('Segoe UI', 12, [System.Drawing.FontStyle]::Bold)
    $rtb.SelectionColor = [System.Drawing.Color]::FromArgb(120, 210, 255)
    $rtb.AppendText("  PTZ Camera & Auto Frame — Setup Guide`r`n")
    & $appendRule

    # ── SECTION 1 ──────────────────────────────────────────────
    & $appendHeading "  1.  OBS HOTKEY SETUP  (REQUIRED FIRST)"
    & $appendRule
    & $appendBody @"
  The PTZ overlay arrows and Auto Frame both work by sending
  hotkey commands through OBS WebSocket using
  TriggerHotkeyByKeySequence. OBS must have these keys
  registered as hotkeys or the buttons appear but do nothing.

"@
    & $appendWarn "  !! If the keyboard Arrow keys are NOT set in OBS,`r`n     the PTZ overlay arrows will NOT move the camera. !!`r`n`r`n"
    & $appendBody @"
  Steps:
    a. In OBS open  File > Settings > Hotkeys  (or press Ctrl+,).
    b. In the search box type the name of your PTZ source
       (e.g. "PTZ Controls", "VISCA", "NDI PTZ", or the source
        name you gave your camera).
    c. You will see entries like:
          Pan Left       Pan Right
          Tilt Up        Tilt Down
          Zoom In        Zoom Out
    d. Click the field next to each action and press the key:

         [Tilt Up]    -> press  Arrow Up    on the keyboard
         [Tilt Down]  -> press  Arrow Down  on the keyboard
         [Pan Left]   -> press  Arrow Left  on the keyboard
         [Pan Right]  -> press  Arrow Right on the keyboard
         [Zoom In]    -> press  Numpad +    on the keyboard
         [Zoom Out]   -> press  Numpad -    on the keyboard

    e. Click  Apply  then  OK.
    f. Test: hover the OBS preview in this app, hold an arrow
       button — the camera should now move.

"@
    & $appendWarn "  NOTE: Each hotkey must be unique in OBS (no conflicts).`r`n"
    & $appendBody "  If another source/filter already uses Arrow keys, OBS`r`n  will trigger both. Remove conflicts or use modifier keys.`r`n`r`n"

    # ── SECTION 2 ──────────────────────────────────────────────
    & $appendHeading "  2.  PTZ OVERLAY ARROWS  (hover the preview)"
    & $appendRule
    & $appendBody @"
  When you move the mouse over the OBS preview panel, four
  directional arrows and two zoom buttons appear:

       [▲]  Tilt Up       hold to tilt camera up continuously
       [▼]  Tilt Down     hold to tilt camera down
       [◄]  Pan Left      hold to pan camera left
       [►]  Pan Right     hold to pan camera right
       [+]  Zoom In       hold to zoom in
       [-]  Zoom Out      hold to zoom out

  Release the button to stop movement.
  The arrows disappear when the mouse leaves the preview.

"@
    & $appendWarn "  Common issue: arrows visible but camera does not move.`r`n"
    & $appendBody @"
    -> The Arrow keys are NOT assigned as OBS hotkeys yet.
       Follow Section 1 above to assign them.
    -> The PTZ camera source must be connected and active in OBS.
    -> Check OBS menu  Help > Log Files  for hotkey errors.

"@

    # ── SECTION 3 ──────────────────────────────────────────────
    & $appendHeading "  3.  AUTO FRAME  (AF: OFF / AF: ON) — CLICK TO CENTER"
    & $appendRule
    & $appendBody @"
  Auto Frame is a CLICK-TO-CENTER tool. You click on the face
  in the preview and the camera tilts to bring that point to
  the vertical centre of the frame.

  HOW TO USE:
    1. Click [AF: OFF] to enable  ->  button turns green [AF: ON].
    2. The cursor changes to a CROSSHAIR when you hover over the
       OBS preview panel (inside the green ROI box).
    3. Move the crosshair over the speaker's nose or eyes.
    4. Click once  ->  the camera tilts up or down to bring
       that exact point to the vertical centre.
    5. Repeat any time the speaker moves or changes position.
    6. If the camera movement is too small or too large, adjust
       the Camera Speed using the [−] and [+] buttons (S:20).
       Increase S: if the camera barely moves; decrease S: if
       it overshoots past the target.

  Notes:
    * Auto Frame only activates on the configured 'Speaker' scene.
    * The green ROI box (Section 4) defines the clickable area.
    * Speed (Section 5) controls how far each click moves the camera.
    * OBS WebSocket must be connected and Arrow Up/Down hotkeys
      must be set in OBS (Section 1) — otherwise clicks do nothing.

"@

    # ── SECTION 4 ──────────────────────────────────────────────
    & $appendHeading "  4.  SET ROI — REGION OF INTEREST"
    & $appendRule
    & $appendBody @"
  The ROI (green rectangle) defines the CLICKABLE AREA for
  Auto Frame. The crosshair cursor is only active when your
  mouse is inside the ROI box — clicks outside it do nothing.

  HOW TO SET IT:
    1. Click [Set ROI]  ->  green box appears, button shows [ROI: ON].
    2. Drag the box LEFT/RIGHT to centre it over the speaker's
       horizontal position in the preview.
    3. Drag the side handles to adjust the WIDTH — narrow it to
       just cover the column where the speaker stands or sits.
    4. Click [Set ROI] again to confirm and hide the editor.

  IMPORTANT — SHAPE THE BOX CORRECTLY:
    * Make it TALL and NARROW — NOT square.
    * Narrow horizontally: since there is no left/right pan,
      you only need to cover the speaker's horizontal column.
    * Make it as TALL as possible (it can extend above and
      below the visible preview edge — that is fine).
      A taller box means you can click anywhere from head to
      waist level, giving a bigger vertical target area.
    * The box height represents the full range of vertical
      positions where you might want to click to re-centre.

  Tips:
    - You can adjust the ROI while AF is ON without disabling it.
    - Re-set the ROI if the speaker's position on screen changes
      or if you switch to a camera with a different framing.

"@

    # ── SECTION 5 ──────────────────────────────────────────────
    & $appendHeading "  5.  CAMERA SPEED  (-  S:XX  +)"
    & $appendRule
    & $appendBody @"
  The speed value controls how many PTZ pulses are sent per
  Auto Frame correction step.

    - Range  : 10 – 200 pulses per correction.
    - Lower  : slower, more precise, less jitter.
    - Higher : faster, larger corrections, may overshoot.
    - Default: 80  (good starting point for most cameras).

  Adjust with [−] and [+] (steps of 10).
  The current value is shown as  S:80  between the buttons.

  Tuning guide:
    S:20-40   Very slow cameras or fine-tuning only.
    S:50-90   Most PTZ cameras at medium speed preset.
    S:100+    Fast cameras or when large corrections are needed.

"@

    # ── SECTION 6 ──────────────────────────────────────────────
    & $appendHeading "  6.  STEP-BY-STEP FIRST-TIME SETUP"
    & $appendRule
    & $appendGreen "  Follow these steps in order:`r`n`r`n"
    & $appendBody @"
  Step 1 — Install PTZ plugin in OBS
    - Download 'obs-ptz' (PTZ Controls) from OBS Forums / GitHub,
      or configure your VISCA-over-IP / NDI PTZ source in OBS.
    - Add a PTZ camera source to your OBS scene.

  Step 2 — Assign Arrow hotkeys in OBS
    - OBS > Settings > Hotkeys
    - Assign Arrow Up/Down/Left/Right and Numpad +/- as in Sec. 1.
    - Apply and close Settings.

  Step 3 — Connect this app to OBS WebSocket
    - In this app open Settings > OBS WebSocket.
    - Enter the host (127.0.0.1) and port (default 4456).
    - Click Connect — status indicator should turn green.

  Step 4 — Test the PTZ arrows
    - Hover the OBS preview panel in this app.
    - Hold [▲] or [▼] — camera should tilt.
    - Hold [◄] or [►] — camera should pan.
    - If nothing moves, re-check Step 2 (hotkeys in OBS).

  Step 5 — Configure Auto Frame
    - Switch OBS Program scene to 'Speaker'.
    - AF controls appear at the top of the preview panel.
    - Click [Set ROI], position the green box, confirm.
    - Set speed with [−] / [+] (start at S:20).
    - Click [AF: OFF] to enable Auto Frame -> [AF: ON].
    - Hover inside the green ROI — cursor turns into a crosshair.
    - Click on the speaker's nose or eyes to tilt the camera
      and bring that point to the vertical centre of the frame.

"@
    & $appendWarn "  REMINDER: Arrow keys must be set as OBS hotkeys (Step 2)`r`n"
    & $appendBody "  before the PTZ overlay arrows or Auto Frame will work.`r`n`r`n"

    $rtb.SelectionStart = 0   # scroll to top
    $rtb.ScrollToCaret()

    $btnClose = New-Object System.Windows.Forms.Button
    $btnClose.Text = 'Close'
    $btnClose.Size = [System.Drawing.Size]::new(90, 28)
    $btnClose.Location = [System.Drawing.Point]::new(345, 6)
    $btnClose.FlatStyle = 'Flat'
    $btnClose.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(80, 80, 80)
    $btnClose.BackColor = [System.Drawing.Color]::FromArgb(55, 55, 55)
    $btnClose.ForeColor = [System.Drawing.Color]::FromArgb(220, 220, 220)
    $btnClose.DialogResult = 'OK'

    $btnMoreInfo = New-Object System.Windows.Forms.Button
    $btnMoreInfo.Text = 'More Info...'
    $btnMoreInfo.Size = [System.Drawing.Size]::new(130, 28)
    $btnMoreInfo.Location = [System.Drawing.Point]::new(205, 6)
    $btnMoreInfo.FlatStyle = 'Flat'
    $btnMoreInfo.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(80, 80, 80)
    $btnMoreInfo.BackColor = [System.Drawing.Color]::FromArgb(55, 55, 55)
    $btnMoreInfo.ForeColor = [System.Drawing.Color]::FromArgb(220, 220, 220)
    $btnMoreInfo.Add_Click({ Open-HelpTopic 'ptz' })

    $btnPanel2 = New-Object System.Windows.Forms.Panel
    $btnPanel2.Dock = 'Bottom'
    $btnPanel2.Height = 40
    $btnPanel2.Controls.Add($btnClose)
    $btnPanel2.Controls.Add($btnMoreInfo)

    $dlg.Controls.Add($rtb)
    $dlg.Controls.Add($btnPanel2)
    $dlg.AcceptButton = $btnClose
    $dlg.CancelButton = $btnClose

    try { $dlg.TopMost = $true } catch {}
    try { $dlg.ShowDialog($script:form) | Out-Null } catch { $dlg.ShowDialog() | Out-Null }
    try { $dlg.Dispose() } catch {}
}

$script:btnAfSpeedDown.Add_Click({
        $script:afSpeed = [Math]::Max(10, $script:afSpeed - 10)
        $script:lblAfSpeed.Text = "S:$($script:afSpeed)"
        Log "AF speed: $($script:afSpeed) pulses"
    })
$script:btnAfSpeedUp.Add_Click({
        $script:afSpeed = [Math]::Min(500, $script:afSpeed + 10)
        $script:lblAfSpeed.Text = "S:$($script:afSpeed)"
        Log "AF speed: $($script:afSpeed) pulses"
    })

function Update-AfToggleUI {
    if ($script:afEnabled) {
        $script:btnAfToggle.Text = 'AF: ON'
        $script:btnAfToggle.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 0)
        $script:btnAfToggle.ForeColor = [System.Drawing.Color]::White
    }
    else {
        $script:btnAfToggle.Text = 'AF: OFF'
        $script:btnAfToggle.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
        $script:btnAfToggle.ForeColor = [System.Drawing.Color]::FromArgb(150, 150, 150)
    }
    Update-AfOverlay
}

$script:btnAfToggle.Add_Click({
        if ($script:afEnabled) {
            # Turning OFF: stop any active movement
            $script:afEnabled = $false
            $script:afRoiVisible = $false
            Reset-AfState
            Log 'Auto Frame: DISABLED'
        }
        else {
            $script:afEnabled = $true
            $script:afRoiVisible = $false
            Reset-AfState
            Log 'Auto Frame: ENABLED — click inside green ROI to centre camera'
        }
        Update-AfToggleUI
    })

$script:btnAfSetRoi.Add_Click({
        # Toggle ROI visibility for repositioning (works even when AF is off)
        $script:afRoiVisible = -not $script:afRoiVisible
        if ($script:afRoiVisible) {
            $script:btnAfSetRoi.BackColor = [System.Drawing.Color]::FromArgb(0, 130, 0)
            $script:btnAfSetRoi.ForeColor = [System.Drawing.Color]::White
            $script:btnAfSetRoi.Text = 'ROI: ON'
            Log 'Auto Frame: ROI visible — drag/resize green box, click Set ROI again to confirm'
        }
        else {
            $script:btnAfSetRoi.BackColor = [System.Drawing.Color]::FromArgb(0, 70, 110)
            $script:btnAfSetRoi.ForeColor = [System.Drawing.Color]::FromArgb(180, 230, 255)
            $script:btnAfSetRoi.Text = 'Set ROI'
            Log "Auto Frame: ROI confirmed at X=$($script:afRoi.X) Y=$($script:afRoi.Y) W=$($script:afRoi.Width) H=$($script:afRoi.Height)"
        }
        Update-AfOverlay
    })

# ---- Scene monitoring ----
$script:afSceneCheckCtr = 0

function Update-AfButtonsVisibility([bool]$show) {
    foreach ($ctl in @($script:btnAfToggle, $script:btnAfSetRoi, $script:btnAfSpeedDown, $script:lblAfSpeed, $script:btnAfSpeedUp, $script:btnAfInfo)) {
        try { if ($ctl -and -not $ctl.IsDisposed) { $ctl.Visible = $show } } catch {}
    }
    Update-AfOverlay
}

function Update-AfScene {
    try {
        $sn = Get-CurrentProgramSceneName
        $was = $script:afSceneActive
        $script:afSceneActive = ($sn -eq $script:AF_SCENE_NAME)
        if ($was -ne $script:afSceneActive) {
            if ($script:afSceneActive) {
                # Speaker scene just went live — restore AF state the user had before leaving
                # AF comes back ON with the ROI confirmed (NOT in setup mode - in setup mode clicks drag the ROI instead of centring).
                if ($script:afWasEnabled) {
                    $script:afEnabled = $true
                }
                $script:afRoiVisible = $false
                Reset-AfState
                Invoke-OnUI {
                    Update-AfButtonsVisibility $true
                    Update-AfToggleUI
                    # Set ROI button back to its normal (not in setup) look
                    $script:btnAfSetRoi.BackColor = [System.Drawing.Color]::FromArgb(0, 70, 110)
                    $script:btnAfSetRoi.ForeColor = [System.Drawing.Color]::FromArgb(180, 230, 255)
                    $script:btnAfSetRoi.Text = 'Set ROI'
                    # Restore speed label
                    try { $script:lblAfSpeed.Text = "S:$($script:afSpeed)" } catch {}
                }
                Log "Auto Frame: '$($script:AF_SCENE_NAME)' live — controls shown (AF=$($script:afEnabled) Speed=$($script:afSpeed))"
            }
            else {
                # Left Speaker scene — remember AF state, disable AF, hide controls
                $script:afWasEnabled = $script:afEnabled
                $script:afEnabled = $false
                $script:afRoiVisible = $false
                Reset-AfState
                Invoke-OnUI {
                    Update-AfButtonsVisibility $false
                    Update-AfToggleUI
                }
                Log "Auto Frame: scene '$sn' — controls hidden (AF was $($script:afWasEnabled), will restore on return)"
            }
        }
    }
    catch {}
}

# ---- AF: click-to-center pulse delivery (30 ms / pulse) ----
$script:_afPollWasDown = $false
$script:_afTimer = New-Object System.Windows.Forms.Timer
$script:_afTimer.Interval = 30
$script:_afTimer.Add_Tick({
        # Scene monitoring every ~2 s (67 × 30 ms)
        $script:afSceneCheckCtr++
        if ($script:afSceneCheckCtr -ge 67) { $script:afSceneCheckCtr = 0; Update-AfScene }

        # ---- Poll-based mouse handling for ROI interior clicks ----
        # LibVLC creates its own internal child HWND inside pLivePreview to render video, which
        # intercepts mouse messages before our WinForms MouseDown/Move/Up events ever reach it -
        # only pAfOverlay's own border/handle pixels (and pbObs in screenshot mode) reliably get
        # normal WinForms mouse events. Polling here works no matter which native window actually
        # owns the pixel under the cursor.
        if (($script:afEnabled -or $script:afRoiVisible) -and -not $script:_legacyUiHidden) {
            $leftDown = ([System.Windows.Forms.Control]::MouseButtons -band [System.Windows.Forms.MouseButtons]::Left) -ne 0
            $pt = $script:pPreview.PointToClient([System.Windows.Forms.Control]::MousePosition)
            $overPreview = $script:pPreview.ClientRectangle.Contains($pt)

            # Hover cursor feedback - forces the actual system cursor (Cursor.Current) rather than
            # setting .Cursor on a control, since libvlc's internal video HWND also swallows
            # WM_SETCURSOR the same way it swallows mouse clicks. Skipped when a real button
            # (AF/PTZ overlay controls) is topmost at this point, so their own Hand cursor wins.
            if ($overPreview) {
                $hitCtl = $script:pPreview.GetChildAtPoint($pt)
                if ($hitCtl -eq $script:pAfOverlay -or $hitCtl -eq $script:pbObs -or $hitCtl -eq $script:pLivePreview) {
                    $onHandleHover = $false
                    if ($script:afRoiVisible) { foreach ($hRect in (Get-AfHandles)) { if ($hRect.Contains($pt)) { $onHandleHover = $true; break } } }
                    if ($script:afEnabled -and -not $onHandleHover -and $script:afRoi.Contains($pt)) {
                        [System.Windows.Forms.Cursor]::Current = [System.Windows.Forms.Cursors]::Cross
                    }
                    elseif ($onHandleHover -or ($script:afRoiVisible -and $script:afRoi.Contains($pt))) {
                        [System.Windows.Forms.Cursor]::Current = [System.Windows.Forms.Cursors]::SizeAll
                    }
                    else {
                        [System.Windows.Forms.Cursor]::Current = [System.Windows.Forms.Cursors]::Default
                    }
                }
            }

            if ($leftDown -and -not $script:_afPollWasDown -and $overPreview -and -not $script:afDragging -and $script:afResizing -lt 0) {
                if ($script:afRoiVisible) {
                    $handles = Get-AfHandles
                    $onHandleIdx = -1
                    for ($i = 0; $i -lt $handles.Count; $i++) { if ($handles[$i].Contains($pt)) { $onHandleIdx = $i; break } }
                    if ($onHandleIdx -ge 0) {
                        $script:afResizing = $onHandleIdx
                        $script:afResizeOrig = $script:afRoi
                    }
                    elseif ($script:afRoi.Contains($pt)) {
                        $script:afDragging = $true
                        $script:afDragOff = New-Object System.Drawing.Point ($pt.X - $script:afRoi.X), ($pt.Y - $script:afRoi.Y)
                    }
                }
                elseif ($script:afEnabled -and $script:afRoi.Contains($pt)) {
                    $rcy3 = $script:afRoi.Y + $script:afRoi.Height / 2.0
                    $ndy = ($pt.Y - $rcy3) / ($script:afRoi.Height / 2.0)
                    $script:afPanPulses = 0
                    $script:afTiltPulses = [int][Math]::Round($ndy * $script:afSpeed)
                    $rcx3 = $script:afRoi.X + [int]($script:afRoi.Width / 2)
                    $script:afClickPt = New-Object System.Drawing.Point $rcx3, $pt.Y
                    Log "AF: centering — tilt=$($script:afTiltPulses)"
                    Update-AfOverlay
                }
            }
            elseif ($leftDown -and ($script:afDragging -or $script:afResizing -ge 0)) {
                if ($script:afResizing -ge 0 -and $script:afResizeOrig) {
                    $r = $script:afResizeOrig
                    $nx = $r.X; $ny = $r.Y; $nw = $r.Width; $nh = $r.Height
                    if ($script:afResizing -eq 0) { $nx = $pt.X; $ny = $pt.Y; $nw = $r.Right - $pt.X; $nh = $r.Bottom - $pt.Y }
                    if ($script:afResizing -eq 1) { $ny = $pt.Y; $nw = $pt.X - $r.Left; $nh = $r.Bottom - $pt.Y }
                    if ($script:afResizing -eq 2) { $nx = $pt.X; $nw = $r.Right - $pt.X; $nh = $pt.Y - $r.Top }
                    if ($script:afResizing -eq 3) { $nw = $pt.X - $r.Left; $nh = $pt.Y - $r.Top }
                    if ($nw -gt 40 -and $nh -gt 40) { $script:afRoi = (_AFRect $nx $ny $nw $nh) }
                    Update-AfOverlay
                }
                elseif ($script:afDragging -and $script:afDragOff) {
                    $pw = $script:pPreview.Width; $ph = $script:pPreview.Height
                    $nx = [Math]::Max(0, [Math]::Min($pt.X - $script:afDragOff.X, $pw - $script:afRoi.Width))
                    $ny = [Math]::Max(0, [Math]::Min($pt.Y - $script:afDragOff.Y, $ph - $script:afRoi.Height))
                    $script:afRoi = (_AFRect $nx $ny $script:afRoi.Width $script:afRoi.Height)
                    Update-AfOverlay
                }
            }
            elseif (-not $leftDown -and $script:_afPollWasDown) {
                $script:afDragging = $false
                $script:afResizing = -1
                $script:afDragOff = $null
                $script:afResizeOrig = $null
            }
            $script:_afPollWasDown = $leftDown
        }

        if (-not $script:afEnabled -or -not $script:ObsConnected) { return }
        # Send one PTZ pulse per tick — tilt only (pan disabled)
        if ($script:afTiltPulses -gt 0) { Send-OBSHotkeyKey 'OBS_KEY_DOWN'; $script:afTiltPulses-- }
        elseif ($script:afTiltPulses -lt 0) { Send-OBSHotkeyKey 'OBS_KEY_UP'; $script:afTiltPulses++ }
        Update-AfOverlay
    })
$script:_afTimer.Start()

