# --- Click behavior: manual nudge + (dis)connect ---
$btnObsConnect.Add_Click({
        try {
            if (-not $script:ObsConnected) {
                # OBS is not running on this PC: start it (the 2 s auto-connect timer connects once it is up)
                if (-not (Test-ObsProcessRunning -MaxAgeMs 0)) {
                    if (Start-ObsApp) {
                        try {
                            if ($script:lblHint) {
                                $script:lblHint.Text = "Starting OBS..."
                                $script:lblHint.Visible = $true
                            }
                        }
                        catch {}
                    }
                    return
                }

                # Guard against racing with the 2s auto-reconnect timer (audit fix #5):
                # if an auto-connect attempt is already in flight, ignore this manual click
                # rather than calling Connect-Obs concurrently (which could corrupt $script:ObsWS).
                if ($script:_connectInProgress) { return }

                # Try an immediate manual connect
                $ok = $false
                $script:_connectInProgress = $true
                try { $ok = Connect-Obs } catch {}
                finally { $script:_connectInProgress = $false }
                if ($ok) {
                    Set-ObsStatusIndicator $true "online"
                    try { if ($script:lblHint) { $script:lblHint.Visible = $false } } catch {}
                }
                else {
                    Set-ObsStatusIndicator $false "connect failed"
                    try {
                        if ($script:lblHint) {
                            $script:lblHint.Text = "Waiting for OBS..."
                            $script:lblHint.Visible = $true
                        }
                    }
                    catch {}
                }
            }
            else {
                # Manual disconnect
                try { Close-Obs } catch {}
                Set-ObsStatusIndicator $false "disconnected"
                try {
                    if ($script:lblHint) {
                        $script:lblHint.Text = "Waiting for OBS..."
                        $script:lblHint.Visible = $true
                    }
                }
                catch {}
            }
        }
        catch {}
    })

