    $lblNote = New-Object System.Windows.Forms.Label
    $lblNote.Text = "The report will be saved to your Desktop."
    $lblNote.AutoSize = $true
    $lblNote.ForeColor = [System.Drawing.Color]::DimGray
    $lblNote.Location = [System.Drawing.Point]::new(12, 14)
    $bp.Controls.Add($lblNote)

    $btnOK = New-Object System.Windows.Forms.Button
    $btnOK.Text = "Save Report"
    $btnOK.Size = [System.Drawing.Size]::new(120, 28)
    $btnOK.Location = [System.Drawing.Point]::new(430, 9)
    $btnOK.BackColor = [System.Drawing.Color]::FromArgb(180, 40, 40)
    $btnOK.ForeColor = [System.Drawing.Color]::White
    $btnOK.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnOK.FlatAppearance.BorderSize = 0
    $btnOK.Add_Click({
            if ([string]::IsNullOrWhiteSpace($txtDesc.Text)) {
                [System.Windows.Forms.MessageBox]::Show($frm, "Please describe the problem before saving.", "Missing Info", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::None) | Out-Null
                return
            }

            # Collect system info
            $osInfo = try { (Get-CimInstance Win32_OperatingSystem -ErrorAction Stop | Select-Object -First 1).Caption } catch { "Unknown OS" }
            $psVer = $PSVersionTable.PSVersion.ToString()
            $appVer = try { [string]$script:APP_VERSION } catch { "N/A" }
            $stamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
            $logSnap = try { ($script:LogBuffer | Select-Object -Last 300) -join "`r`n" } catch { "(no log available)" }

            $report = @"
JWL+OBS ASSISTANT — BUG REPORT
================================
Date/Time : $stamp
App Version: $appVer
OS         : $osInfo
PowerShell : $psVer

--- PROBLEM DESCRIPTION ---
$($txtDesc.Text.Trim())

--- HARDWARE SETUP ---
$($txtHW.Text.Trim())

--- APPLICATION LOG (last 300 lines) ---
$logSnap
"@

            $desktop = [System.Environment]::GetFolderPath('Desktop')
            $fileName = "JWL-OBS-BugReport_$(Get-Date -Format 'yyyyMMdd_HHmmss').txt"
            $filePath = Join-Path $desktop $fileName

            try {
                [System.IO.File]::WriteAllText($filePath, $report, [System.Text.Encoding]::UTF8)
            }
            catch {
                [System.Windows.Forms.MessageBox]::Show($frm, "Could not save report file:`n$_", "Save Error", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::None) | Out-Null
                return
            }

            $instrMsg = @"
Your bug report has been saved to your Desktop:

  $fileName

Please send it by email to:

  mvpapen@gmail.com

Steps:
  1. Open your email client.
  2. Create a new email to  mvpapen@gmail.com
  3. Attach the file from your Desktop.
  4. Optionally add a short subject line, e.g. 'JWL+OBS Bug Report'.
  5. Send!

Thank you for helping improve the app.
"@
            [System.Windows.Forms.MessageBox]::Show($frm, $instrMsg, "Report Saved", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::None) | Out-Null
            $frm.Close()
        })
    $bp.Controls.Add($btnOK)

    $btnCancel = New-Object System.Windows.Forms.Button
    $btnCancel.Text = "Cancel"
    $btnCancel.Size = [System.Drawing.Size]::new(90, 28)
    $btnCancel.Location = [System.Drawing.Point]::new(562, 9)
    $btnCancel.Add_Click({ $frm.Close() })
    $frm.CancelButton = $btnCancel
    $bp.Controls.Add($btnCancel)

    $frm.Show($OwnerForm)
    while ($frm.Visible) {
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 30
    }
    $frm.Dispose()
}

# ---- Local HTML Help Center ----
# Opens a topic page (Help\pages\$Key.html) in the user's default browser, falling back to the
# Help Center's start page if that specific topic doesn't exist yet - lets pages be added
# incrementally without ever breaking the "More Info" button. No embedded browser control or
# internet connection required, just static files shipped alongside the app (see Help\ folder).
function Open-HelpTopic([string]$Key = '') {
    try {
        $helpDir = Join-Path (Split-Path -Path $scriptPath) 'Help'
        $target = if ($Key) { Join-Path $helpDir "pages\$Key.html" } else { $null }
        if (-not $target -or -not (Test-Path $target)) { $target = Join-Path $helpDir 'index.html' }
        if (-not (Test-Path $target)) {
            [System.Windows.Forms.MessageBox]::Show($script:form, "Help files not found. Expected folder:`n$helpDir", 'Help', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
            return
        }
        # Local .html files can hit a broken/missing file-type association even when the
        # system has a perfectly good default browser for regular web links (confirmed on
        # a real machine: https:// links opened Brave fine, but Start-Process on the local
        # .html path/file:// URI triggered Windows' "Open With" chooser instead). So resolve
        # the SAME browser Windows uses for http/https via the registry and launch it
        # directly with the file path, sidestepping the local-file association entirely.
        $browserExe = $null
        try {
            $progId = (Get-ItemProperty 'HKCU:\SOFTWARE\Microsoft\Windows\Shell\Associations\UrlAssociations\https\UserChoice' -ErrorAction Stop).ProgId
            if ($progId) {
                $cmd = (Get-ItemProperty "Registry::HKEY_CLASSES_ROOT\$progId\shell\open\command" -ErrorAction Stop).'(default)'
                if ($cmd -match '"([^"]+\.exe)"') { $browserExe = $Matches[1] }
                elseif ($cmd -match '^(\S+\.exe)') { $browserExe = $Matches[1] }
            }
        }
        catch {}
        if ($browserExe -and (Test-Path $browserExe)) {
            Start-Process -FilePath $browserExe -ArgumentList "`"$target`""
        }
        else {
            Start-Process $target
        }
    }
    catch { Log "Open-HelpTopic error: $_" }
}

function Show-InfoPopup {
    param([string]$Title, [string]$Key, [string]$DefaultText,
        [System.Windows.Forms.Form]$Owner = $null)

    $popup = New-Object System.Windows.Forms.Form
    $popup.Text = $Title
    $popup.Size = [System.Drawing.Size]::new(650, 720)
    $popup.MinimumSize = [System.Drawing.Size]::new(500, 400)
    $popup.MinimizeBox = $false
    $popup.MaximizeBox = $true
    $popup.FormBorderStyle = 'Sizable'
    # TopMost=true so the popup appears above the modal settings dialog (which keeps all
    # non-owned windows behind it). Owner is NOT set — Owner inside ShowDialog() freezes.
    $popup.TopMost = $true
    $refWin = if ($Owner -and -not $Owner.IsDisposed) { $Owner } `
        elseif ($script:form -and -not $script:form.IsDisposed) { $script:form } `
        else { $null }
    if ($refWin) {
        $scr = [System.Windows.Forms.Screen]::FromControl($refWin).WorkingArea
        $x = [int]($refWin.Bounds.X + ($refWin.Bounds.Width - 650) / 2)
        $y = [int]($refWin.Bounds.Y + ($refWin.Bounds.Height - 720) / 2)
        $x = [math]::Max($scr.X, [math]::Min($x, $scr.Right - 650))
        $y = [math]::Max($scr.Y, [math]::Min($y, $scr.Bottom - 720))
        $popup.StartPosition = 'Manual'
        $popup.Location = [System.Drawing.Point]::new($x, $y)
    }
    else {
        $popup.StartPosition = 'CenterScreen'
    }

    $btnPanel = New-Object System.Windows.Forms.Panel
    $btnPanel.Dock = 'Bottom'
    $btnPanel.Height = 40
    $popup.Controls.Add($btnPanel)

    $tb = New-Object System.Windows.Forms.TextBox
    $tb.Multiline = $true
    $tb.ScrollBars = 'Vertical'
    $tb.ReadOnly = $true
    $tb.Font = New-Object System.Drawing.Font('Segoe UI', 10)
    $tb.Text = $DefaultText
    $tb.Dock = 'Fill'
    $tb.BackColor = [System.Drawing.Color]::White
    $tb.BorderStyle = [System.Windows.Forms.BorderStyle]::None
    $popup.Controls.Add($tb)

    $btnClose = New-Object System.Windows.Forms.Button
    $btnClose.Text = 'Close'
    $btnClose.Size = [System.Drawing.Size]::new(100, 28)
    $btnClose.Location = [System.Drawing.Point]::new(345, 6)
    $btnClose.Add_Click({ param($s, $e) try { $s.FindForm().Close() } catch {} })
    $popup.AcceptButton = $btnClose
    $popup.CancelButton = $btnClose
    $btnPanel.Controls.Add($btnClose)

    $btnMoreInfo = New-Object System.Windows.Forms.Button
    $btnMoreInfo.Text = 'More Info...'
    $btnMoreInfo.Size = [System.Drawing.Size]::new(130, 28)
    $btnMoreInfo.Location = [System.Drawing.Point]::new(205, 6)
    $btnMoreInfo.Add_Click({ Open-HelpTopic $Key }.GetNewClosure())
    $btnPanel.Controls.Add($btnMoreInfo)

    # Script-scope ref keeps the popup alive and accessible after this function returns
    $script:_infoPopupRef = $popup
    $popup.Add_FormClosed({ param($s, $e) $script:_infoPopupRef = $null })

    # Non-blocking: Show() and return immediately. TopMost keeps it above non-TopMost windows.
    # A 1ms timer re-activates the popup after the click handler returns (at which point
    # the TopMost settings dialog would otherwise steal focus and cover the popup).
    $popup.Show()
    $script:_infoRaTimer = New-Object System.Windows.Forms.Timer
    $script:_infoRaTimer.Interval = 1
    $script:_infoRaTimer.Add_Tick({
            $script:_infoRaTimer.Stop(); $script:_infoRaTimer.Dispose(); $script:_infoRaTimer = $null
            try { if ($script:_infoPopupRef -and -not $script:_infoPopupRef.IsDisposed -and $script:_infoPopupRef.Visible) { $script:_infoPopupRef.Activate() } } catch {}
        })
    $script:_infoRaTimer.Start()
}

# Show-CenteredDialog: non-blocking OK / YesNo dialog centered over the app.
# - App remains fully usable while dialog is visible (Show + DoEvents, not ShowDialog).
# - Auto-closes after $AutoCloseSeconds with the safe default (OK / No).
# - Countdown shown in button label so user knows it will dismiss itself.
function Show-CenteredDialog {
    param(
        [string]$Text,
        [string]$Title = 'JWL Assistant',
        [System.Windows.Forms.MessageBoxButtons]$Buttons = [System.Windows.Forms.MessageBoxButtons]::OK,
        [System.Windows.Forms.MessageBoxIcon]$Icon = [System.Windows.Forms.MessageBoxIcon]::Information,
        [System.Windows.Forms.Form]$Parent = $null,
        [int]$AutoCloseSeconds = 10
    )
    $refWin = if ($Parent -and -not $Parent.IsDisposed) { $Parent } `
        elseif ($script:form -and -not $script:form.IsDisposed) { $script:form } `
        else { $null }
    $fw = 440; $fh = 185
    $f = New-Object System.Windows.Forms.Form
    $f.Text = $Title
    $f.Size = [System.Drawing.Size]::new($fw, $fh)
    $f.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
    $f.MinimizeBox = $false; $f.MaximizeBox = $false; $f.ShowInTaskbar = $false
    $f.StartPosition = 'Manual'
    if ($refWin) {
        $f.Owner = $refWin   # owned window stays above its owner automatically
        $scr = [System.Windows.Forms.Screen]::FromControl($refWin).WorkingArea
        $x = [int]($refWin.Bounds.X + ($refWin.Bounds.Width - $fw) / 2)
        $y = [int]($refWin.Bounds.Y + ($refWin.Bounds.Height - $fh) / 2)
        $x = [math]::Max($scr.X, [math]::Min($x, $scr.Right - $fw))
        $y = [math]::Max($scr.Y, [math]::Min($y, $scr.Bottom - $fh))
        $f.Location = [System.Drawing.Point]::new($x, $y)
    }
    else {
        $f.Location = [System.Drawing.Point]::new(100, 100)
    }

    $lbl = New-Object System.Windows.Forms.Label
    $lbl.Text = $Text
    $lbl.Font = New-Object System.Drawing.Font('Segoe UI', 10)
    $lbl.Location = [System.Drawing.Point]::new(16, 16)
    $lbl.Size = [System.Drawing.Size]::new($fw - 32, 95)
    $f.Controls.Add($lbl)

    # Shared state via hashtable so all closures see the same data
    $state = @{ Result = 'None'; SecsLeft = $AutoCloseSeconds; Btn1 = $null; Btn2 = $null }
    $isYesNo = ([string]$Buttons -eq 'YesNo')
    $btnY = 118

    if ($isYesNo) {
        $bN = New-Object System.Windows.Forms.Button
        $bN.Text = "No ($AutoCloseSeconds)"; $bN.Size = Sz 110 30; $bN.Location = Pt 235 $btnY
        $bN.Add_Click({ $state.Result = 'No'; $f.Close() })
        $bY = New-Object System.Windows.Forms.Button
        $bY.Text = 'Yes'; $bY.Size = Sz 90 30; $bY.Location = Pt 135 $btnY
        $bY.Add_Click({ $state.Result = 'Yes'; $f.Close() })
        $f.Controls.Add($bN); $f.Controls.Add($bY)
        $f.CancelButton = $bN
        $state.Btn1 = $bN   # countdown on No (safe default)
    }
    else {
        $bO = New-Object System.Windows.Forms.Button
        $bO.Text = "OK ($AutoCloseSeconds)"; $bO.Size = Sz 110 30; $bO.Location = Pt 165 $btnY
        $bO.Add_Click({ $state.Result = 'OK'; $f.Close() })
        $f.Controls.Add($bO)
        $f.AcceptButton = $bO; $f.CancelButton = $bO
        $state.Btn1 = $bO   # countdown on OK
    }

    # 1-second countdown timer — updates button label, auto-closes on zero
    $cdTimer = New-Object System.Windows.Forms.Timer
    $cdTimer.Interval = 1000
    $cdTimer.Add_Tick({
            $state.SecsLeft--
            if ($state.Btn1 -and -not $f.IsDisposed) {
                $label = if ($isYesNo) { "No" } else { "OK" }
                $state.Btn1.Text = if ($state.SecsLeft -gt 0) { "$label ($($state.SecsLeft))" } else { $label }
            }
            if ($state.SecsLeft -le 0) { $cdTimer.Stop(); if (-not $f.IsDisposed) { $f.Close() } }
        })
    $cdTimer.Start()

    $f.Show()
    while ($f.Visible) {
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 30
    }
    $cdTimer.Stop(); $cdTimer.Dispose()
    $f.Dispose()

    # Map string result to DialogResult
    switch ($state.Result) {
        'Yes' { return [System.Windows.Forms.DialogResult]::Yes }
        'No' { return [System.Windows.Forms.DialogResult]::No }
        default { return [System.Windows.Forms.DialogResult]::OK }
    }
}

function Show-ZoomAutoToggleWarning {
    param([switch]$Silent)  # When $Silent, fix state quietly without showing a dialog
    try {
        # Guard FIRST — set before any early returns so re-entrancy is impossible
        if ($script:_zoomWarningShownThisToggle) { return }
        $script:_zoomWarningShownThisToggle = $true

        # Only act if we have a Zoom participant and know current mic/camera state
        if (-not $script:ZoomParticipantFound) { return }

        $micOff = ($script:ZoomMicStatus -eq $false)
        $camOff = ($script:ZoomCameraStatus -eq $false)

        if (-not ($micOff -or $camOff)) { return }

        if ($Silent) {
            # Auto-start path: fix state silently, no dialog blocking the countdown
            Log "Auto Toggle: Zoom mic muted=$micOff, camera off=$camOff — correcting silently"
            if ($micOff) {
                try {
                    [void](Enable-ZoomAudioIfMuted)
                    $script:ZoomMicStatus = $true
                    $status = @{ MicOn = $true; CameraOn = $script:ZoomCameraStatus; Found = $true }
                    try { Update-ZoomStatusIcons $status } catch {}
                }
                catch {}
            }
            if ($camOff) {
                try {
                    if (Enable-ZoomCamera) {
                        $script:ZoomCameraStatus = $true
                        $status = @{ MicOn = $script:ZoomMicStatus; CameraOn = $true; Found = $true }
                        try { Update-ZoomStatusIcons $status } catch {}
                    }
                }
                catch {}
            }
            return
        }

        $msg = "Check Zoom Mic and Zoom Camera!`r`n`r`n" +
        "Zoom Mic is currently " + ($(if ($micOff) { 'MUTED' } else { 'ON' })) +
        " and Zoom Camera is " + ($(if ($camOff) { 'OFF' } else { 'ON' })) + ".`r`n`r`n" +
        "Auto mode will still run. Do you want to unmute mic and turn camera on now?`r`n`r`n" +
        "Yes = Unmute/turn camera on now`r`n" +
        "No  = Keep current Zoom state (for pre-meeting checks)."

        $res = Show-AppMessageBox $msg "Zoom Auto Toggle" ([System.Windows.Forms.MessageBoxButtons]::YesNo) ([System.Windows.Forms.MessageBoxIcon]::Warning)

        if ($res -eq [System.Windows.Forms.DialogResult]::Yes) {
            if ($micOff) {
                try {
                    [void](Enable-ZoomAudioIfMuted)
                    $script:ZoomMicStatus = $true
                    $status = @{ MicOn = $true; CameraOn = $script:ZoomCameraStatus; Found = $true }
                    try { Update-ZoomStatusIcons $status } catch {}
                }
                catch {}
            }
            if ($camOff) {
                try {
                    if (Enable-ZoomCamera) {
                        $script:ZoomCameraStatus = $true
                        $status = @{ MicOn = $script:ZoomMicStatus; CameraOn = $true; Found = $true }
                        try { Update-ZoomStatusIcons $status } catch {}
                    }
                }
                catch {}
            }
        }
    }
    catch {
        Log "Zoom Auto Toggle warning error: $_"
    }
}

# Parse entries like: "Thu 19:00", "Sun 10:00", case-insensitive, optional seconds "19:00:00"
function Get-WeeklyMeetingStartTimes {
    $out = @()
    foreach ($line in @($script:Cfg.Meeting.Lines)) {
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        # Expected: Ddd HH:mm[:ss]
        if ($line -match '^(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\s+(\d{1,2}:\d{2}(:\d{2})?)$') {
            $dow = $matches[1]
            $tod = $matches[2]
            # Compute next occurrence this week (today or future), in local time
            $now = Get-Date
            # Map Ddd -> 0..6
            $map = @{Sun = 0; Mon = 1; Tue = 2; Wed = 3; Thu = 4; Fri = 5; Sat = 6 }
            $target = $map[$dow]
            $delta = ($target - [int]$now.DayOfWeek + 7) % 7
            $date = $now.Date.AddDays($delta)
            $ts = [TimeSpan]::Parse($tod)
            $start = $date + $ts
            # If it's today but time already passed, bump 7 days
            if ($delta -eq 0 -and $start -lt $now) { $start = $start.AddDays(7) }
            $out += $start
        }
    }
    # Return sorted upcoming starts (this week/next)
    $out | Sort-Object
}

# Compute the next meeting window and update $lblNext
function Update-NextMeetingLabelAndWindow {
    try {
        $starts = Get-WeeklyMeetingStartTimes
        if (-not $starts -or $starts.Count -eq 0) {
            $lblNext.Text = "Next: —"
            return $null
        }
        # Next start is the soonest in the future
        $nextStart = $starts | Select-Object -First 1
        $lblNext.Text = "Next: " + $nextStart.ToString("ddd HH:mm:ss")

        $leadMin = [int]$script:Cfg.Meeting.GuardLeadMinutes
        $durMin = [int]$script:Cfg.Meeting.GuardMinutes
        if ($leadMin -lt 0) { $leadMin = 0 }
        if ($durMin -le 0) { $durMin = 95 }

        $guardStart = $nextStart.AddMinutes(-$leadMin)
        $guardEnd = $nextStart.AddMinutes($durMin)

        return [pscustomobject]@{
            Start = $guardStart
            End   = $guardEnd
        }
    }
    catch {
        return $null
    }
}

# Start the guard if we're within a computed window; otherwise stop it.
function Invoke-AutoMeetingGuardCheck {
    try {
        if (-not $script:Cfg.Meeting.AutoGuard) { return }

        $win = Update-NextMeetingLabelAndWindow
        if (-not $win) { Stop-MeetingGuard; return }

        $now = Get-Date
        if ($now -ge $win.Start -and $now -lt $win.End) {
            # Inside window → guard until End
            $script:MeetingGuardUntil = $win.End
            try { $meetingTickTimer.Start() } catch {}
            # If music is playing, fade/stop it now
            try {
                if (Test-MusicIsPlaying) {
                    $ms = [int]($script:Music.FadeOutSeconds * 1000)
                    Stop-MusicFade -ms $ms -StopAfter $true
                    Log "Background music auto-stopped for Meeting Mode."
                }
            }
            catch {}
        }
        else {
            # Outside window → no guard
            Stop-MeetingGuard
        }
    }
    catch {}
}

# Run auto-guard check every 30s (plus once at startup)
$autoGuardTimer = New-Object System.Windows.Forms.Timer
$autoGuardTimer.Interval = 30000
$autoGuardTimer.Add_Tick({ 
        if ($script:ShuttingDown) { return }
        try { Invoke-AutoMeetingGuardCheck } catch {}
    })
$autoGuardTimer.Start()
Invoke-AutoMeetingGuardCheck

