# ---------- Gear Settings button (bottom-right, sticky) ----------
# Pre-compile Add-Type helpers at script load time so Show-SettingsDialog opens without delay.
# PanelWheelRouter — routes WM_MOUSEWHEEL to the scrollable settings panel
if (-not ([System.Management.Automation.PSTypeName]'PanelWheelRouter').Type) {
    $__wfAssemblies = @('System.Windows.Forms', 'System.Drawing')
    foreach ($__asm in @('System.Windows.Forms.Primitives', 'System.Drawing.Primitives', 'System.ComponentModel.Primitives')) {
        try { [void][System.Reflection.Assembly]::Load($__asm); $__wfAssemblies += $__asm } catch {}
    }
    Add-Type -ReferencedAssemblies $__wfAssemblies -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using System.Drawing;
public class PanelWheelRouter : IMessageFilter {
    private Panel _panel;
    private const int WM_MOUSEWHEEL = 0x020A;
    [DllImport("user32.dll")] static extern IntPtr SendMessage(IntPtr h, int msg, IntPtr w, IntPtr l);
    public PanelWheelRouter(Panel p) { _panel = p; }
    public bool PreFilterMessage(ref Message m) {
        if (m.Msg != WM_MOUSEWHEEL) return false;
        Point cur = Control.MousePosition;
        Point panelScreen = _panel.PointToScreen(Point.Empty);
        Rectangle r = new Rectangle(panelScreen, _panel.ClientSize);
        if (!r.Contains(cur)) return false;
        SendMessage(_panel.Handle, WM_MOUSEWHEEL, m.WParam, m.LParam);
        return true;
    }
}
"@
}
# ===== Monitor/DPI services (WPF-migration Phase 1 note, no behavior change) =====
# Five DPI/monitor representations coexist in this app today (flagged as the #2 migration risk
# in WPF-Migration-Planning-Audit.md). This file does not unify their math yet - that needs real
# mixed-DPI hardware testing - but documenting which one to use where is a safe Phase 1 step:
#   1. WinForms automatic DPI  - $script:form.AutoScaleMode = 'Dpi' (main window auto-layout).
#   2. Custom app UI scale     - Set-UIScale / $script:_currentUIScale (user S/M/L zoom, not OS DPI).
#   3. Physical-pixel ROI      - Get-DpiScaleFactor + Get-RoiRect (OCR capture coordinates).
#   4. Per-monitor Win32 query - RoiScreen (below): accurate per-monitor DPI via EnumDisplayMonitors/
#                                 GetDpiForMonitor; used by ROI picker and Get-HandAlertScreen because
#                                 WinForms' Screen class only reports the calling thread's DPI context.
#   5. WPF DIPs                - Hand Alert overlay (New-HandAlertWindow) converts RoiScreen's physical
#                                 pixels to WPF device-independent units manually.
# A future WPF shell should standardize on DIPs + per-monitor awareness and convert to physical
# pixels only at OS/screen-capture boundaries (RoiScreen already models that boundary correctly).
# DpiHelper — optional helper for thread DPI context switches
if (-not ([System.Management.Automation.PSTypeName]'DpiHelper').Type) {
    Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class DpiHelper {
    [DllImport("user32.dll")] public static extern IntPtr SetThreadDpiAwarenessContext(IntPtr ctx);
}
"@
}

# --- BEGIN RoiScreen ---
# ROI coordinates are stored in PHYSICAL virtual-screen pixels. Every call that reads cursor/monitor/screen
# pixels switches the calling thread to Per-Monitor-V2 first, so the result no longer depends on how the
# host (pwsh / powershell / ps2exe) happens to be DPI-aware and no scale factor is ever needed.
if (-not ([System.Management.Automation.PSTypeName]'RoiScreen').Type) {
    $__roiAsm = @('System.Windows.Forms', 'System.Drawing')
    foreach ($__a in @('System.Windows.Forms.Primitives', 'System.Drawing.Primitives', 'System.ComponentModel.Primitives', 'System.Collections', 'System.Drawing.Common', 'System.Threading.Thread', 'System.Private.Windows.Core', 'System.Private.Windows.GdiPlus')) {
        try { [void][System.Reflection.Assembly]::Load($__a); $__roiAsm += $__a } catch {}
    }
    Add-Type -ReferencedAssemblies $__roiAsm -TypeDefinition @"
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Runtime.InteropServices;
using System.Text;
using System.Windows.Forms;

public class RoiMonitor {
    public string Name;
    public Rectangle Bounds;
    public bool Primary;
    public int Dpi;
}

public static class RoiScreen {
    [StructLayout(LayoutKind.Sequential)]
    struct RECT { public int Left, Top, Right, Bottom; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    struct MONITORINFOEX {
        public int cbSize; public RECT rcMonitor; public RECT rcWork; public uint dwFlags;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string szDevice;
    }
    delegate bool MonitorEnumProc(IntPtr hMon, IntPtr hdc, ref RECT rc, IntPtr data);
    [DllImport("user32.dll")] static extern IntPtr SetThreadDpiAwarenessContext(IntPtr ctx);
    [DllImport("user32.dll")] static extern bool EnumDisplayMonitors(IntPtr hdc, IntPtr clip, MonitorEnumProc cb, IntPtr data);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern bool GetMonitorInfoW(IntPtr h, ref MONITORINFOEX mi);
    [DllImport("shcore.dll")] static extern int GetDpiForMonitor(IntPtr h, int type, out uint x, out uint y);

    // Returns the previous context (IntPtr.Zero if the switch is unsupported); pass it to Leave().
    public static IntPtr Enter() {
        try { return SetThreadDpiAwarenessContext(new IntPtr(-4)); } catch { return IntPtr.Zero; }
    }
    public static void Leave(IntPtr prev) {
        if (prev == IntPtr.Zero) return;
        try { SetThreadDpiAwarenessContext(prev); } catch { }
    }

    public static List<RoiMonitor> Monitors() {
        List<RoiMonitor> list = new List<RoiMonitor>();
        IntPtr prev = Enter();
        try {
            MonitorEnumProc cb = delegate(IntPtr h, IntPtr hdc, ref RECT rc, IntPtr d) {
                MONITORINFOEX mi = new MONITORINFOEX();
                mi.cbSize = Marshal.SizeOf(typeof(MONITORINFOEX));
                if (GetMonitorInfoW(h, ref mi)) {
                    RoiMonitor m = new RoiMonitor();
                    m.Name = mi.szDevice;
                    m.Bounds = Rectangle.FromLTRB(mi.rcMonitor.Left, mi.rcMonitor.Top, mi.rcMonitor.Right, mi.rcMonitor.Bottom);
                    m.Primary = (mi.dwFlags & 1) != 0;
                    uint dx = 96, dy = 96;
                    try { GetDpiForMonitor(h, 0, out dx, out dy); } catch { }
                    m.Dpi = (int)dx;
                    list.Add(m);
                }
                return true;
            };
            EnumDisplayMonitors(IntPtr.Zero, IntPtr.Zero, cb, IntPtr.Zero);
            GC.KeepAlive(cb);
        }
        finally { Leave(prev); }
        return list;
    }

    public static Rectangle VirtualScreen() {
        Rectangle r = Rectangle.Empty;
        foreach (RoiMonitor m in Monitors()) r = r.IsEmpty ? m.Bounds : Rectangle.Union(r, m.Bounds);
        return r;
    }

    public static string Describe() {
        StringBuilder sb = new StringBuilder();
        foreach (RoiMonitor m in Monitors())
            sb.Append(m.Name + " " + m.Bounds.X + "," + m.Bounds.Y + " " + m.Bounds.Width + "x" + m.Bounds.Height + " dpi=" + m.Dpi + (m.Primary ? " (primary)" : "") + "; ");
        return sb.ToString();
    }

    // Copies a physical-pixel screen rectangle. Throws if the screen DC is unavailable.
    public static Bitmap Capture(Rectangle r) {
        IntPtr prev = Enter();
        Bitmap bmp = null;
        try {
            bmp = new Bitmap(r.Width, r.Height);
            using (Graphics g = Graphics.FromImage(bmp)) { g.CopyFromScreen(r.Location, Point.Empty, r.Size); }
            return bmp;
        }
        catch { if (bmp != null) bmp.Dispose(); throw; }
        finally { Leave(prev); }
    }
}

// Full-virtual-screen dim overlay: drag a rectangle, release to accept, Esc / right-click to cancel.
public class RoiPickerForm : Form {
    [StructLayout(LayoutKind.Sequential)]
    struct POINT { public int X, Y; }
    [DllImport("user32.dll")] static extern bool GetCursorPos(out POINT p);
    [DllImport("user32.dll")] static extern bool ClientToScreen(IntPtr h, ref POINT p);
    [DllImport("user32.dll")] static extern bool SetWindowPos(IntPtr h, IntPtr after, int x, int y, int cx, int cy, uint flags);

    public Rectangle Result = Rectangle.Empty;
    public bool Picked;
    Rectangle _area; string _hint; Point _hintAt;
    bool _drag; Point _a, _b;

    public RoiPickerForm(Rectangle area, string hint, Point hintAt) {
        _area = area; _hint = hint; _hintAt = hintAt;
        SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer, true);
        AutoScaleMode = AutoScaleMode.None;
        FormBorderStyle = FormBorderStyle.None;
        StartPosition = FormStartPosition.Manual;
        ShowInTaskbar = false; TopMost = true;
        BackColor = Color.Black; Opacity = 0.4;
        Cursor = Cursors.Cross; KeyPreview = true;
        Bounds = area;
    }

    // Shows the overlay and pumps messages until it closes. Returns Rectangle.Empty when cancelled.
    public Rectangle Run() {
        Show();
        SetWindowPos(Handle, new IntPtr(-1), _area.X, _area.Y, _area.Width, _area.Height, 0x40);
        Activate(); Focus();
        while (!IsDisposed && Visible) { Application.DoEvents(); System.Threading.Thread.Sleep(10); }
        return Picked ? Result : Rectangle.Empty;
    }

    static Point Cur() { POINT p; GetCursorPos(out p); return new Point(p.X, p.Y); }
    static Rectangle Norm(Point a, Point b) {
        return Rectangle.FromLTRB(Math.Min(a.X, b.X), Math.Min(a.Y, b.Y), Math.Max(a.X, b.X), Math.Max(a.Y, b.Y));
    }
    Point Origin() { POINT o = new POINT(); ClientToScreen(Handle, ref o); return new Point(o.X, o.Y); }
    void InvalidateScreenRect(Rectangle sr) {
        Point o = Origin();
        Rectangle cr = new Rectangle(sr.X - o.X, sr.Y - o.Y, sr.Width, sr.Height);
        cr.Inflate(80, 80);
        Invalidate(cr);
    }

    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.Clear(BackColor);
        Point o = Origin();
        if (_drag) {
            Rectangle r = Norm(_a, _b);
            Rectangle cr = new Rectangle(r.X - o.X, r.Y - o.Y, r.Width, r.Height);
            g.FillRectangle(Brushes.White, cr);
            using (Pen p = new Pen(Color.Red, 3)) g.DrawRectangle(p, cr);
            using (Font f = new Font("Segoe UI", 12, FontStyle.Bold))
                g.DrawString(r.Width + " x " + r.Height, f, Brushes.Yellow, cr.X, cr.Bottom + 6);
        }
        if (!string.IsNullOrEmpty(_hint)) {
            using (Font f = new Font("Segoe UI", 16, FontStyle.Bold))
                g.DrawString(_hint, f, Brushes.White, _hintAt.X - o.X, _hintAt.Y - o.Y);
        }
    }
    protected override void OnMouseDown(MouseEventArgs e) {
        if (e.Button == MouseButtons.Left) { _a = _b = Cur(); _drag = true; Invalidate(); }
        else if (e.Button == MouseButtons.Right) { Picked = false; Close(); }
    }
    protected override void OnMouseMove(MouseEventArgs e) {
        if (!_drag) return;
        Rectangle old = Norm(_a, _b);
        _b = Cur();
        InvalidateScreenRect(Rectangle.Union(old, Norm(_a, _b)));
    }
    protected override void OnMouseUp(MouseEventArgs e) {
        if (!_drag || e.Button != MouseButtons.Left) return;
        _drag = false; _b = Cur();
        Rectangle r = Norm(_a, _b);
        if (r.Width >= 8 && r.Height >= 8) { Result = r; Picked = true; Close(); }
        else Invalidate();
    }
    protected override void OnKeyDown(KeyEventArgs e) {
        if (e.KeyCode == Keys.Escape) { Picked = false; Close(); }
        base.OnKeyDown(e);
    }
    protected override void WndProc(ref Message m) {
        if (m.Msg == 0x02E0) return;   // WM_DPICHANGED: keep the overlay exactly on the virtual screen
        base.WndProc(ref m);
    }
}
"@
}
# --- END RoiScreen ---

$script:_settingsDialogBusy = $false   # Guard: prevents opening multiple settings dialogs

function Step-SettingsPump {
    # Called between sections while the Settings dialog is built. Pumping messages there lets every queued timer and
    # scan-completion run in the middle of the build, which made opening Settings take many seconds. With the new UI
    # and the live camera preview nothing needs pumping (the video is drawn by its own window and the gear spins on
    # WPF's render thread), so the build runs straight through and the queued work happens right after.
    if ($script:NewUiPrimary -and $script:_wpfShellCamActive) {
        # Only let WPF draw its next frame (the spinning gear lives in a layered window that is drawn by the UI thread);
        # timers and queued work are NOT run here.
        try { $script:_wpfShellWindow.Dispatcher.Invoke([Action] {}, [System.Windows.Threading.DispatcherPriority]::Render) } catch {}
        return
    }
    [System.Windows.Forms.Application]::DoEvents()
}

# Loads a picture from the Help\images folder shipped next to the app (returns $null if it is missing, so the text still shows)
function Get-HelpImage([string]$FileName) {
    try {
        $p = Join-Path (Join-Path (Join-Path (Split-Path -Path $scriptPath) 'Help') 'images') $FileName
        if (-not (Test-Path $p)) { return $null }
        $ms = New-Object System.IO.MemoryStream(, [System.IO.File]::ReadAllBytes($p))
        return [System.Drawing.Image]::FromStream($ms)
    }
    catch { return $null }
}

# A round yellow badge with a raised hand, used in front of the Hand Alert settings line
function New-HandBadgeBitmap([int]$Size = 26) {
    $bmp = New-Object System.Drawing.Bitmap($Size, $Size)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    try {
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
        $fill = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(255, 205, 0))
        $pen = New-Object System.Drawing.Pen ([System.Drawing.Color]::FromArgb(200, 140, 0)), 1.5
        $g.FillEllipse($fill, 1, 1, $Size - 3, $Size - 3)
        $g.DrawEllipse($pen, 1, 1, $Size - 3, $Size - 3)
        $font = New-Object System.Drawing.Font('Segoe UI Emoji', ($Size * 0.42), [System.Drawing.FontStyle]::Regular, [System.Drawing.GraphicsUnit]::Pixel)
        $sf = New-Object System.Drawing.StringFormat
        $sf.Alignment = [System.Drawing.StringAlignment]::Center; $sf.LineAlignment = [System.Drawing.StringAlignment]::Center
        $ink = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(70, 45, 0))
        $g.DrawString([string][char]0x270B, $font, $ink, (New-Object System.Drawing.RectangleF(0, 1, $Size, $Size)), $sf)
        $fill.Dispose(); $pen.Dispose(); $font.Dispose(); $ink.Dispose(); $sf.Dispose()
    }
    finally { $g.Dispose() }
    return $bmp
}

function Show-SettingsDialog {
    $script:_settingsBuildSw = [System.Diagnostics.Stopwatch]::StartNew()
    # Helper: Disable mouse wheel on NumericUpDown controls
    function Disable-NumericMouseWheel($control) {
        $control.Add_MouseWheel({ param($s, $e); $e.Handled = $true })
    }

    # Keep settings dialog in the same DPI context as the main UI.
