    $tbKey = New-Object System.Windows.Forms.TextBox; $tbKey.Text = $script:Cfg.Keyword; $tbKey.Location = Pt 106 33; $tbKey.Size = Sz 74 24; $grpKeyTess.Controls.Add($tbKey)
    $tbKey.HideSelection = $true
