    Log "Settings: build at $($script:_settingsBuildSw.ElapsedMilliseconds) ms - OCR region"
    $grpROI = New-Object System.Windows.Forms.GroupBox; $grpROI.Text = "OCR Region of Interest (screen coords)"; $grpROI.Location = Pt 14 $y; $grpROI.Size = Sz 792 146; $panel.Controls.Add($grpROI)
    $lblROIHint = New-Object System.Windows.Forms.Label; $lblROIHint.Text = "Click 'Set ROI (drag)', then drag a rectangle around the keyword area on any monitor (Esc cancels). The ROI is stored in real screen pixels, so it keeps working when you change the Windows display scale."; $lblROIHint.AutoSize = $false; $lblROIHint.Size = Sz 700 40; $lblROIHint.Anchor = 'Left, Right'; $lblROIHint.Location = Pt 10 20; $grpROI.Controls.Add($lblROIHint)
    $btnROIInfo = New-Object System.Windows.Forms.Button
    $btnROIInfo.Text = "i"
    $btnROIInfo.Font = New-Object System.Drawing.Font("Segoe UI", 9, [System.Drawing.FontStyle]::Bold)
    $btnROIInfo.Size = Sz 26 22
    $btnROIInfo.Location = Pt 716 20
    $btnROIInfo.Anchor = 'Right'
    $btnROIInfo.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnROIInfo.FlatAppearance.BorderSize = 0
