    $btnPrev = New-Object System.Windows.Forms.Button; $btnPrev.Text = "Preview ROI"; $btnPrev.Size = Sz 110 26; $btnPrev.Location = Pt 10 98; $grpROI.Controls.Add($btnPrev)
    $btnPrev.Add_Click({
