        })

    # ---------- Audio Ducking Section ----------
    Step-SettingsPump
    # Enable ducking checkbox
    $chkDuckingEnabled = New-Object System.Windows.Forms.CheckBox
    $chkDuckingEnabled.Text = "Enable Auto-Ducking"
